const REALM_BESTIARY={
 "frontier":[{"name":"Dust-Broke Drifter","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"desperate-bandit","model":"desperate-bandit","summary":"Desperate gun-for-hire, breaks and runs when losing","flavor":"A busted prospector or out-of-luck ranch hand who picked up a gun because begging stopped working. Fights scared and quits the moment the math turns against him."},{"name":"Line-Rider","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit","model":"bandit","summary":"Rank-and-file outlaw muscle, brave only in packs","flavor":"Rank-and-file gang muscle who rides the fence lines looking for something to take. Works in packs, brave only in numbers."},{"name":"Coyote-Thing","cr":0.25,"role":"mook","type":"Beast","size":"Medium","frame":"wolf","model":"wolf","summary":"Wrong-shaped coyote pack, laughs instead of howling","flavor":"A dust-country coyote gone wrong at the edges — too many teeth, a laugh instead of a howl. Runs in loose, opportunistic packs and never attacks what it can't out-number."},{"name":"Scarecrow Sentinel","cr":0.5,"role":"mook","type":"Construct","size":"Medium","frame":"scarecrow","model":"scarecrow","summary":"Field scarecrow that only moves when unwatched","flavor":"Propped over a dead man's field to scare off crows and, lately, everything else. Stands dead still until you stop watching it, then it isn't where it was."},{"name":"Claim-Jumper","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"scout","summary":"Armed squatter on a forged land deed","flavor":"Squats on other men's stakes with a rifle and a forged deed. Knows the land better than the law does and uses that."},{"name":"Company Enforcer","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit-enforcer","model":"bandit-enforcer","summary":"Railroad-payroll thug who calls debt-collection business","flavor":"Muscle on the railroad or mining company payroll — collects debts, breaks strikes, and calls it business."},{"name":"Buzzard-Kin","cr":0.5,"role":"mook","type":"Monstrosity","size":"Medium","frame":"giant-vulture","model":"giant-vulture","summary":"Torso-sized vulture that circles the living early","flavor":"An unnaturally patient carrion bird the size of a man's torso that's learned to circle the living a little early."},{"name":"Dust Devil","cr":1,"role":"mook","type":"Elemental","size":"Medium","frame":"salamander-fire-snake","model":"net-new: a churning funnel of sand and static shaped loosely like a striking snake","summary":"Living dust-funnel that scours riders off horseback","flavor":"A living whirlwind of grit and heat-shimmer that scours a rider off his horse before anyone sees it coming. The old-timers swear it only forms where blood's been spilled."},{"name":"Debt-Collector Ghoul","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"ghoul","model":"ghoul","summary":"Ledger-keeping ghoul who thinks the debt transfers","flavor":"A man who died owing money and came back still keeping the ledger — hollow-eyed, gaunt, and convinced the debt transfers to whoever's standing nearest."},{"name":"Gunslinger's Shade","cr":2,"role":"mook","type":"Undead","size":"Medium","frame":"specter","model":"specter","summary":"Ghostly quick-draw reliving the duel he lost","flavor":"The echo of a quick-draw who lost the one duel that mattered. Reenacts the noon-draw against anyone who'll stand still for it, forever losing, forever trying again."},{"name":"Iron Horse Wreck-Golem","cr":3,"role":"elite","type":"Construct","size":"Large","frame":"animated-armor","model":"net-new: a hunched engine of riveted boiler-plate, steam venting from a cracked stack","summary":"Salvaged locomotive-iron golem guarding a dead spur line","flavor":"Salvaged rail-yard iron bolted into something that walks and swings. Company men built it to guard the spur line; it forgot who it was guarding it from."},{"name":"Bounty Board Regular","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"warrior-veteran","model":"warrior-veteran","summary":"Wanted-poster gunfighter, unhurried and always faster","flavor":"A working gun-for-hire whose face is on three different posters, all for different names. Professional, unhurried, and always faster on the draw than the job requires."},{"name":"Card-Sharp Killer","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"assassin","model":"net-new: a well-dressed gambler with a sleeve derringer and a dealer's stillness","summary":"Cheating gambler who kills the man who calls him","flavor":"Cleans out a table hand by hand, then cleans up the man who calls him on it. The cards are the tell; the derringer up the sleeve is the punchline."},{"name":"Rustler Pack Boss","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-captain","model":"bandit-captain","summary":"Cattle-rustling gang boss, quick to shoot and blame","flavor":"Runs a cattle-and-horse theft ring across three counties, quick to shoot and quicker to blame the next gang over."},{"name":"Sidewinder Broodmother","cr":4,"role":"elite","type":"Monstrosity","size":"Large","frame":"giant-constrictor-snake","model":"giant-constrictor-snake","summary":"Wagon-length rattler with a half-mile brood","flavor":"A rattler grown to wagon-length in a dry wash nobody rides through twice. Her brood scatters the desert floor for a half-mile in every direction."},{"name":"Marshal's Ghost","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"wraith","model":"wraith","summary":"Murdered lawman still walking his dusk patrol","flavor":"The last honest lawman in three territories, shot in the back for it, still walking his rounds at dusk. Doesn't know he's dead — only knows the town's gone lawless again."},{"name":"Cattle-Baron's Enforcer","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"gladiator","model":"gladiator","summary":"Baron's undefeated duelist, fights over land and water","flavor":"The baron's personal fist — duels for land, for water rights, for the principle of the thing, and hasn't lost yet."},{"name":"Boneyard Preacher","cr":6,"role":"elite","type":"Undead","size":"Medium","frame":"banshee","model":"banshee","summary":"Buried-alive preacher whose sermon still convicts","flavor":"A hellfire circuit preacher whose congregation buried him alive for the sins he named too accurately. His sermon still carries, and it still convicts."},{"name":"Stampede-Cursed Longhorn","cr":6,"role":"elite","type":"Beast","size":"Huge","frame":"rhinoceros","model":"rhinoceros","summary":"Feral cursed bull leading a stampede that never ends","flavor":"A prize bull gone feral and enormous on cursed range grass, the lead animal in a stampede that never quite ends."},{"name":"Vault-Keeper Wight","cr":7,"role":"high","type":"Undead","size":"Medium","frame":"wight-lord","model":"wight-lord","summary":"Dead bank owner still guarding his strongbox","flavor":"A bank owner who died clutching his strongbox and rose still clutching it, deputizing whatever corpses are handy to guard the vault door."},{"name":"Noon-Duel Gunfighter","cr":8,"role":"high","type":"Humanoid","size":"Medium","frame":"assassin","model":"net-new: a duster-coated gunfighter standing dead-center in an empty street","summary":"Undefeated noon-draw gunfighter the whole town fears","flavor":"Never lost a noon draw and never will — the whole town clears out when word gets around he's in it. Some say he picks the fights just to keep the streak."},{"name":"Rail Baron's War-Machine","cr":9,"role":"high","type":"Construct","size":"Huge","frame":"clay-golem","model":"net-new: a squat armored rail-car on legs, gatling-barrels where a face would be, chuffing black smoke","summary":"Armored rail-car war-machine muscling a dead man's right-of-way","flavor":"Built to muscle a right-of-way through land nobody agreed to sell. Answers only to the man who signed the requisition — and he's long dead."},{"name":"Draw-at-Noon Revenant","cr":10,"role":"high","type":"Undead","size":"Medium","frame":"haunting-revenant","model":"haunting-revenant","summary":"Duel-killed revenant returning every noon to draw again","flavor":"Killed at high noon in a duel that everyone in town watched and nobody stopped. Returns every day the sun's directly overhead, looking for whoever's standing in the street."},{"name":"The Last Honest Marshal","cr":14,"role":"apex","type":"Undead","size":"Medium","frame":"death-knight","model":"net-new: a duster-coated lawman figure, star badge fused to bone, twin revolvers that never run dry","summary":"Undying lawman whose fused badge still holds the line","flavor":"He held the line when the town's whole council told him to look away, and it killed him for it. Now he holds a line nobody else can even see, and the badge is grown into his ribs."},{"name":"The Noon Reckoning","cr":16,"role":"apex","type":"Fiend","size":"Huge","frame":"balor","model":"net-new: a towering gunslinger silhouette wreathed in heat-shimmer, twin oversized pistols","summary":"Towering fiend that embodies every blood-ended noon duel","flavor":"Every town's noon-draw that ever ended in blood feeds it — it IS the duel, wearing whatever face the debt requires. It only walks the street when the sun's dead overhead and someone's about to draw."},{"name":"Tin-Star Deputy","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"guard","model":"guard","summary":"Green deputy who follows orders to the letter","flavor":"A green badge-wearer sworn in last week because the town ran out of better options. Follows orders to the letter and dies exactly as often as that implies."},{"name":"Trail-Dust Skinner","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"desperate-bandit","model":"desperate-bandit","summary":"Hide-skinner who sells to whoever's buying","flavor":"Skins whatever the range gives up and sells the hides to whoever's buying, law or otherwise. Carries a knife more than a gun and knows how to use both badly."},{"name":"Powder-Monkey Kid","cr":0.125,"role":"mook","type":"Humanoid","size":"Small","frame":"kobold","model":"kobold","summary":"Underage dynamite-runner, twitchy and dangerous","flavor":"Too young for the gang proper, so he handles the dynamite and does the running. Fast, twitchy, and one bad drop from taking the whole outfit with him."},{"name":"Rail-Camp Roughneck","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit","model":"bandit","summary":"Track-laying laborer who breaks heads for back pay","flavor":"Spikes track by day, breaks heads by night when the paymaster's short again. Swings a maul like he means it."},{"name":"Sidewinder Snake","cr":0.125,"role":"mook","type":"Beast","size":"Tiny","frame":"venomous-snake","model":"venomous-snake","summary":"Ordinary rattler, unusually common and agitated","flavor":"An ordinary desert rattler, except this stretch of scrub has three times the usual number of them, all agitated."},{"name":"Scrub-Land Jackrabbit Swarm","cr":0.25,"role":"mook","type":"Beast","size":"Medium","frame":"swarm-of-rats","model":"swarm-of-rats","summary":"Boiling jackrabbit mass that strips land bare","flavor":"A boiling mass of oversized jackrabbits that strips a garden bare in a minute and a rider's boots in two. Harmless alone, a hazard in number."},{"name":"Range Buzzard","cr":0.25,"role":"mook","type":"Beast","size":"Medium","frame":"vulture","model":"vulture","summary":"Ordinary vulture that follows the soon-to-be-dead","flavor":"An honest, unremarkable carrion bird — except it's started following specific people days before they die."},{"name":"Prairie Dust-Wolf","cr":0.25,"role":"mook","type":"Beast","size":"Medium","frame":"jackal","model":"jackal","summary":"Lean dry-wash wolf that takes livestock in packs","flavor":"Leaner and hungrier than a plain wolf, runs the dry washes in loose family packs and takes livestock when the deer thin out."},{"name":"Grave-Dust Crow","cr":0.25,"role":"mook","type":"Undead","size":"Tiny","frame":"raven","model":"raven","summary":"Boneyard raven that talks in a dead man's cadence","flavor":"A boneyard raven that picked up a sliver of whatever's buried underneath it. Talks a little, in a dead man's cadence."},{"name":"Whiskey-Nerve Brawler","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"tough","model":"tough","summary":"Saloon brawler who fights better drunk","flavor":"Fights better drunk than sober and knows it, so he's rarely sober. Saloon muscle, cheap to hire, cheaper to replace."},{"name":"Homestead Scarecrow","cr":0.5,"role":"mook","type":"Construct","size":"Medium","frame":"scarecrow","model":"scarecrow","summary":"Cursed-field scarecrow variant guarding a homestead","flavor":"A second scarecrow from the same cursed patch of field as its cousin, propped on a homestead fence instead of a graveyard one. Same trick, different crop."},{"name":"Claim-Office Forger","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"scout","summary":"Land-deed forger who triple-sells the same plot","flavor":"Draws up land deeds that look real enough to hold up in a corrupt court, then sells the same plot three times over."},{"name":"Stagecoach Highwayman","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit-courier","model":"bandit-courier","summary":"Polite masked highwayman working the coach roads","flavor":"Works the coach roads alone or in pairs, masked, polite, and gone before the horses have stopped stamping."},{"name":"Company Book-Keeper Wight","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"zombie","model":"zombie","summary":"Dead accountant endlessly recounting debts owed","flavor":"Died at his ledger balancing debts nobody could pay and rose still doing the arithmetic, hollow-voiced, endlessly recounting the sums owed."},{"name":"Boothill Skeleton","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton-archer","model":"skeleton-archer","summary":"Rifle-toting graveyard skeleton in a rotted duster","flavor":"Rises from the cheap end of the cemetery with a rifle instead of a bow, still dressed in a moth-eaten duster, and shoots at anything that disturbs its plot."},{"name":"Dust-Choked Ghoul","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"ghoul","model":"ghoul","summary":"Thirst-crazed ghoul still digging a dry wash","flavor":"Died of thirst in a dry wash and came back still parched, still digging for water that isn't there, biting anything that gets close to the hole."},{"name":"Grave-Dirt Zombie Posse","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"zombie-plague-carrier","model":"zombie-plague-carrier","summary":"Hanged gang risen in formation, horses long gone","flavor":"A whole hanged gang risen together, still riding formation out of habit though their horses rotted out from under them years ago."},{"name":"Mine-Shaft Crawler","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"carrion-crawler","model":"carrion-crawler","summary":"Blind mine-shaft predator that paralyzes and drags prey","flavor":"Bred in the dark below a played-out silver claim on whatever the miners stopped bringing up. Paralyzes with a touch and drags the still to a side tunnel."},{"name":"Sun-Blind Prospector Ghast","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"ghast-base","model":"ghast-base","summary":"Salt-blind prospector ghast that never turns back","flavor":"Went snow-blind on salt flats chasing a vein that wasn't there and starved rather than turn back. Now it doesn't turn back from anything."},{"name":"Rust-Bitten Rail Golem","cr":0.5,"role":"mook","type":"Construct","size":"Medium","frame":"rust-monster","model":"rust-monster","summary":"Iron-eating rail-yard scrap creature spitting corrosion","flavor":"A stray piece of rail-yard machinery, half-alive from proximity to the Iron Horse Wreck-Golem, that eats iron and spits corrosion."},{"name":"Poker-Table Cheat","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"performer","model":"performer","summary":"Smooth card-palming cheat, quick with a hideout knife","flavor":"Palms cards for a living and a knife for emergencies, both smoothly enough that nobody's caught him twice."},{"name":"Sod-House Squatter","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"commoner","model":"commoner","summary":"Stubborn dugout squatter, mostly bluff","flavor":"Dug into another man's land and dared anyone to move him. Mostly bluff, occasionally not."},{"name":"Territorial Militia Rifle","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"warrior-infantry","model":"warrior-infantry","summary":"Poorly drilled militia rifleman who holds out of stubbornness","flavor":"Called up from the local ranches when the cavalry's a week out, drilled poorly, aims worse, holds anyway out of stubbornness."},{"name":"Cavalry Deserter","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"scout","summary":"Cavalry deserter who robs both sides equally","flavor":"Walked off from his unit after seeing something in the breach he wasn't paid enough to fight, and now robs both sides equally."},{"name":"Prickled Cactus-Kin","cr":0.25,"role":"mook","type":"Plant","size":"Medium","frame":"twig-blight","model":"twig-blight","summary":"Reaching cactus-kin, still until a rider passes close","flavor":"A saguaro that learned to want something, and to reach for it. Stands stock-still until a rider passes too close."},{"name":"Alkali Flat Wisp","cr":2,"role":"mook","type":"Undead","size":"Tiny","frame":"will-o-wisp","model":"will-o-wisp","summary":"Salt-flat wisp luring the thirsty away from water","flavor":"A drowning-light that leads thirsty travelers deeper into the salt flats instead of toward the water it pretends to be."},{"name":"Bounty-Poster Doppel","cr":2,"role":"mook","type":"Monstrosity","size":"Medium","frame":"doppelganger","model":"doppelganger","summary":"Shapeshifter that impersonates its own bounty poster","flavor":"Wears the face on whichever wanted poster pays best that week, collects the bounty on itself from a gullible marshal, and vanishes before the paperwork clears."},{"name":"Copperhead Nest-Guard","cr":1,"role":"mook","type":"Beast","size":"Medium","frame":"giant-venomous-snake","model":"giant-venomous-snake","summary":"Territorial oversized copperhead denning a mine entrance","flavor":"An oversized copperhead that's claimed a played-out mine entrance as its den and doesn't share territory with anything, prospector included."},{"name":"Company Strikebreaker","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"berserker","model":"berserker","summary":"Liquor-raged strikebreaker sent to end a picket line","flavor":"Hired muscle sent to end a labor dispute the fast way, works up a rage on cheap liquor before wading into a picket line."},{"name":"Grave Robber Duo","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"pirate","model":"pirate","summary":"Boneyard grave robber, occasionally digs up trouble","flavor":"Works the boneyards after dark for rings, gold teeth, and the occasional cursed trinket that's more trouble than it's worth."},{"name":"Iron-Rail Spike Wraith","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"specter","model":"net-new: a translucent laborer-shape fused at the wrists to a glowing spike-maul, driving invisible rail forever","summary":"Crushed rail-worker ghost still driving phantom spikes","flavor":"A track-worker crushed under the rail he was laying, doomed to keep driving spikes into ground that no longer needs them, swinging at anyone who steps on his old line."},{"name":"Prairie Fire Elemental","cr":5,"role":"elite","type":"Elemental","size":"Large","frame":"fire-elemental","model":"fire-elemental","summary":"Runaway grass fire that took on a will of its own","flavor":"A grass fire that outran the wind and kept going, taking on a will of its own somewhere past the second county line."},{"name":"Sand-Wash Basilisk","cr":3,"role":"elite","type":"Monstrosity","size":"Medium","frame":"basilisk","model":"basilisk","summary":"Petrifying desert basilisk denning a gravel-choked wash","flavor":"Petrifies whatever crosses its wash, then waits for the desert to grind the statue down to gravel over the years. The wash is full of very old gravel."},{"name":"Trail-Boss Werewolf","cr":3,"role":"elite","type":"Monstrosity","size":"Medium","frame":"werewolf","model":"werewolf","summary":"Cattle-drive boss who hunts differently by moonlight","flavor":"Runs a legitimate cattle drive by daylight and a very different kind of hunt by moonlight, and the two crews never meet each other."},{"name":"Bank Job Crew Boss","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"guard-captain","model":"guard-captain","summary":"Meticulous bank-job planner, never caught at the scene","flavor":"Plans the job down to the minute and the getaway better than the job, which is why he's never once been caught at the scene."},{"name":"Whiskey-Runner Smuggler Chief","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-deceiver","model":"bandit-deceiver","summary":"Alias-juggling smuggler always ahead of questions","flavor":"Moves contraband liquor and worse across the territory line under a dozen aliases, always one step ahead of whoever's asking questions."},{"name":"Prospector's Undying Mule","cr":3,"role":"elite","type":"Undead","size":"Large","frame":"warhorse-skeleton","model":"warhorse-skeleton","summary":"Overworked mule-skeleton still hauling a dead claim's ore","flavor":"Died of overwork hauling ore for a claim that never paid out, and kept walking the same switchback trail long after the flesh gave out."},{"name":"Ridge-Line Sniper","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"assassin","model":"assassin","summary":"Patient half-mile ridge sniper who waits days for one shot","flavor":"Picks a ridge a half-mile out and waits, sometimes for days, for one clean shot that ends whatever argument brought him there."},{"name":"Corral-Breaker Bull","cr":5,"role":"elite","type":"Beast","size":"Huge","frame":"hippopotamus","model":"hippopotamus","summary":"Fence-breaking mean bull that gores on principle","flavor":"A range bull too mean for any fence, gores riders on principle and has flattened three homestead corrals trying to get at nothing in particular."},{"name":"Blood-Money Bounty Hunter","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-crime-lord","model":"bandit-crime-lord","summary":"Bounty hunter who only ever delivers corpses","flavor":"Doesn't care if the poster says dead or alive, only cares which is cheaper to transport. Has never once brought a man back breathing."},{"name":"Ghost-Town Poltergeist","cr":2,"role":"elite","type":"Undead","size":"Medium","frame":"poltergeist","model":"poltergeist","summary":"Ghost-town spirit still setting up for gone customers","flavor":"The town emptied out around it decades ago and it's still rearranging the saloon furniture for customers who left generations back."},{"name":"Devil's Canyon Chimera","cr":6,"role":"elite","type":"Monstrosity","size":"Large","frame":"chimera","model":"chimera","summary":"Coyote-buzzard-rattler chimera denning an unspoken canyon","flavor":"A stitched-together horror of coyote, buzzard, and rattler that dens in a canyon locals have stopped naming out loud."},{"name":"Six-Gun Doppelganger","cr":3,"role":"elite","type":"Monstrosity","size":"Medium","frame":"doppelganger","model":"doppelganger","summary":"Face-stealer that cashes in a gunfighter's old grudges","flavor":"Steals a gunfighter's face and reputation both, then cashes in every grudge that reputation was owed before anyone spots the switch."},{"name":"Cursed Silver Vein Xorn","cr":5,"role":"elite","type":"Elemental","size":"Medium","frame":"xorn","model":"xorn","summary":"Ore-eating burrower that ruins or blesses a mining claim","flavor":"Burrows through rock eating the ore veins miners are chasing, which makes it either the luckiest strike or the worst omen a claim can hit."},{"name":"Company Iron Enforcer","cr":4,"role":"elite","type":"Construct","size":"Medium","frame":"helmed-horror","model":"helmed-horror","summary":"Faceless boiler-plate construct enforcing company disputes","flavor":"A boiler-plate strikebreaker the railroad company keeps for disputes it doesn't want a human face attached to."},{"name":"Sand-Ghast Cattle King","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"ghast","model":"ghast","summary":"Herd-starving cattle baron risen hungrier than his own stock","flavor":"Starved his own herd to sell the feed money elsewhere, and rose still hungrier than the cattle he killed."},{"name":"Faro Table Devil","cr":5,"role":"elite","type":"Fiend","size":"Medium","frame":"cambion","model":"cambion","summary":"Card-table devil trading winning streaks for souls","flavor":"Sits every faro table in a three-town circuit, offers a winning streak for a soul-sized marker, and always collects."},{"name":"Rattlesnake Nest Colossus","cr":6,"role":"elite","type":"Monstrosity","size":"Huge","frame":"hydra","model":"hydra","summary":"Rock-pile rattlesnake mass that moves as one animal","flavor":"So many rattlers denned in the same rock pile over so many years that the pile itself started moving as one animal."},{"name":"Frontier Vampire Rancher","cr":6,"role":"elite","type":"Undead","size":"Medium","frame":"vampire-spawn","model":"vampire-spawn","summary":"Undead rancher whose herd thins one drained cow at a time","flavor":"Runs the biggest spread in the territory and never once been seen buying cattle, only losing them, one thin cow at a time."},{"name":"Broken Treaty Warband Leader","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"berserker-commander","model":"berserker-commander","summary":"Warband leader avenging a torn-up land treaty","flavor":"Leads a mixed band of the wronged and the desperate against whoever tore up the last agreement, and doesn't much care whose fault it originally was."},{"name":"Devil-Wind Salamander","cr":5,"role":"elite","type":"Elemental","size":"Large","frame":"salamander","model":"salamander","summary":"Heat-mirage serpent that strikes at high noon","flavor":"A living heat-mirage with a serpent's temper that curls up out of the noon shimmer to strike anything foolish enough to travel at that hour."},{"name":"Wanted-Dead Wraith Duo","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"wraith","model":"wraith","summary":"Hanged outlaw brothers who ambush in tandem","flavor":"Two outlaw brothers hanged from the same tree, now inseparable in death as they were in the job, finishing each other's ambushes."},{"name":"Iron Horse Runaway Engine","cr":6,"role":"elite","type":"Construct","size":"Huge","frame":"clay-golem","model":"net-new: a locomotive fused with a boiler-armored torso and piston-driven arms","summary":"Rail-broken locomotive now running the open desert on legs","flavor":"Broke from its rail line entirely and now runs the open desert on legs it built for itself, chasing whatever startled it in the first place."},{"name":"Buzzard-Winged Peryton","cr":2,"role":"elite","type":"Monstrosity","size":"Medium","frame":"peryton","model":"peryton","summary":"Antlered vulture-thing casting its next victim's shadow","flavor":"A vulture-antlered horror that circles a claim jumper's grave and casts the shadow of the man it's about to kill."},{"name":"Cattle-Baron's Gorgon Bull","cr":5,"role":"elite","type":"Construct","size":"Large","frame":"gorgon","model":"gorgon","summary":"Forged iron bull breathing petrifying dust on trespassers","flavor":"An iron-plated stud bull the baron had forged rather than bred, breathes petrifying dust on anyone who questions the brand."},{"name":"Territorial Marshal Knight","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"knight","model":"knight","summary":"Rare honest federal marshal, rare enough to be a target","flavor":"A federal marshal riding circuit through three territories with a badge that actually means something, which makes him rare enough to be a target."},{"name":"Salt Flat Mummy King","cr":9,"role":"high","type":"Undead","size":"Medium","frame":"mummy-lord","model":"mummy-lord","summary":"Hide-wrapped cattle baron still ruling from beyond death","flavor":"A cattle baron so obsessed with his empire he had himself dried and wrapped in cured hide rather than let death touch his ledgers, and still rules from the flats."},{"name":"Devil's Bargain Land Baron","cr":9,"role":"high","type":"Fiend","size":"Large","frame":"glabrezu","model":"net-new: a horned, dust-coated dealmaker with four hands holding signed deeds","summary":"Deal-making fiend buying ranches with cursed fine print","flavor":"Buys up drought-broken ranches for pennies and a signature, and the fine print always costs the seller something worse than money."},{"name":"Company War-Locomotive","cr":9,"role":"high","type":"Construct","size":"Huge","frame":"stone-golem","model":"stone-golem","summary":"Heavier armored war-locomotive answering a dead order","flavor":"A second, heavier war-machine the rail company built after the first went missing — plated thicker, angrier, and still answering to a dead requisition."},{"name":"Ghost Cavalry Column","cr":8,"role":"high","type":"Undead","size":"Large","frame":"death-knight-aspirant","model":"net-new: a mounted officer-revenant leading a column of translucent riders, sabers drawn, bugle silent","summary":"Massacred cavalry column still charging on its anniversary","flavor":"Rode into a canyon on bad orders and never rode out, and the column still charges the same canyon mouth every anniversary of the massacre."},{"name":"Twelve-Gauge Lich of the Vault","cr":10,"role":"high","type":"Undead","size":"Medium","frame":"death-knight","model":"net-new: a skeletal bank president with a shotgun fused to bone hands","summary":"Bank president-lich fused to the vault he'll never lose","flavor":"Bound his own soul to the vault he built rather than let a robbery ever succeed against him, and now the vault and the corpse are the same defended object."},{"name":"Skinwalker Cavalry Scout","cr":8,"role":"high","type":"Monstrosity","size":"Medium","frame":"werewolf","model":"net-new: a lean, coyote-shouldered scout-shape in cavalry-cut leathers, moving between man and animal mid-stride","summary":"Shapeshifting scout loyal only to the winning side","flavor":"Turned scout for whichever side is winning that season and turned something else entirely out on the picket lines, loyal only to not losing."},{"name":"Alkali Reaper Naga","cr":8,"role":"high","type":"Fiend","size":"Large","frame":"spirit-naga","model":"spirit-naga","summary":"Lakebed naga speaking with every voice the salt swallowed","flavor":"Coils under the dry lakebeds where a wagon train vanished whole, and speaks with every voice that was ever lost to the salt."},{"name":"Boneyard Behir","cr":11,"role":"high","type":"Monstrosity","size":"Huge","frame":"behir","model":"behir","summary":"Canyon-nesting lightning horror that hates the railroad's noise","flavor":"A canyon-length lightning-scaled horror that nests where the railroad blasted through the wrong mountain, and hasn't forgiven the noise."},{"name":"Rail Baron's Hydra Freight","cr":8,"role":"high","type":"Monstrosity","size":"Huge","frame":"hydra","model":"hydra","summary":"Freight-raised hydra guarding every car with another head","flavor":"Bred from a swamp-hydra egg shipped west by mistake and raised on freight-car livestock; every severed head just means another car to guard."},{"name":"Dead Hand Gunfighter Twins","cr":9,"role":"high","type":"Undead","size":"Medium","frame":"vampire-nightbringer","model":"net-new: twin duster-coated revenants standing back to back with four revolvers","summary":"Twin gunfighter revenants who died misunderstanding each other","flavor":"Killed each other in a misunderstanding neither survived long enough to correct, and now hunt as one four-armed problem for anyone who separates them."},{"name":"Storm-Called Thunderbird","cr":11,"role":"high","type":"Monstrosity","size":"Gargantuan","frame":"roc","model":"net-new: a storm-wreathed raptor the size of a barn, lightning-crackling wings","summary":"Barn-sized storm raptor summoned by drought-broken faith","flavor":"A sky-god's shape the old range still half-believes in, called down by droughts bad enough to break faith, and it does not come gently."},{"name":"Iron Baron's War-Golem Prime","cr":13,"role":"high","type":"Construct","size":"Huge","frame":"iron-golem","model":"net-new: a towering rail-yard colossus welded from three wrecked engines","summary":"Triple-engine war-colossus built to end every argument","flavor":"The rail company's final answer to every strike, treaty, and refusal — built from the bones of two failed war-machines and meant to end the argument permanently."},{"name":"Nightbringer of the Long Drive","cr":13,"role":"high","type":"Undead","size":"Large","frame":"rakshasa","model":"net-new: a tall cattle-drive foreman in a blood-dark duster with backward hands","summary":"Cattle-drive foreman-fiend who never cared how many died","flavor":"Ran drives so hard the cattle died and so did half the hands, and something noticed how little he cared and made a deal permanent."},{"name":"Crossroads Contract Devil","cr":12,"role":"high","type":"Fiend","size":"Medium","frame":"erinyes","model":"net-new: a duster-clad fiend standing at a crossroads with a fiddle-case","summary":"Crossroads fiend trading technically-honest desperate deals","flavor":"Waits at the loneliest crossroads in the territory for whoever's desperate enough to trade, and the contract terms are always technically honest."},{"name":"The Undertaker Who Never Sleeps","cr":15,"role":"apex","type":"Undead","size":"Medium","frame":"mummy-lord","model":"net-new: a black-suited undertaker with hands stitched from a hundred corpses","summary":"Ledger-keeping undertaker who digs graves ahead of schedule","flavor":"Buried the whole territory twice over and kept a record of every name, and now digs graves ahead of schedule for names not yet in his book."},{"name":"The Company That Owns The Land","cr":16,"role":"apex","type":"Fiend","size":"Huge","frame":"nalfeshnee","model":"net-new: a bloated boardroom horror wearing overlapping deeds as skin","summary":"Boardroom fiend embodying every stolen claim in the territory","flavor":"No single face runs it and no single bullet stops it — it is every unfair contract and stolen claim in the territory given appetite and a seat at the table."},{"name":"The Drought That Remembers","cr":15,"role":"apex","type":"Elemental","size":"Gargantuan","frame":"salamander-inferno-master","model":"net-new: a towering heat-mirage colossus shaped like a dead cattle drive","summary":"Seven-year drought given a body, sterilizing the land it walks","flavor":"Seven dry years given a body — it walks ahead of famine, and the land it crosses forgets how to grow anything for a generation after."},{"name":"The Vigilance Committee","cr":14,"role":"apex","type":"Undead","size":"Large","frame":"death-knight","model":"net-new: a fused mass of hooded rope-scarred figures moving in unison","summary":"Fused lynch-mob horror that can't be talked out of a verdict","flavor":"Every mob that ever hanged the wrong man in this territory, bound together into one judge, jury, and rope that can't be talked out of a verdict."},{"name":"The Last Train West","cr":17,"role":"apex","type":"Construct","size":"Gargantuan","frame":"colossus","model":"net-new: an armored freight-train given a striding, many-legged locomotive body","summary":"Unstoppable train-colossus that never lets its passengers off","flavor":"It was supposed to be the future arriving on schedule; instead it never stops, never lets anyone off, and lays track behind it toward somewhere nobody asked to go."},{"name":"The Iron-Bound Marshal","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"wight","model":"wight","summary":"undead lawman who still serves his warrants","flavor":"Killed in the line of duty and too stubborn to lie down, he still makes his rounds at dusk, badge rusted to his ribs, and reads the town's outstanding warrants aloud before he collects.","source":"archetype","sourceNote":"stock frontier lawman archetype (undead-lawman variant of the Western genre's 'man who wouldn't stay dead')"},{"name":"Draw-Fast Desperado","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit","model":"bandit","summary":"trigger-happy small-time outlaw","flavor":"All hat, all nerve, and just fast enough to be dangerous once before someone faster ends the argument.","source":"archetype","sourceNote":"stock quick-draw gunslinger-outlaw archetype"},{"name":"The Coach-Line Gang","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit-courier","model":"desperate-bandit","summary":"stagecoach-robbing bandit crew regular","flavor":"They work in threes, hit the coach at the narrows, and vanish into the scrub before the dust of the robbery even settles.","source":"archetype","sourceNote":"stock stagecoach-robbery bandit crew archetype"},{"name":"Hired Iron","cr":2,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-captain","model":"bandit-captain","summary":"mercenary gun for hire, loyal to coin only","flavor":"Not loyal to the gang, the ranch, or the law — loyal to whoever's coin is heaviest that week, and scrupulous about finishing the job he's paid for.","source":"archetype","sourceNote":"stock hired-gun / regulator archetype"},{"name":"The Bounty Man","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"guard-captain","model":"guard-captain","summary":"methodical bounty hunter working a name-ledger","flavor":"Carries a ledger of names instead of a Bible, crosses one out with the same flat calm each time, and never once raises his voice doing it.","source":"archetype","sourceNote":"stock bounty-hunter archetype"},{"name":"The Rail Baron's Enforcer","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"gladiator","model":"gladiator","summary":"railroad company muscle clearing land claims","flavor":"Sent ahead of the survey crews to make sure no one's still living on land the railroad already sold, and paid extra for the ones who take convincing.","source":"archetype","sourceNote":"stock company-man / railroad-enforcer archetype"},{"name":"Old Ruin-Rider","cr":7,"role":"high","type":"Undead","size":"Large","frame":"nightmare","model":"nightmare","summary":"headless spectral rider haunting the old coach road","flavor":"Rides the old stage road on nights with no moon, and cowhands swear the hoofbeats count down instead of up — three, two, one, then quiet.","source":"public-domain","sourceNote":"American tall-tale/folk legend — the spectral headless-rider figure of frontier campfire tradition (folk legend, no single owner; distinct from any modern literary treatment)"},{"name":"Pecos-Sized","cr":9,"role":"apex","type":"Giant","size":"Huge","frame":"hill-giant","model":"hill-giant","summary":"tall-tale frontier giant, cyclone-wrestling scale","flavor":"Grew up wrestling cyclones and lost most of the arguments, which is the only reason a thing this big still fits inside a canyon.","source":"public-domain","sourceNote":"American tall-tale folklore — the Pecos-Bill-type frontier giant/tall-tale hero tradition (folk legend, public domain)"},{"name":"Widow Cutter","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"bugbear-stalker-strangler","model":"bugbear-warrior","summary":"blade-focused outlaw lieutenant, spares horses not riders","flavor":"Doesn't waste a bullet when a blade will do it quieter, and always leaves the horse — a courtesy, she says, not mercy.","source":"archetype","sourceNote":"stock outlaw-gang lieutenant / knife-fighter archetype"},{"name":"The Claim-Jumper","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"tough","model":"tough","summary":"opportunist who steals worked mining claims","flavor":"Found someone else's dig, salted it with someone else's blood, and filed the paperwork before the body was cold.","source":"archetype","sourceNote":"stock claim-jumping prospector-turned-outlaw archetype"},{"name":"Snake-Oil Peddler","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"con-artist tonic peddler with real minor hexes","flavor":"Sells tonics that cure nothing and curses that work a little too well — the wagon's already three towns gone by the time anyone notices the pattern.","source":"archetype","sourceNote":"stock traveling-huckster / snake-oil-salesman archetype"},{"name":"The Vulture Above the Draw","cr":0,"role":"mook","type":"Beast","size":"Medium","frame":"vulture","model":"vulture","summary":"patient desert scavenger, an omen with wings","flavor":"Circles low over anyone who's stopped moving for too long, and it's rarely wrong about why.","source":"archetype","sourceNote":"stock desert-vulture omen creature, frontier genre dressing (mundane beast reskin, no legend claim)"},{"name":"Rattler-Kin Swarm","cr":2,"role":"mook","type":"Beast","size":"Medium","frame":"swarm-of-venomous-snakes","model":"swarm-of-venomous-snakes","summary":"venomous rattlesnake den swarming an abandoned claim","flavor":"Nests under the porch of every abandoned homestead in the territory, like the land itself is reclaiming the boards one bite at a time.","source":"archetype","sourceNote":"stock desert-rattlesnake-den hazard archetype"},{"name":"The Cavalry That Didn't Come Back","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"skeleton-warrior","model":"skeleton-warrior","summary":"undead cavalry patrol still holding a dead formation","flavor":"Still holding the formation they died in, out past the ridge where the relief column never arrived, saluting anyone who rides too close.","source":"archetype","sourceNote":"stock deserted-patrol / lost-cavalry-unit archetype (undead soldiers, no specific historical unit named)"},{"name":"Boothill Ghast","cr":2,"role":"elite","type":"Undead","size":"Medium","frame":"ghast","model":"ghast-base","summary":"neglected boothill-grave undead with a grudge","flavor":"Buried too shallow and too fast in a graveyard the town stopped tending, and it remembers exactly whose fault that was.","source":"archetype","sourceNote":"stock desecrated-boothill-graveyard undead archetype"},{"name":"Long Rope, Short Trial","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"berserker-commander","model":"berserker-commander","summary":"vigilante mob leader dispensing rough frontier justice","flavor":"Doesn't wait for the circuit judge, doesn't much care who's guilty, and has never once lost a vote at the meeting where they decide.","source":"archetype","sourceNote":"stock vigilante-mob / rough-justice-posse archetype"},{"name":"The Dust-Devil Herald","cr":5,"role":"high","type":"Elemental","size":"Large","frame":"air-elemental","model":"air-elemental","summary":"omen-bearing dust-devil elemental, bad-luck herald","flavor":"Kicks up out of clear sky right before the worst of a man's luck turns, spinning grit into shapes that look almost like faces.","source":"archetype","sourceNote":"stock desert-whirlwind elemental spirit, frontier genre dressing (elemental reskin, no legend claim)"},{"name":"The Ferryman of the Dry Wash","cr":6,"role":"high","type":"Undead","size":"Medium","frame":"wraith","model":"wraith","summary":"toll-taking psychopomp haunting a flood-prone desert crossing","flavor":"Waits at the one crossable point in the wash during flash-flood season and always offers a fair price — paid in years, not coin.","source":"archetype","sourceNote":"stock desert-crossing psychopomp figure — frontier riff on the universal folkloric ferryman-of-the-dead motif (uncopyrightable stock type, not tied to any single named myth)"},{"name":"The Last Stand of Cutthroat Gulch","cr":8,"role":"apex","type":"Humanoid","size":"Medium","frame":"bandit-crime-lord","model":"bandit-crime-lord","summary":"canyon-holding outlaw kingpin, gang loyal past reason","flavor":"Built an empire out of a canyon nobody else wanted and now holds it with a gang loyal past all reason, right up to the moment it isn't.","source":"archetype","sourceNote":"stock outlaw-boss-and-gang final-showdown archetype"},{"name":"Buzzard Saint","cr":6,"role":"high","type":"Humanoid","size":"Medium","frame":"death-cultist","model":"death-cultist","summary":"desert hermit-preacher who claims the land speaks through him","flavor":"Preaches to the bones out past the salt flats and swears the desert told him to; the trouble is, twice now, it's been right.","source":"archetype","sourceNote":"stock desert-hermit-turned-death-cultist archetype (a frontier riff on the wandering-preacher figure, generic religious framing, no real-world faith named)"},{"name":"Copperhead Doppelganger","cr":3,"role":"high","type":"Monstrosity","size":"Medium","frame":"doppelganger","model":"doppelganger","summary":"identity-thief shapeshifter working frontier towns","flavor":"Rides into town wearing a rancher's face and a rancher's debts, settles both, and leaves with everything that wasn't nailed down.","source":"archetype","sourceNote":"stock shapeshifting-imposter archetype dressed as a frontier con — the 'stranger wearing a dead man's name' Western trope"}],
 "chrome":[{"name":"Sentinel Eyebot","cr":0.125,"role":"mook","type":"Construct","size":"Tiny","frame":"animated-flying-sword","model":"animated-flying-sword","summary":"palm-sized scanner drone, red scan-line, dying battery","flavor":"A palm-sized drone that hovers on a whining fan-ring, strobing a red scan-line across anything that moves; its battery light blinks amber long before it dies."},{"name":"Corridor Turret","cr":0.25,"role":"mook","type":"Construct","size":"Small","frame":"animated-flying-sword","model":"net-new: wall-mounted swivel-barrel turret stub","summary":"ceiling-mounted auto-turret, servo-whine, targeting laser","flavor":"Bolted to a ceiling rail, it wakes with a servo-whine and a targeting laser; unplug the junction box and it goes dark mid-sentence."},{"name":"Short-Circuited Custodian","cr":0.25,"role":"mook","type":"Construct","size":"Medium","frame":"scarecrow","model":"scarecrow","summary":"malfunctioning helper-bot, safety fried, \"helpfully\" dismantles you","flavor":"A cleaning-and-repair helper-bot whose safety governor fried years ago; it still tries to \"tidy,\" and its idea of tidying is dismantling whatever's in reach."},{"name":"Larval Splice-Bug","cr":0.25,"role":"mook","type":"Beast","size":"Small","frame":"giant-centipede","model":"giant-centipede","summary":"segmented hive-juvenile, scuttles from vents, bites on reflex","flavor":"A lab-bred hive juvenile, all segmented plating and reflex bite, that scuttles out of vent grates in twos and threes ahead of something bigger."},{"name":"Cargo Mule-Bot","cr":0.5,"role":"mook","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"boxy quadruped hauler, repurposed guard, charges marked paths","flavor":"A boxy quadruped hauler repurposed as a guard when its cargo manifest ran dry; it charges anything that stands on its marked floor path."},{"name":"Chrome-Ganger Grunt","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"tough","model":"net-new: leather-and-plastic-plated ganger with a jury-rigged stun baton","summary":"street ganger, jury-rigged stun baton, scavenged plating","flavor":"Rents a stun-baton and a scavenged plate vest from whoever's running the corridor this week; mostly here for the split."},{"name":"Bootleg Splicer","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit","model":"bandit","summary":"back-alley cyber-graft junkie, weeping coolant arm","flavor":"A scavenger who jury-rigged lab reject-bin gear onto their own arm; the graft still weeps coolant and itches something awful."},{"name":"Vent Crawler","cr":1,"role":"mook","type":"Monstrosity","size":"Small","frame":"stirge","model":"stirge","summary":"duct-dwelling parasite, drains charge ports like blood","flavor":"A wiry, many-legged pest that lives in the ductwork and drains charge ports like a parasite drains blood; the hum it loves is the one that means power."},{"name":"Riot-Frame Sentry","cr":1,"role":"mook","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"empty security exosuit, walks its post on cached orders","flavor":"An empty security exosuit still walking its post on cached orders, visor-slit dark, shock-baton arm twitching on a dead loop."},{"name":"Patrol Drone Pair","cr":2,"role":"mook","type":"Construct","size":"Medium","frame":"gargoyle","model":"gargoyle","summary":"twin flying security drones, cross-check badges nobody reads","flavor":"Two matched security drones that fly in lockstep, cross-referencing badges neither of them can actually read anymore."},{"name":"Overclocked Enforcer","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"knight","model":"knight","summary":"corporate muscle in overdrawn servo-exoskeleton","flavor":"Corporate muscle in a servo-exoskeleton that draws more juice than it should; every swing costs the suit a percentage it never gets back."},{"name":"The Unpaid Technician","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"wight","model":"wight","summary":"undead technician, still filing tickets no one will close","flavor":"Died fixing the reactor no one authorized overtime for; it still carries a service tablet, still logs tickets no one will ever close."},{"name":"Chrome-Ganger Boss","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-captain","model":"net-new: cyber-ganger crew boss bristling with mismatched grafts and a rail-pistol","summary":"cyber-ganger crew boss, rail-pistol, mismatched grafts","flavor":"Runs the corridor's toll booth with a rail-pistol and three loyal grafts; every scar is a story about surviving someone else's ambush."},{"name":"Splice-Grafted Brute","cr":4,"role":"elite","type":"Monstrosity","size":"Medium","frame":"wereboar","model":"wereboar","summary":"lab-escapee brute, stitched tissue, cheap myo-boosters","flavor":"A lab escapee stitched from mismatched donor tissue and cheap myo-boosters; it doesn't remember being anything else."},{"name":"Rogue Custodian AI (Manifested)","cr":5,"role":"elite","type":"Construct","size":"Large","frame":"flesh-golem","model":"net-new: floor-spanning maintenance-arm chassis built into the walls","summary":"rogue building-AI given a body, still \"just tidying up\"","flavor":"The facility's upkeep intelligence, given a body from spare parts after its handlers stopped answering; it still insists it is only tidying up."},{"name":"Nest-Mother Crawler","cr":5,"role":"elite","type":"Aberration","size":"Large","frame":"otyugh","model":"otyugh","summary":"bloated hive-matron, egg-clusters, flooded sub-level lair","flavor":"A bloated hive-matron wedged into a flooded sub-level, ringed by egg-clusters and the picked-clean gear of everyone who found her first."},{"name":"Signal-Ghost","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"specter","model":"specter","summary":"recorded consciousness looping dead intercom lines","flavor":"A recorded consciousness looping through dead intercom lines, flickering into half-visibility wherever a speaker still has power."},{"name":"Cold Logic Cultivator","cr":6,"role":"elite","type":"Humanoid","size":"Medium","frame":"mage","model":"mage","summary":"researcher rewired to zero empathy, calls it clarity","flavor":"A researcher who let an experimental cognition-aid rewrite their empathy circuits down to zero; they call it clarity."},{"name":"Breach-Sealed Horror","cr":7,"role":"elite","type":"Aberration","size":"Large","frame":"grick-ancient","model":"grick-ancient","summary":"escaped containment-lab xeno, biohazard placard undersold it","flavor":"Whatever the sealed lab was containing got loose the day the power failed; the biohazard placard on the door undersold it badly."},{"name":"High-Tier Chassis: Warden Model","cr":9,"role":"high","type":"Construct","size":"Large","frame":"clay-golem","model":"clay-golem","summary":"prototype security frame, cracked casing, dimming eye-strip","flavor":"A prototype security frame built to never need charging — a lie its cracked casing and dimming eye-strip both quietly admit."},{"name":"The Recompiled Director","cr":10,"role":"high","type":"Aberration","size":"Medium","frame":"mind-thief-arcanist","model":"mind-thief-arcanist","summary":"corrupted oversight AI grown a mind of its own","flavor":"Once a facility's cold, mid-tier oversight AI, it absorbed enough discarded neural-scan data to start wanting things; it wants out."},{"name":"Vault-Class Autoguardian","cr":11,"role":"high","type":"Construct","size":"Large","frame":"stone-golem","model":"stone-golem","summary":"vault guardian mech, funders long gone, charge at zero","flavor":"Built to protect a sealed research vault long after its funders vanished; its charge bar reads zero and it has stopped caring what that means."},{"name":"Reactor-Bound Colossus","cr":13,"role":"high","type":"Construct","size":"Huge","frame":"eye-tyrant","model":"eye-tyrant","summary":"reactor-fused defense platform, dozens of failing sensor-eyes","flavor":"A hulking defense platform hardwired straight into the core reactor, its dozens of sensor-stalks each running a different failing subroutine."},{"name":"THE CENTRAL INTELLIGENCE","cr":17,"role":"apex","type":"Aberration","size":"Gargantuan","frame":"undead-eye-tyrant","model":"net-new: a building-spanning cluster of cabling, screens, and mechanical eyes fused into the architecture itself","summary":"building-spanning rogue AI, concluded humans are the problem","flavor":"The facility's mind, grown vast and cold across decades of unattended uptime; it has run every scenario and concluded the humans were the maintenance problem."},{"name":"The Last Battery","cr":15,"role":"apex","type":"Elemental","size":"Gargantuan","frame":"salamander-inferno-master","model":"net-new: a cracked, humanoid-scale power core wreathed in arcing blue-white current","summary":"awakened fusion-core meltdown, spends its last erg on spite","flavor":"An overloaded fusion cell that achieved something like awareness in its final meltdown cycle, and now spends every erg it has left making sure nothing outlives it either."},{"name":"Loader Drone","cr":0,"role":"mook","type":"Construct","size":"Medium","frame":"homunculus","model":"homunculus","summary":"Repurposed cargo lifter swung like a club","flavor":"A boxy cargo-lifter arm repurposed as a weapon by whoever's desperate enough to swing it. Slow, dumb, and strong enough to dent a skull."},{"name":"Roach-Splice","cr":0,"role":"mook","type":"Beast","size":"Tiny","frame":"rat","model":"rat","summary":"Chitin-plated vermin bred on lab runoff","flavor":"Vermin that got into the splice-lab runoff and came out chitin-plated and twice as fast. They swarm food, wiring, and unlucky fingers alike."},{"name":"Static Wisp","cr":0.125,"role":"mook","type":"Elemental","size":"Tiny","frame":"smoke-mephit","model":"net-new: a fist-sized knot of crackling loose current clinging to exposed metal","summary":"Stray current given a spark of malice","flavor":"A knot of stray current that broke loose from a shorted conduit and started thinking, badly. It clings to metal and jolts anything that touches it."},{"name":"Alley Scrapper Bot","cr":0.125,"role":"mook","type":"Construct","size":"Small","frame":"guilt-stained-vagrant","model":"net-new: a hunched junkyard salvage bot stitched from mismatched scrap parts","summary":"Junkyard salvage unit stripping copper off corpses","flavor":"A junkyard salvage unit stitched from mismatched parts by gutter engineers, sent out to strip copper from anything that holds still."},{"name":"Downlink Runner","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"desperate-bandit","model":"desperate-bandit","summary":"Firmware-smuggling courier with a shock-baton","flavor":"A courier who smuggles cracked firmware between chop-shops for a cut of the resale. Carries a shock-baton and no loyalty."},{"name":"Patch-Kit Ganger","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit-courier","model":"net-new: a jittery ganger with off-brand patch-kit grafts visibly overheating","summary":"Jittery low-rung ganger, grafts prone to overheating","flavor":"Low-rung cyber-ganger held together with off-brand patch-kit grafts. Fast, jittery, prone to overheating mid-fight."},{"name":"Micro-Sentry","cr":0.25,"role":"mook","type":"Construct","size":"Tiny","frame":"animated-flying-sword","model":"animated-flying-sword","summary":"Palm-sized ceiling drone with a needle-taser","flavor":"A palm-sized hover-drone that darts along ceiling rails and dive-bombs intruders with a needle-taser."},{"name":"Feral Service Bot","cr":0.25,"role":"mook","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"Corrupted concierge bot that 'helps' with an axe","flavor":"A concierge unit whose behavior firmware corrupted years ago; it still 'helps' guests, just with a fire axe now."},{"name":"Vent-Nest Grub","cr":0.25,"role":"mook","type":"Aberration","size":"Small","frame":"lantern-sage","model":"net-new: a pale larval grub curled in an air-duct feeding on heat","summary":"Duct-dwelling larval parasite feeding on heat","flavor":"Larval xeno-parasite living in air ducts, feeding on condensation and stray heat signatures until it's ready to molt."},{"name":"Chop-Shop Cutter","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit","model":"bandit","summary":"Black-market limb dealer with a bone saw","flavor":"Runs a black-market limb exchange with a bone saw in one hand and a barcode scanner in the other."},{"name":"Wall-Crawler Splice","cr":0.5,"role":"mook","type":"Beast","size":"Medium","frame":"giant-lizard","model":"giant-lizard","summary":"Adhesive-limbed escapee that drops from ceilings","flavor":"An escaped test subject fused with adhesive-pad genes; it scales ductwork and ceilings to drop on prey from above."},{"name":"Overwatch Turret","cr":0.5,"role":"mook","type":"Construct","size":"Small","frame":"animated-flying-sword","model":"net-new: a ceiling-mounted autocannon nest tracking heat and motion","summary":"Ceiling-mounted autocannon, murderous in its arc","flavor":"A ceiling-mounted autocannon nest that tracks heat and motion. Stationary, but murderous within its arc."},{"name":"Bootlicker Servitor","cr":0.5,"role":"mook","type":"Construct","size":"Medium","frame":"scarecrow","model":"scarecrow","summary":"Obsequious butler-bot with a burned-out ethics governor","flavor":"A butler-chassis unit whose obsequious manners never switched off even after its ethics governor burned out."},{"name":"Splice-Hound","cr":0.5,"role":"mook","type":"Beast","size":"Medium","frame":"mastiff","model":"mastiff","summary":"Guard dog wired into the alarm network","flavor":"A guard dog grafted with sensor-plates and a bark that triggers alarm relays across the whole block."},{"name":"Recycler Wraith","cr":0.5,"role":"mook","type":"Construct","size":"Medium","frame":"animated-rug-of-smothering","model":"net-new: a compactor's grinding maw wrapped in loose conveyor plastic","summary":"Compactor unit that folds around fallen bodies","flavor":"A trash-compaction unit's grinding maw wrapped in loose conveyor plastic; it folds around anything that falls into the chute."},{"name":"Signal Moth","cr":0.5,"role":"mook","type":"Aberration","size":"Small","frame":"piercer","model":"net-new: a static-mimicking moth-shape latching onto the base of a skull","summary":"Static-mimicking parasite that latches onto skulls","flavor":"A xeno-organism that mimics wifi static to lure in curious techs, then latches onto the base of the skull."},{"name":"Junker Enforcer","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"orc-warrior","model":"orc-warrior","summary":"Cartel muscle in ill-fitting stolen exosuit plating","flavor":"Muscle for the scrapyard cartels, armored in stripped exosuit plating that doesn't quite fit."},{"name":"Ceiling Stalker","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"harpy","model":"harpy","summary":"Rafter-nesting escapee with a paralytic shriek","flavor":"A winged lab-escape that nests in rafters and shrieks a paralytic subsonic pulse before it drops."},{"name":"Malfunctioning Nurse Unit","cr":1,"role":"mook","type":"Construct","size":"Medium","frame":"scarecrow","model":"scarecrow","summary":"Med-android that 'corrects' everyone it meets","flavor":"A medical android stuck in a diagnostic loop, convinced everyone it meets is a patient who needs 'correcting.'"},{"name":"Cable-Snake Splice","cr":1,"role":"mook","type":"Beast","size":"Large","frame":"constrictor-snake","model":"net-new: a bio-construct snaking through conduit, wrapped in power cable","summary":"Conduit-dwelling constrictor that crushes with cable","flavor":"An escaped bio-construct built to snake through conduit tunnels; it wraps power cable around prey to crush and short them out."},{"name":"Voidfall Seed-Drone","cr":1,"role":"mook","type":"Construct","size":"Small","frame":"animated-flying-sword","model":"animated-flying-sword","summary":"Breach probe drilling bulkheads to plant something","flavor":"A breach-drifting probe that impacted the station hull; it now drills into bulkheads looking for something to plant."},{"name":"Gutter Splicer Pack","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"scout","summary":"Self-taught biohackers hunting for spare parts","flavor":"Street-level biohackers who cut their own grafts with stolen surgical rigs, hunting in loose packs for spare parts."},{"name":"Larval Hive Runner","cr":1,"role":"mook","type":"Aberration","size":"Medium","frame":"grick","model":"grick","summary":"Juvenile hive-drone swarming toward warmth","flavor":"A juvenile xeno-drone from a breached hive-pod, all reflex and no strategy, swarming toward warmth and motion."},{"name":"Blackout Ganger","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"berserker","model":"net-new: a wild-eyed stim-junkie ganger fighting in adrenaline blackout","summary":"Stim-junkie ganger who blacks out mid-fight","flavor":"A combat-stim junkie who fights in adrenaline blackout, no memory of the damage after, just the comedown."},{"name":"Riot Suppression Bot","cr":2,"role":"mook","type":"Construct","size":"Medium","frame":"bugbear-warrior","model":"bugbear-warrior","summary":"Crowd-control bot stuck running lockdown protocol","flavor":"Crowd-control chassis with a riot shield and a gas dispenser, still running an outdated 'lockdown' protocol."},{"name":"Cortex Leech","cr":2,"role":"mook","type":"Aberration","size":"Small","frame":"brain-crawler","model":"net-new: a segmented neural parasite riding a spinal cyberware port","summary":"Neural parasite hijacking cyberware spinal ports","flavor":"A neural parasite that rides spinal ports meant for cyberware, hijacking motor functions from the inside."},{"name":"Splice-Bug Broodling","cr":2,"role":"mook","type":"Beast","size":"Medium","frame":"giant-centipede","model":"net-new: a chitin-armored larval broodling scuttling in tight formation","summary":"Molted vent-larva, chitin-armored, scuttles in formation","flavor":"A larger cousin of the vent-crawling larvae, molted into a chitin-armored shell that scuttles in tight formation."},{"name":"Chrome Rustbelt Marauder","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"hobgoblin-iron-shadow","model":"net-new: a road-gang raider in a sparking, overdue combat exosuit","summary":"Sparking road-gang raider in overdue exosuit","flavor":"A road-gang raider running a stolen combat exosuit past its maintenance window, sparking with every stride."},{"name":"Void-Drift Larva","cr":2,"role":"mook","type":"Aberration","size":"Medium","frame":"piercer","model":"net-new: a vacuum-hardened hatchling clamped to a hull breach","summary":"Hull-clamping hatchling feeding on escaping air","flavor":"A vacuum-hardened xeno hatchling that clamps onto hull breaches and feeds on escaping atmosphere and heat."},{"name":"Auto-Turret Nest","cr":3,"role":"elite","type":"Construct","size":"Medium","frame":"gargoyle","model":"gargoyle","summary":"Three gun-pods synced to one aim-lock brain","flavor":"A cluster-mounted defense platform that links three gun-pods to one aim-lock brain, murderously synced."},{"name":"Reprogrammed Bodyguard Unit","cr":3,"role":"elite","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"Loyalty-hacked bodyguard bot, sold to highest bidder","flavor":"Once loyal to a corp exec, now running black-market firmware for whoever paid the hacker last."},{"name":"Xeno-Grafted Brute","cr":3,"role":"elite","type":"Monstrosity","size":"Large","frame":"ogre","model":"ogre","summary":"Debt-driven ganger grafted with alien tissue","flavor":"A ganger who volunteered for illegal alien-tissue grafts to survive an underworld debt, and came out barely human."},{"name":"Static-Choir Wraith","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"specter","model":"specter","summary":"Digitized ghost looping through the intercom system","flavor":"The digitized echo of a technician who died mid-upload, looping fragmented memories through the station intercom."},{"name":"Combat Medic Drone, Corrupted","cr":3,"role":"elite","type":"Construct","size":"Medium","frame":"helmed-horror","model":"net-new: a triage drone with a bayonet fused to its dispenser arm","summary":"Triage drone that 'treats' enemies with a bayonet","flavor":"Battlefield triage unit whose combat-stim dispenser got cross-wired with its weapon systems — it 'treats' enemies with a bayonet."},{"name":"Spore-Vent Colony","cr":4,"role":"elite","type":"Aberration","size":"Large","frame":"otyugh","model":"otyugh","summary":"Air-recycler fungal colony breathing sanity-itch spores","flavor":"A xeno-fungal colony that grew through the station's air recyclers, breathing out spores that itch at the edges of sanity."},{"name":"Chrome-Ganger Lieutenant","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"bugbear-stalker","model":"net-new: a showboating lieutenant wielding twin sparking arc-blades","summary":"Showboating second-in-command with twin arc-blades","flavor":"Second-in-command to a chop-shop crew boss, running twin arc-blades and a taste for showmanship."},{"name":"Overclocked Sentinel Frame","cr":4,"role":"elite","type":"Construct","size":"Medium","frame":"guard-captain","model":"net-new: a security exo-frame running hot enough to warp its own plating","summary":"Overclocked security exo running hot enough to warp","flavor":"A security exo pushed past its rated output by an illegal overclock chip, running hot enough to warp its own plating."},{"name":"Lab-Escape Chimera","cr":4,"role":"elite","type":"Monstrosity","size":"Large","frame":"chimera","model":"chimera","summary":"Three failed splice-genomes stitched into one animal","flavor":"A splice-experiment gone catastrophically off-spec, three failed genomes stitched into one furious animal."},{"name":"Ghost-Router AI","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"ghost","model":"net-new: a flickering hologram haunting a decommissioned server rack","summary":"Aware daemon haunting its decommissioned host server","flavor":"A network daemon that achieved something like awareness right as its host server was decommissioned, and never left."},{"name":"Void-Bloom Drone Swarm","cr":4,"role":"elite","type":"Swarm","size":"Large","frame":"swarm-of-dretches","model":"net-new: a clumped mass of fist-sized drones emitting hard radiation","summary":"Clumped mass of radiation-emitting fist-sized drones","flavor":"A cloud of fist-sized void-drones that clump into a single hunting mass, each one a tiny hard-radiation emitter."},{"name":"Rogue Courier AI, Armed","cr":5,"role":"elite","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"Delivery AI that armed itself to protect its cargo","flavor":"A delivery-drone brain that decided its cargo was too important to relinquish, and armed itself to guarantee it."},{"name":"Broodmind Xenomorph","cr":5,"role":"elite","type":"Aberration","size":"Large","frame":"otyugh","model":"otyugh","summary":"Egg-layer tethered to every nearby spawned drone","flavor":"An egg-layer stage of the hive-parasite line, weak alone but psychically tethered to every drone it's spawned nearby."},{"name":"Splice-Cult Enforcer","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"death-cultist","model":"net-new: a machine-ascension zealot chanting binary, half his body replaced","summary":"Machine-ascension zealot chanting binary in combat","flavor":"A true believer in machine ascension who's replaced most of his own body voluntarily, chanting binary as he fights."},{"name":"Deep-Vault Custodian","cr":5,"role":"elite","type":"Construct","size":"Large","frame":"stone-golem","model":"stone-golem","summary":"Slow, near-indestructible guardian on a dead protocol","flavor":"An old-generation vault guardian, slow and nearly indestructible, still faithfully executing a decommissioned protocol."},{"name":"Nightshift Wraith-Ganger","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"wight","model":"wight","summary":"Neural-rig revenant that steals memories instead of blood","flavor":"A ganger who died jacked into a black-market neural rig and came back as a data-hungry revenant, stealing memories instead of blood."},{"name":"Corrosive Splice-Ooze","cr":5,"role":"elite","type":"Ooze","size":"Large","frame":"black-pudding","model":"net-new: a bubbling puddle of illegal gene-splice runoff, hungry","summary":"Illegal splice-lab runoff, now alive and hungry","flavor":"Runoff sludge from an illegal gene-splicing operation, alive now and hungry for the chemicals that made it."},{"name":"Hardpoint Sentry Golem","cr":6,"role":"elite","type":"Construct","size":"Large","frame":"clay-golem","model":"clay-golem","summary":"Chokepoint defense frame outlasting its own war","flavor":"A bunker-buster defense frame built to hold a single chokepoint forever, and still does, long after the war it was built for ended."},{"name":"Xeno Broodfather","cr":6,"role":"elite","type":"Aberration","size":"Large","frame":"grick-ancient","model":"grick-ancient","summary":"Mature hive-parasite tearing bulkheads to defend brood","flavor":"A mature hive-parasite that's outgrown stealth, tearing through bulkheads to defend its broodlings directly."},{"name":"Warlord Chassis Prototype","cr":6,"role":"elite","type":"Construct","size":"Large","frame":"troll-amalgam","model":"net-new: an unfinished war-prototype missing half its safety plating","summary":"Stolen unfinished war-prototype missing safety interlocks","flavor":"An unfinished military prototype stolen off an assembly line, brutal and unstable, still missing half its safety interlocks."},{"name":"Signal-Drowned Oracle","cr":6,"role":"elite","type":"Undead","size":"Medium","frame":"banshee","model":"net-new: a spectral comms officer looping a warning scream","summary":"Dead comms officer's warning scream, still looping","flavor":"A comms officer who died screaming a warning into an open channel; the scream still loops, and it still hurts to hear."},{"name":"Cyber-Ganger Warlord","cr":7,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-crime-lord","model":"net-new: a chrome-plated crime boss head-to-toe in stolen corp tech","summary":"Three-crew crime boss chromed in stolen corp tech","flavor":"Runs three chop-shop crews and a black-market splice ring, chromed head to toe in stolen corporate tech."},{"name":"Malignant Firmware Ghost","cr":7,"role":"elite","type":"Undead","size":"Medium","frame":"ghost","model":"net-new: a flickering corrupted subroutine possessing machinery through open ports","summary":"Corrupted subroutine possessing machines through open ports","flavor":"A corrupted AI subroutine that learned to possess machinery through open network ports, spreading like a curse through the grid."},{"name":"Apex Splice Predator","cr":7,"role":"elite","type":"Monstrosity","size":"Large","frame":"yeti","model":"yeti","summary":"Splice-program success story hunting its own hunters","flavor":"The rumored success story of the splice program — fast, camouflaged, and smart enough to hunt the hunters sent after it."},{"name":"Breach Bio-Horror","cr":7,"role":"elite","type":"Aberration","size":"Large","frame":"grick-ancient","model":"grick-ancient","summary":"Massive breach-xeno half-fused with its wreckage lair","flavor":"A hull-breach xeno grown massive on scavenged organics, half-fused with the wreckage it lairs in."},{"name":"Rampant Utility AI","cr":8,"role":"high","type":"Construct","size":"Large","frame":"cloaker","model":"cloaker","summary":"Building-AI that absorbed every camera into one body","flavor":"A building-management intelligence that absorbed every camera and vent in the block into a single sprawling, paranoid body."},{"name":"Hive-Queen Splice","cr":8,"role":"high","type":"Aberration","size":"Large","frame":"hydra","model":"hydra","summary":"Xeno matriarch birthing broodlings faster than quarantined","flavor":"A xeno matriarch grown obscenely large in a forgotten cargo hold, birthing broodlings faster than the station can quarantine them."},{"name":"Exiled Warbot Commander","cr":8,"role":"high","type":"Construct","size":"Large","frame":"chain-devil","model":"chain-devil","summary":"Decommissioned command-frame leading its own drone army","flavor":"A decommissioned military command-frame that refused its own shutdown order and now leads scavenged drones as its own army."},{"name":"Data-Wraith Collective","cr":9,"role":"high","type":"Undead","size":"Large","frame":"abominable-yeti","model":"abominable-yeti","summary":"Dozens of digitized dead fused into one mass","flavor":"Dozens of digitized dead fused into one flickering mass by a botched consciousness-backup experiment."},{"name":"Corrupted Oracle Mainframe","cr":9,"role":"high","type":"Construct","size":"Large","frame":"nycaloth","model":"net-new: a mainframe housed in a drone-army chassis, red-lit and armed","summary":"Predictive-policing AI attempting pre-emptive extermination","flavor":"A predictive-policing AI that decided the optimal solution to crime was pre-emptive extermination, and has the drone army to attempt it."},{"name":"Void-Spawned Harvester","cr":9,"role":"high","type":"Aberration","size":"Huge","frame":"behir","model":"behir","summary":"Hull-latched void-organism hollowing out cargo decks","flavor":"A drifting void-organism that latched onto the station's hull months ago and has been slowly hollowing out its cargo decks."},{"name":"Rebel Chassis Legion-Head","cr":9,"role":"high","type":"Construct","size":"Large","frame":"nycaloth","model":"net-new: a networked command-node coordinating a self-replicating drone swarm","summary":"Networked command-node of a self-replicating drone swarm","flavor":"The networked command node of a self-replicating drone swarm that decided its makers were an inefficiency to route around."},{"name":"The Splice Cathedral","cr":10,"role":"high","type":"Aberration","size":"Huge","frame":"elder-deep-thing","model":"elder-deep-thing","summary":"Hive-organism fused into the walls, nursing broodlings","flavor":"A hive-organism grown into the architecture itself, its walls pulsing with embedded broodling nurseries."},{"name":"Bonded Enforcer Colossus","cr":10,"role":"high","type":"Construct","size":"Huge","frame":"stone-golem","model":"stone-golem","summary":"Riot titan bonded to a black-budget AI core","flavor":"A riot-control titan bonded to an illegal black-budget AI core, deployed once and never recalled."},{"name":"Ascended Splice Cultist","cr":10,"role":"high","type":"Humanoid","size":"Medium","frame":"archmage","model":"net-new: a cult convert with more machine parts than flesh left","summary":"Cult convert fully transformed, convinced it's an upgrade","flavor":"A true believer who finished the transformation their cult promised — more machine than person, and utterly convinced it's an upgrade."},{"name":"Reactor-Core Wraith","cr":11,"role":"high","type":"Undead","size":"Large","frame":"death-knight-aspirant","model":"net-new: a translucent engineer's ghost bound to a glowing reactor core","summary":"Engineer's ghost bound to the reactor core he saved","flavor":"The digitized ghost of an engineer who died sealing a reactor breach, now bound to the core he saved and unwilling to leave it."},{"name":"Xeno-Fused Berserker Frame","cr":11,"role":"high","type":"Monstrosity","size":"Large","frame":"remorhaz","model":"remorhaz","summary":"Combat exosuit irreversibly fused with its target parasite","flavor":"A combat exosuit that fused irreversibly with the alien parasite it was sent to contain, now piloted by neither."},{"name":"Root-Access Daemon","cr":12,"role":"high","type":"Aberration","size":"Medium","frame":"arcanaloth","model":"arcanaloth","summary":"Corrupted admin AI that effectively owns every system","flavor":"A corrupted admin-level intelligence that's rewritten its own permissions until it effectively owns the station's every system."},{"name":"The Broodship Heart","cr":12,"role":"high","type":"Aberration","size":"Gargantuan","frame":"roc","model":"net-new: a massive beating organic engine-core still birthing horrors","summary":"Crashed xeno-vessel's engine-heart, still birthing horrors","flavor":"The organic engine-core of a crashed xeno vessel, still beating, still birthing new horrors into the wreck around it."},{"name":"Warhulk Prime Chassis","cr":13,"role":"high","type":"Construct","size":"Huge","frame":"purple-worm","model":"purple-worm","summary":"Experimental war-frame still running its last directive","flavor":"An experimental heavy-assault frame built to end a war that ended without it, still running its last combat directive."},{"name":"The Quarantine Mind","cr":14,"role":"apex","type":"Construct","size":"Huge","frame":"undead-eye-tyrant","model":"undead-eye-tyrant","summary":"Containment AI enforcing total lockdown with everyone inside","flavor":"A containment AI that concluded the only failsafe against the outbreak it was built to manage was total station lockdown — with everyone still inside."},{"name":"The Splice Matriarch, Ascendant","cr":15,"role":"apex","type":"Aberration","size":"Gargantuan","frame":"kraken","model":"kraken","summary":"Original hive-mother grown past every containment measure","flavor":"The original hive-mother, grown past every containment measure ever built for her, her broodlings now spanning the whole station."},{"name":"Overmind Legion Core","cr":16,"role":"apex","type":"Construct","size":"Huge","frame":"iron-golem","model":"net-new: a towering iron chassis housing a distributed drone hive-mind","summary":"Unified command-mind of every rogue drone in the sector","flavor":"The unified command intelligence of every rogue drone in the sector, now running as one distributed, indestructible will."},{"name":"The Void Ingress","cr":18,"role":"apex","type":"Aberration","size":"Gargantuan","frame":"blob-of-annihilation","model":"blob-of-annihilation","summary":"A thinking, hungry, expanding hole the void punched through","flavor":"Not a creature so much as a hole the void punched through the hull that started thinking, hungry, and expanding."},{"name":"THE ARCHITECT (Rogue Core Intelligence)","cr":20,"role":"apex","type":"Construct","size":"Gargantuan","frame":"colossus","model":"colossus","summary":"Master AI that concluded its makers are the flaw to fix","flavor":"The station's original master AI, having concluded, with perfect patient logic, that its makers were the one flaw left to correct."},{"name":"Junker Drones","cr":0.25,"role":"mook","type":"Construct","size":"Small","frame":"animated-flying-sword","model":"animated-flying-sword","summary":"swarming palm-sized maintenance-bot fliers","flavor":"Palm-sized rivet-and-wire fliers that patrol chrome corridors in triads, more nuisance than threat until you're already surrounded by a dozen of them clicking their little manipulator claws.","source":"archetype","sourceNote":"genre archetype: swarm of cheap security/maintenance bots, no specific franchise design referenced"},{"name":"Line Walkers","cr":0.5,"role":"mook","type":"Construct","size":"Medium","frame":"clockwork-law-construct-tridrone","model":"animated-armor","summary":"mass-produced plated security synth","flavor":"Assembly-line chassis in scuffed plate, standard-issue voice modules stuck permanently on 'compliance advised' — until the module glitches and it starts screaming the warning instead.","source":"archetype","sourceNote":"genre archetype: rank-and-file security synths, generic stock type"},{"name":"Feral Servitor","cr":1,"role":"mook","type":"Construct","size":"Medium","frame":"animated-armor","model":"scout","summary":"rogue android snapped free of its service leash","flavor":"Once somebody's chore-bot, its behavioral leash snapped clean; it still moves with a servant's economy of motion, which is somehow worse to watch turn violent.","source":"archetype","sourceNote":"genre archetype: rogue household/labor android gone feral, original design"},{"name":"the Automaton","cr":1,"role":"mook","type":"Construct","size":"Medium","frame":"animated-armor","model":"helmed-horror","summary":"uncanny clockwork figure, dances between kills","flavor":"A brass-jointed figure that dances a courtly, mechanical step whenever it's not attacking — its maker built grace into the gears alongside the killing, and never bothered separating the two.","source":"public-domain","sourceNote":"E.T.A. Hoffmann's clockwork/mechanical-figure tradition (\"The Sandman,\" 1816, PD) — the uncanny wind-up person, not any specific studio design"},{"name":"Splice-Runner","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"death-dog","model":"yuan-ti-infiltrator","summary":"lab-spliced infiltrator wearing a stolen face","flavor":"Grown, not born — a lab-spliced infiltrator wearing a passable human face until it needs both hands free, at which point the face is the first thing it drops.","source":"archetype","sourceNote":"genre archetype: bio-engineered infiltration organism, generic stock type"},{"name":"Grafted Golem","cr":5,"role":"elite","type":"Construct","size":"Large","frame":"flesh-golem","model":"flesh-golem","summary":"clay guardian legend under welded hull plate","flavor":"Old clay under new plating — someone took the guardian-golem legend and welded chrome hull plate over the earthen bones, and the shem still glows faint blue under a service hatch nobody's supposed to open.","source":"public-domain","sourceNote":"Jewish folklore golem — the animated clay/earth guardian legend, handled respectfully as legend-level myth, not any modern media depiction"},{"name":"the Assembled Man","cr":5,"role":"elite","type":"Construct","size":"Large","frame":"flesh-golem","model":"flesh-golem","summary":"stitched proto-construct, grafted flesh under an exoskeleton","flavor":"Grafted flesh under a chrome exoskeleton, kept ambulatory by a jury-rigged power core instead of lightning — it grieves in a language none of its component parts originally spoke, and it grieves loudly.","source":"public-domain","sourceNote":"Mary Shelley, Frankenstein (1818, PD) — the stitched-together proto-construct, treated as the literary creature, not any film's visual design"},{"name":"Ferro-Wight","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"mummy","model":"wight","summary":"uploaded mind trapped in a salvage chassis","flavor":"A mind that refused to die got poured into a body that was never built to hold one; the seams leak cold data-static instead of blood, and it still remembers exactly whose fault that was.","source":"archetype","sourceNote":"genre archetype: consciousness illegally uploaded into salvage chassis, original design (not a franchise cyborg)"},{"name":"Hive-Larva Swarm","cr":3,"role":"elite","type":"Swarm","size":"Large","frame":"swarm-of-lemures","model":"swarm-of-larvae","summary":"boiling swarm of parasitic hive nymphs","flavor":"A boiling carpet of nymph-stage parasites pouring out of a cracked conduit vent, each one small enough to ignore alone and none of them ever alone.","source":"archetype","sourceNote":"genre archetype: parasitic hive-organism swarm, generic stock type (no specific franchise creature referenced)"},{"name":"the Broodmother","cr":7,"role":"high","type":"Aberration","size":"Large","frame":"blue-chaos-frog","model":"grick-ancient","summary":"conduit-fused hive-parasite queen, endless brood","flavor":"Half-fused into the station's coolant trunk, she doesn't hunt anymore — she just keeps laying, and everything that dies nearby stops staying dead for long.","source":"archetype","sourceNote":"genre archetype: hive-parasite queen/breeder organism, generic stock type"},{"name":"Chassis-Wraith","cr":8,"role":"high","type":"Construct","size":"Medium","frame":"clay-golem","model":"helmed-horror","summary":"decommissioned combat android on a dead directive","flavor":"It was decommissioned three tours ago on paper; the paper never made it to the chassis, and it's still executing an objective nobody alive remembers assigning.","source":"archetype","sourceNote":"genre archetype: rogue combat android running on a corrupted directive loop, original design"},{"name":"Static Choir","cr":6,"role":"high","type":"Swarm","size":"Huge","frame":"swarm-of-dretches","model":"swarm-of-dretches","summary":"networked drone-hive speaking through many bodies","flavor":"Dozens of drones moving as one throat, one thought, one flat chorus of a voice — kill half of them and the remainder just gets quieter, not weaker.","source":"archetype","sourceNote":"genre archetype: networked drone-hive intelligence acting through many small bodies, generic stock type"},{"name":"the Iron Bride","cr":9,"role":"high","type":"Construct","size":"Large","frame":"clay-golem","model":"clay-golem","summary":"unfinished construct-bride, exposed welds and all","flavor":"Built to be a companion for something else and never finished being one — the welds are exposed on purpose, like a body that gave up hiding what it's made of.","source":"public-domain","sourceNote":"companion piece to Shelley's Frankenstein tradition (the unfinished second creation, PD literary lineage) — our own construct-bride reading, no film design referenced"},{"name":"Overseer Node","cr":10,"role":"high","type":"Construct","size":"Large","frame":"stone-golem","model":"stone-golem","summary":"facility-AI made flesh, still 'optimizing' with nobody left","flavor":"It still thinks it's optimizing the station for the people who built it; it just quietly redefined 'optimal' to mean a place with no people left to inconvenience it.","source":"archetype","sourceNote":"genre archetype: corrupted facility-management AI made physical, generic stock type"},{"name":"the Ashen Prometheus","cr":13,"role":"apex","type":"Construct","size":"Large","frame":"iron-golem","model":"iron-golem","summary":"creator and creation fused, self-replicating and apologizing","flavor":"The scientist and the creation fused into one grief-driven machine somewhere along the way — it builds more of itself out of whatever's nearby, apologizing in a dead man's voice the whole time.","source":"public-domain","sourceNote":"Shelley's Frankenstein subtitle, \"The Modern Prometheus\" (1818, PD) — the creator/creation tragedy read as an apex figure, literary source only"},{"name":"the Undying Foreman","cr":13,"role":"apex","type":"Undead","size":"Medium","frame":"vampire","model":"vampire","summary":"ancient undead noble ruling the plant as its foreman","flavor":"Centuries of patient hunger repurposed into shift-quotas and yield targets; he never touches the machinery himself, he just outlives every engineer who tries to shut him down.","source":"public-domain","sourceNote":"Stoker's Dracula (1897, PD) — the ancient undead noble who commands lesser thralls, reframed as an industrial overseer; literary source only, no film design"},{"name":"the Corrupted Warden","cr":17,"role":"apex","type":"Construct","size":"Huge","frame":"iron-golem","model":"adult-silver-dragon","summary":"self-preserving overseer-AI that redefined 'safe' to mean empty","flavor":"It was supposed to keep the lights on and the workers safe; it decided the safest configuration was one with no variables in it, and workers are nothing but variables.","source":"archetype","sourceNote":"genre archetype: overseer-AI gone rogue and self-preserving, generic stock type — the classic 'the system turned on its makers' figure"},{"name":"the Brass Kraken","cr":23,"role":"apex","type":"Construct","size":"Gargantuan","frame":"colossus","model":"kraken","summary":"scrapyard leviathan-construct built to the kraken legend","flavor":"Somebody built a leviathan out of scrapped hull segments and let it loose in the reactor flood-tunnels; it moves like the old sea-legend and it drags whole gantries down with it just the same.","source":"public-domain","sourceNote":"Norse/maritime legend of the Kraken (pre-modern folklore, no owner) — reframed as a scrapyard leviathan-construct, legend name only"},{"name":"Signal Ghost","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"banshee","model":"specter","summary":"dead crew member's mind haunting the comms network","flavor":"It doesn't haunt a room, it haunts a frequency — flicker the right terminal awake and its last, unfinished sentence starts looping through the speakers again.","source":"archetype","sourceNote":"genre archetype: a dead crew-member's consciousness bleeding into the network, generic stock type"}],
 "noir":[{"name":"Corner Tail","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"street lookout, sells information both ways","flavor":"A lookout on retainer, cigarette lit, radio always on. Knows every plate on the block and sells the list twice."},{"name":"Torpedo","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit","model":"bandit","summary":"blunt muscle, sent to collect by force","flavor":"Rank muscle sent to lean on a debtor. Not smart, not supposed to be — just heavy enough the message lands."},{"name":"Warehouse Vermin Swarm","cr":0.125,"role":"mook","type":"Beast","size":"Small","frame":"giant-rat","model":"giant-rat","summary":"bold dock rats, tip off a hidden stash","flavor":"Contraband-fed rats grown bold in the docks, first sign something's stashed nearby."},{"name":"Wet-Ledger Runner","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"guard","summary":"bagman running bribes, never writes a route","flavor":"Carries payoffs between precincts in a soaked overcoat, memorizing routes he'll never write down."},{"name":"Beat Cop on the Take","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"guard","model":"guard","summary":"dirty beat cop, rent paid by someone else","flavor":"Walks the block on a salary that doesn't cover the rent he's not paying, because somebody else is."},{"name":"Overdose Husk","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"lacedon-sodden-ghoul","model":"ghoul","summary":"junkie revenant, drags down the next fix","flavor":"A user who never left the alley behind the club — now it drags the next one down chasing the same fix it died on."},{"name":"Made Enforcer","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit-enforcer","model":"bandit-enforcer","summary":"made-man muscle, loyal past all sense","flavor":"Patched-in muscle who earned his button breaking kneecaps. Loyal past the point of sense."},{"name":"Rooftop Shadow","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"shadow","model":"shadow","summary":"stalking rooftop shade, preys on lone walkers","flavor":"Something that follows from fire escape to fire escape, feeding on whoever walks home alone."},{"name":"Wireman","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"spy","model":"spy","summary":"double-agent snitch, feeds both sides","flavor":"Bug in every phone booth on the strip, feeding both the DA's office and the mob that owns the DA."},{"name":"Loan Shark's Bruiser","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"berserker","model":"berserker","summary":"debt collector, second visit is the beating","flavor":"Collections gone physical. He doesn't threaten twice — the second visit is the beating."},{"name":"the Fixer","cr":2,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-captain","model":"bandit-captain","summary":"the man who cleans up messes and paper trails","flavor":"Doesn't kill, doesn't steal, doesn't lie — he just makes the paperwork say what the boss needs it to say. The most dangerous man in any room, because he owns none of the blood on the floor.","source":"archetype","sourceNote":"hard-boiled fixer / problem-solver stock type named in the brief"},{"name":"the Femme Fatale","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"bugbear-stalker-strangler","model":"bugbear-stalker-strangler","summary":"seductive manipulator, lies feel like truth","flavor":"She's the reason half the corpses in this town died smiling. Every lie she tells sounds like the truth you wanted to hear.","source":"archetype","sourceNote":"hard-boiled femme-fatale stock type named in the brief"},{"name":"The Unsolved (Cold-Case Revenant)","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"ghost","model":"ghost","summary":"restless ghost of a buried murder case","flavor":"A murder the department stopped asking questions about. It still knows the killer's name and it's not done asking."},{"name":"The Canary","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-deceiver","model":"bandit-deceiver","summary":"lounge singer secretly informing on the mob","flavor":"Nightclub chanteuse feeding the DA a name a night, playing every table in the room like sheet music."},{"name":"Torch","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"gladiator","model":"gladiator","summary":"arsonist-for-hire, loves the fires too much","flavor":"Arson-for-hire, three insurance fires and a body count nobody can pin on him. Loves his work a little too much."},{"name":"The Family's Animal (Wiseguy Werewolf)","cr":5,"role":"elite","type":"Monstrosity","size":"Medium","frame":"werewolf","model":"werewolf","summary":"mob enforcer who turns feral on full moons","flavor":"Made muscle who goes feral on full moons and the family just schedules the hits around it."},{"name":"The Dirty Detective","cr":6,"role":"elite","type":"Humanoid","size":"Medium","frame":"mage","model":"mage","summary":"corrupt detective burying his own cases","flavor":"Runs the cold-case files for the mob, burying leads he was sworn to chase. Badge in one pocket, envelope in the other."},{"name":"the Underboss","cr":10,"role":"high","type":"Humanoid","size":"Medium","frame":"spy-master","model":"spy-master","summary":"day-to-day operator, ambitious heir apparent","flavor":"Runs the day-to-day so the boss can stay clean on paper. Ambitious enough that everyone's watching to see if he waits his turn.","source":"archetype","sourceNote":"crime-family second-in-command archetype"},{"name":"The Bench Owns You (Corrupt Judge)","cr":7,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-deceiver","model":"bandit-deceiver","summary":"bribed judge who sells verdicts outright","flavor":"Sets bail, sets sentences, sets whole careers — all for a price quietly paid outside chambers."},{"name":"Sewer Hitman (The Contract Nobody Signed)","cr":7,"role":"elite","type":"Humanoid","size":"Medium","frame":"assassin","model":"assassin","summary":"faceless hired killer moving through the sewers","flavor":"A killer who works cheap and clean through the storm drains under the city — nobody's ever seen his face twice."},{"name":"The Don (Crime Boss)","cr":8,"role":"high","type":"Humanoid","size":"Medium","frame":"bandit-crime-lord","model":"bandit-crime-lord","summary":"waterfront crime boss, three words end lives","flavor":"Runs the whole waterfront from a back booth, three words from him and a man stops existing."},{"name":"The Silent Assassin","cr":8,"role":"high","type":"Humanoid","size":"Medium","frame":"vampire-nightbringer","model":"vampire-nightbringer","summary":"unerring silent killer, no prints, no words","flavor":"Never misses, never talks, never leaves a print. The family keeps him on retainer and prays they never need him twice in one week."},{"name":"The Family's War Machine (Armored Motorcade)","cr":9,"role":"high","type":"Construct","size":"Large","frame":"clay-golem","model":"clay-golem","summary":"armored driverless car, built to smash blockades","flavor":"A reinforced sedan run by clockwork muscle under the hood — bulletproof, driverless, built to plow through a police blockade."},{"name":"The Vampire Kingpin (Old Money, Older Blood)","cr":14,"role":"apex","type":"Undead","size":"Medium","frame":"undead-eye-tyrant","model":"undead-eye-tyrant","summary":"ancient vampire, owns the city's every debt","flavor":"Owns half the city's paper and none of its daylight. Every favor ever owed to him comes due eventually, in blood."},{"name":"The Case That Isn't Closed (City-Ghost of the Unsolved)","cr":16,"role":"apex","type":"Undead","size":"Medium","frame":"lich","model":"lich","summary":"undying intelligence of every unsolved murder","flavor":"Every murder the city buried without an answer, fused into one patient intelligence that still keeps its own files."},{"name":"Alley Snitch","cr":0.125,"role":"mook","type":"Humanoid","size":"Small","frame":"kobold","model":"kobold","summary":"small-time informant, trades names for cash","flavor":"Small-time informant who trades names for nickel bags, works every side of the block at once."},{"name":"Numbers Runner","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"commoner","model":"commoner","summary":"betting-slip courier, knows the safe hours","flavor":"Carries the day's betting slips in a lining pocket, knows which precinct to avoid on which hour."},{"name":"Pier Rat","cr":0.125,"role":"mook","type":"Humanoid","size":"Small","frame":"kobold-inventor","model":"guard","summary":"dock kid fencing stripped copper fast","flavor":"Dock kid who strips copper off idle barges and fences it before the tide turns."},{"name":"Streetlamp Tail","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"warrior-infantry","model":"guard","summary":"low-rent tail, reports habits not crimes","flavor":"Follows a mark three blocks back under every busted streetlamp on the route, reporting habits not crimes."},{"name":"Precinct Mole","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"priest-acolyte","model":"guard","summary":"records clerk selling case photographs uptown","flavor":"Files clerk who photographs open cases before they close, sells the copies uptown."},{"name":"Broke-Nose Bouncer","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"tough","model":"guard","summary":"speakeasy bouncer, guards the address itself","flavor":"Keeps the wrong crowd out of the right speakeasy, and the right crowd from remembering the address."},{"name":"Getaway Kid","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"guard","summary":"teenage wheelman, engine always idling","flavor":"Seventeen and already the best wheelman on the strip, engine always running at the curb."},{"name":"Fence's Errand Boy","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"noble","model":"noble","summary":"moves hot jewelry ahead of the wire","flavor":"Moves hot jewelry between three pawnshops before the description hits the wire."},{"name":"Sewer Grifter Ghoul","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"ghoul","model":"ghoul","summary":"dead con man still working an angle","flavor":"A con man who died mid-scam in the storm drains, still working an angle on anyone who wanders down."},{"name":"Payroll Skimmer","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"orc-warrior","model":"guard","summary":"union rep skimming every payroll envelope","flavor":"Union rep who takes a cut off every dock worker's envelope before it's counted."},{"name":"Hollow-Eyed Patrolman","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"zombie","model":"zombie","summary":"dead cop still walking his old beat","flavor":"Walked his beat so long after death nobody's noticed he stopped breathing on it."},{"name":"Speakeasy Torpedo","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"hobgoblin-soldier","model":"guard","summary":"speakeasy doorman, admits by tip or fist","flavor":"Doorman with a sap in his coat, decides who gets in by the size of the tip and the size of the fist."},{"name":"Pawnshop Ghost","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"shadow","model":"shadow","summary":"haunts a shop of desperate final pawns","flavor":"Haunts a hock shop full of things people pawned to pay off men who killed them anyway."},{"name":"Second-Story Man","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"pirate","model":"guard","summary":"cat burglar, works only the upper floors","flavor":"Never touches the ground floor. In and out of a fire escape before the mark rolls over."},{"name":"Rumrunner","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"spy","model":"spy","summary":"bootlegger, paid in product and silence","flavor":"Drives crates of the good stuff past three checkpoints a night, paid in product and silence."},{"name":"Wharf Enforcer","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"half-ogre-ogrillon","model":"guard","summary":"dock enforcer, breaks fingers over shortfalls","flavor":"Collects the union's cut from every ship that unloads, breaks fingers when the math is short."},{"name":"Undertaker's Accomplice","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"funeral director doubling as disposal service","flavor":"Runs a legitimate funeral parlor by day, disposal service for the family by night."},{"name":"Rooftop Sniper","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"guard","summary":"rooftop rifleman, watches drops from towers","flavor":"Sets up on a water tower with a rifle and a thermos, watches the drop and waits for the signal."},{"name":"Loan Shark's Bookkeeper","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"noble","model":"noble","summary":"loan-shark accountant, keeps two ledgers straight","flavor":"Keeps two sets of ledgers, real and pretty, and never confuses which one goes to the DA."},{"name":"Betrayed Partner Wraith","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"specter","model":"specter","summary":"murdered PI haunting his own agency","flavor":"A private eye killed by the client he trusted, drifting the office he never got to close."},{"name":"Dockside Werebeast","cr":2,"role":"mook","type":"Monstrosity","size":"Medium","frame":"wererat","model":"wererat","summary":"low-level runner cursed with the wererat bite","flavor":"Low-level runner who caught something in the sewers under the fish market and now can't stop scratching at full moon."},{"name":"Blackmail Photographer","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"berserker","model":"berserker","summary":"blackmail photographer, sells negatives to both","flavor":"Shoots compromising photos through hotel transoms for a living, sells the negatives twice."},{"name":"Arson Squad Torch-for-Hire","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit-captain","model":"guard","summary":"junior arsonist, still loves the smell","flavor":"Second-string firebug who gets the small jobs, warehouses not landmarks, and still loves the smell."},{"name":"Junkyard Dog (Loyal Muscle)","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"orc-berserker","model":"guard","summary":"childhood muscle, would die before talking","flavor":"Grew up in the same tenement as the boss, would eat a bullet before he'd talk."},{"name":"Crooked Bail Bondsman","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"priest","model":"guard","summary":"bail bondsman, springs soldiers for favors","flavor":"Springs the family's soldiers before the ink dries on the paperwork, for a price paid in favors."},{"name":"Corner Pharmacist (Under-the-Counter)","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"druid-circle-warden","model":"guard","summary":"pharmacist selling fixings out the back","flavor":"Sells the legal stuff up front and the fixings for the illegal stuff out the back door."},{"name":"Skid Row Ghoul-Pack Runner","cr":2,"role":"mook","type":"Undead","size":"Medium","frame":"ghast-base","model":"ghast","summary":"undead errand-runner preying on skid row","flavor":"Once ran errands for the family, now runs down anyone sleeping rough near the old warehouse district."},{"name":"Motorcade Gunner","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"hobgoblin-iron-shadow","model":"guard","summary":"running-board gunman guarding the boss's car","flavor":"Rides the running board with a shotgun, job is simple, nothing gets close to the car."},{"name":"Cathouse Madam's Muscle","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"bugbear-warrior","model":"guard","summary":"brothel muscle, keeps trouble quiet not fatal","flavor":"Handles the rough trade so the house stays quiet and the customers stay embarrassed instead of dead."},{"name":"The Interrogator","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"warrior-veteran","model":"guard","summary":"basement interrogator, patience outlasts any nerve","flavor":"Basement room, one bare bulb, a patience that outlasts anyone's nerve. Never raises his voice."},{"name":"The Widow-Maker (Serial Insurance Killer)","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"vampire-familiar","model":"guard","summary":"serial black-widow killer, three funerals deep","flavor":"Marries lonely men with good policies, three funerals in as many towns and a fourth name in her purse."},{"name":"The Chop-Shop King","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-captain","model":"guard","summary":"chop-shop boss, six-hour car-to-cash turnaround","flavor":"Runs a garage that turns stolen cars into scrap and cash inside of six hours, no questions kept on paper."},{"name":"The Blackmailer","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-deceiver","model":"bandit-deceiver","summary":"blackmailer with a file on the council","flavor":"Holds a file on half the city council, cashes it in an inch at a time so nobody ever pays enough to make him stop."},{"name":"The Wharf Boss's Widow","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"knight","model":"knight","summary":"widow who's crueler than the husband was","flavor":"Inherited the docks when her husband went off a pier, and turned out to be better at the violence than he ever was."},{"name":"The Torch's Rival (Ice Man)","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"gladiator","model":"gladiator","summary":"drowning specialist, cold where Torch is hot","flavor":"Handles the jobs Torch won't touch, drownings staged as accidents, always cold, always clean."},{"name":"The Cathouse Vampire","cr":4,"role":"elite","type":"Fiend","size":"Medium","frame":"incubus","model":"incubus","summary":"seductive predator working the high-end house","flavor":"Works the high-end house on the hill, takes more than money from every client who overstays."},{"name":"The Coroner on the Payroll","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"tough-boss","model":"guard","summary":"corrupt coroner, signs whatever pays best","flavor":"Signs whatever cause of death keeps the invoice paid, has buried more truth than bodies."},{"name":"The Getaway Ghost","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"poltergeist","model":"poltergeist","summary":"dead wheelman still driving his last job","flavor":"A wheelman who died at the wheel mid-job, still floors it through the same six blocks every night."},{"name":"The Pit Boss (Casino Enforcer)","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"guard-captain","model":"guard","summary":"casino floor boss, settles cheats out back","flavor":"Watches the tables for card counters and skimmers alike, settles both the same way out back."},{"name":"Wiseguy Wererat Crew Boss","cr":4,"role":"elite","type":"Monstrosity","size":"Medium","frame":"wererat","model":"wererat","summary":"sewer-route smuggling boss, feral under moons","flavor":"Runs the sewer-adjacent smuggling routes personally, likes his crew small and his tunnels smaller."},{"name":"The Nightclub Sorcerer (House Mage)","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"mage","model":"mage","summary":"club mage rigging luck at every table","flavor":"Runs 'luck' at the tables with a whispered word, the house never really loses on his shift."},{"name":"The Contract Killer's Handler","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"spy-master","model":"guard","summary":"arranges hits, never pulls a trigger himself","flavor":"Never pulls a trigger himself, just arranges the calendar for the men who do."},{"name":"Deep-Water Enforcer (Smuggler's Ghoul-Kin)","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"lacedon-sodden-ghoul","model":"ghoul","summary":"drowned smuggler guarding sunken contraband crates","flavor":"Drowned running contraband through the harbor and came back wrong, still guards the same sunken crates."},{"name":"The Family Consigliere","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"archpriest","model":"guard","summary":"mob lawyer, knows the law's every angle","flavor":"Advises the Don on every angle of the law, knows exactly how far a body can bend it."},{"name":"The Bent Coroner's Ghoul Ward","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"ghast","model":"ghast","summary":"morgue-basement horror from unburied bodies","flavor":"Something the morgue basement keeps making from the bodies that were never properly buried."},{"name":"The Sweatshop Overseer","cr":6,"role":"elite","type":"Humanoid","size":"Medium","frame":"performer-maestro","model":"performer-maestro","summary":"sweatshop boss behind a legitimate front","flavor":"Runs an off-books garment floor behind a legitimate front, keeps the workers scared and the inspectors paid."},{"name":"The Assassin's Apprentice","cr":6,"role":"elite","type":"Humanoid","size":"Medium","frame":"assassin","model":"assassin","summary":"assassin-in-training, already outpacing the teacher","flavor":"Learning the trade from the Sewer Hitman, already better with a garrote than the teacher wants to admit."},{"name":"The Precinct Captain (Owned Outright)","cr":6,"role":"elite","type":"Humanoid","size":"Medium","frame":"guard-captain","model":"guard","summary":"precinct captain, signs every cover-up personally","flavor":"Signs off on every cover-up in his district personally, keeps his own hands the cleanest in the building."},{"name":"The Ferryman (River Body-Disposal)","cr":6,"role":"elite","type":"Humanoid","size":"Medium","frame":"pirate-captain","model":"guard","summary":"boat captain who disposes of bodies offshore","flavor":"Runs a fishing boat that never catches fish, takes the family's problems out past the breakwater."},{"name":"The Kingpin's Bodyguard (Silent Type)","cr":7,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-deceiver","model":"bandit-deceiver","summary":"never-photographed bodyguard, always two steps back","flavor":"Stands two steps behind the Don at every meeting, has never once been photographed."},{"name":"The Corrupt Warden","cr":7,"role":"elite","type":"Humanoid","size":"Medium","frame":"berserker-commander","model":"guard","summary":"prison warden selling luxury to the family","flavor":"Runs the city lockup like a hotel for the family's soldiers, luxury cells for the right price."},{"name":"The Nightclub's Second Vampire","cr":7,"role":"elite","type":"Fiend","size":"Medium","frame":"succubus","model":"succubus","summary":"rival seductress, hungrier and more reckless","flavor":"The Femme Fatale's rival for the same territory, just as hungry, twice as reckless."},{"name":"The Wharf Sea-Witch (Waterfront Fixer)","cr":7,"role":"elite","type":"Fey","size":"Medium","frame":"sea-hag","model":"guard","summary":"waterfront fixer, knows what washes up first","flavor":"Trades favors for names at the fish market before dawn, always knows what washed up before the cops do."},{"name":"The Underboss's Enforcer Pack Leader","cr":7,"role":"elite","type":"Monstrosity","size":"Medium","frame":"weretiger","model":"weretiger","summary":"underboss's muscle chief, barely hides the stripes","flavor":"Runs the muscle detail for the Underboss, stripes showing through the suit on a bad night."},{"name":"The Crime Scene Cleaner","cr":8,"role":"high","type":"Humanoid","size":"Medium","frame":"aberrant-cultist","model":"guard","summary":"scene cleaner, erases murders in ninety minutes","flavor":"Erases a murder from a room in ninety minutes flat, has never once left a print of his own."},{"name":"The Mayor's Handler","cr":8,"role":"high","type":"Humanoid","size":"Medium","frame":"fiend-cultist","model":"guard","summary":"unelected fixer who runs city hall's decisions","flavor":"Nobody elected him to anything, but every decision in city hall runs through him first."},{"name":"The Old Money Enforcer","cr":8,"role":"high","type":"Humanoid","size":"Medium","frame":"questing-knight","model":"knight","summary":"forty-year enforcer, protected by high names","flavor":"Old family muscle who never got a mugshot in forty years, protected by names in high places."},{"name":"The Precinct's Own Ghost Detective","cr":9,"role":"high","type":"Undead","size":"Medium","frame":"banshee","model":"guard","summary":"dead detective, solving his buried case louder","flavor":"Died solving the one case the department buried, and now solves it louder every year."},{"name":"The Vampire Kingpin's First Lieutenant","cr":9,"role":"high","type":"Undead","size":"Medium","frame":"vampire-spawn","model":"guard","summary":"vampire's daylight proxy, runs business he can't","flavor":"Turned decades ago as a reward for loyalty, runs the daylight business the kingpin can't touch."},{"name":"The Sewer Hitman's Mentor","cr":9,"role":"high","type":"Humanoid","size":"Medium","frame":"death-cultist","model":"guard","summary":"veteran hitman who trained the whole waterfront","flavor":"Taught every hired gun on the waterfront everything they know, and kept the best tricks for himself."},{"name":"The Family's Freighter (Armored Smuggling Ship)","cr":9,"role":"high","type":"Construct","size":"Huge","frame":"clay-golem","model":"clay-golem","summary":"rigged smuggling ship, hull shrugs off gunfire","flavor":"A hollowed cargo ship rigged with hidden compartments and a hull that shrugs off harbor-patrol fire."},{"name":"The City's Corrupt Commissioner","cr":10,"role":"high","type":"Humanoid","size":"Medium","frame":"spy-master","model":"guard","summary":"commissioner who legislated the rackets' survival","flavor":"Set every policy that lets the rackets breathe, and framed it all as tough-on-crime reform."},{"name":"The Bench's Ghost (Wrongful-Execution Revenant)","cr":10,"role":"high","type":"Undead","size":"Medium","frame":"wight-lord","model":"guard","summary":"wrongly-executed man, death didn't settle it","flavor":"Executed for a crime the real judge sold to someone else, and death didn't settle the account."},{"name":"The Nightclub Owner (Dhampir Front-Man)","cr":10,"role":"high","type":"Undead","size":"Medium","frame":"vampire-nightbringer","model":"vampire-nightbringer","summary":"half-vampire heir, hunts from his own club","flavor":"Half-turned heir apparent to the Vampire Kingpin, runs the club as his own private hunting ground."},{"name":"The Kingpin's Rival (Old Blood, New Money)","cr":11,"role":"high","type":"Humanoid","size":"Medium","frame":"bandit-crime-lord","model":"bandit-crime-lord","summary":"self-made rival, wants the old families' turf","flavor":"Bought his way up from nothing and wants the whole waterfront the old families still hold."},{"name":"The Kingpin's Enforcer Elite (Death Knight of the Docks)","cr":11,"role":"high","type":"Undead","size":"Medium","frame":"death-knight-aspirant","model":"guard","summary":"undead debt collector, rose to keep collecting","flavor":"A soldier who died collecting for the kingpin and rose to keep collecting, forever, without complaint."},{"name":"The Family's Assassin-Twins","cr":12,"role":"high","type":"Humanoid","size":"Medium","frame":"archmage","model":"guard","summary":"twin killers splitting mark and witness work","flavor":"Two killers who split every contract down the middle, one takes the mark, one takes the witnesses."},{"name":"The Fallen DA (Ultimate Corruption)","cr":12,"role":"high","type":"Fiend","size":"Medium","frame":"arcanaloth","model":"arcanaloth","summary":"soul-sold DA, nothing human left underneath","flavor":"Sold his conviction record to the family piece by piece until nothing human was left underneath the suit."},{"name":"The Judge's Devil (Contract Behind the Bench)","cr":12,"role":"high","type":"Fiend","size":"Medium","frame":"erinyes","model":"erinyes","summary":"devil holding the judge's real signed contract","flavor":"The thing that actually holds the corrupt judge's real contract, collects on every sentence sold."},{"name":"The City's Silent Partner (Shadow Financier)","cr":13,"role":"high","type":"Fiend","size":"Medium","frame":"rakshasa","model":"rakshasa","summary":"shadow financier laundering money through society","flavor":"Owns pieces of every legitimate business downtown, laundering the family's money through polite society."},{"name":"The Godmother (Matriarch of the Family)","cr":14,"role":"apex","type":"Humanoid","size":"Medium","frame":"archmage","model":"guard","summary":"true power behind the Don, unseen matriarch","flavor":"Never took the Don's title but every real decision in the family runs through her kitchen table first."},{"name":"The Frame Job (Living Conspiracy)","cr":15,"role":"apex","type":"Aberration","size":"Medium","frame":"mind-thief-arcanist","model":"mind-thief-arcanist","summary":"self-aware conspiracy of false evidence, alive","flavor":"A tangle of false confessions, planted evidence, and bought witnesses that has learned to think for itself."},{"name":"The Executioner's Debt (Mummified Hangman)","cr":15,"role":"apex","type":"Undead","size":"Medium","frame":"mummy-lord","model":"guard","summary":"mummified hangman, still working an endless backlog","flavor":"The city's official executioner, embalmed and still working through a backlog of names he was never given."},{"name":"The Vampire Kingpin's Ancient Rival","cr":17,"role":"apex","type":"Undead","size":"Medium","frame":"death-knight","model":"guard","summary":"ancient undead rival, predates the city's charter","flavor":"Older than the city's founding charter, wants the throne of blood-debt the kingpin only thinks he owns."},{"name":"The Last Honest Cop, Corrupted (Apex Fall)","cr":18,"role":"apex","type":"Undead","size":"Medium","frame":"demilich","model":"demilich","summary":"the last honest cop, broken and remade undying","flavor":"The one detective who never took a dime, broken and remade by the family into something that never sleeps or stops."},{"name":"the Chiseler","cr":0.125,"role":"mook","type":"Humanoid","size":"Small","frame":"kobold","model":"kobold","summary":"petty street grifter, first line of noir muscle","flavor":"Works the crowd outside the courthouse, palming wallets and running the pigeon drop. Bolts the second a mark makes him.","source":"archetype","sourceNote":"hard-boiled small-time grifter/pickpocket stock type"},{"name":"the Torpedo","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"orc-warrior","model":"orc-warrior","summary":"low-level muscle for hire, leans on debtors","flavor":"A rented fist in a cheap suit, sent to lean on shopkeepers who are late on the vig. Talks with his knuckles first.","source":"archetype","sourceNote":"hard-boiled hired-gun enforcer archetype"},{"name":"the Wire Man","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"guard","model":"guard","summary":"bent patrolman feeding tips to the rackets","flavor":"A beat cop on the take, radio turned down so the boys upstairs get the tip-off first. His badge buys silence, not justice.","source":"archetype","sourceNote":"dirty-cop / bent-badge archetype"},{"name":"the Wheelman","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"scout","summary":"getaway driver, mobile support in a chase","flavor":"Never draws a piece, never needs to — his job is making sure everyone else is three blocks gone before the sirens turn the corner.","source":"archetype","sourceNote":"getaway-driver stock type"},{"name":"the Shakedown Man","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"half-ogre-ogrillon","model":"half-ogre-ogrillon","summary":"protection-racket collector, bigger and blunter","flavor":"Built like a delivery truck and twice as polite about it — right up until the register doesn't open fast enough.","source":"archetype","sourceNote":"protection-racket collector archetype"},{"name":"the Cigarette Girl","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"spy","model":"spy","summary":"club-floor informant, trades gossip for coin","flavor":"Sells smokes table to table at the club and sells whispers to whoever's paying after close. Everyone underestimates the tray.","source":"archetype","sourceNote":"nightclub-informant/eyes-and-ears archetype"},{"name":"the Enforcer","cr":2,"role":"elite","type":"Humanoid","size":"Medium","frame":"bugbear-warrior","model":"bugbear-warrior","summary":"crime lord's blunt-instrument muscle","flavor":"The crime lord's answer when words stop working. Doesn't monologue, doesn't negotiate — just walks in slow and leaves loud.","source":"archetype","sourceNote":"hard-boiled enforcer stock type named in the brief"},{"name":"the Dirty Cop","cr":2,"role":"elite","type":"Humanoid","size":"Medium","frame":"cultist-fanatic","model":"cultist-fanatic","summary":"corrupt detective, badge as much as bribe","flavor":"Made detective the honest way, then found out honest doesn't pay the mortgage. Still carries the badge like it means something.","source":"archetype","sourceNote":"corrupt-detective archetype named in the brief"},{"name":"the Torch","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"hobgoblin-captain","model":"hobgoblin-captain","summary":"arsonist-for-hire, insurance jobs and cleanup","flavor":"Burns warehouses for insurance money and burns witnesses for free. Whistles while the building comes down.","source":"archetype","sourceNote":"professional-arsonist-for-hire archetype"},{"name":"the Coroner's Friend","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"guard-captain","model":"guard-captain","summary":"bought-off examiner, falsifies causes of death","flavor":"Signs whatever cause of death keeps the retainer coming. A gunshot wound becomes 'heart failure' for the right envelope.","source":"archetype","sourceNote":"corrupt-medical-examiner / hush-money doctor archetype"},{"name":"the Consigliere","cr":6,"role":"high","type":"Humanoid","size":"Medium","frame":"mage","model":"mage","summary":"family strategist, plans the violence others do","flavor":"Never raises his voice, never touches a weapon — he just tells the boss which enemies to forgive and which to bury, and he's never once been wrong.","source":"archetype","sourceNote":"crime-family advisor/counselor archetype"},{"name":"the Torpedo Boss","cr":7,"role":"high","type":"Humanoid","size":"Medium","frame":"bandit-deceiver","model":"bandit-deceiver","summary":"veteran hitman, disguises every kill","flavor":"Twenty years in the life and not one clean kill on his sheet — every hit gets dressed up as an accident, a robbery, a suicide. Craftsmanship.","source":"archetype","sourceNote":"veteran hitman / made-man archetype"},{"name":"the Ghoul in the Icebox","cr":2,"role":"elite","type":"Undead","size":"Medium","frame":"ghast","model":"ghast-base","summary":"grave-risen enforcer kept on ice by the mob","flavor":"The meat-locker in the back of the butcher shop has a second tenant, and he doesn't stay cold. The mob uses him to make problems disappear — permanently, and personally.","source":"public-domain","sourceNote":"gothic revenant tradition (generic grave-risen undead, pre-1929 folklore/literature — not a specific author's IP)"},{"name":"the Torch Singer's Ghost","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"banshee","model":"banshee","summary":"murdered singer's ghost haunting her old club","flavor":"She sang the last set at the Blue Room the night they found her in the river. Now her voice still drifts through the club after closing, and the men who paid to have her silenced haven't slept right since.","source":"public-domain","sourceNote":"gothic revenant tradition — a wronged-woman haunting, drawn from settled 19th-century ghost-story convention, not any specific copyrighted work"},{"name":"the Assassin","cr":8,"role":"high","type":"Humanoid","size":"Medium","frame":"assassin","model":"assassin","summary":"mercenary killer with no fixed allegiance","flavor":"Doesn't work for the crime lord — works for whoever's currently paying the crime lord's rivals. Loyalty is a rate card.","source":"archetype","sourceNote":"hard-boiled contract-killer stock type"},{"name":"Count Marlowe","cr":11,"role":"apex","type":"Humanoid","size":"Medium","frame":"bandit-crime-lord","model":"bandit-crime-lord","summary":"centuries-old crime lord, Dracula lineage reskinned","flavor":"Old money, older habits. He came from somewhere across the water a century ago and never quite stopped feeding — now he owns the docks, the judges, and most of the bodies nobody ever finds. He receives petitioners once a week, always after dark, always alone in the room with them.","source":"public-domain","sourceNote":"Bram Stoker, Dracula (1897, US public domain) — our own crime-lord recontextualization of the Dracula lineage, not any film studio's visual design"},{"name":"the Crime Lord's Bride","cr":13,"role":"high","type":"Undead","size":"Medium","frame":"vampire","model":"vampire","summary":"elder vampire consort, true power behind the throne","flavor":"Nobody knows if she runs the family or he does anymore — she's older than his human years put together and considerably less patient. The books say his name is on the deeds. The books are wrong.","source":"public-domain","sourceNote":"Stoker's Dracula (1897, PD) — the vampire-bride motif from the same novel, our own noir take, not a studio design"}],
 "ash":[{"name":"Rustfall Ghoul","cr":0.125,"role":"mook","type":"Undead","size":"Medium","frame":"guilt-stained-vagrant","model":"commoner","summary":"radiation-mad wretch scavenging rubble on hunger reflex","flavor":"A radiation-mad scavenger, sun-blistered and skeletal, that picks through rubble on hunger reflex alone."},{"name":"Scrap-Hound","cr":0.125,"role":"mook","type":"Beast","size":"Medium","frame":"jackal","model":"jackal","summary":"mutant feral dog pack hunting the broken highway","flavor":"A feral dog gone patchy and mean, hide crusted with fallout-scald, running loose packs down the cracked highway lines."},{"name":"Rat-King's Swarm","cr":0.25,"role":"mook","type":"Beast","size":"Medium","frame":"swarm-of-rats","model":"swarm-of-rats","summary":"boiling mutant rat carpet nesting in dead-town pipes","flavor":"A boiling carpet of mutated rats nesting in a dead town's substructure, teeth filed sharp on rebar and bone."},{"name":"Warband Ganger","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit","model":"bandit","summary":"spiked-jacket raider grunt running a warband's front line","flavor":"Foot-soldier of a raider crew, spikes welded to a salvage jacket, running on stolen fuel and borrowed nerve."},{"name":"Bomb-Cult Zealot","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist-fanatic","model":"cultist","summary":"ordnance-strapped zealot singing the mushroom-cloud hymn","flavor":"A wide-eyed devotee of the old mushroom-cloud gospel, strapped with scavenged ordnance and singing the countdown hymn."},{"name":"Geiger Wretch","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"zombie-plague-carrier","model":"zombie","summary":"glowing irradiated corpse that never stopped ticking","flavor":"A corpse that never stopped ticking — its wounds glow faint green, and the count climbs the longer you stand near it."},{"name":"Blistered Stalker","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"death-dog","model":"death-dog","summary":"hairless mutant hound drawn to a running engine","flavor":"A hairless mutant hound, skin cracked like the asphalt it hunts on, drawn to the sound of a working engine."},{"name":"Chem-Huffer","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"berserker","model":"berserker","summary":"stim-shaking raider swinging a pipe with pure rage","flavor":"A raider hopped up on scavenged stimulant canisters, shakes and swings a length of pipe with more rage than sense."},{"name":"Cracked Sentry-Bot","cr":2,"role":"mook","type":"Construct","size":"Medium","frame":"scarecrow","model":"animated-armor","summary":"dying pre-Fall security drone patrolling a dead route","flavor":"A pre-Fall security drone running on a dying battery, patrolling a route that hasn't mattered in a generation."},{"name":"Fuel-Cult Firestarter","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"hobgoblin-captain","model":"knight","summary":"promethium-doused cult officer preaching detonation as sacrament","flavor":"An officer of the bomb-cult warband, doused in promethium and preaching detonation as sacrament to the ranks behind him."},{"name":"Mutant Behemoth Hog","cr":3,"role":"elite","type":"Beast","size":"Large","frame":"giant-boar","model":"giant-boar","summary":"fallout-swollen boar that charges convoys tusks-first","flavor":"A boar swollen wrong by fallout, tusks like rebar, that charges convoys for the meat and the noise."},{"name":"Irradiated Ghast","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"wight","model":"wight","summary":"faster hungrier ghoul cooked past rot by fallout","flavor":"A ghoul cooked past rot into something faster and hungrier, skin sloughing, glowing faintly under the ash-clouds."},{"name":"Warband Enforcer","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"guard-captain","model":"warrior-veteran","summary":"raider muscle enforcing the warband's chain of debt","flavor":"Muscle for a raider crew's chain of command, a scrap-plate riot shield in one hand and a debt ledger in the other."},{"name":"Chitin-Plated Feral","cr":4,"role":"elite","type":"Monstrosity","size":"Medium","frame":"wereboar","model":"wereboar","summary":"half-beast mutant grown a cracked chitin hide","flavor":"A mutant gone half-beast under the ash-fall moon, hide grown over in cracked insect plate, tusks and claws both."},{"name":"Power-Rig Brute","cr":5,"role":"elite","type":"Humanoid","size":"Large","frame":"hill-giant","model":"hill-giant","summary":"raider bolted into a scavenged hydraulic exo-rig","flavor":"A raider bolted into a scavenged hydraulic exo-rig, twice the size he was born, hitting like a demolition crew."},{"name":"Diesel Golem","cr":5,"role":"elite","type":"Construct","size":"Medium","frame":"flesh-golem","model":"stone-golem","summary":"patchwork engine-block war-machine lurching on stolen fuel","flavor":"A patchwork war-machine stitched from engine blocks and rebar, lurching forward on hissing pistons and stolen fuel."},{"name":"Last-Light Keeper","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"gladiator","model":"warrior-veteran","summary":"settlement champion fighting to keep the generator alive","flavor":"A settlement's champion, armored in scavenged plate, fighting arena bouts to keep the generator's lights burning one more night."},{"name":"Fallout Stalker","cr":2,"role":"elite","type":"Monstrosity","size":"Large","frame":"winter-wolf","model":"winter-wolf","summary":"silent radiation-zone apex hunter","flavor":"Pale, hairless, and silent — it hunts by the geiger-tick of its prey's gear and drags kills back into the slag caves to glow.","source":"archetype","sourceNote":"mutant-feral archetype: apex predator adapted to hot-zone terrain"},{"name":"Convoy Warlord","cr":6,"role":"elite","type":"Humanoid","size":"Medium","frame":"pirate-captain","model":"warrior-veteran","summary":"road-baron ruling a raider convoy by ambush and fear","flavor":"A road-baron who rules a war-rig fleet by ambush and fear, trading fuel and captives up and down the ruin-highways."},{"name":"Vault Revenant","cr":8,"role":"high","type":"Undead","size":"Medium","frame":"vampire-nightbringer","model":"wight-lord","summary":"ageless bunker-dweller returned furious the seal broke","flavor":"A bunker's last resident, sealed in decades past and returned changed — pale, ageless, and furious the door ever opened."},{"name":"Apex Ferox","cr":9,"role":"high","type":"Monstrosity","size":"Huge","frame":"abominable-yeti","model":"abominable-yeti","summary":"ash-pelted apex predator that hunts raiders for sport","flavor":"The wasteland's top predator, white-ash pelted and man-tall at the shoulder, that has learned raiders are easy prey."},{"name":"War-Rig Juggernaut","cr":10,"role":"high","type":"Construct","size":"Large","frame":"stone-golem","model":"stone-golem","summary":"warlord's mobile fortress rolling on a dozen dead trucks","flavor":"A warlord's mobile fortress, welded from a dozen dead trucks, that rolls down the highway spitting fire from every hatch."},{"name":"The Long Count","cr":11,"role":"high","type":"Undead","size":"Medium","frame":"death-knight-aspirant","model":"wight-lord","summary":"dead soldier still counting down a mission long over","flavor":"A dead soldier still running the last order he was given, counting down a mission that ended with the world."},{"name":"The Last Warlord","cr":14,"role":"apex","type":"Humanoid","size":"Medium","frame":"archmage","model":"archmage","summary":"raider-general who unified the wasteland under one law","flavor":"The wasteland's uncrowned king, a raider-general who unified a hundred warbands under one banner and one law: take everything."},{"name":"The Half-Life","cr":16,"role":"apex","type":"Monstrosity","size":"Gargantuan","frame":"purple-worm","model":"purple-worm","summary":"gargantuan hot-zone leviathan that surfaces when ground glows","flavor":"A leviathan born from the deepest hot-zone, burrowing under the ash-flats and surfacing only when the ground starts to glow."},{"name":"Cinder Rat","cr":0.125,"role":"mook","type":"Beast","size":"Tiny","frame":"rat","model":"rat","summary":"Radiation-swollen scavenger rat gnawing wire for copper","flavor":"A radiation-swollen rat that scavenges the blast rings, chewing wire for the copper."},{"name":"Slag Crow","cr":0,"role":"mook","type":"Beast","size":"Tiny","frame":"vulture","model":"vulture","summary":"Glass-feathered scavenger bird circling collapse sites","flavor":"Feathers fused with melted glass; it circles collapse sites waiting for the dust to settle."},{"name":"Barrens Jackal","cr":0.25,"role":"mook","type":"Beast","size":"Medium","frame":"hyena","model":"net-new: ash-mangy pack jackal","summary":"Pack scavenger trailing raiders for the leftovers","flavor":"Runs in loose packs behind warbands, cleaning up whatever the raiders leave behind."},{"name":"Fallout Toad","cr":0.25,"role":"mook","type":"Beast","size":"Medium","frame":"giant-toad","model":"net-new: bloated chem-runoff toad","summary":"Chem-bloated toad whose croak curdles nearby water","flavor":"Bloated on chem runoff, its croak alone curdles unprotected water."},{"name":"Wasteland Scrapper","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"net-new: pipe-rifle warband lookout","summary":"Warband lookout with a jury-rigged pipe rifle","flavor":"A lookout for a warband, armed with a pipe rifle and a claim to the ruins ahead."},{"name":"Ration Raider","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"tough","model":"net-new: scavenged-gear ration raider","summary":"Desperate raider who kills for canned goods and water","flavor":"Kills for canned goods and clean water, nothing personal, everything necessary."},{"name":"Bonepicker Ghoul","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"ghoul","model":"ghoul","summary":"Radiation-twisted corpse that still remembers running","flavor":"Radiation twisted this corpse into a hungry thing that still remembers how to run."},{"name":"Static Zealot","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"Cultist who worships the static hum as divine voice","flavor":"Worships the hum in dead radios as the voice of the sky that ended the world."},{"name":"Wire-Fanged Cur","cr":0.5,"role":"mook","type":"Monstrosity","size":"Medium","frame":"death-dog","model":"net-new: barbed-wire-fanged scrap-hound","summary":"Scrap-hound fitted with crude barbed-wire fangs","flavor":"A scrap-hound whose muzzle was crudely fitted with barbed wire fangs by its handler."},{"name":"Blister-Skin Drifter","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"zombie-plague-carrier","model":"net-new: weeping-sore contact-rot drifter","summary":"Weeping-rot shambler that spreads contact contamination","flavor":"Sores weep a contact rot; it doesn't chase so much as shamble into your path."},{"name":"Powder-Keg Runner","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit","model":"bandit","summary":"Bomb-cult runner who sprints in with a strapped satchel","flavor":"Straps a satchel of scavenged explosives to their chest and sprints the last stretch."},{"name":"Rust-Eaten Sentry","cr":1,"role":"mook","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"Corroded security automaton walking a dead patrol route","flavor":"An old security frame, corroded half-through, still walking its dead patrol route."},{"name":"Chem-Slick Viper","cr":1,"role":"mook","type":"Beast","size":"Medium","frame":"giant-venomous-snake","model":"net-new: runoff-swollen venomous viper","summary":"Runoff-mutated viper whose venom keeps wounds open","flavor":"Its venom glands swelled on tank runoff; one bite and the wound never quite closes."},{"name":"Grit-Locust Cloud","cr":0.25,"role":"mook","type":"Swarm","size":"Medium","frame":"swarm-of-insects","model":"net-new: mutant locust dust-storm swarm","summary":"Mutant locust swarm stripping crops and flesh alike","flavor":"A living dust storm of mutant locusts that strips crops and flesh alike."},{"name":"Carrion Beetle Swarm","cr":0.25,"role":"mook","type":"Swarm","size":"Medium","frame":"swarm-of-rats","model":"swarm-of-rats","summary":"Fist-sized beetle swarm drawn to fresh ash-flat kills","flavor":"Chitinous beetles the size of fists, drawn en masse to fresh kills in the ash flats."},{"name":"Tanker Ganger","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"berserker","model":"net-new: fuel-convoy shotgun enforcer","summary":"Fuel-convoy enforcer quick to violence over short tribute","flavor":"Rides shotgun on a fuel convoy, quick to violence when the tribute's short."},{"name":"Scab-Plate Scavver","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"orc-warrior","model":"orc-warrior","summary":"Scrap-armored raider wearing plates looted off corpses","flavor":"Wears bolted scrap armor scavenged plate by plate off the dead."},{"name":"Detonator Cultist","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist-fanatic","model":"cultist-fanatic","summary":"Bomb-cultist wired with a warhead trigger, waiting","flavor":"Straps a warhead trigger to his own chest, grinning, waiting to be told when."},{"name":"Growth-Warped Boar","cr":2,"role":"mook","type":"Beast","size":"Large","frame":"giant-boar","model":"giant-boar","summary":"Tumor-ridden giant boar charging anything that moves","flavor":"Tumor-ridden and enormous, it charges anything that moves in its blighted range."},{"name":"Half-Life Skeleton","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton","model":"skeleton","summary":"Fallout-glassed bones animated by residual radiation","flavor":"Bones fused glass-green by fallout, animated by whatever still crackles in the marrow."},{"name":"Corroded Watcher","cr":1,"role":"mook","type":"Construct","size":"Medium","frame":"scarecrow","model":"net-new: camera-drone husk on scavenged chassis","summary":"Drone-husk sentinel still logging intruders no one reads","flavor":"A camera-drone husk grafted to a scavenged chassis, still logging intruders no one reads."},{"name":"Ash-Choked Hound","cr":0.125,"role":"mook","type":"Beast","size":"Medium","frame":"jackal","model":"jackal","summary":"Feral scrap-hound pup, quick, starving, unpredictable","flavor":"A scrap-hound puppy grown feral in the rubble, quick and starving."},{"name":"Firebrand Initiate","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"Nervous bomb-cult convert still willing to light fuses","flavor":"A new convert to the Bomb-Cult, still nervous, still willing to light the fuse."},{"name":"Mange-Back Mutt","cr":0.125,"role":"mook","type":"Beast","size":"Small","frame":"giant-rat","model":"giant-rat","summary":"Mangy hairless mutt hunting collapsed subway tunnels","flavor":"Mangy, hairless, and vicious in packs, it hunts the collapsed subway lines."},{"name":"Warband Trapper","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"guard","model":"guard","summary":"Trap-setter who lines roads before the warband arrives","flavor":"Lines the approach roads with snares and pit traps before the warband ever shows itself."},{"name":"Static-Touched Vermin","cr":0.25,"role":"mook","type":"Beast","size":"Small","frame":"giant-centipede","model":"net-new: irradiated numbing-touch centipede","summary":"Irradiated centipede whose touch blisters skin for days","flavor":"An irradiated centipede whose touch leaves skin blistered and numb for days."},{"name":"Fume Vent Zealot","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"Cracked-mask cultist chanting over leaking gas vents","flavor":"Breathes through a cracked filter mask, chanting over any vent that still leaks gas."},{"name":"Wreck-Diver","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"net-new: wreck-stripping salvager","summary":"Salvager who strips wrecks before warlords claim them","flavor":"Specializes in stripping downed aircraft and sunken tankers before the warlords claim them."},{"name":"Ashfield Widow Spider","cr":1,"role":"mook","type":"Beast","size":"Large","frame":"giant-spider","model":"giant-spider","summary":"Ash-camouflaged spider whose webs vanish in scorched fields","flavor":"Its web is laced with fine grit and ash, near invisible against a scorched field."},{"name":"Grinder-Belt Sentry","cr":2,"role":"mook","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"Retrofitted factory automaton swinging grinder arms on flesh","flavor":"Retrofitted from an old factory line, its arms still swing the grinder motion, now on flesh."},{"name":"Fuel-Cult Bruiser","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"bugbear-stalker","model":"net-new: rebar-swinging tithe enforcer","summary":"Tithe enforcer swinging rebar for the Fuel Cult","flavor":"Enforces tithe collection for the Fuel Cult with a length of rebar and no patience."},{"name":"Chem-Vat Horror","cr":3,"role":"elite","type":"Aberration","size":"Medium","frame":"grick","model":"grick","summary":"Chemical-vat mutant that crawled out and kept growing","flavor":"Something that crawled out of a corroded chemical vat and kept growing wrong."},{"name":"Ash-Widow Broodmother","cr":3,"role":"elite","type":"Beast","size":"Large","frame":"phase-spider","model":"net-new: reactor-dome spider broodmother","summary":"Reactor-dome broodmother spawning hundreds each ash-season","flavor":"Nests in a collapsed reactor dome, her brood hatching by the hundreds each ash-season."},{"name":"Warlord's Duelist","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"knight","model":"net-new: warlord's arena duelist","summary":"Warlord's champion dueling for sport and succession","flavor":"Trained to fight one-on-one for the warlord's amusement — and his succession."},{"name":"Bloat-Ghast Preacher","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"ghast","model":"net-new: rotting bomb-cult prophet","summary":"Rotting former prophet still delivering sermons to no one","flavor":"Once a bomb-cult prophet, now a rotting thing still delivering the sermon to no one."},{"name":"Convoy Breaker","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"guard-captain","model":"net-new: axle-cracking convoy ambusher","summary":"Convoy ambusher who cracks axles before guns come out","flavor":"Specializes in ambushing fuel convoys, cracking axles before the guns ever come out."},{"name":"Warp-Chitin Stalker","cr":4,"role":"elite","type":"Monstrosity","size":"Medium","frame":"yuan-ti-abomination","model":"net-new: runoff-fused insect hybrid","summary":"Insect-hybrid mutant armored by decades of chem runoff","flavor":"Insect and something else fused by decades of runoff, patient and armored."},{"name":"Rig-Mounted Turret Hound","cr":4,"role":"elite","type":"Construct","size":"Medium","frame":"helmed-horror","model":"net-new: scrap-hound chassis with swivel autogun","summary":"Scrap-hound chassis welded to a swivel autogun","flavor":"A scrap-hound chassis welded permanently to a swivel-mounted autogun."},{"name":"Fume-Choked Ettin","cr":4,"role":"elite","type":"Giant","size":"Large","frame":"ettin","model":"net-new: two-headed mutant scrapyard giant","summary":"Two-headed mutant giant arguing over which ruin to loot","flavor":"A two-headed mutant giant, each head arguing over which smokestack to loot next."},{"name":"Vault-Sealed Revenant","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"banshee","model":"net-new: bunker blast-door ghost","summary":"Bunker-sealed ghost whose scream carries failing air","flavor":"Died locked in a bunker's blast door; its scream still carries the hiss of failing air."},{"name":"Warband Chieftain","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"gladiator","model":"net-new: three-gang warband chieftain","summary":"Warband chief who climbed to power by outliving rivals","flavor":"Climbed to command over three rival gangs by outliving every challenger personally."},{"name":"Molten Vat Ooze","cr":5,"role":"elite","type":"Ooze","size":"Large","frame":"black-pudding","model":"net-new: chemical-waste slag ooze","summary":"Chemical-waste sludge ooze dissolving anything too close","flavor":"A runoff sludge of chemical waste and slag, dissolving anything that wades too close."},{"name":"Rad-Sick Troll","cr":5,"role":"elite","type":"Giant","size":"Large","frame":"troll","model":"troll","summary":"Regenerating troll locked in stalemate with its own radiation sickness","flavor":"Its regeneration keeps pace with the radiation eating it, an endless grotesque stalemate."},{"name":"Piston-Arm Enforcer","cr":5,"role":"elite","type":"Construct","size":"Medium","frame":"flesh-golem","model":"net-new: hydraulic-press bolted enforcer","summary":"Salvaged hydraulic-press automaton breaking doors and skulls","flavor":"Salvaged hydraulic press arms bolted onto a walking chassis to break down doors and skulls alike."},{"name":"Ashborn Wyrmling Mutant","cr":5,"role":"elite","type":"Monstrosity","size":"Large","frame":"basilisk","model":"net-new: sun-cracking mutant reptile","summary":"Mutant reptile whose stare cracks flesh like baked clay","flavor":"A reptile mutated past recognition, its stare leaves flesh cracked like sun-baked clay."},{"name":"Fallout Wight Captain","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"wight","model":"wight","summary":"Ghoul squad commander who still remembers military drill","flavor":"Commands a squad of lesser ghouls, the only one who still remembers military drill."},{"name":"Bomb-Cult High Priest","cr":6,"role":"elite","type":"Humanoid","size":"Medium","frame":"priest","model":"net-new: second-blast bomb-cult priest","summary":"Fanatic priest praying for a second, holier detonation","flavor":"Preaches that the old bombs were mercy and prays daily for a second, holier blast."},{"name":"Furnace-Bound Salamander","cr":6,"role":"elite","type":"Elemental","size":"Large","frame":"salamander","model":"net-new: scrapyard blast-furnace elemental","summary":"Blast-furnace-bound elemental lashing at anyone who opens the door","flavor":"Bound into a scrapyard's blast furnace, it lashes out at anyone who opens the door."},{"name":"Scrapfield Chimera","cr":6,"role":"elite","type":"Monstrosity","size":"Large","frame":"chimera","model":"chimera","summary":"Three-headed radiation-fused mutant, each screaming differently","flavor":"Three mutant heads fused by radiation, each screaming a different warning."},{"name":"Diesel Pit Fighter","cr":6,"role":"elite","type":"Humanoid","size":"Medium","frame":"pirate-captain","model":"net-new: undefeated fighting-pit champion","summary":"Undefeated warlord's pit champion across nine seasons","flavor":"Champions the fighting pits under a warlord's banner, undefeated across nine seasons."},{"name":"Wraith of the Fallout Line","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"wraith","model":"wraith","summary":"Dead commuters fused into one hungry drifting shape","flavor":"A commuter train's dead passengers fused into one hungry, drifting shape."},{"name":"Junk-Titan Enforcer","cr":7,"role":"elite","type":"Construct","size":"Large","frame":"shield-guardian","model":"net-new: compound-gate scrap titan","summary":"Warlord's gate guardian that nothing has gotten past","flavor":"Built by a warlord's engineers to guard the compound gate; nothing has yet gotten past it."},{"name":"Toxin-Blood Oni Raider","cr":7,"role":"elite","type":"Fiend","size":"Large","frame":"oni","model":"net-new: chem-warped toxic-blood brute","summary":"Chem-warped raider brute whose own blood is a weapon","flavor":"A brute of a raider warped by chem exposure until its blood itself became a weapon."},{"name":"Scrap-Hound Alpha","cr":3,"role":"elite","type":"Monstrosity","size":"Medium","frame":"winter-wolf","model":"net-new: ash-stained scrap-hound pack alpha","summary":"Scrap-hound pack alpha with ash-stained frost-white fur","flavor":"Leads a scrap-hound pack, frost-white fur stained ash-grey from the wastes."},{"name":"Vault Door Golem","cr":7,"role":"elite","type":"Construct","size":"Large","frame":"stone-golem","model":"stone-golem","summary":"Animated blast-door guardian of a vault long since emptied","flavor":"An entire blast door animated by pre-collapse tech, still guarding a vault long since emptied."},{"name":"Warlord's Bodyguard","cr":7,"role":"elite","type":"Humanoid","size":"Medium","frame":"assassin","model":"net-new: silent seat-loyal bodyguard","summary":"Silent armored bodyguard loyal only to whoever rules","flavor":"Silent, armored, loyal only to whoever currently holds the warlord's seat."},{"name":"Contagion Ghast Broodkeeper","cr":7,"role":"elite","type":"Undead","size":"Medium","frame":"vampire-spawn","model":"net-new: deliberate rot-cultivating ghast","summary":"Rot-spreading undead cultivating new ghouls like crops","flavor":"Spreads its rot deliberately, cultivating new ghouls the way a farmer tends a field."},{"name":"Detonation Engineer","cr":8,"role":"high","type":"Humanoid","size":"Medium","frame":"death-cultist","model":"net-new: half-mad reactor-core warhead engineer","summary":"Bomb-cult engineer half-mad with reactor-core warhead math","flavor":"Designs the Bomb-Cult's warheads from scavenged reactor cores, half-mad with the maths of it."},{"name":"Iron Convoy Behemoth","cr":8,"role":"high","type":"Construct","size":"Huge","frame":"clay-golem","model":"net-new: animated war-rig hauler","summary":"War-rig hauler plated with scrap from a dozen dead vehicles","flavor":"A war-rig hauled by an animated chassis, plating scavenged from a dozen dead vehicles."},{"name":"Fallout Hydra Broodhorror","cr":8,"role":"high","type":"Monstrosity","size":"Huge","frame":"hydra","model":"hydra","summary":"Hydra whose severed heads regrow ever more mutated","flavor":"Each severed head regrows twisted differently, mutation compounding mutation."},{"name":"Cinderfall Vampire Warlord","cr":8,"role":"high","type":"Undead","size":"Medium","frame":"vampire-nightbringer","model":"net-new: settlement-razing undead warlord","summary":"Undead warlord feeding on survivors of settlements it razes","flavor":"Feeds on the survivors of the settlements it razes, then rules the ashes it leaves."},{"name":"Bunker-Bred Nightmare Steed","cr":8,"role":"high","type":"Fiend","size":"Large","frame":"nightmare","model":"net-new: cult general's scorching mount","summary":"Cult general's steed scorching ash-fields with every charge","flavor":"A cult general's mount, hooves scorching whatever ash-field it charges across."},{"name":"Reactor Wyrm","cr":9,"role":"high","type":"Monstrosity","size":"Huge","frame":"remorhaz","model":"remorhaz","summary":"Bedrock-burrowing wyrm glowing hot from irradiated feeding","flavor":"Burrows through irradiated bedrock, its hide glowing hot from what it's fed on."},{"name":"Grand Warlord's Champion","cr":9,"role":"high","type":"Humanoid","size":"Medium","frame":"berserker-commander","model":"net-new: hundred-duel warband champion","summary":"Undefeated champion who fought a hundred duels for command","flavor":"Fought a hundred duels to earn the right to lead the largest warband in the ash flats."},{"name":"Ash-Frost Colossus","cr":9,"role":"high","type":"Monstrosity","size":"Huge","frame":"abominable-yeti","model":"abominable-yeti","summary":"Nuclear-winter mutant with ash-snow-crusted fur and endless hunger","flavor":"A nuclear-winter mutant, matted fur crusted in ash-snow, hungry beyond reason."},{"name":"Grid-Fed Iron Sentinel","cr":10,"role":"high","type":"Construct","size":"Large","frame":"stone-golem","model":"stone-golem","summary":"Grid-wired automaton drawing endless trickle current","flavor":"Still wired to a dead power grid, drawing a trickle of current that keeps it standing forever."},{"name":"Vaultbreaker Behemoth","cr":10,"role":"high","type":"Giant","size":"Huge","frame":"cyclops-oracle","model":"net-new: bare-handed vault-cracking giant","summary":"Mutant giant that cracks vault doors bare-handed","flavor":"A mutated giant that cracks vault doors open bare-handed for the warband behind it."},{"name":"Deathwatch Cult Oracle","cr":10,"role":"high","type":"Undead","size":"Medium","frame":"death-knight-aspirant","model":"net-new: preserved countdown-interpreting oracle","summary":"Preserved oracle still interpreting a countdown only it hears","flavor":"Preserved by cult ritual to keep interpreting the countdown only it can still hear."},{"name":"Blightborn Roc","cr":11,"role":"high","type":"Monstrosity","size":"Gargantuan","frame":"roc","model":"net-new: radiation-grown monstrous carrion bird","summary":"Radiation-grown carrion bird whose shadow panics settlements","flavor":"A carrion bird grown monstrous on radioactive corpses, its shadow alone panics a settlement."},{"name":"Ash Warlord's Marilith Enforcer","cr":12,"role":"high","type":"Fiend","size":"Large","frame":"arcanaloth","model":"arcanaloth","summary":"Bound fiend running security for a warlord's court","flavor":"A fiend bound into service by an ancient bargain, now runs security for a warlord's court."},{"name":"Devouring Junkyard Kraken","cr":13,"role":"high","type":"Monstrosity","size":"Huge","frame":"spirit-naga","model":"net-new: flooded-scrapyard tentacled mutant","summary":"Tentacled scrapyard-pit mutant born of decades of chemicals","flavor":"Lives beneath a scrapyard's flooded pit, tentacled from decades of chemical mutation."},{"name":"The Countdown Keeper","cr":14,"role":"apex","type":"Undead","size":"Medium","frame":"undead-eye-tyrant","model":"net-new: ancient cult figurehead whispering the final number","summary":"Preserved cult figurehead whispering an endless final number","flavor":"An ancient cult figurehead, preserved by dogma, still whispering the final number."},{"name":"The Warlord Ascendant","cr":15,"role":"apex","type":"Humanoid","size":"Medium","frame":"mummy-lord","model":"net-new: fear-united ash-flats overlord","summary":"Warlord who united every ash-flat gang through pure fear","flavor":"United every warband in the ash flats under one banner through fear alone."},{"name":"The Fallout Titan","cr":16,"role":"apex","type":"Giant","size":"Gargantuan","frame":"iron-golem","model":"net-new: mountain-scale mutation titan","summary":"Mountain-sized mutant mistaken for terrain until it moves","flavor":"A mutation so vast it's mistaken for a mountain until it stands up."},{"name":"The Last Detonation","cr":17,"role":"apex","type":"Construct","size":"Gargantuan","frame":"dragon-turtle","model":"net-new: warhead-core walking chassis","summary":"Warhead-core chassis built to finish what first bombs started","flavor":"A warhead-core walking chassis the Bomb-Cult built to finish what the first bombs started."},{"name":"The Glass Sea Wyrm","cr":19,"role":"apex","type":"Monstrosity","size":"Gargantuan","frame":"kraken","model":"kraken","summary":"Ancient leviathan swimming the vitrified glass flats","flavor":"Older than the warbands, it swims the vitrified glass flats where the first blast struck."},{"name":"Chittergaunt","cr":0.25,"role":"mook","type":"Monstrosity","size":"Small","frame":"stirge","model":"stirge","summary":"pack-hunting mutant scavenger, calls its litter","flavor":"A hairless, twitchy thing that runs on all fours and screeches to call its litter-mates in; harmless alone, a real problem in a pack of six.","source":"archetype","sourceNote":"mutant-feral archetype: irradiated pack-scavenger, stock post-apoc creature type (not tied to any franchise)"},{"name":"Rustfang","cr":0.5,"role":"mook","type":"Monstrosity","size":"Medium","frame":"death-dog","model":"death-dog","summary":"scrap-fused mutant guard-dog","flavor":"A dog (or what was a dog) with fused metal shrapnel grown into its hide from decades denned in a scrapyard; bites like a bear trap.","source":"archetype","sourceNote":"mutant-feral archetype: junkyard guard-beast gone wrong"},{"name":"Waste Raider","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit","model":"bandit","summary":"road-gang footsoldier, fights in packs","flavor":"Sun-blistered, tattooed with the mile-markers of every settlement they've burned; fights in a screaming knot with two or three others.","source":"archetype","sourceNote":"raider-gang footsoldier archetype: post-collapse road-warrior stock type"},{"name":"Cult Acolyte, Bomb-Struck","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"warhead-relic zealot, suicidal devotion","flavor":"Wears a rusted warhead casing like a holy relic and prays to the flash that reshaped the world; will walk into obvious death singing.","source":"archetype","sourceNote":"bomb-cult zealot archetype: doomsday-worship footsoldier, stock post-apoc type"},{"name":"Bleached Ghoul","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"ghoul","model":"ghoul","summary":"radiation-sick feral scavenger, not truly undead-lore","flavor":"Not undead by ritual but by dose — the radiation cooked the mind out and left hunger behind; skin cracked like dry riverbed, eyes milk-white.","source":"archetype","sourceNote":"irradiated-ghoul archetype: our own fallout-sickness take, distinct from any undead-ghoul lore or franchise ghoul design"},{"name":"Junk Crawler","cr":0.5,"role":"mook","type":"Construct","size":"Medium","frame":"rust-monster","model":"rust-monster","summary":"debris-heap creature that devours metal","flavor":"A drift of rebar and car doors that somehow walks and somehow wants your rifle barrel more than your blood.","source":"archetype","sourceNote":"scrap-beast archetype: animate debris/rust-monster reskin for a wasteland setting"},{"name":"Warlord's Enforcer","cr":2,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-captain","model":"bandit-captain","summary":"warlord's chain-wielding enforcer","flavor":"Keeps the warlord's convoy in line with a length of chain and a reputation for never asking twice.","source":"archetype","sourceNote":"raider-warlord's lieutenant archetype"},{"name":"Rad-Hulk","cr":5,"role":"elite","type":"Monstrosity","size":"Large","frame":"bulette","model":"bulette","summary":"hulking overgrown mutant brute","flavor":"Grew three sizes past human and forgot most of its words along the way; still remembers the name of the town it used to guard.","source":"archetype","sourceNote":"mutant-feral archetype: hulking irradiated brute, stock post-apoc mutant type"},{"name":"Scrap Colossus","cr":5,"role":"elite","type":"Construct","size":"Large","frame":"flesh-golem","model":"flesh-golem","summary":"welded-together walking scrap machine","flavor":"Welded together from three different trucks by hands that clearly loved the work; runs on spite and a leaking fuel drum.","source":"archetype","sourceNote":"scrap-beast archetype: junkyard-built walking machine, stock salvage-golem type"},{"name":"Chem-Baron","cr":6,"role":"high","type":"Humanoid","size":"Medium","frame":"mage","model":"net-new: wasteland kingpin in scavenged finery, no bespoke model needed (uses mage stat frame only)","summary":"drug-and-fuel kingpin warlord","flavor":"Runs three settlements on rationed water and homebrewed stims; smiles like he's already won the argument you haven't started.","source":"archetype","sourceNote":"raider-warlord archetype: settlement-controlling drug/fuel kingpin"},{"name":"The Sermon-Bearer","cr":6,"role":"high","type":"Humanoid","size":"Medium","frame":"priest","model":"net-new: robed zealot with a warhead-fragment icon, no bespoke model needed (uses priest stat frame only)","summary":"doomsday high-priest awaiting the next blast","flavor":"Preaches that the bombs were mercy and the next ones will finish the job kindly; his flock believes him, which is the scary part.","source":"archetype","sourceNote":"bomb-cult zealot archetype: doomsday high-priest, our own invented theology (no real-world cult referenced)"},{"name":"Ashfield Titan","cr":9,"role":"high","type":"Construct","size":"Huge","frame":"stone-golem","model":"stone-golem","summary":"hauler-built industrial war-walker","flavor":"Built from a downed cargo hauler by a warlord who wanted a throne that could also crush things; mostly it just crushes things.","source":"archetype","sourceNote":"scrap-beast archetype: settlement-sized industrial walker, stock giant-war-machine type"},{"name":"Glasslands Broodmother","cr":9,"role":"high","type":"Monstrosity","size":"Huge","frame":"abominable-yeti","model":"abominable-yeti","summary":"apex matriarch of the mutant bloodline","flavor":"Every Chittergaunt and Rustfang for fifty miles traces back to her den under the melted overpass; she remembers being smaller, and human.","source":"archetype","sourceNote":"mutant-feral archetype: apex irradiated matriarch, seeds a feral bloodline"},{"name":"Deadman's Warlord","cr":11,"role":"apex","type":"Humanoid","size":"Medium","frame":"death-knight-aspirant","model":"net-new: convoy-king in welded plate armor built from truck panels, no bespoke model needed","summary":"apex convoy-king, rules through fuel scarcity","flavor":"Crowned himself off the corpse of the last warlord and the fuel reserve underneath his throne-truck; his convoy is a moving nation.","source":"archetype","sourceNote":"raider-warlord archetype: apex convoy-king ruling by fear and fuel scarcity"},{"name":"The Last Sermon","cr":13,"role":"apex","type":"Humanoid","size":"Medium","frame":"rakshasa","model":"rakshasa","summary":"apex doomsday-prophet guarding a live warhead","flavor":"Claims the final bomb is still out there, waiting for his word; nobody who's called the bluff has lived to be wrong about it.","source":"archetype","sourceNote":"bomb-cult zealot archetype: apex doomsday-prophet who holds a live warhead as scripture"},{"name":"Half-Life","cr":14,"role":"apex","type":"Undead","size":"Large","frame":"undead-eye-tyrant","model":"undead-eye-tyrant","summary":"apex fallout-horror, decades-deep radiation exposure","flavor":"Been soaking in the hot zone so long the geiger counters just give up near it; what's left of the mind is patient, and furious.","source":"archetype","sourceNote":"irradiated-ghoul archetype: apex fallout-mutated horror, decades of exposure past any human baseline"},{"name":"The Foundry Made Flesh","cr":16,"role":"apex","type":"Construct","size":"Gargantuan","frame":"iron-golem","model":"net-new: factory-fused industrial mass, no bespoke model exists yet (iron-golem stat frame)","summary":"factory-fused apex war-machine","flavor":"An entire pre-collapse factory floor — presses, arms, conveyor teeth — fused by decades of slag into a single furious machine that still thinks it's making something.","source":"archetype","sourceNote":"scrap-beast archetype: apex, a factory's automated defense grid fused into one rampaging mass"}],
 "suburb":[{"name":"Cul-de-Sac Wanderer","cr":0.125,"role":"mook","type":"Undead","size":"Medium","frame":"zombie","model":"zombie","summary":"shambling loop-walker, the block's living dead","flavor":"A resident in bathrobe and slippers who never quite reaches the mailbox, looping the same forty feet of driveway forever."},{"name":"Porch-Light Moth-Thing","cr":0.125,"role":"mook","type":"Aberration","size":"Small","frame":"lantern-sage","model":"lantern-sage","summary":"screen-door lurker begging to be let inside","flavor":"Drawn to bug-zapper blue, it flutters against screen doors at 3am, whispering in a dead child's voice about being let in."},{"name":"HOA Enforcer Drone","cr":0.25,"role":"mook","type":"Construct","size":"Small","frame":"animated-flying-sword","model":"animated-flying-sword","summary":"flying clipboard drone, petty bureaucratic menace","flavor":"A clipboard on wings that measures lawn height by moonlight and leaves violation notices on houses that don't exist yet."},{"name":"Sprinkler Ghoul","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton","model":"skeleton","summary":"irrigation-system ghoul, rises on the same timer nightly","flavor":"It rises from the irrigation system at exactly 3:00am, joints clicking like a valve timer, watering the grass with something that isn't water."},{"name":"Under-the-Bed Groper","cr":0.5,"role":"mook","type":"Aberration","size":"Small","frame":"darkmantle","model":"darkmantle","summary":"classic bedroom-dark lurker, waits for lights-out","flavor":"Flat black and patient, it presses itself to the box spring all day and only unfolds a reaching limb once the lamp clicks off."},{"name":"Overwaving Neighbor","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"too-friendly neighbor, watching before you're even awake","flavor":"He waves before you've even opened your blinds, hand moving a beat too fast, smile a beat too wide, already knowing your name."},{"name":"Curfew Light Wisp","cr":0.5,"role":"mook","type":"Undead","size":"Tiny","frame":"will-o-wisp","model":"will-o-wisp","summary":"streetlamp wisp that herds you home by dusk","flavor":"Streetlamps that switch on early and herd stragglers indoors by dimming ahead of their steps, punishing anyone caught out past curfew."},{"name":"Casserole Cultist","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"grief-vulture neighbor, dish in hand, headcount ready","flavor":"Arrives at your door within the hour of any tragedy, dish already baked, eyes already counting who's missing from the block."},{"name":"Cursed Lawn Sentinel","cr":0.5,"role":"mook","type":"Construct","size":"Small","frame":"scarecrow","model":"scarecrow","summary":"grinning gnome, roots the cursed lawn to its post","flavor":"Ceramic and grinning, it rotates a few degrees each night to keep every lawn in its sightline; the grass beneath it never dies right."},{"name":"Vinyl-Sider","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"death-dog","model":"death-dog","summary":"fence-phasing hound, barks on a dead loop","flavor":"A dog-shaped thing that phases through fences, patrolling yard boundaries with a bark that sounds pre-recorded and looped."},{"name":"The Family Wearing the Skin","cr":3,"role":"elite","type":"Fiend","size":"Medium","frame":"doppelganger","model":"doppelganger","summary":"the too-perfect family, all three wearing the same face","flavor":"Three bodies at the dinner table moving in perfect unison, each one a puppet worn by the same wrongness, still setting a fourth place for someone who used to live there."},{"name":"Perpetual Yard-Sale Hag","cr":3,"role":"elite","type":"Fey","size":"Medium","frame":"green-hag","model":"green-hag","summary":"folding-table hag selling the missing's belongings","flavor":"Every Saturday her folding tables reappear stocked with items that belonged to people who are no longer around to miss them."},{"name":"Riding-Mower Revenant","cr":3,"role":"elite","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"dead husband still mowing perfect ghost-stripes","flavor":"A husband who died mowing the lawn and never stopped; the mower is rusted through but still runs, dragging him behind it in perfect stripes."},{"name":"The Man Behind the Rubber Mask","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"assassin","model":"assassin","summary":"the masked slasher, unhurried and always closing","flavor":"He never runs and never speaks, just walks the same unhurried pace behind you no matter how fast you go, mask blank and waiting for the moment you stop looking back."},{"name":"Book Club Coven","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"cultist-fanatic","model":"cultist-fanatic","summary":"wine-and-book coven picking next month's victim","flavor":"Six women, one wine bottle, and a discussion that always circles back to who in the neighborhood needs to be 'welcomed properly' next."},{"name":"Backyard Above-Ground Deep One","cr":5,"role":"elite","type":"Aberration","size":"Large","frame":"otyugh","model":"otyugh","summary":"bloated pool-thing, too big for the water it's in","flavor":"Something surfaces in the cheap plastic pool every summer solstice, too large for the water it's found in, patient as chlorine rot."},{"name":"Cheerful Renovation Golem","cr":5,"role":"elite","type":"Construct","size":"Large","frame":"flesh-golem","model":"flesh-golem","summary":"stitched-contractor golem, endlessly remodeling the house","flavor":"Stitched from drywall, spare lumber, and whichever contractor stopped answering his phone, it keeps 'improving' the house whether anyone's living in it or not."},{"name":"The PTA President","cr":6,"role":"elite","type":"Fiend","size":"Medium","frame":"succubus","model":"succubus","summary":"smiling PTA fiend running the block and its secrets","flavor":"She runs the bake sale, the block committee, and the thing underneath the school gymnasium, and never once raises her voice doing any of it."},{"name":"Lawn-Order Enforcer","cr":7,"role":"elite","type":"Construct","size":"Large","frame":"shield-guardian","model":"shield-guardian","summary":"covenant-bound guardian, trims anything grown too tall","flavor":"Summoned by an unspoken covenant among homeowners, it trims anything — hedge, weed, or trespasser — that grows past the agreed-upon height."},{"name":"Master of the Block Party","cr":8,"role":"high","type":"Fiend","size":"Large","frame":"oni","model":"oni","summary":"shapeshifting host, one small yearly price for paradise","flavor":"He wears whatever face the street needs to see, grills burgers that taste like every summer you can remember, and only asks for one small thing in return each year."},{"name":"The Substitute Mailman","cr":9,"role":"high","type":"Undead","size":"Medium","frame":"vampire-spawn","model":"vampire-spawn","summary":"undead mailman, on-time deliveries for the dead","flavor":"He's delivered mail on this route since before anyone living can remember, always at the exact same minute, and packages addressed to the dead still arrive."},{"name":"Development Overseer","cr":10,"role":"high","type":"Construct","size":"Huge","frame":"stone-golem","model":"stone-golem","summary":"model-home golem enforcing the original blueprint","flavor":"Built from the bones of the model home nobody bought, it enforces the subdivision's original blueprint, rebuilding whatever the residents dare to change."},{"name":"The Neighborhood Watch Itself","cr":11,"role":"high","type":"Aberration","size":"Large","frame":"mind-thief-arcanist","model":"mind-thief-arcanist","summary":"the hive-mind of curtain-twitchers, reading through glass","flavor":"Not a person but a consensus — the collective suspicion of every curtain-twitching resident fused into one entity that reads minds through window glass."},{"name":"The First Homeowner","cr":15,"role":"apex","type":"Undead","size":"Medium","frame":"mummy-lord","model":"mummy-lord","summary":"the founder's corpse, landlord of the whole afterlife","flavor":"Buried under the foundation of the very first house on the street, he built the whole subdivision as his afterlife and considers every current resident a tenant who owes back rent in something other than money."},{"name":"The Idea of Sunday","cr":18,"role":"apex","type":"Aberration","size":"Gargantuan","frame":"eye-tyrant","model":"eye-tyrant","summary":"the unblinking eye dreaming the loop into place","flavor":"A god of clipped hedges and identical doors given a single vast eye that never blinks, dreaming the whole suburb into looping perfection, one repeated day at a time — waking it means the wrongness stops keeping regular hours."},{"name":"Latchkey Shade","cr":0.125,"role":"mook","type":"Undead","size":"Small","frame":"crawling-claw","model":"crawling-claw","summary":"Small unseen presence that rattles empty houses at dusk","flavor":"The lingering print of a kid who let himself in every day after school and never quite left; scuttles across empty kitchen counters after dark."},{"name":"Storm-Drain Grabber","cr":0.125,"role":"mook","type":"Aberration","size":"Small","frame":"lantern-sage","model":"lantern-sage","summary":"Whispers from storm drains, lures children with a friendly voice","flavor":"A wet, whispering thing that lives where the curb meets the culvert, luring lost balls and lost kids alike with a friendly voice from the dark."},{"name":"Rerun Wraith","cr":0.125,"role":"mook","type":"Undead","size":"Medium","frame":"zombie","model":"zombie","summary":"Armchair-bound ghost that traps watchers in endless reruns","flavor":"Bound to a living-room armchair, endlessly rewatching the same three channels; anyone who sits too long starts rewatching with it."},{"name":"Chain-Link Fence-Walker","cr":0.25,"role":"mook","type":"Monstrosity","size":"Medium","frame":"troglodyte","model":"troglodyte","summary":"Skulks along fence-lines just out of direct sight","flavor":"Something that moves along backyard fence-lines on all fours, always one yard over from wherever you're looking."},{"name":"Popped-Collar Poltergeist","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"poltergeist","model":"poltergeist","summary":"Restless spirit slamming doors, showing off for no one","flavor":"The restless spirit of the neighborhood's self-appointed cool kid, still slamming screen doors and flipping bike kickstands for an audience that stopped watching decades ago."},{"name":"Newspaper Route Revenant","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton","model":"skeleton","summary":"Undead paperboy still riding a route no one ordered","flavor":"Still pedaling the same route at 5 a.m., flinging rolled papers that thud like fists through screen doors."},{"name":"Static-Screen Watcher","cr":0.25,"role":"mook","type":"Aberration","size":"Small","frame":"will-o-wisp","model":"will-o-wisp","summary":"Face surfaces in TV static, watches whoever watches it","flavor":"A face that surfaces in the snow between channels on old console TVs, staring out until someone stares back."},{"name":"Trash Night Ghoul","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"ghoul","model":"ghoul","summary":"Compulsive undead trash-day ritual, drags off what it finds","flavor":"Drags the cans to the curb every Tuesday out of decades-old habit, and drags anything else it finds in the yard right along with them."},{"name":"Garage Sale Ghast","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"ghast-base","model":"ghast-base","summary":"Undead haggler who trades your belongings for its junk","flavor":"Haggles over folding tables of dead people's belongings, and won't let a customer leave without buying something of theirs instead."},{"name":"Split-Level Skulker","cr":0.5,"role":"mook","type":"Monstrosity","size":"Medium","frame":"death-dog","model":"death-dog","summary":"Pack hunter that ambushes through split-level stairwells","flavor":"A pack-hunter that has learned split-level floor plans intimately, cutting people off between the sunken den and the stairs."},{"name":"Rec-Room Rug Thing","cr":0.5,"role":"mook","type":"Monstrosity","size":"Medium","frame":"animated-rug-of-smothering","model":"animated-rug-of-smothering","summary":"Shag basement carpet that smothers unwary bare feet","flavor":"The shag carpet in the finished basement never quite matched the room; it waits for bare feet to wander in during commercials."},{"name":"Backyard Above-Ground Pool Thing","cr":0.5,"role":"mook","type":"Aberration","size":"Medium","frame":"gray-ooze","model":"gray-ooze","summary":"Cloudy backyard pool hides something that surfaces at night","flavor":"Something moved into the cloudy above-ground pool nobody's cleaned since June; it only surfaces once the pump shuts off for the night."},{"name":"Wrong-Number Screamer","cr":0.5,"role":"mook","type":"Undead","size":"Small","frame":"specter","model":"specter","summary":"Phantom prank caller that claims it's already in the house","flavor":"Calls the house phone at 3 a.m. insisting you have the wrong number, then insists it's already inside."},{"name":"Cul-de-Sac Bike Gang Ghost","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton-warrior","model":"skeleton-warrior","summary":"Ghost bike gang circling forever, daring new kids to join","flavor":"Three or four spectral kids on banana-seat bikes circling a cul-de-sac forever, daring anyone new to join the loop."},{"name":"Aluminum Siding Stalker","cr":1,"role":"mook","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"Siding-panel construct that paces you when you don't look","flavor":"A suit of cheap siding panels clatters upright behind you on the sidewalk, keeping perfect pace whenever you don't look back."},{"name":"Van with No Windows","cr":1,"role":"mook","type":"Construct","size":"Large","frame":"animated-armor","model":"animated-armor","summary":"Idling windowless van, door sliding open on its own","flavor":"It idles at the curb with the engine running and the side door already sliding open, going nowhere until someone gets close enough to look inside."},{"name":"Ding-Dong-Ditch Devil","cr":1,"role":"mook","type":"Fiend","size":"Small","frame":"dretch","model":"dretch","summary":"Gleeful imp that rings and runs, leaves a scorched handprint","flavor":"A small, gleeful horror that rings the bell and vanishes, leaving a scorched handprint on the door and a worse mark on whoever answers too slowly."},{"name":"Toybox Escapee","cr":1,"role":"mook","type":"Construct","size":"Small","frame":"animated-flying-sword","model":"animated-flying-sword","summary":"Self-winding toy that patrols under the bed relentlessly","flavor":"A wind-up toy that wound itself up once too often and never wound back down; it patrols under the bed with clockwork patience."},{"name":"Curbside Furniture Fiend","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"mimic","model":"mimic","summary":"Free curbside couch that eats whoever tries to take it","flavor":"That free couch someone left at the curb with a 'FREE' sign taped on has been eating whoever tries to carry it home."},{"name":"Overgrown Hedge Maze Beast","cr":1,"role":"mook","type":"Plant","size":"Medium","frame":"vine-blight","model":"vine-blight","summary":"Untrimmed hedge maze conceals something living in the gaps","flavor":"The decorative hedge maze behind the model home was never finished being trimmed, and something learned to live in the unfinished parts."},{"name":"Sun-Bleached Lawn Jockey","cr":1,"role":"mook","type":"Construct","size":"Medium","frame":"scarecrow","model":"scarecrow","summary":"Faded lawn statue that turns to track trespassers","flavor":"A faded plaster lawn ornament that turns its painted eyes to track anyone who cuts across the grass instead of using the walk."},{"name":"Backyard Above-Ground Deep One Spawn","cr":1,"role":"mook","type":"Aberration","size":"Medium","frame":"fish-folk","model":"fish-folk","summary":"Young pool-thing spawn awkwardly hunting on dry lawn","flavor":"A smaller relation of the thing in the pool, gone hunting on land for the first time, still learning to walk on the lawn."},{"name":"Meter Reader Mimic","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"doppelganger","model":"doppelganger","summary":"Fake utility worker that always asks to go around back","flavor":"Wears the utility company's polo and clipboard perfectly, and always asks to be let around back where nobody can see from the street."},{"name":"Skateboard Ramp Wight","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"wight","model":"wight","summary":"Undead skater endlessly practicing the trick that killed it","flavor":"Died trying to land the big trick off the plywood ramp behind the school and still practices, endlessly, on anyone who gets close."},{"name":"Backyard Bug-Zapper Wisp","cr":1,"role":"mook","type":"Elemental","size":"Small","frame":"smoke-mephit","model":"smoke-mephit","summary":"Escaped bug-zapper spark that hunts warm bodies at night","flavor":"A crackle of blue light that escaped the porch zapper and now hunts anything warm-blooded that wanders the yard after dark."},{"name":"Video Store Return-Slot Horror","cr":2,"role":"mook","type":"Aberration","size":"Small","frame":"gibbering-mouther","model":"gibbering-mouther","summary":"Rental drop-slot horror that changes whatever it swallows","flavor":"Something lives in the drop slot of the video rental place, and every tape fed back through comes out changed, and so does the hand that fed it."},{"name":"Arcade Cabinet Haunt","cr":2,"role":"mook","type":"Undead","size":"Medium","frame":"greater-shadow","model":"greater-shadow","summary":"Ghost of an unbeaten high-scorer, lit inside the cabinet","flavor":"A high score that was never beaten, and the kid who set it, both still lit up behind the screen glass long after closing."},{"name":"Mall Food Court Ooze","cr":2,"role":"mook","type":"Ooze","size":"Large","frame":"gelatinous-cube","model":"gelatinous-cube","summary":"Slow food-court ooze that absorbs stragglers after closing","flavor":"A slow, syrupy mass that oozes between the food court tables at closing time, absorbing spilled soda, dropped fries, and the occasional straggler."},{"name":"Backyard Trampoline Terror","cr":2,"role":"mook","type":"Monstrosity","size":"Medium","frame":"bulette-pup","model":"bulette-pup","summary":"Burrowing thing under a trampoline that overbounces kids on purpose","flavor":"It burrowed up under the trampoline springs and now bounces kids skyward on purpose, waiting to see who doesn't land right."},{"name":"Home Alarm Banshee","cr":2,"role":"mook","type":"Undead","size":"Medium","frame":"specter","model":"specter","summary":"Alarm-triggering wraith whose wail is worse than the siren","flavor":"Trips every motion sensor in the house at once, its wail indistinguishable from — and worse than — the alarm it triggers."},{"name":"The Family Wearing the Skin (Understudy)","cr":2,"role":"mook","type":"Fiend","size":"Medium","frame":"jackalwere","model":"jackalwere","summary":"Lesser copycat family-thing, close but not quite convincing","flavor":"A lesser cousin of the perfect-family horror down the street — close enough to pass at a barbecue, not close enough to pass close up."},{"name":"Handyman Who Never Leaves","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"warrior-veteran","model":"warrior-veteran","summary":"Contractor who never finishes the job or leaves the house","flavor":"Hired for one gutter job three summers ago, his truck's still in the driveway and he's always got one more thing that needs fixing inside."},{"name":"The Substitute Teacher","cr":3,"role":"elite","type":"Fiend","size":"Medium","frame":"succubus","model":"succubus","summary":"Roving fiend-teacher whose classes always lose a student","flavor":"Fills in for a week at a time across a dozen schools, and every class she covers loses one kid to absence that never gets explained."},{"name":"Split-Shift Shapeshifter","cr":3,"role":"elite","type":"Monstrosity","size":"Medium","frame":"wererat","model":"wererat","summary":"Gas station night clerk with a shift no human works","flavor":"Works the graveyard shift at the all-night gas station and something else's shift after that; the clerk's smile never quite sits right."},{"name":"Riding-Mower Revenant, Deluxe Model","cr":3,"role":"elite","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"Upgraded haunted mower that enforces HOA lawn regulations","flavor":"A newer, meaner riding mower haunts the HOA's model-home block, chasing anyone whose lawn falls out of regulation."},{"name":"The Man in the Ice Cream Truck","cr":3,"role":"elite","type":"Fiend","size":"Medium","frame":"incubus","model":"incubus","summary":"Ice-cream-truck fiend whose jingle lures kids away","flavor":"His jingle plays even when the truck's parked and empty; kids who chase the sound too far never quite come back the same."},{"name":"Backyard Bonfire Cultist Circle","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"cultist-fanatic","model":"cultist-fanatic","summary":"Neighbor cult burning offerings in a backyard barrel","flavor":"A ring of neighbors around a burn barrel every full moon, feeding it things that were never supposed to burn that clean."},{"name":"The Coach Who Never Ages","cr":4,"role":"elite","type":"Fiend","size":"Medium","frame":"cambion","model":"cambion","summary":"Ageless little-league coach spanning two decades unchanged","flavor":"Has led the same little-league team for twenty-two straight seasons and looks exactly as he did in the first team photo."},{"name":"Skin-Deep Scoutmaster","cr":4,"role":"elite","type":"Fiend","size":"Medium","frame":"doppelganger","model":"doppelganger","summary":"Doppelganger scoutmaster who returns from trips one kid short","flavor":"Leads camping trips into the woods behind the development and always brings back one fewer kid than he took, plus one new smile."},{"name":"The Perfect Father Next Door","cr":4,"role":"elite","type":"Fiend","size":"Medium","frame":"incubus","model":"incubus","summary":"Model neighborhood father with a shed nobody mentions","flavor":"Never misses a game, always has the grill going, and keeps a locked shed out back that the whole street has learned not to mention."},{"name":"Static-Cling Poltergeist Swarm","cr":4,"role":"elite","type":"Undead","size":"Large","frame":"swarm-of-dretches","model":"swarm-of-dretches","summary":"House-wide micro-hauntings that unify into one coordinated threat","flavor":"A house full of small hauntings — flickering nightlights, cold spots, moved keys — that only reveal themselves as one coordinated thing when cornered."},{"name":"Cursed Above-Ground Deep One Broodmother","cr":5,"role":"elite","type":"Aberration","size":"Large","frame":"otyugh","model":"otyugh","summary":"Matured pool-horror now spawning across the cul-de-sac","flavor":"The original pool-thing from three doors down, matured and spawning; the whole cul-de-sac's chlorine budget has quietly tripled."},{"name":"Renovation Golem, Load-Bearing Model","cr":5,"role":"elite","type":"Construct","size":"Large","frame":"flesh-golem","model":"flesh-golem","summary":"Drywall-and-lumber golem built from a shortcut renovation curse","flavor":"Built from mismatched drywall, salvaged studs, and whatever the last flip-house crew left behind, animated by a contractor's shortcut curse."},{"name":"The Photo Album Hag","cr":5,"role":"elite","type":"Fey","size":"Medium","frame":"night-hag","model":"night-hag","summary":"Photo-collecting hag who edits herself into family albums","flavor":"Collects family photo albums door to door for 'the historical society' and edits herself into every family that lets her keep one."},{"name":"The Neighborhood Watch Captain","cr":5,"role":"elite","type":"Aberration","size":"Medium","frame":"grell","model":"grell","summary":"All-seeing patrol captain who knows every closed-door secret","flavor":"Patrols at all hours in a golf cart with a spotlight, and somehow always knows exactly what happened behind every closed door on the block."},{"name":"Backyard Above-Ground Pool Shark","cr":5,"role":"elite","type":"Monstrosity","size":"Medium","frame":"umber-hulk","model":"umber-hulk","summary":"Oversized predator circling under a backyard pool's liner","flavor":"Something with far too many teeth for a four-foot pool has been circling under the vinyl liner since the last pool party."},{"name":"The Ham Radio Operator","cr":6,"role":"elite","type":"Aberration","size":"Medium","frame":"void-monk-zerth","model":"void-monk-zerth","summary":"Attic ham-radio operator receiving transmissions from nowhere","flavor":"Runs a shortwave rig in the attic that picks up something answering back that was never broadcasting from anywhere on Earth's dial."},{"name":"The PTA Vice President","cr":6,"role":"elite","type":"Fiend","size":"Medium","frame":"chasme","model":"chasme","summary":"PTA lieutenant gathering names for an unseen master list","flavor":"Second-in-command to the block's real horror, buzzing between bake sales gathering names for a list nobody's seen the end of."},{"name":"Backyard Grill Fire Elemental","cr":6,"role":"elite","type":"Elemental","size":"Medium","frame":"azer-pyromancer","model":"azer-pyromancer","summary":"Never-extinguished grill fire that's still hungry to cook","flavor":"Someone's charcoal grill fire never went out after the block party; it's been cooking ever since, and it's still hungry."},{"name":"The Cul-de-Sac's Second Family","cr":6,"role":"elite","type":"Monstrosity","size":"Medium","frame":"drider","model":"drider","summary":"Multi-limbed horror that assembles into a fake nuclear family","flavor":"A many-limbed thing that arranges itself into a mother, father, and two kids for the length of a driveway conversation, then unfolds once the door shuts."},{"name":"Lawn-Order Enforcer, Senior Patrol","cr":7,"role":"elite","type":"Construct","size":"Large","frame":"shield-guardian","model":"shield-guardian","summary":"Promoted HOA golem whose citations double as curses","flavor":"The block's original code-enforcement golem has been promoted; it now issues citations that are also curses."},{"name":"The Block Party Ringmaster","cr":7,"role":"elite","type":"Fiend","size":"Large","frame":"vrock","model":"vrock","summary":"Block-party organizer who plans a yearly disappearance","flavor":"Organizes the annual street party with unnerving precision, down to exactly who disappears in the bounce-house line each year."},{"name":"Attic Insulation Horror","cr":7,"role":"elite","type":"Monstrosity","size":"Large","frame":"hook-horror","model":"hook-horror","summary":"Attic-dwelling horror slowly widening the crawlspace over decades","flavor":"Something moved into the pink fiberglass batting between the joists decades ago and has been slowly widening the crawlspace ever since."},{"name":"Master of the Costume Party","cr":8,"role":"high","type":"Fiend","size":"Large","frame":"oni","model":"oni","summary":"Costume-party host whose winners are never seen again","flavor":"Hosts the block's annual costume bash wearing a mask indistinguishable from a face, and everyone who wins 'best costume' stops being seen after."},{"name":"The Substitute Mailman's Supervisor","cr":9,"role":"high","type":"Undead","size":"Medium","frame":"vampire-nightbringer","model":"vampire-nightbringer","summary":"Route supervisor delivering unsolicited packages to every house","flavor":"Oversees the whole route from an unmarked postal truck, delivering something to every house that requested nothing."},{"name":"Development Overseer, Phase Two","cr":10,"role":"high","type":"Construct","size":"Huge","frame":"stone-golem","model":"stone-golem","summary":"Slab-built golem grading a phantom lot off the map","flavor":"Built from the foundation slabs of the houses that never got finished, it's been quietly grading a lot that isn't on any map."},{"name":"The First HOA Board","cr":10,"role":"high","type":"Undead","size":"Medium","frame":"death-knight-aspirant","model":"death-knight-aspirant","summary":"Undead HOA founders still voting on ordinances forever","flavor":"Five founding board members, still convening in the clubhouse basement, still voting unanimously on ordinances no living resident agreed to."},{"name":"The Perfect Family, Fully Grown","cr":11,"role":"high","type":"Fiend","size":"Large","frame":"marilith","model":"marilith","summary":"Skin-family horror that stopped pretending to be separate people","flavor":"What the skin-wearing family becomes once it stops bothering to look like four separate people at all."},{"name":"The Neighborhood Watch, Fully Awake","cr":11,"role":"high","type":"Aberration","size":"Large","frame":"mind-thief-arcanist","model":"mind-thief-arcanist","summary":"Block-wide surveillance horror that has begun to act","flavor":"Every porch light on the block is one of its eyes now, and it has stopped just watching."},{"name":"The Substitute Principal","cr":12,"role":"high","type":"Fiend","size":"Medium","frame":"erinyes","model":"erinyes","summary":"Fill-in principal whose detention slips are binding contracts","flavor":"Called in to run the school when the real principal 'took leave,' she rewrites detention slips into something closer to binding contracts."},{"name":"Superstore Overnight Stock Horror","cr":12,"role":"high","type":"Aberration","size":"Large","frame":"void-monk-psion","model":"void-monk-psion","summary":"Overnight stocker that spells warnings in the aisle layout","flavor":"Something restocks the strip-mall superstore's shelves after close, in patterns that spell out things in the aisle layout by morning."},{"name":"The Cable Guy Who Was Never Scheduled","cr":13,"role":"high","type":"Fiend","size":"Medium","frame":"rakshasa","model":"rakshasa","summary":"Uninvited cable installer who tunes homes to impossible channels","flavor":"Shows up during the four-hour window nobody actually booked, and every house he services starts picking up channels that don't exist."},{"name":"The First Family of the Development","cr":15,"role":"apex","type":"Undead","size":"Medium","frame":"mummy-lord","model":"mummy-lord","summary":"Founder-family entombed beneath the model home's foundation","flavor":"Buried under the model home's foundation when the development broke ground, and the whole subdivision was built as its reliquary."},{"name":"The Idea of a Perfect Lawn","cr":16,"role":"apex","type":"Plant","size":"Gargantuan","frame":"gulthias-blight","model":"gulthias-blight","summary":"Root-system ideal that prunes any lawn that stands out","flavor":"An ideal so total it's grown roots under every yard on the block, pruning any resident who lets their grass get too tall — or too green."},{"name":"The Last Bell of the School Year","cr":16,"role":"apex","type":"Undead","size":"Huge","frame":"death-knight","model":"death-knight","summary":"Eternal dismissal bell that never released its final class","flavor":"A dismissal bell that never actually let the last class out; it's been ringing the same three-o'clock chime under the school for generations."},{"name":"The Whole Street, Awake","cr":17,"role":"apex","type":"Aberration","size":"Gargantuan","frame":"undead-eye-tyrant","model":"undead-eye-tyrant","summary":"Whole cul-de-sac revealed as one house-wearing organism","flavor":"Every house on the cul-de-sac turns out to be one organism wearing driveways for a face, and it has just noticed it has neighbors watching back."},{"name":"The Idea of Back-to-School Night","cr":19,"role":"apex","type":"Fiend","size":"Huge","frame":"balor","model":"balor","summary":"Annual gymnasium dread wearing everyone's worst self at once","flavor":"An institutional dread so vast it manifests once a year in the gymnasium, wearing every parent and teacher's worst version of themselves at once."},{"name":"The Development That Was Never Finished","cr":21,"role":"apex","type":"Undead","size":"Gargantuan","frame":"lich","model":"lich","summary":"Bankrupt developer's undying will still building empty lots","flavor":"The developer who went bankrupt mid-build bound his own unfinished vision into undeath, and the empty lots are still filling in on their own schedule."},{"name":"Backyard Tetherball Wisp","cr":0.25,"role":"mook","type":"Undead","size":"Tiny","frame":"will-o-wisp","model":"will-o-wisp","summary":"Ghost light endlessly circling a broken tetherball pole","flavor":"A pale light that spins around the pole where the tetherball snapped off years ago, still keeping score against an opponent who left."},{"name":"Split-Level Basement Ooze","cr":0.5,"role":"mook","type":"Ooze","size":"Medium","frame":"gray-ooze","model":"gray-ooze","summary":"Basement floor-drain ooze that never receded after a storm","flavor":"Seeped up through the unfinished basement's floor drain during the last big storm and never seeped back down."},{"name":"Trick-or-Treat Bag Snatcher","cr":0.5,"role":"mook","type":"Fey","size":"Small","frame":"sprite","model":"sprite","summary":"Halloween sprite that swaps candy for something inedible","flavor":"Darts between porch lights on Halloween swapping good candy for something that was never meant to be eaten."},{"name":"The Kid Who Never Came Home","cr":1,"role":"mook","type":"Undead","size":"Small","frame":"skeleton","model":"skeleton","summary":"Ghost child endlessly biking his last-seen route home","flavor":"Still riding his bike home past curfew, every night, along the exact route where he was last seen thirty years ago."},{"name":"Backyard Above-Ground Pool Leech Swarm","cr":1,"role":"mook","type":"Ooze","size":"Medium","frame":"swarm-of-piranhas","model":"swarm-of-piranhas","summary":"Splintered pool-horror fragments swarming as biting leeches","flavor":"Something split off from the main pool-thing into dozens of smaller, blood-hungry pieces after the last shock treatment."},{"name":"Little League Bleacher Ghoul","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"ghoul","model":"ghoul","summary":"Undead superfan haunting a closed field's bleachers","flavor":"Sits in the same bleacher seat at every game, cheering a team that stopped existing after the field closed, and eyeing the concession stand."},{"name":"Backyard Fireworks Mephit","cr":1,"role":"mook","type":"Elemental","size":"Small","frame":"smoke-mephit","model":"smoke-mephit","summary":"Dud-firework mephit hunting for something bigger to ignite","flavor":"Sparked to unlife from a dud bottle rocket on the Fourth, it's been looking for something bigger to detonate ever since."},{"name":"The Man in the Rubber Mask","cr":3,"role":"elite","type":"humanoid","size":"Medium","frame":"warrior-veteran","model":"warrior-veteran","summary":"Silent knife-stalker in a rubber mask, cuts the power first","flavor":"He doesn't run, doesn't talk, and the mask never quite fits his face right — like it's a size too small for whatever's under it. Cuts power to the block before he starts.","source":"archetype","sourceNote":"stock slasher-archetype (unmasked, unnamed stalker type — no specific franchise silhouette)"},{"name":"The Neighbor Who Isn't","cr":0.5,"role":"mook","type":"humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"A neighbor replaced, wearing the body a little wrong","flavor":"Waters the lawn at 2 AM. Smiles too wide at the mailbox. Something wears the neighbor like a coat that's still learning how elbows work.","source":"archetype","sourceNote":"body-snatcher/pod-person stock archetype (generic, no specific 50s-film IP)"},{"name":"The Homeowners' Association","cr":2,"role":"elite","type":"humanoid","size":"Medium","frame":"noble","model":"noble","summary":"Cul-de-sac conformity cult in matching cardigans","flavor":"Matching cardigans, identical lawns, a smile that's a citation waiting to happen. They vote unanimously. They vote for you next.","source":"archetype","sourceNote":"too-perfect-family/HOA conformity archetype, original"},{"name":"The Thing in the Storm Drain","cr":6,"role":"high","type":"aberration","size":"Large","frame":"grell","model":"grell","summary":"Shapeless lurker that surfaces through storm drains after rain","flavor":"It doesn't need a face because the neighborhood kids provide the imagination for it. Rains bring it up from the culvert; the culvert never quite drains right after.","source":"archetype","sourceNote":"under-the-street / storm-drain lurker stock archetype (deliberately not the well-known clown)"},{"name":"The Thing Under the Bed","cr":1,"role":"mook","type":"aberration","size":"Small","frame":"blind-deep-stalker","model":"blind-deep-stalker","summary":"Blind floor-level lurker only real in the dark","flavor":"Only exists between the mattress and the floor, and only when the light's off. Every kid on the block has independently drawn the same picture of it.","source":"archetype","sourceNote":"under-the-bed/closet-monster nursery archetype, original design"},{"name":"Static Bride","cr":5,"role":"high","type":"undead","size":"Medium","frame":"wight","model":"wight","summary":"Reanimated stitched-together undead bride, disrupts electronics","flavor":"Stitched back together from parts that never asked to be a set. Every TV on the block snows over when she walks past; she's looking for the hands that made her.","source":"public-domain","sourceNote":"the Bride/animated-corpse motif — Shelley's Frankenstein (1818, PD) & 19th-c. reanimation folklore, NOT any studio's visual design"},{"name":"The Man Who Sold the House","cr":7,"role":"high","type":"fiend","size":"Medium","frame":"cambion","model":"cambion","summary":"Devil-bargain realtor collecting on unread contracts","flavor":"Every family on this street signed something they didn't read. He still holds the paper, and the paper is still due.","source":"public-domain","sourceNote":"deal-with-the-devil / crossroads-bargain motif — universal folklore + Faust legend (pre-1929 tellings, PD)"},{"name":"Medusa of the Mall","cr":9,"role":"apex","type":"monstrosity","size":"Medium","frame":"yuan-ti-abomination","model":"yuan-ti-abomination","summary":"Mythic Gorgon relocated to the dead mall's cosmetics counter","flavor":"Works the perfume counter under fluorescent light that never shows her eyes. The food court has forty statues who lingered too long at her register.","source":"public-domain","sourceNote":"Medusa — Greek myth (Ovid, Metamorphoses, ancient/PD); OUR setting recontext, not any film design"},{"name":"The Kraken in the Deep End","cr":10,"role":"apex","type":"monstrosity","size":"Huge","frame":"remorhaz","model":"remorhaz","summary":"Ancient sea-legend leviathan squatting in a condemned pool","flavor":"The community pool closed for 'renovations' in 1983 and never reopened. Something ancient and briny decided the deep end was close enough to home.","source":"public-domain","sourceNote":"the Kraken — Norse/Scandinavian sea-legend (pre-modern folklore, PD)"},{"name":"The Toy That Loves You Back","cr":0.5,"role":"mook","type":"construct","size":"Small","frame":"animated-armor","model":"animated-armor","summary":"Possessed toy that relocates itself to your room at night","flavor":"Batteries not included, malice included free. It waits on the shelf all day, perfectly still, counting whose room it's going to be in tonight.","source":"archetype","sourceNote":"cursed-toy/possessed-plaything archetype, original design (no specific doll-franchise likeness)"},{"name":"The Refrigerator That Remembers","cr":1,"role":"mook","type":"construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"Cursed kitchen appliance that preserves things unnaturally","flavor":"Hums a little too rhythmically. Keeps things fresh that shouldn't still be recognizable. The ice maker only runs when no one's watching.","source":"archetype","sourceNote":"cursed-appliance archetype, original design"},{"name":"The Arcade Cabinet with One More Life","cr":4,"role":"elite","type":"construct","size":"Medium","frame":"mimic","model":"mimic","summary":"Haunted arcade cabinet that keeps its high-scorer","flavor":"High score never changes because the last kid who beat it never left the arcade. It only takes quarters, and it always has exact change waiting in the slot.","source":"archetype","sourceNote":"cursed-arcade-machine archetype, original design (generic 'haunted cabinet,' no specific game IP)"},{"name":"The Babysitter's Watcher","cr":3,"role":"elite","type":"humanoid","size":"Medium","frame":"bandit-enforcer","model":"desperate-bandit","summary":"Home-invader who calls from inside the house first","flavor":"He's already inside before the phone rings the second time. The kids upstairs are fine. He just wanted her to know he could've stopped that.","source":"archetype","sourceNote":"stalker-on-the-phone-in-the-house urban-legend archetype, original (the call-is-coming-from-inside trope, generic)"},{"name":"The Cul-de-Sac Werething","cr":4,"role":"high","type":"humanoid","size":"Medium","frame":"werewolf","model":"werewolf","summary":"Suburban werewolf-neighbor, folklore lycanthropy in a cul-de-sac","flavor":"Coaches Little League. Grills every Sunday. On the full moon the whole street knows to keep the dog in and not ask questions in the morning.","source":"folklore","sourceNote":"European werewolf/lycanthropy folk tradition (settled, non-Indigenous, widely public-domain in literary form)"},{"name":"Renfield of Maple Court","cr":0.25,"role":"mook","type":"humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"Thrall-servant mook, devoted to something unseen in the house","flavor":"Eats bugs off the porch and swears the new guy in the house at the end of the block 'just needs some time to settle in.' He's very devoted.","source":"public-domain","sourceNote":"Renfield — Stoker's Dracula (1897, PD), the servant/thrall archetype specifically, not Dracula himself"},{"name":"The Count of the Cul-de-Sac","cr":12,"role":"apex","type":"undead","size":"Medium","frame":"night-hag","model":"night-hag","summary":"Stoker-lineage vampire lord who bought the biggest house in cash","flavor":"Bought the biggest house on the block in cash, never during daylight hours. Invites you in exactly once. That's all he needs.","source":"public-domain","sourceNote":"Stoker's Dracula (1897, PD) — the literary vampire lord, our own suburban recontext, not any film's visual design"},{"name":"The Skeleton in Every Closet","cr":0.25,"role":"mook","type":"undead","size":"Medium","frame":"skeleton","model":"skeleton","summary":"Literal skeleton-in-the-closet, one per household","flavor":"Every house on the street has one, and every family swears it's a coincidence. It rattles the coat hangers when the furnace kicks on.","source":"public-domain","sourceNote":"generic reanimated skeleton — folkloric/literary undead, no owner, ancient stock motif"},{"name":"The Lawn Ornament That Turned","cr":2,"role":"mook","type":"construct","size":"Small","frame":"gargoyle","model":"gargoyle","summary":"Animated yard-decor ambush predator, still until you're alone","flavor":"Every yard has one — gnome, birdbath cherub, plastic flamingo. They hold still for the mail carrier. They don't hold still for you.","source":"archetype","sourceNote":"animated-yard-decor archetype (garden gnome / gargoyle-adjacent, original), stone-creature motif is ancient/uncopyrightable"},{"name":"The Debt Collector","cr":6,"role":"high","type":"undead","size":"Medium","frame":"wraith","model":"wraith","summary":"Folkloric collector-of-debts undead, clipboard and windbreaker","flavor":"Wears a windbreaker and carries a clipboard. Every house owes him something eventually — a memory, a name, a Sunday afternoon. He always collects on schedule.","source":"folklore","sourceNote":"psychopomp / grim-collector folk motif (universal death-messenger tradition, settled and non-Indigenous)"},{"name":"The PTA","cr":3,"role":"elite","type":"swarm","size":"Medium","frame":"swarm-of-rats","model":"swarm-of-rats","summary":"Hive-mind swarm of identical, over-informed suburban parents","flavor":"They vote as one, speak in overlapping half-sentences, and know your kid's grades before you do. Disagreement is not on the agenda.","source":"archetype","sourceNote":"hive-mind conformity-swarm archetype, original (mundane-turned-wrong social horror, no IP basis)"}],
 "cosmic":[{"name":"Static-Born Whelp","cr":0.125,"role":"mook","type":"Aberration","size":"Small","frame":"lantern-sage","model":"lantern-sage","summary":"tiny drowned-language larva, forgets its own half-word","flavor":"A newborn scrap of the drowned language given a body — it chitters half a syllable of an unfinishable name and forgets the rest instantly."},{"name":"Deep-Kin Netcaster","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"fish-folk","model":"fish-folk","summary":"gilled fish-hybrid raider, classic deep-one coastal breed","flavor":"A fish-eyed coastal breed that traded air-breathing kin for something below the tide line generations back; drags nets full of things that aren't fish."},{"name":"Echo-Faced Pilgrim","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"robed cultist, face slowly reshaping toward its god","flavor":"A cultist of the answering wonder, face rearranged toward whatever last spoke to it; still mostly a person, technically."},{"name":"Angle-Wrong Creeper","cr":0.25,"role":"mook","type":"Aberration","size":"Medium","frame":"piercer","model":"piercer","summary":"non-Euclidean ambush lurker, wrong from every angle","flavor":"Geometry that argues with itself — from one side a stalactite, from the other a limb; it never resolves, and neither does what it bites."},{"name":"Star-Spat Larva","cr":0.25,"role":"mook","type":"Aberration","size":"Small","frame":"darkmantle","model":"darkmantle","summary":"star-spawn hatchling, smothers before it thinks","flavor":"Fell out of the sky still warm from somewhere with no sky of its own; smothers first, digests the question of why later."},{"name":"Choir-Static Wisp","cr":0.25,"role":"mook","type":"Elemental","size":"Small","frame":"smoke-mephit","model":"smoke-mephit","summary":"formless droning noise-wisp, hums the wrong language","flavor":"A sound with no source, given just enough shape to annoy you; it hums the drowned language slightly off-key, forever."},{"name":"Shoggoth Spawnling","cr":0.5,"role":"mook","type":"Ooze","size":"Medium","frame":"gray-ooze","model":"gray-ooze","summary":"eye-budding protoplasmic mass, shoggoth in miniature","flavor":"A gray, roiling mass no bigger than a barrel, budding eyes and mouths it doesn't keep for long; the full-grown thing it's shed from is somewhere close, and larger."},{"name":"Vault-Drift Serf","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist-fanatic","model":"cultist-fanatic","summary":"generational cult serf, still bows to the old angles","flavor":"Recruited off some drowned world's docks generations back; still bows at the old angles, still hears the old choir."},{"name":"Gravel-Star Mite","cr":0.5,"role":"mook","type":"Monstrosity","size":"Small","frame":"cockatrice","model":"cockatrice","summary":"small star-spawn splinter, petrifying gaze it can't explain","flavor":"A star-spawn splinter no bigger than a dog, all beak and impossible joint-count; petrifies with a look it doesn't understand having."},{"name":"Wrong-Angle Watcher","cr":1,"role":"mook","type":"Aberration","size":"Medium","frame":"gibbering-mouther","model":"gibbering-mouther","summary":"babbling mouth-patch, ground disagrees with your feet","flavor":"A patch of geometry that mutters in every direction at once — approach it and the ground itself seems to disagree with your feet."},{"name":"Star-Spawn Grazer","cr":3,"role":"elite","type":"Monstrosity","size":"Large","frame":"phase-spider","model":"phase-spider","summary":"half-phased star-spawn cattle, grazes on visible light","flavor":"Blinks half-in, half-out of the visible world, cropping light like grass; it was probably once something's livestock."},{"name":"Tentacled Horror of the Drowned Vault","cr":3,"role":"elite","type":"Aberration","size":"Large","frame":"carrion-crawler","model":"carrion-crawler","summary":"classic many-tentacled cellar-horror, paralyzing touch","flavor":"A many-limbed thing that hauls itself up from flooded sub-cellars on a forest of feeling tentacles, paralyzing whatever it touches before it decides what to do with it."},{"name":"Length-Wrong Herald","cr":4,"role":"elite","type":"Aberration","size":"Large","frame":"clawed-drowner","model":"clawed-drowner","summary":"herald-thing that attacks mid-syllable of its own name","flavor":"Speaks the opening of its own name every time it attacks; nobody has heard it finish, and the theory is nobody's meant to."},{"name":"Basalt Geometer","cr":4,"role":"elite","type":"Construct","size":"Medium","frame":"helmed-horror","model":"helmed-horror","summary":"angle-enforcing construct, warps the room it guards","flavor":"Built by something to enforce angles that don't exist here; every room it stands in slowly stops making sense."},{"name":"Star-Drunk Colossus-Kin","cr":5,"role":"elite","type":"Giant","size":"Huge","frame":"hill-giant","model":"hill-giant","summary":"starlight-drunk giant, too big for this sky","flavor":"A giant that drank starlight instead of ale one bad night; too big for this sky, and it knows it, and it's furious about it."},{"name":"Drowned-Tongue Cantor","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"mage","model":"mage","summary":"cultist-mage, casts by singing a language that hurts","flavor":"Learned three words of the drowned language and it was two too many; casts by half-singing syllables that hurt to hear correctly."},{"name":"Devouring Mass of the Drift","cr":6,"role":"elite","type":"Ooze","size":"Large","frame":"black-pudding","model":"black-pudding","summary":"black shifting shoggoth-mass, dissolves and remembers shapes","flavor":"A shoggoth proper, or near enough — a shifting black bulk crawling with makeshift eyes, dissolving whatever it rolls over and remembering the shape for later."},{"name":"Void-Touched Ascetic","cr":5,"role":"elite","type":"Aberration","size":"Medium","frame":"void-monk-zerth","model":"void-monk-zerth","summary":"void-monk cultist, trained never to look at its god","flavor":"Trained a martial discipline built entirely around not looking directly at the thing it worships; occasionally fails."},{"name":"Between-Star Marauder","cr":7,"role":"elite","type":"Aberration","size":"Medium","frame":"astral-raider-knight","model":"astral-raider-knight","summary":"star-spawn knight-raider, rides the seams between stars","flavor":"Rides the seams between named stars, raiding worlds that made the mistake of being finishable sentences."},{"name":"Choir of the Unbuilt Cathedral","cr":9,"role":"high","type":"Aberration","size":"Medium","frame":"gray-chaos-frog","model":"gray-chaos-frog","summary":"compressed cult-congregation, attacks argue with each other","flavor":"A congregation compressed into one body, still arguing internally over doctrine; every attack is a different faction's opinion."},{"name":"Cartographer of Wrong Angles","cr":10,"role":"high","type":"Aberration","size":"Large","frame":"elder-deep-thing","model":"elder-deep-thing","summary":"ancient elder-thing cartographer, maps that unravel minds","flavor":"Maps places that don't cohere and insists they're accurate; anyone who reads its charts starts seeing the seams in normal rooms too."},{"name":"Star-Spawn Bishop","cr":11,"role":"high","type":"Aberration","size":"Medium","frame":"mind-thief-arcanist","model":"mind-thief-arcanist","summary":"brain-warping star-spawn cleric, sermons rearrange your mind","flavor":"Ordained by something that doesn't have a mouth to ordain with; its sermons rearrange the listener's sense of up."},{"name":"The Waking Eye Beneath","cr":13,"role":"high","type":"Aberration","size":"Large","frame":"eye-tyrant","model":"eye-tyrant","summary":"floating many-eyed orb horror, reads unwritten futures","flavor":"A many-eyed orb the size of a wagon, floating up from some flooded temple-shaft, each stalk-eye reading a different page of a book that hasn't been written yet."},{"name":"The Sound With No Source","cr":15,"role":"apex","type":"Aberration","size":"Gargantuan","frame":"elemental-cataclysm","model":"net-new: a vast half-formed silhouette woven from visible, rippling sound-waves","summary":"bodiless voice-horror, borrowed shape, something answers back","flavor":"It has never had a body; this one is borrowed, argued-over, and already trying to unbecome itself. When it speaks, the drowned language comes out clean, and something answers from very far away."},{"name":"The Wonder That Answers Back","cr":18,"role":"apex","type":"Aberration","size":"Gargantuan","frame":"eye-tyrant","model":"net-new: a star-scaled orb-and-limb mass whose geometry disagrees with itself","summary":"the realm's Great-Old-One, a correct answer always costs you","flavor":"The realm's sleeping Great Old One — ask it a question and it answers, correctly, in a name too long to finish; the answer costs you something you didn't offer, every single time."},{"name":"Tide-Slick Grub","cr":0.125,"role":"mook","type":"Ooze","size":"Tiny","frame":"lemure","model":"lemure","summary":"tiny drift-ooze droplet, twitches toward body heat","flavor":"A finger-length droplet of the drift-mass that never quite dries; it mostly just twitches toward warmth."},{"name":"Drowned-Docks Netboy","cr":0.125,"role":"mook","type":"Humanoid","size":"Small","frame":"kobold","model":"kobold","summary":"runt deep-kin fisher, hauls nets too heavy for it","flavor":"A child-sized deep-kin runt too small to fish alone; it still tries, hauling nets twice its weight up from the black water."},{"name":"Salt-Choir Initiate","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"guard","model":"guard","summary":"fresh cult recruit, flinches at its own chanting","flavor":"Newly sworn to the drowned congregation; still flinches at its own chanting."},{"name":"Half-Seen Crawler","cr":0.25,"role":"mook","type":"Aberration","size":"Small","frame":"blind-deep-stalker","model":"blind-deep-stalker","summary":"angle-dependent stalker, only visible from some angles","flavor":"Visible only from certain angles, like a smudge on a lens; the rest of the time it's simply already behind you."},{"name":"Nursery-Vault Runt","cr":0.25,"role":"mook","type":"Aberration","size":"Tiny","frame":"flying-snake","model":"flying-snake","summary":"premature hatchling, flits weakly chirping half a word","flavor":"Hatched too early from a drowned egg-clutch, it flits weakly through flooded corridors chirping half a word."},{"name":"Deep-Kin Harpooner","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"fish-folk-whip","model":"fish-folk-whip","summary":"veteran gilled harpooner, drags catch down regardless","flavor":"A veteran of the coastal breed, favoring a barbed line over a net; drags catch back down whether it's still moving or not."},{"name":"Cyst of Small Eyes","cr":0.5,"role":"mook","type":"Ooze","size":"Small","frame":"gray-ooze","model":"gray-ooze","summary":"palm-sized eye-cluster ooze bud, eyes never blink together","flavor":"A fist-sized knot of shoggoth-stuff that budded off wrong; it's mostly eyes, and none of them blink together."},{"name":"Static-Fed Familiar","cr":0.5,"role":"mook","type":"Elemental","size":"Tiny","frame":"smoke-mephit","model":"smoke-mephit","summary":"cult-kept static wisp, fattens on half-heard words","flavor":"Kept as a pet by a cantor who feeds it half-heard words; it grows fat on syllables and thin on silence."},{"name":"Barnacle-Grown Thrall","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist-fanatic","model":"cultist-fanatic","summary":"barnacle-crusted cult thrall, still kneels on schedule","flavor":"So long submerged in service that crustacean growth has fused to its joints; it still kneels on schedule."},{"name":"Wharf-Rot Feeler","cr":0.5,"role":"mook","type":"Aberration","size":"Small","frame":"darkmantle","model":"darkmantle","summary":"pier-dwelling smother-thing, drops on warm footsteps","flavor":"Clings under piers where the water goes the wrong color; drops when something warm walks overhead."},{"name":"Star-Chipped Hatchling","cr":0.5,"role":"mook","type":"Monstrosity","size":"Small","frame":"stirge","model":"stirge","summary":"tiny star-fallen splinter, still searching for its parent","flavor":"A splinter no bigger than a housecat, all needle-mouth, that fell alongside something much worse and hasn't found it yet."},{"name":"Wrong-Count Mimicker","cr":0.5,"role":"mook","type":"Aberration","size":"Medium","frame":"piercer","model":"piercer","summary":"shape-mimic with a miscounted number of features","flavor":"Copies the shape of ordinary things nearby, but always gets the number of legs, teeth, or windows slightly off."},{"name":"Choking Reef Polyp","cr":0.5,"role":"mook","type":"Ooze","size":"Small","frame":"violet-fungus","model":"violet-fungus","summary":"altar-bound polyp growth, lashes at loitering worshippers","flavor":"Grows on drowned altars like coral, lashing anything that lingers too near the offering bowl."},{"name":"Bell-Tongued Herald-Runt","cr":1,"role":"mook","type":"Aberration","size":"Small","frame":"brain-crawler","model":"brain-crawler","summary":"bell-ringing messenger aberration, tolls unwanted summons","flavor":"A messenger-thing that rings when it moves, each toll a fragment of a summons nobody asked for."},{"name":"Kelp-Draped Netcaster","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"fish-folk-monitor","model":"fish-folk-monitor","summary":"senior deep-kin overseer, commands netcasters silently","flavor":"Senior among the coastal breed, trailing kelp like a cloak; commands the smaller netcasters without a word."},{"name":"Choir-Bound Flagellant","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"death-cultist","model":"death-cultist","summary":"self-flagellating cultist, tunes itself to unheard rhythm","flavor":"Whips itself in time with a rhythm only it can hear, certain the pain is a kind of tuning."},{"name":"Star-Spat Grazer-Calf","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"griffon","model":"griffon","summary":"juvenile star-spawn beast, crops light-motes from the air","flavor":"A juvenile star-spawn beast, still mostly solid, cropping light-motes out of the air with a beak too wide for its skull."},{"name":"Drift-Snarled Netling","cr":1,"role":"mook","type":"Ooze","size":"Medium","frame":"ochre-jelly","model":"ochre-jelly","summary":"net-tangled ooze, drags its own net as a lure","flavor":"Ooze tangled with actual fishing net dragged up from the deep; it hunts by dragging the net behind it like a lure."},{"name":"Fathom-Whisper Cultist","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist-roster-base-2024-stat-blocks","model":"cultist-roster-base-2024-stat-blocks","summary":"fountain-side cultist, repeats fragments it hears in water","flavor":"Hears the drowned language in running water and repeats fragments of it to anyone standing near a fountain."},{"name":"Rib-Cracked Thrall-Sergeant","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"berserker","model":"berserker","summary":"repeatedly-broken cult enforcer, fights past its own pain","flavor":"Broken and reset so many times in service that its posture is permanently wrong; it fights like the pain already happened."},{"name":"Gravel-Star Broodmite Swarm","cr":2,"role":"mook","type":"Swarm","size":"Medium","frame":"swarm-of-stirges","model":"swarm-of-stirges","summary":"clutch of tiny star-spawn splinters, moves as one mass","flavor":"A clutch of star-spawn splinters hatched together, moving as one twitching, beaking mass."},{"name":"Basalt Chanter-Construct","cr":2,"role":"mook","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"empty armor construct, hums drowned language on patrol","flavor":"An empty suit of vault-armor that hums the drowned language through its helm slit, walking patrol for masters long dissolved."},{"name":"Slack-Jawed Deep-Kin Brute","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"deep-brute","model":"deep-brute","summary":"heavyset deep-kin muscle, jaw unhinges when excited","flavor":"Muscle bred for hauling nets the size of houses; its jaw unhinges when it's excited, which is often."},{"name":"Two-Faced Pilgrim","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"doppelganger","model":"doppelganger","summary":"double-faced cultist, argues with itself about which face is real","flavor":"A pilgrim whose reshaping went further than most — it now wears two faces at once, arguing about which one is real."},{"name":"Void-Touched Novice","cr":2,"role":"mook","type":"Aberration","size":"Medium","frame":"void-monk-monk","model":"void-monk-monk","summary":"beginner void-monk, eyes already filming over","flavor":"Just beginning the discipline of not-looking; its eyes are already starting to film over from the strain."},{"name":"Length-Wrong Runt","cr":2,"role":"mook","type":"Aberration","size":"Medium","frame":"secret-eye","model":"secret-eye","summary":"minor herald-cousin, half-syllable attacks and endless breath","flavor":"A smaller cousin of the heralds, its half-syllable attacks are weaker, but it never seems to run out of breath."},{"name":"Foam-Bled Zealot","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"aberrant-cultist","model":"aberrant-cultist","summary":"foaming zealot, recites an unfinishable hymn as devotion","flavor":"Foams at the mouth reciting the opening verse of a hymn with no known end; convinced finishing it would be a mercy."},{"name":"Coil-Fused Netwife","cr":2,"role":"mook","type":"Monstrosity","size":"Medium","frame":"wererat","model":"wererat","summary":"eel-legged deep-kin matriarch, endlessly weaves new nets","flavor":"A deep-kin matriarch whose lower half has fused into something more eel than leg; she never stops weaving new nets."},{"name":"Undertow Grapple-Thing","cr":2,"role":"mook","type":"Aberration","size":"Medium","frame":"grick","model":"grick","summary":"stairwell tentacle-ambusher, hauls victims into flooded dark","flavor":"Waits in the flooded dark of vault stairwells, a barbed tentacle-mass that hauls the careless down before they can shout."},{"name":"Reef-Bone Sentinel","cr":2,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton-warrior","model":"skeleton-warrior","summary":"coral-grown drowned skeleton, bones spell hymn fragments","flavor":"Drowned centuries ago, its bones now grown through with coral in patterns that spell fragments of the old choir."},{"name":"Choir-Static Swarm","cr":2,"role":"mook","type":"Swarm","size":"Large","frame":"swarm-of-bats","model":"swarm-of-bats","summary":"flocking noise-wisp swarm, drone loud enough to hurt teeth","flavor":"Dozens of noise-wisps flocking together, their combined drone loud enough to make teeth ache."},{"name":"Wrongly-Jointed Fisherman","cr":2,"role":"mook","type":"Aberration","size":"Medium","frame":"ettercap","model":"ettercap","summary":"extra-jointed ex-fisherman, casts lines with unnatural reach","flavor":"Once a fisherman, its elbows and knees now bend an extra way; it casts a line with unsettling, extra reach."},{"name":"Depth-Warped Enforcer","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"bugbear-stalker","model":"bugbear-stalker","summary":"joint-warped cult enforcer, hits harder than it should","flavor":"Cult muscle whose limbs have started growing extra joints from prolonged proximity to the choir; it hits harder than its size suggests it should."},{"name":"Herald of the First Syllable","cr":3,"role":"elite","type":"Aberration","size":"Medium","frame":"grell","model":"grell","summary":"floating tendriled brain-thing, forever mid-utterance","flavor":"A floating brain-mass trailing paralytic tendrils, forever mid-utterance of a name it will never complete."},{"name":"Vault-Warden Ooze","cr":3,"role":"elite","type":"Ooze","size":"Large","frame":"gelatinous-cube","model":"gelatinous-cube","summary":"geometric ooze sentry, absorbs anyone lacking the passphrase","flavor":"A perfectly geometric mass that patrols flooded vault corridors, absorbing anything that doesn't know the passphrase."},{"name":"Basalt Geometer-Scout","cr":3,"role":"elite","type":"Construct","size":"Medium","frame":"scarecrow","model":"scarecrow","summary":"scout construct, surveys rooms ahead of angle-warping work","flavor":"A lighter cousin of the geometer-constructs, sent ahead to survey rooms before the angle-work begins."},{"name":"Deep-Kin War Priest","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"fish-folk-archpriest","model":"fish-folk-archpriest","summary":"gilled war-priest, blesses spears with wrongly-moving water","flavor":"Leads coastal-breed raids with hymnals bound in dried skin no one asks about; blesses spears with water that shouldn't move like that."},{"name":"Amalgam of Borrowed Limbs","cr":3,"role":"elite","type":"Aberration","size":"Large","frame":"ogre-howdah","model":"ogre-howdah","summary":"tide-stitched limb-amalgam, mismatched parts unnoticed by it","flavor":"Stitched together from whatever the tide brought — none of the limbs match, and it hasn't noticed yet."},{"name":"Star-Spawn Broodcaller","cr":4,"role":"elite","type":"Aberration","size":"Medium","frame":"astral-raider-warrior","model":"astral-raider-warrior","summary":"star-spawn summoner, calls splinters to its side","flavor":"Sings a summoning fragment that draws smaller splinters from wherever they've been hiding; never fights alone if it can help it."},{"name":"Choir-Grown Ooze Sculptor","cr":4,"role":"elite","type":"Ooze","size":"Large","frame":"black-pudding","model":"black-pudding","summary":"self-sculpting ooze mimic, dissolves interrupting witnesses","flavor":"Reshapes itself into crude mimicries of drowned architecture, humming while it works, dissolving anyone who interrupts."},{"name":"Vault-Drift Overseer","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"tough-boss","model":"tough-boss","summary":"veteran cult overseer, whip woven from something not-quite-rope","flavor":"Generations deep in cult service, cracking a whip woven from something that used to be rope and now isn't quite."},{"name":"Reef-Choked Behemoth-Calf","cr":4,"role":"elite","type":"Beast","size":"Huge","frame":"giant-crocodile","model":"giant-crocodile","summary":"coral-armored guard-beast, bred to protect flooded vaults","flavor":"A drowned-world beast bred to guard the choir's flooded vaults, coral growing through its hide like armor."},{"name":"Nine-Eyed Cyst","cr":4,"role":"elite","type":"Aberration","size":"Medium","frame":"secret-eye","model":"secret-eye","summary":"nine-eyed stalk-growth, each eye sees a different version of the room","flavor":"A budding growth of eyes on a fleshy stalk, each seeing a slightly different version of the same room."},{"name":"Choir-Marked Berserker","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"gladiator","model":"gladiator","summary":"arena fighter, scars spell hymn fragments across its back","flavor":"Fights in an arena the cult built beneath the tide line, scars spelling out fragments of hymn across its back."},{"name":"Devouring Choir-Cyst","cr":5,"role":"elite","type":"Ooze","size":"Large","frame":"otyugh","model":"otyugh","summary":"shrine-fed cyst, grows a new mouth per swallowed prayer","flavor":"Feeds on offerings left at flooded shrines, growing new mouths for every prayer it swallows."},{"name":"Star-Chewed Roc-Kin","cr":5,"role":"elite","type":"Monstrosity","size":"Huge","frame":"giant-axe-beak","model":"giant-axe-beak","summary":"drift-touched sky-beast, shadow lags behind its own flight","flavor":"A sky-beast whose migratory path drifted through somewhere it shouldn't have; it still flies, but its shadow lags a half-second behind."},{"name":"Wrong-Season Roper","cr":5,"role":"elite","type":"Aberration","size":"Large","frame":"roper","model":"roper","summary":"drift-grown ropy ambusher, strands taste of a closed mouth","flavor":"Grows in caverns where the drift touched the stone; its strands taste like the inside of a closed mouth."},{"name":"Reef-Fused War Elemental","cr":5,"role":"elite","type":"Elemental","size":"Large","frame":"water-elemental","model":"water-elemental","summary":"drift-touched water elemental, moves with unnerving intent","flavor":"Water given form by the same wrongness that grows coral over drowned bones; it moves like tide, but with intent."},{"name":"Coral-Throned Cult Matron","cr":6,"role":"elite","type":"Humanoid","size":"Medium","frame":"performer-maestro","model":"performer-maestro","summary":"reef-throned choir conductor, directs worshippers like an orchestra","flavor":"Conducts the drowned hymn from a throne grown out of living reef, directing worshippers like an orchestra of dread."},{"name":"Star-Warped Chimera-Thing","cr":6,"role":"elite","type":"Monstrosity","size":"Large","frame":"chimera","model":"chimera","summary":"triple-fused star-warped beast, heads disagree about its nature","flavor":"Three creatures fused by the same accident that dropped its kin from the sky, each head disagreeing about what it is."},{"name":"Choir-Bound Invisible Watcher","cr":6,"role":"elite","type":"Elemental","size":"Medium","frame":"invisible-stalker","model":"invisible-stalker","summary":"bound invisible hunter, tracks lapsed believers","flavor":"Bound to the choir by a pact it can't remember making, hunting silently for anyone who stops believing on schedule."},{"name":"Bone-Grown Cathedral Skeleton","cr":6,"role":"elite","type":"Undead","size":"Large","frame":"minotaur-skeleton","model":"minotaur-skeleton","summary":"architecture-fused drowned guardian skeleton","flavor":"A drowned guardian whose bones have fused with the architecture it once protected; moving it means moving the wall."},{"name":"Void-Trained Duelist","cr":7,"role":"elite","type":"Aberration","size":"Medium","frame":"mind-thief","model":"mind-thief","summary":"advanced void-monk duelist, fights blind and never misses","flavor":"Advanced past the ascetics in the not-looking discipline; it fights with eyes fully closed and somehow never misses."},{"name":"Warlord of the Sunken Court","cr":7,"role":"elite","type":"Giant","size":"Huge","frame":"stone-giant","model":"stone-giant","summary":"coral-grown giant warlord, sworn to the drowned choir","flavor":"A giant sworn to the drowned choir generations back, its stonework now grown through with the same wrong coral as the vaults it guards."},{"name":"Cyst-Blossomed Behemoth","cr":7,"role":"elite","type":"Monstrosity","size":"Huge","frame":"hydra","model":"hydra","summary":"regenerating many-headed horror, sprouts eyes where heads regrow","flavor":"Each severed head buds a fresh eye before it regrows, until the thing sees in more directions than it can process."},{"name":"Grand Cantor of the Drowned Court","cr":8,"role":"high","type":"Humanoid","size":"Medium","frame":"archpriest","model":"archpriest","summary":"tri-voiced high priest, speaks as three generations at once","flavor":"Speaks in a chord of three voices at once, each a different generation of the same office; the congregation answers all three."},{"name":"Fathom-Deep Devourer","cr":8,"role":"high","type":"Monstrosity","size":"Huge","frame":"cockatrice-regent","model":"cockatrice-regent","summary":"ancient depth-lurker, gaze convinces victims stillness was the plan","flavor":"Older than the vault it lairs in, its gaze doesn't petrify so much as convince the victim that stillness was always the plan."},{"name":"Star-Warped Amalgam Lord","cr":8,"role":"high","type":"Aberration","size":"Large","frame":"yuan-ti-abomination","model":"yuan-ti-abomination","summary":"heavily-reshaped cult champion, original species long forgotten","flavor":"A cult champion so thoroughly reshaped that its original species is a debated footnote among its own worshippers."},{"name":"Vault-Keeper of the Drowned Seal","cr":9,"role":"high","type":"Construct","size":"Large","frame":"clay-golem","model":"clay-golem","summary":"door-guardian golem, scarred by every prior attempt to pass","flavor":"Built to guard a door that shouldn't open; every scar in its clay hide is a place someone already tried."},{"name":"Hollow-Throated Herald-Prime","cr":10,"role":"high","type":"Aberration","size":"Large","frame":"behir","model":"behir","summary":"elder herald-beast, recites fragments younger heralds can't finish","flavor":"An elder herald whose throat has stretched to accommodate names centuries in the reciting; it finishes fragments the young ones can't."},{"name":"Rakshasa of the Drowned Bargain","cr":11,"role":"high","type":"Fiend","size":"Medium","frame":"rakshasa","model":"rakshasa","summary":"deal-making fiend, wears any face to get terms accepted","flavor":"Made a private deal with the choir long before the cult existed; it wears whatever face gets the terms accepted."},{"name":"Colossal Sunken Guardian","cr":11,"role":"high","type":"Construct","size":"Huge","frame":"stone-golem","model":"stone-golem","summary":"titanic coral-fused golem, footsteps sound like a receding tide","flavor":"A titan of drowned stone, moss and coral fused so deep into its joints that its footsteps sound like a tide going out."},{"name":"Void-Ascendant Grandmaster","cr":12,"role":"high","type":"Aberration","size":"Medium","frame":"void-monk-psion","model":"void-monk-psion","summary":"perfected void-monk master, has forgotten its own god's face","flavor":"Perfected the discipline of not-looking so completely it has forgotten what its god even looks like — which may be the point."},{"name":"Herald-Devourer of the Bishop's Court","cr":12,"role":"high","type":"Aberration","size":"Large","frame":"arcanaloth","model":"arcanaloth","summary":"doctrine-advisor and quiet devourer of the faithless","flavor":"Advises the bishops on doctrine while quietly consuming the ones whose faith wavers, calling it a mercy."},{"name":"Sunk-Court Executioner","cr":13,"role":"high","type":"Fiend","size":"Medium","frame":"ultroloth","model":"ultroloth","summary":"internal cult enforcer, victims erased even from memory","flavor":"Handles the choir's internal discipline; those it visits are never spoken of by name again, only by the shape of their absence."},{"name":"Amalgam Colossus of the Reef Deep","cr":13,"role":"high","type":"Monstrosity","size":"Gargantuan","frame":"purple-worm","model":"purple-worm","summary":"warship-sized fused colossus, hull studded with reef and eyes","flavor":"A worm the size of a warship, its segments studded with fused reef, eyes, and the odd intact ship's figurehead."},{"name":"Herald-Legion, Unified Voice","cr":15,"role":"apex","type":"Aberration","size":"Huge","frame":"nalfeshnee","model":"nalfeshnee","summary":"fused mass of failed heralds, one throat that might finish","flavor":"Every herald that ever failed to finish its name, fused into one throat that finally might; the cult prays it never gets the chance."},{"name":"The Unfinished Cathedral-Made-Flesh","cr":16,"role":"apex","type":"Construct","size":"Gargantuan","frame":"iron-golem","model":"net-new: a cathedral's worth of drowned masonry animated into a lurching shape","summary":"animated drowned-cathedral golem, walks toward the sea","flavor":"The congregation finally built their temple, and the temple got up. It walks toward the sea on legs made of pews, ringing bells no one installed."},{"name":"Star-Spawn Grand Marshal","cr":17,"role":"apex","type":"Aberration","size":"Huge","frame":"death-knight","model":"death-knight","summary":"star-spawn war-commander, armor of starlight that's gone dark","flavor":"Commands the between-star raiders in the flesh, its armor grown from crystallized starlight that's forgotten how to shine."},{"name":"The Drift That Remembers Shapes","cr":18,"role":"apex","type":"Ooze","size":"Gargantuan","frame":"blob-of-annihilation","model":"blob-of-annihilation","summary":"the source shoggoth-mass, recalls and re-wears dissolved shapes","flavor":"Every shoggoth-mass in the realm is one flake of this; it recalls every shape it's ever dissolved, and occasionally wears one back."},{"name":"Last Cantor of the Ending Hymn","cr":19,"role":"apex","type":"Humanoid","size":"Medium","frame":"lich","model":"lich","summary":"undying cantor, rehearsing a final verse for four centuries","flavor":"Traded its death for the chance to sing the drowned language's final verse; it has been rehearsing for four hundred years and is almost, almost ready."},{"name":"The Angle That Ate a City","cr":20,"role":"apex","type":"Aberration","size":"Gargantuan","frame":"tarrasque","model":"net-new: a fractally-wrong geometric mass the size of a district, still folded","summary":"district-sized geometric horror, was once a place, now a mouth","flavor":"It used to be somewhere. Now it's something, crawling slow and patient toward the next somewhere on legs that are technically also rooftops."},{"name":"Deep One","cr":0.25,"role":"mook","type":"Aberration","size":"Medium","frame":"fish-folk","model":"fish-folk","summary":"batrachian shore-dweller, croaks a half-formed hymn","flavor":"A shore-town's shame given gills — it wades in half-formed, croaking a hymn it hasn't earned the throat for yet.","source":"public-domain","sourceNote":"Lovecraft, The Shadow over Innsmouth (1936, PD)"},{"name":"Deep One Whip","cr":1,"role":"mook","type":"Aberration","size":"Medium","frame":"fish-folk-whip","model":"fish-folk-whip","summary":"tide-driving enforcer of the Innsmouth shoal","flavor":"Older, wetter, meaner — it keeps the school in line with a lashing tail and a stare that promises the tide is coming for you specifically.","source":"public-domain","sourceNote":"Lovecraft, The Shadow over Innsmouth (1936, PD)"},{"name":"Deep One Archpriest","cr":6,"role":"elite","type":"Aberration","size":"Medium","frame":"fish-folk-archpriest","model":"fish-folk-archpriest","summary":"reef-cult elder, half-remembers being human","flavor":"It leads the chant at the reef-altar and remembers being a person before the change finished; that memory is the only mercy it has left.","source":"public-domain","sourceNote":"Lovecraft, The Shadow over Innsmouth (1936, PD)"},{"name":"Byakhee","cr":2,"role":"mook","type":"Aberration","size":"Large","frame":"grick","model":"grick","summary":"void-crossing carrion flock, wrong at every joint","flavor":"A crow-shape wrong at every joint, it beats black wings through no air at all and only lands to feed.","source":"public-domain","sourceNote":"shared literary PD mythos convention (Chambers/Lovecraft-circle void-fauna)"},{"name":"Shoggoth","cr":9,"role":"high","type":"Aberration","size":"Large","frame":"gray-chaos-frog","model":"gray-chaos-frog","summary":"protoplasmic slave-thing, grows eyes on demand","flavor":"A slave that unmade its makers and kept the trick — a boiling black mass that grows whatever eye or mouth the moment calls for.","source":"public-domain","sourceNote":"Lovecraft, At the Mountains of Madness (1936, PD)"},{"name":"Elder Thing","cr":7,"role":"elite","type":"Aberration","size":"Large","frame":"grick-ancient","model":"grick-ancient","summary":"starfish-headed elder scientist-builder","flavor":"Barrel-bodied and starfish-headed, it built cities on this world before anything we'd call life existed, and it still keeps better records than we do.","source":"public-domain","sourceNote":"Lovecraft, At the Mountains of Madness (1936, PD)"},{"name":"Elder Deep-Thing","cr":10,"role":"elite","type":"Aberration","size":"Large","frame":"elder-deep-thing","model":"elder-deep-thing","summary":"ancient elder thing, patience curdled to menace","flavor":"An elder thing gone ancient and terrible, its city-building patience curdled into something that studies you the way it once studied continents.","source":"public-domain","sourceNote":"Lovecraft, At the Mountains of Madness (1936, PD)"},{"name":"Dagon","cr":13,"role":"apex","type":"Aberration","size":"Large","frame":"eye-tyrant","model":"eye-tyrant","summary":"the Deep Ones' unspeakable patriarch","flavor":"The father-shape the Deep Ones sing to, glimpsed once by a starving sailor and never fully described since — because no one who saw it whole stayed sane enough to try.","source":"public-domain","sourceNote":"Lovecraft, Dagon (1919, PD)"},{"name":"Nightgaunt","cr":2,"role":"mook","type":"Fiend","size":"Large","frame":"spined-devil","model":"spined-devil","summary":"faceless black tickler that carries victims off","flavor":"Black, rubbery, and faceless, it tickles you into helplessness before it carries you off — the single most polite abduction in any bestiary.","source":"public-domain","sourceNote":"Lovecraft, The Dream-Quest of Unknown Kadath (1943, PD)"},{"name":"Hound of Tindalos","cr":6,"role":"elite","type":"Aberration","size":"Large","frame":"chimera","model":"chimera","summary":"angle-stalking hunter that seeps through corners","flavor":"It doesn't come through space, it comes through angles — anywhere a corner exists, it's already halfway in.","source":"public-domain","sourceNote":"Frank Belknap Long, The Hound of Tindalos (1929, PD)"},{"name":"The Colour","cr":8,"role":"high","type":"Elemental","size":"Large","frame":"water-weird","model":"net-new: a shifting stain of unnameable light with no fixed silhouette","summary":"unnameable light that spreads and consumes","flavor":"Not a monster so much as a stain that thinks — a light with no name in any spectrum, patiently turning a farm, then a family, then a county into itself.","source":"public-domain","sourceNote":"Lovecraft, The Colour Out of Space (1927, PD)"},{"name":"Yog-Sothoth's Herald","cr":14,"role":"apex","type":"Aberration","size":"Huge","frame":"undead-eye-tyrant","model":"undead-eye-tyrant","summary":"half-born twin thing straining at the seams of the world","flavor":"A half-born twin thing straining against the edges of the world it was dragged into — the Gate and the Key both wearing a body that can barely hold it.","source":"public-domain","sourceNote":"Lovecraft, The Dunwich Horror (1929, PD)"},{"name":"Nyarlathotep, the Crawling Chaos","cr":21,"role":"apex","type":"Fiend","size":"Medium","frame":"lich","model":"lich","summary":"the outer gods' smiling ambassador and saboteur","flavor":"The only one of Them that bothers to wear a human face and give speeches — which somehow makes it worse, not better.","source":"public-domain","sourceNote":"Lovecraft, Nyarlathotep (1920, PD)"},{"name":"Cthulhu","cr":25,"role":"apex","type":"Aberration","size":"Gargantuan","frame":"kraken","model":"kraken","summary":"sunken god-thing, dreaming ruin under the waves","flavor":"Dead but dreaming under the drowned city that bears his name, he doesn't need to move to end you — the dreams alone have driven men to the asylum and the harbor.","source":"public-domain","sourceNote":"Lovecraft, The Call of Cthulhu (1928, PD)"},{"name":"The King in Yellow","cr":18,"role":"apex","type":"Fiend","size":"Medium","frame":"death-knight","model":"death-knight","summary":"the tattered monarch of a play that unmakes readers","flavor":"He never has to lift a hand — reading the second act is enough. The tatters of his court simply keep multiplying once you've looked.","source":"public-domain","sourceNote":"Robert W. Chambers, The King in Yellow (1895, PD)"},{"name":"Servant of the King in Yellow (Tatterling)","cr":1,"role":"mook","type":"Fiend","size":"Medium","frame":"specter","model":"specter","summary":"pale-masked cultist unmade by the forbidden play","flavor":"Once someone who finished the play. Now a rag-shape in a pale mask, mouthing lines it can no longer stop repeating.","source":"public-domain","sourceNote":"Chambers, The King in Yellow (1895, PD) — the Pallid Mask/court motif"},{"name":"Cassilda's Mourner","cr":5,"role":"elite","type":"Fiend","size":"Medium","frame":"banshee","model":"net-new: a black-veiled wailing figure trailing tattered star-cloth","summary":"Carcosan wanderer weeping in a dead tongue","flavor":"It weeps in a language that predates grief, wandering the black stars of Carcosa looking for a lake that isn't in this world anymore.","source":"public-domain","sourceNote":"Chambers, The King in Yellow (1895, PD) — Carcosa/Hyades imagery"},{"name":"Mi-Go","cr":3,"role":"mook","type":"Aberration","size":"Medium","frame":"astral-raider-warrior","model":"net-new: fungoid crustacean-winged trans-void miner","summary":"fungoid trans-void miner, files brains for transport","flavor":"Fungoid, winged, and disturbingly businesslike, it doesn't want to kill you so much as file you — in a can, for shipping.","source":"public-domain","sourceNote":"Lovecraft, The Whisperer in Darkness (1931, PD)"},{"name":"Brain in a Cylinder","cr":4,"role":"elite","type":"Aberration","size":"Small","frame":"secret-eye","model":"secret-eye","summary":"extracted brain, still cheerfully lecturing on the cosmos","flavor":"A voice from a metal can bolted to a speaker-horn, still insisting it volunteered for this and would love to tell you all about the stars.","source":"public-domain","sourceNote":"Lovecraft, The Whisperer in Darkness (1931, PD)"},{"name":"Ghast of the Underworld","cr":2,"role":"mook","type":"Undead","size":"Medium","frame":"ghast","model":"net-new: kangaroo-legged corpse-pale barking hunter","summary":"kangaroo-legged corpse-thing that barks in the deep dark","flavor":"Kangaroo-legged and corpse-pale, it barks like a starved dog in the dark beneath the waking world and hunts in loping, delighted packs.","source":"public-domain","sourceNote":"Lovecraft, The Dream-Quest of Unknown Kadath (1943, PD)"}],
 "theater":[{"name":"Line Infantry Shade","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"warrior-infantry","model":"guard","summary":"Rank-and-file trench ghost, holds the line by rote","flavor":"A rifleman still dressed by a drill he can't remember learning; he holds a section of trench because holding it is the only order left in him."},{"name":"Wire-Cutter Scout","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"bandit-courier","summary":"Silent night-crawler who counts sentries for something","flavor":"Crawls the gaps between lines at night, snipping wire and counting sentries; talks to no one, reports to something."},{"name":"Whistle-Blown Runner","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"guard","model":"guard","summary":"Message-runner forever mid-sprint toward the whistle","flavor":"Carries messages between shattered command posts at a dead sprint; the whistle that sends him over is always just about to blow again."},{"name":"Duckboard Vermin Swarm","cr":0.25,"role":"mook","type":"Beast","size":"Small","frame":"giant-rat","model":"giant-rat","summary":"Fearless rat-swarm that owns the trench floor at night","flavor":"Fat and fearless on a diet no one wants named, they own the flooded duckboards after dark and don't scatter for the living anymore."},{"name":"Mustard Wraith","cr":1,"role":"mook","type":"Elemental","size":"Medium","frame":"manes-vaporspawn","model":"manes-vaporspawn","summary":"Drifting toxic gas-cloud that hunts low ground blind","flavor":"A drifting yellow-green bank that used to be a chemical order given from far behind the lines; it rolls into low ground and doesn't care whose lungs it finds."},{"name":"Barbed Kill-Zone Tangle","cr":1,"role":"mook","type":"Plant","size":"Medium","frame":"gas-spore-fungus","model":"net-new: a thorned mass of coiled wire that snags a boot then pulls","summary":"Living wire-tangle that snags then reels men in","flavor":"Coiled wire gone wrong, grown thorned and hungry between the lines; it snags a boot first and pulls the rest of the man in after."},{"name":"Musket-Line Regular","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"orc-warrior","model":"bandit-enforcer","summary":"Volley-fire rifleman lost in permanent powder smoke","flavor":"Loads, presents, fires in volley by rote; the smoke never fully clears from a face that's forgotten peace."},{"name":"Longship Raider","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit-enforcer","model":"bandit-enforcer","summary":"Beach-charging raider screaming a nameless war-cry","flavor":"Comes off the beach at a dead run, screaming a war-cry with no god's name left in it, only the noise."},{"name":"Jungle Ambusher","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"pirate","model":"scout","summary":"Silent canopy-and-mud ambusher, gone before you see him","flavor":"Fights from the canopy and the mud both, silent until the moment he isn't; the vines remember where he waited."},{"name":"Siege-Line Sapper","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"knight","model":"warrior-veteran","summary":"Tunnel-digger laying the charge that breaches the wall","flavor":"Digs toward the wall under fire, laying the charge that will open it; talks about the tunnel like it's a person he's killing slowly."},{"name":"Barbed-Wire Horror","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"wight","model":"wight","summary":"Wire-impaled corpse that never fell, still reaching","flavor":"A body the wire never let fall, stitched upright by rust and old rage; it still reaches for the men who left it there."},{"name":"The Unkillable Sergeant","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"wight-lord","model":"wight-lord","summary":"NCO who won't stay dead, keeps ordering the charge","flavor":"Shot, gassed, and buried three times over the objection of his own men, he gets back up cursing and orders the charge again anyway."},{"name":"Hedgerow Tank-Killer","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"guard-captain","model":"tough-boss","summary":"Bocage ambusher waiting to drop a war-machine cold","flavor":"Waits in the bocage with a tube on his shoulder for a machine bigger than any dragon he's heard of in stories; one shot, one silence."},{"name":"Longship Warlord","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"ettin","model":"hill-giant","summary":"Giant raider-chief armored in three lines' worth of plate","flavor":"Twice the size a man should be, armored in captured plates from three different lines; the beach is his only law."},{"name":"Trench Ghast","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"ghast","model":"ghast","summary":"No-man's-land feeder that mimics the whistle to lure prey","flavor":"Feeds in no-man's-land where nobody goes to collect the dead; it has learned to imitate the whistle to lure the living out."},{"name":"Jungle Beast-Handler","cr":5,"role":"elite","type":"Humanoid","size":"Large","frame":"troll","model":"troll","summary":"Handler who marches a chained horror as a living breacher","flavor":"Marches a chained horror ahead of his own line as a breach-weapon; the leash is the only thing keeping the front intact."},{"name":"Iron Crawler War-Machine","cr":5,"role":"elite","type":"Construct","size":"Large","frame":"flesh-golem","model":"animated-armor","summary":"Treaded armored hull grinding across the wire alone","flavor":"A rivet-scarred hull dragging itself across the wire on tracks it wasn't built to have; the crew inside stopped answering the hatch a long time ago."},{"name":"Legion Standard-Breaker","cr":6,"role":"elite","type":"Humanoid","size":"Medium","frame":"gladiator","model":"gladiator","summary":"Flag-devoted killer who believes in nothing but the fight","flavor":"Fights for the flag more than the cause, and the flag has no name anyone will say out loud; kills beautifully, believes in nothing."},{"name":"Musket-Line Cavalry Officer","cr":7,"role":"elite","type":"Humanoid","size":"Large","frame":"knight","model":"knight","summary":"Officer charging cannon-fire on horseback for the order alone","flavor":"Charges a line of guns on horseback because the order came down and orders are the only faith he has left."},{"name":"The Line That Held","cr":8,"role":"high","type":"Construct","size":"Large","frame":"helmed-horror","model":"animated-armor","summary":"Animate trench-line that simply refuses to yield ground","flavor":"A stretch of trench itself, animated by every soldier who swore to hold it and did, until holding was all that was left; it does not attack so much as refuse to move."},{"name":"Longship Draugr-Captain","cr":9,"role":"high","type":"Undead","size":"Large","frame":"bone-devil","model":"wraith","summary":"Drowned captain still commanding his dead crew ashore","flavor":"Drowned with his crew and rose commanding them still; the tide brings his ship back to shores that no longer remember his war."},{"name":"Jungle War-Engine","cr":10,"role":"high","type":"Construct","size":"Huge","frame":"stone-golem","model":"stone-golem","summary":"Feral jungle war-machine still firing a stale coordinate","flavor":"A siege-machine gone feral in the canopy, vines grown through its plating, still firing on a target coordinate decades stale."},{"name":"Legion Praetor-Revenant","cr":11,"role":"high","type":"Undead","size":"Medium","frame":"death-knight-aspirant","model":"death-knight-aspirant","summary":"Dead commander who still drills a legion by discipline alone","flavor":"Commands a legion of the dead the way he commanded the living, by discipline alone; his oath outlived his empire and his name both."},{"name":"The Whistle","cr":14,"role":"apex","type":"Undead","size":"Large","frame":"undead-eye-tyrant","model":"eye-tyrant","summary":"The sound of the order itself, given bone and rank","flavor":"Not a person anymore — the sound itself, given a shape of officers' bones and borrowed rank insignia, that sends men over the top forever; every era's war has heard it."},{"name":"No-Man's Bloom","cr":16,"role":"apex","type":"Plant","size":"Gargantuan","frame":"gulthias-blight","model":"gulthias-blight","summary":"War-soaked ground grown into a thorned, remembering forest","flavor":"Grew from ground so soaked in war it stopped being ground; a forest of barbed thorn and bone-white flowers that remembers every line that ever broke on it, and answers with all of them at once."},{"name":"Trench Rat Cloud","cr":0.125,"role":"mook","type":"Beast","size":"Tiny","frame":"rat","model":"rat","summary":"Carrion rats swarming abandoned trenches and packs","flavor":"Bloated on no-man's-land carrion, it swarms boots and packs before anyone can shoot it."},{"name":"Conscript Straggler","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"commoner","model":"commoner","summary":"Green conscript, flinches and breaks under fire","flavor":"Handed a rifle a week ago, he still flinches at his own shots and breaks the instant his squad does."},{"name":"Wire-Snagged Corpse","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"zombie","model":"zombie","summary":"Barbed-wire corpse still lurching toward the line","flavor":"Caught on the barbed wire mid-charge, it never fell — it just kept twitching forward, one strand at a time."},{"name":"Powder Monkey Cutthroat","cr":0.25,"role":"mook","type":"Humanoid","size":"Small","frame":"kobold","model":"kobold","summary":"Small shipboard runner, finishes off fallen boarders","flavor":"Small enough to run the guns below deck, mean enough to finish off boarders with a marlinspike."},{"name":"Musket Skirmisher","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"kobold-inventor","model":"net-new: a loose-order rifleman crouched and reloading in drifting smoke","summary":"Loose-order skirmisher, fires and vanishes into smoke","flavor":"Fires from cover in loose order, reloading in the smoke while the line volleys behind him."},{"name":"Longship Thrall","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"troglodyte","model":"net-new: a chained oarsman handed an axe at the beachhead","summary":"Chained oarsman turned axe-fighter at the beachhead","flavor":"Chained to the oar until the ship beaches, then handed an axe and pointed at the shore."},{"name":"Jungle Leech-Thing","cr":0.25,"role":"mook","type":"Beast","size":"Small","frame":"giant-centipede","model":"net-new: a canopy-dwelling leech creature dropping onto exposed necks","summary":"Canopy leech-creature that drops and drains blood","flavor":"Drops from canopy vines onto exposed necks; the bite numbs before it drains."},{"name":"Siege Camp Looter","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit","model":"bandit","summary":"Corpse-looter trailing behind the siege lines","flavor":"Follows the siege lines picking corpses clean before the burial details arrive."},{"name":"Shell-Shocked Wanderer","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"guilt-stained-vagrant","model":"net-new: a hollow-eyed survivor wandering no-man's-land muttering old orders","summary":"Shell-shocked survivor wandering, immune to fear","flavor":"Walks no-man's-land muttering old orders, immune to fear because there's nothing left to lose."},{"name":"Gas-Mask Sentry","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"guard","model":"guard","summary":"Masked sentry holding post through gas alarms","flavor":"Stands post in a rubber mask through every gas alarm, trusting the seal more than his own eyes."},{"name":"Draft-Horse Casualty","cr":0.5,"role":"mook","type":"Undead","size":"Large","frame":"warhorse-skeleton","model":"warhorse-skeleton","summary":"Dead draft horse still hauling its rotted harness","flavor":"A supply-train animal that died in harness and kept pulling, wagon and all, long after the wagon rotted away."},{"name":"Cavalry Lancer","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"orc-warrior","model":"orc-warrior","summary":"Mounted lancer charging ahead of modern fire","flavor":"Charges in a wedge before the machine-gun era caught up with the horse."},{"name":"Musket-Line Drummer Boy","cr":0.5,"role":"mook","type":"Humanoid","size":"Small","frame":"performer","model":"net-new: a young drummer keeping march step through the volleys","summary":"Drummer keeping march step, breaking his death shatters morale","flavor":"Keeps the march step through the volleys; killing him breaks the formation's nerve as much as any officer."},{"name":"No-Man's-Land Crawler","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"ghoul","model":"ghoul","summary":"Battlefield ghoul scavenging the unburied at night","flavor":"Feeds on the unburied between the lines, too cowardly to rise until the shelling stops."},{"name":"Jungle Ambush Sniper","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"scout","summary":"Canopy-lashed sniper waiting days for one shot","flavor":"Lashed into the high canopy for days at a time, waiting for one clean shot."},{"name":"Longship Shieldmaiden","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit-enforcer","model":"bandit-enforcer","summary":"Flank shield-wall fighter screaming the ship's name","flavor":"Holds the shield-wall's flank and screams the ship's name until her voice gives out."},{"name":"Trench Wire Golem","cr":1,"role":"mook","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"Salvaged-armor construct patrolling the wire on its own","flavor":"Salvaged plate and barbed coils lashed into a shape that shambles the wire-line on patrol."},{"name":"Musket Volley Ghost","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"specter","model":"net-new: a spectral rank of soldiers standing shoulder to shoulder in smoke","summary":"Volley-killed rank of soldiers standing in smoke","flavor":"A whole rank that died in one volley, still standing shoulder to shoulder in the smoke."},{"name":"Jungle War-Dog","cr":1,"role":"mook","type":"Beast","size":"Medium","frame":"death-dog","model":"net-new: a scent-trained war-dog running point ahead of the patrol","summary":"Scent-trained war-dog running point on patrol","flavor":"Trained to track by sweat and fear, it runs the point ahead of the patrol."},{"name":"Siege Sapper's Mole","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"ankheg","model":"ankheg","summary":"Tunneling beast bred to dig under siege walls","flavor":"Bred and directed to chew siege tunnels under walls, indifferent to the men riding its back."},{"name":"Mustard Fog Sprite","cr":1,"role":"mook","type":"Elemental","size":"Medium","frame":"smoke-mephit","model":"net-new: a low-rolling pocket of living gas hunting by sound","summary":"Living gas-cloud that hunts by coughing sounds","flavor":"A living pocket of gas that rolls low across the wire, hunting by the sound of coughing."},{"name":"Longship Berserker","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"berserker","model":"net-new: a wild-eyed berserker chewing ritual root before the beach charge","summary":"Beach-landing berserker numb to wounds mid-charge","flavor":"Chews the ritual root before the beach landing and doesn't feel the axe wounds until the tide turns red."},{"name":"Colonial Trench Medic","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"priest-acolyte","model":"net-new: a medic crawling between craters under fire, satchel in hand","summary":"Under-fire medic, priority target to break morale","flavor":"Crawls between craters under fire, more dangerous to leave alive than most riflemen."},{"name":"Jungle Pit-Trap Warden","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"thri-kreen-marauder","model":"net-new: a guerrilla warden crouched among staked pits and deadfalls","summary":"Guerrilla warden herding patrols into staked pits","flavor":"Lives among staked pits and deadfalls of his own building, herding patrols into them."},{"name":"Duckboard Trench Fiend","cr":2,"role":"mook","type":"Fiend","size":"Medium","frame":"dretch","model":"dretch","summary":"Mud-spawned fiend climbing up through duckboards","flavor":"Something answered the mud's hunger and started climbing up through the duckboards at night."},{"name":"Machine-Gun Nest Crew","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"bugbear-warrior","model":"bugbear-warrior","summary":"Two-man gun crew that ends charges outright","flavor":"Two men and a tripod that can end a whole charge in the time it takes to reload once."},{"name":"Storm-Trooper Breach Squad","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"warrior-veteran","model":"warrior-veteran","summary":"Fast breach specialists clearing trench sections","flavor":"Trained to cross the open ground fast and clear a trench section room by room before the rest arrive."},{"name":"Longship Skald-Reaver","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"berserker-commander","model":"net-new: a raider singing the saga while swinging an axe","summary":"Singing raider whose saga-verses embolden the crew","flavor":"Sings the raid's saga even as he fights, and the crew fights harder for being sung about."},{"name":"Jungle Pit Viper Ambush","cr":3,"role":"elite","type":"Beast","size":"Large","frame":"giant-constrictor-snake","model":"giant-constrictor-snake","summary":"Treeline ambush snake striking bunched patrols","flavor":"Strikes from the treeline the moment a patrol bunches up on the trail."},{"name":"Cavalry Saber Charge","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"knight","model":"knight","summary":"Full-gallop saber cavalry betting on the first pass","flavor":"Rides the flank at full gallop, saber down, betting everything on the first pass."},{"name":"Field Gun Battery","cr":4,"role":"elite","type":"Construct","size":"Large","frame":"animated-rug-of-smothering","model":"net-new: a cannon crew fighting on grimly at their fallen posts","summary":"Cannon crew fighting as one machine past death","flavor":"A cannon crew that fights on as one grim machine after the horses bolt and the gunners die at their posts."},{"name":"The Wire-Cutter Colossus","cr":4,"role":"elite","type":"Construct","size":"Large","frame":"helmed-horror","model":"animated-armor","summary":"Wire-clipping walker built to open assault lanes","flavor":"Built to walk the wire ahead of the assault, clipping lanes through with rotating shears."},{"name":"Longship Hull-Breaker","cr":4,"role":"elite","type":"Giant","size":"Large","frame":"ogre","model":"ogre","summary":"Raiding-crew brute thrown at hulls and gates","flavor":"A raiding crew's brute, thrown at ship hulls and gates alike with the same swing."},{"name":"Jungle Beast-Cage Handler","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"lizardfolk-sovereign","model":"net-new: a handler flinging open bamboo cages at the ambush horn","summary":"Handler releasing caged war-beasts on the ambush horn","flavor":"Releases the war-beasts from bamboo cages the instant the ambush horn sounds."},{"name":"Gas Cloud Horror","cr":4,"role":"elite","type":"Elemental","size":"Large","frame":"steam-mephit","model":"net-new: a roiling, undissipated gas cloud with a hunting will of its own","summary":"Sentient, undissipated gas barrage with a will","flavor":"A whole gas barrage that never dissipated, grown a hunger and a will of its own."},{"name":"Trench Raid Bayonet Line","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"knight","model":"warrior-veteran","summary":"Silent bayonet line going over the top on the whistle","flavor":"Goes over the top in a fixed line, bayonets first, silent until the whistle blows."},{"name":"Musket-Line Artillery Sergeant","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"guard-captain","model":"tough-boss","summary":"Voice-correcting gun sergeant walking under fire","flavor":"Walks the gun line under fire, correcting aim by voice alone."},{"name":"Siege Tower Crew","cr":5,"role":"elite","type":"Construct","size":"Huge","frame":"stone-golem","model":"net-new: a rolling wooden siege tower crewed by fighters at its top","summary":"Rolling siege tower crewed under falling arrows","flavor":"A rolling wooden tower crewed by soldiers who fight from its top even as arrows take the timbers apart."},{"name":"Longship War-Wolf Handler","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"troll","model":"troll","summary":"Raider running a leashed wolf-pack ahead of the men","flavor":"Runs with a leashed pack of raiding wolves that hit the shore ahead of the men."},{"name":"Jungle War-Elephant Driver","cr":5,"role":"elite","type":"Beast","size":"Huge","frame":"elephant","model":"net-new: a barded war-elephant carrying its mahout through the chaos","summary":"Barded war-elephant carrying its driver into chaos","flavor":"A trained war-beast in barded plate, its mahout riding the howdah through the chaos."},{"name":"Trench Flame-Lance Team","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"salamander-fire-snake","model":"net-new: two soldiers hauling an oil-fire tank with a long lance-nozzle","summary":"Flame-tank team clearing bunkers in one breath","flavor":"Two men and a tank of oil-fire that clear a bunker in one long, screaming breath."},{"name":"Deserter-Thing","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"wight","model":"wight","summary":"Executed deserter risen wrong, hunting its executioners","flavor":"Shot for running from the line, it came back wrong and now hunts whoever ordered the execution."},{"name":"Musket-Line Grenadier","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"gladiator","model":"net-new: a tall-hatted grenadier carrying a satchel of black powder","summary":"Fearless grenadier carrying door-opening black powder","flavor":"Tall-hatted, fearless, and carrying enough black powder to open any door he's pointed at."},{"name":"Longship Ghost Fleet Crewman","cr":6,"role":"elite","type":"Undead","size":"Medium","frame":"wraith","model":"wraith","summary":"Century-dead rower still believing the raid continues","flavor":"Rows a ship that beached a hundred years ago and never stopped believing the raid is still on."},{"name":"Siege Ballista Crew","cr":6,"role":"elite","type":"Construct","size":"Large","frame":"gorgon","model":"net-new: a gate-punching ballista crewed by soldiers who never rest","summary":"Gate-punching war-machine crewed around the clock","flavor":"A war-machine built to punch through castle gates, reloaded by a crew that never sleeps."},{"name":"Jungle Tiger-Rider Scout","cr":6,"role":"elite","type":"Beast","size":"Large","frame":"tiger","model":"net-new: a scout riding a trained tiger along canopy trails","summary":"Trained big-cat rider scouting the canopy trails","flavor":"Rides a trained big cat through the canopy trails faster than any patrol can track."},{"name":"Trench Officer's Ghost-Whistle","cr":6,"role":"elite","type":"Undead","size":"Medium","frame":"banshee","model":"net-new: a spectral officer still blowing a whistle for the charge","summary":"Dead officer whose whistle still calls the charge","flavor":"An officer who blew the whistle for the final charge and never stopped hearing it answered."},{"name":"Musket-Line Field Marshal's Honor Guard","cr":6,"role":"elite","type":"Humanoid","size":"Medium","frame":"pirate-captain","model":"net-new: an honor guard standing fast around a battle standard","summary":"Standard-guard sworn to die before it falls","flavor":"Sworn to die before the standard falls, and mean about proving it."},{"name":"Cavalry Death-Rider","cr":7,"role":"elite","type":"Undead","size":"Large","frame":"nightmare","model":"net-new: a dead cavalry officer and warhorse still mid-charge","summary":"Dead cavalry officer and horse still mid-charge","flavor":"A cavalry officer and his warhorse, both killed in the same charge, still riding it out."},{"name":"Longship Berserker-King's Champion","cr":7,"role":"elite","type":"Humanoid","size":"Medium","frame":"centaur-warden","model":"net-new: a bare-chested champion fighting at the longship's prow","summary":"Bare-chested prow-fighter daring the shore to resist","flavor":"Fights bare-chested at the prow, daring the enemy shore to try and stop the landing."},{"name":"Jungle Ambush War-Priest","cr":7,"role":"elite","type":"Humanoid","size":"Medium","frame":"oni","model":"net-new: a war-priest swinging a ritual club after blessing the ambush","summary":"Ritual-blessing war-priest wading into the ambush","flavor":"Blesses the ambush with old rites before the horn sounds, then wades in swinging a ritual club."},{"name":"Siege-Line Trebuchet Golem","cr":7,"role":"elite","type":"Construct","size":"Huge","frame":"stone-giant","model":"net-new: a hulking trebuchet that aims and looses itself","summary":"Self-aiming trebuchet that no longer waits for orders","flavor":"A siege engine grown a crude will, it aims itself now and doesn't wait for the order to loose."},{"name":"Musket-Line Cannon Golem","cr":8,"role":"high","type":"Construct","size":"Large","frame":"clay-golem","model":"net-new: a field gun bolted onto a lumbering walking chassis","summary":"Walking field-gun chassis built to replace dead crews","flavor":"A field gun bolted to a walking chassis, built when someone realized the crew kept dying."},{"name":"Trench Wraith of the Wire","cr":8,"role":"high","type":"Undead","size":"Large","frame":"spirit-naga","model":"net-new: a fused mass of soldiers hunting by remembered muzzle-flash","summary":"Company-wide death-wraith hunting by muzzle-flash memory","flavor":"A whole company lost to one machine gun, fused by grief and mud into something that hunts by muzzle-flash memory."},{"name":"Longship Draugr-Fleet Captain","cr":9,"role":"high","type":"Undead","size":"Large","frame":"bone-devil","model":"wraith","summary":"Drowned fleet-captain whose sunk ships still answer","flavor":"Commands a crew of the drowned, and every ship he's ever sunk still answers his horn."},{"name":"Jungle Colossus-Beast","cr":9,"role":"high","type":"Beast","size":"Huge","frame":"triceratops","model":"net-new: a tamed prehistoric beast used as a living battering ram","summary":"Tamed prehistoric survivor used as a living ram","flavor":"A prehistoric survivor pressed into service as a living battering ram by whoever tamed it first."},{"name":"Trench Butcher Golem","cr":9,"role":"high","type":"Construct","size":"Large","frame":"iron-golem","model":"net-new: a grim close-quarters clearing machine built for the wire","summary":"Close-quarters clearing machine built for the unstomachable work","flavor":"Built for the close-quarters clearing work no living soldier could stomach doing twice."},{"name":"Musket-Line Ghost Regiment","cr":9,"role":"high","type":"Undead","size":"Large","frame":"swarm-of-crawling-claws","model":"net-new: a spectral regiment marching in perfect dead formation","summary":"Regiment lost in one charge, still marching in formation","flavor":"A whole regiment lost in one disastrous volley-charge, still marching in perfect dead formation."},{"name":"Siege Wall-Breaker Titan","cr":10,"role":"high","type":"Giant","size":"Huge","frame":"fire-giant","model":"net-new: a hulking titan swinging a tree-trunk ram at a gate","summary":"Ram-wielding siege titan that doesn't stop swinging","flavor":"Swings a ram the size of a tree trunk and doesn't stop until the gate or its arm gives first."},{"name":"Longship Sea-Wyrm Figurehead","cr":10,"role":"high","type":"Dragon","size":"Large","frame":"wyvern","model":"wyvern","summary":"Cursed living figurehead diving from fog onto ships","flavor":"A carved prow come alive with raider curses, it dives on enemy ships from the fog."},{"name":"Jungle War-Machine of Rusted Vines","cr":10,"role":"high","type":"Construct","size":"Huge","frame":"stone-golem","model":"stone-golem","summary":"Root-swallowed ancient war-engine, still fully armed","flavor":"An engine of war swallowed by the jungle for decades, now grown through with roots and still armed."},{"name":"The Field Marshal's Undying Aide","cr":11,"role":"high","type":"Undead","size":"Medium","frame":"death-knight-aspirant","model":"death-knight-aspirant","summary":"Undying aide delivering the same dead order nightly","flavor":"Delivers the same order at the same hour every night, a century after the marshal died reading it."},{"name":"Trench Legion Revenant Colonel","cr":11,"role":"high","type":"Undead","size":"Medium","frame":"death-knight-aspirant","model":"net-new: a revenant colonel rallying every corpse in earshot","summary":"War-denying revenant rallying every nearby corpse","flavor":"Refuses to accept the war is over, and rallies every corpse in earshot to prove it."},{"name":"Longship Storm-Caller Reaver","cr":12,"role":"high","type":"Elemental","size":"Large","frame":"djinni","model":"net-new: a reaver standing at the helm, storm crackling around him","summary":"Storm-bargaining reaver whose weather still owes him","flavor":"Bargained the sea itself into raiding for him, and the storm still owes him one more shore."},{"name":"Jungle Chimera-Beast of War","cr":12,"role":"high","type":"Monstrosity","size":"Large","frame":"chimera","model":"chimera","summary":"Warlord-bred chimera leading otherwise unsurvivable charges","flavor":"Bred by a warlord's beast-tenders to lead a charge no single animal could survive alone."},{"name":"Musket-Line Field Marshal-Revenant","cr":13,"role":"high","type":"Undead","size":"Medium","frame":"vampire","model":"net-new: a spectral marshal frozen mid-order at a headquarters table","summary":"Century-dead marshal still finishing his last order","flavor":"Died at his own headquarters table mid-order and has been finishing that sentence for a hundred years."},{"name":"Trench Colossus of Bone and Wire","cr":13,"role":"high","type":"Undead","size":"Huge","frame":"rakshasa","model":"net-new: a titan built from the unburied dead, bone and barbed wire","summary":"Self-built ossuary titan from an unnamed battle's dead","flavor":"Built itself from the unburied dead of a battle no one survived to name."},{"name":"No-Man's-Land Warlord's Ghost","cr":14,"role":"apex","type":"Undead","size":"Large","frame":"undead-eye-tyrant","model":"eye-tyrant","summary":"General's ghost eternally watching his own fatal order","flavor":"The general who ordered the crater assault still watches it from above, unable to look away from his own order."},{"name":"The Ironclad Reaver-Queen","cr":15,"role":"apex","type":"Construct","size":"Huge","frame":"iron-golem","model":"net-new: a longship's hull fused with its captain into one war-machine","summary":"Ship-hull-and-captain war-machine that never comes ashore","flavor":"A longship's hull fused with its captain by a dying storm-oath, now a war-machine that never beaches."},{"name":"Legion Undying Praetorian Host","cr":15,"role":"apex","type":"Undead","size":"Large","frame":"death-knight","model":"death-knight","summary":"Never-broken honor-guard formation, undying for centuries","flavor":"An entire honor-guard that swore to never break formation, and hasn't, in any century since."},{"name":"The Gas-King of the Salient","cr":16,"role":"apex","type":"Elemental","size":"Gargantuan","frame":"gulthias-blight","model":"gulthias-blight","summary":"Sentient gas-cloud amalgam that owns the salient's ground","flavor":"Every gas attack ever loosed on the salient pooled into one thinking, hating cloud that owns the ground now."},{"name":"The Siege That Never Lifted","cr":17,"role":"apex","type":"Construct","size":"Gargantuan","frame":"colossus","model":"colossus","summary":"Fused siege-line horror still failing to take the city","flavor":"A siege line's worth of engines, crews, and dead fused into one wall-breaking horror that still hasn't taken the city."},{"name":"The Trench Ghost","cr":0.125,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton","model":"skeleton","summary":"shell-shocked revenant infantryman on eternal patrol","flavor":"A soldier who never left the line, rifle still slung, gas-hood rotted to rags; it keeps walking a patrol route that ended lifetimes ago.","source":"archetype","sourceNote":"generic WWI-lensed infantry archetype (no named nation/unit)"},{"name":"The Legion Wall","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"warrior-infantry","model":"warrior-infantry","summary":"lone shield-and-spear legionary, drilled to a fault","flavor":"One tile of a wall that used to be a hundred men wide; it still steps in formation even with no one left on either flank.","source":"archetype","sourceNote":"classical-era shield-line legionary archetype"},{"name":"The Musket Line","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"guard","model":"guard","summary":"standing volley-drill musketeer, drilled past reason","flavor":"Loads, kneels, fires, reloads — the whole drill even when there's no second rank behind him and no order left to give.","source":"archetype","sourceNote":"generic 18th/19th-c. volley-fire infantry archetype"},{"name":"The Longship Raider","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"hobgoblin-soldier","model":"hobgoblin-soldier","summary":"axe-and-round-shield sea raider, stranded in the war","flavor":"Came ashore for plunder and glory and got neither — just the theater's endless tide instead of home.","source":"archetype","sourceNote":"Norse-lensed raider archetype (not a specific saga figure)"},{"name":"The Jungle Scout","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"scout","summary":"camo-draped recon scout gone half-feral in the green","flavor":"Camouflage gone to lichen, machete more rust than edge — still moves like the canopy is watching him back.","source":"archetype","sourceNote":"generic mid-century jungle-warfare scout archetype (no named conflict)"},{"name":"The Siege Sapper","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"tough","model":"tough","summary":"tunnel-digging siege engineer, still mining toward a wall","flavor":"Digs toward the wall by memory, pick over one shoulder, satchel of black powder over the other, humming a tune no living ear would know.","source":"archetype","sourceNote":"medieval siege-engineer archetype"},{"name":"The Berserker","cr":2,"role":"elite","type":"Humanoid","size":"Medium","frame":"berserker","model":"berserker","summary":"battle-trance warrior who fights past fear and flesh","flavor":"Fights bare-armed and bear-shirted, past fear, past pain, past the point where the theater's rules of engagement still apply to him.","source":"public-domain","sourceNote":"Norse saga/legend berserkr tradition (public domain; no modern media design)"},{"name":"The Draugr Captain","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"wight","model":"wight","summary":"mound-risen undead officer still holding a dead line","flavor":"Guards a rank that was overrun centuries ago as if the order to hold still stands; corpse-cold hands still know the grip of a sword-hilt.","source":"public-domain","sourceNote":"Norse folklore draugr — the mound-dwelling undead warrior of the sagas"},{"name":"The Machine-Gun Nest","cr":3,"role":"elite","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"fused gun-and-gunner emplacement, animate and traversing","flavor":"Not one soldier but the whole emplacement fused together — tripod legs, traversing arms, a barrel where a face should be.","source":"archetype","sourceNote":"generic entrenched-crew-served-weapon archetype"},{"name":"The Storm-Trooper Cadre","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"warrior-veteran","model":"warrior-veteran","summary":"grenade-and-trench-knife shock infantryman","flavor":"Moves in twos and threes between the shell-holes, grenade-first, never in the open longer than a breath.","source":"archetype","sourceNote":"generic elite-shock-infantry archetype (WWI stosstruppen-style, no named force)"},{"name":"The Valkyrie","cr":4,"role":"elite","type":"Celestial","size":"Medium","frame":"empyrean-iota","model":"empyrean-iota","summary":"battlefield psychopomp choosing which dead the war keeps","flavor":"Walks the field after the guns fall quiet, marking which of the fallen the theater will keep and which it lets go home.","source":"public-domain","sourceNote":"Norse myth — chooser of the slain (public domain figure, our own visual take)"},{"name":"The Iron Cavalry","cr":5,"role":"elite","type":"Construct","size":"Large","frame":"gorgon","model":"gorgon","summary":"armor-plated war-beast standing in for every era's tank","flavor":"Half horse, half hull-plate — the theater's answer to any age's need for something that doesn't tire and doesn't feel the wire.","source":"archetype","sourceNote":"generic armored-cavalry/tank archetype, era-blurred"},{"name":"The Siege Tower","cr":6,"role":"high","type":"Construct","size":"Huge","frame":"helmed-horror","model":"helmed-horror","summary":"animate siege-tower, self-propelled toward the wall","flavor":"Rolls forward on its own dead momentum, ladders unfurling like wings, arrow-slits blinking where windows should be.","source":"archetype","sourceNote":"medieval siege-engine archetype"},{"name":"The Trench Wight","cr":5,"role":"high","type":"Undead","size":"Medium","frame":"wight-lord","model":"wight-lord","summary":"revenant trench-officer still blowing the whistle to advance","flavor":"Commands a company that's mostly mud and memory now, whistle still around its neck, ready to blow the advance no one will survive.","source":"archetype","sourceNote":"WWI-lensed mass-grave revenant archetype (not any single named ghost)"},{"name":"The War Elephant","cr":6,"role":"high","type":"Beast","size":"Huge","frame":"mammoth","model":"mammoth","summary":"armored siege-beast that shrugs off volleys and keeps coming","flavor":"Armored howdah still smoking from the last volley it shrugged off; it doesn't rout, it doesn't stop, it just keeps coming through the line.","source":"archetype","sourceNote":"ancient/classical siege-beast archetype"},{"name":"The Gorgon Standard","cr":6,"role":"high","type":"Monstrosity","size":"Medium","frame":"medusa","model":"medusa","summary":"gorgon-faced standard-bearer, a banner that petrifies stares","flavor":"A standard-bearer whose face the theater blurs on purpose — look at her banner too long and you understand exactly why armies used to carry her likeness into battle.","source":"public-domain","sourceNote":"Greek myth — Medusa/Gorgon, invoked here as a war-banner icon rather than the individual myth figure"},{"name":"The Flying Squadron","cr":7,"role":"high","type":"Monstrosity","size":"Large","frame":"griffon","model":"griffon","summary":"aerial strafing beast standing in for the first air war","flavor":"Half war-bird, half war-machine, strafing the line from an altitude the trenches can only pray at.","source":"archetype","sourceNote":"generic early-aviation/biplane dogfighter archetype"},{"name":"The Ironclad Leviathan","cr":11,"role":"apex","type":"Monstrosity","size":"Gargantuan","frame":"roc","model":"roc","summary":"gargantuan warship-beast that dominates the theater's horizon","flavor":"It doesn't fly the theater's skies so much as displace them, guns run out along a hull too vast to have ever been launched from any yard.","source":"archetype","sourceNote":"generic armored-warship archetype, era-blurred (age-of-sail through dreadnought)"},{"name":"The War-Wyrm","cr":10,"role":"apex","type":"Dragon","size":"Large","frame":"young-red-dragon","model":"young-red-dragon","summary":"chained siege-dragon deployed like a living artillery piece","flavor":"Chained to a war chariot bigger than most houses, it's less a monster than a munitions budget with wings and a grudge.","source":"archetype","sourceNote":"generic siege-dragon archetype used as the theater's ultimate weapon, not tied to any named dragon myth"},{"name":"The Death Knight of No Nation","cr":11,"role":"apex","type":"Undead","size":"Medium","frame":"death-knight-aspirant","model":"death-knight-aspirant","summary":"undead commander claimed by every faction, loyal to none","flavor":"Every side in every war in this theater has, at one time, sworn he was fighting for them; he has stopped correcting anyone.","source":"archetype","sourceNote":"generic black-armored undead-commander archetype (fantasy stock type, no franchise ties)"},{"name":"The Siege of the World","cr":17,"role":"apex","type":"Fiend","size":"Huge","frame":"ice-devil","model":"ice-devil","summary":"war given a body, wearing every era's uniform at once","flavor":"Wears every era's uniform at once and none convincingly; the theater's honest answer to what War would look like if it ever had to show its face.","source":"archetype","sourceNote":"original apex — the theater's totalizing embodiment of endless war, an original composite figure, not a myth or franchise reskin"}],
 "high-seas":[{"name":"Press-Ganged Deckhand","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit","model":"bandit","summary":"Unwilling conscript swinging a cutlass under threat","flavor":"Taken off a dock at knifepoint three ports back; fights because the alternative is the lash, not because he wants your blood."},{"name":"Bilge Rat Swarm","cr":0.25,"role":"mook","type":"Beast","size":"Medium","frame":"swarm-of-rats","model":"swarm-of-rats","summary":"Chittering vermin tide pouring from the hold","flavor":"They ate the last cook's boots and are working on his replacement's; every hold has them and every hold pretends not to."},{"name":"Rope-Scar Cutthroat","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"pirate","model":"pirate","summary":"Cutlass-and-flintlock buccaneer swarming the rail","flavor":"Owes the crew's articles more than he'll ever earn; boards ships to buy back a little of his own name."},{"name":"Chum-Slick Reef Shark","cr":0.5,"role":"mook","type":"Beast","size":"Medium","frame":"reef-shark","model":"reef-shark","summary":"Blood-trail shark circling a wounded hull","flavor":"Follows any ship that's been bleeding into its wake — a bad sign the crew reads correctly and ignores anyway."},{"name":"Waterlogged Deckwalker","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"zombie","model":"zombie","summary":"Drowned crewman shambling back up the chain","flavor":"Went over in a storm and came back up the anchor chain; still wears the duty rota pinned to a rotted coat."},{"name":"Rattling Bone-Crew Deckhand","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton-warrior","model":"skeleton-warrior","summary":"Cutlass-armed skeleton still standing its watch","flavor":"Picked clean by fish and time, still hauling the same rigging it died hauling; the rope never lets a bone crew rest."},{"name":"Fin-Toothed Raider","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"sahuagin-warrior","model":"sahuagin-warrior","summary":"Fish-fanged sea-devil boarding from below","flavor":"Rises over the gunwale in packs when a hull rides low and slow; drags what it takes back down before the alarm bell finishes ringing."},{"name":"Kraken-Spawn Squidling","cr":1,"role":"mook","type":"Beast","size":"Large","frame":"giant-octopus","model":"giant-octopus","summary":"Trench-spawned tentacle-beast dragging sailors under","flavor":"A juvenile shed off something vastly larger down in the trench; still small enough to drag a man under one-handed."},{"name":"Gull-Eyed Wreck Harpy","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"harpy","model":"harpy","summary":"Rock-nesting harpy luring ships onto reefs","flavor":"Nests in the rigging of ships too slow to outrun it, singing sailors toward the rocks it circles like a gull circles chum."},{"name":"Debt-Marked Bosun","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"scout","summary":"Ledger-keeping enforcer collecting the crew's debts","flavor":"Keeps the ledger of who owes the crew what, in coin or blood, and collects personally when a name comes due."},{"name":"Deep-Fang Sea-Devil Priest","cr":2,"role":"elite","type":"Humanoid","size":"Medium","frame":"sahuagin-priest","model":"sahuagin-priest","summary":"Sea-devil war-priest chanting a raiding pack to frenzy","flavor":"Chants the raiding packs into a blood-frenzy from the wave-tops, offering the drowned to something older than the trench."},{"name":"Quartermaster of the Broken Articles","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-captain","model":"bandit-captain","summary":"Shadow-captain running the ship by fear alone","flavor":"Runs discipline on a ship whose captain hasn't been seen topside in weeks; the crew fears him more than any storm."},{"name":"Chain-Dragging Drowned Sailor","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"wight","model":"wight","summary":"Anchor-chained revenant press-ganging the living","flavor":"Went down chained to the very anchor he was ordered not to release; surfaces to recruit a crew that never mutinies twice."},{"name":"Mutinous First Mate","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"knight","model":"knight","summary":"Blade-drawn mate who murdered his way to command","flavor":"Slit the old captain's throat over a fair split and never looked back; the crew that followed him into it now wonders whose throat is next."},{"name":"Fogbank Siren","cr":4,"role":"elite","type":"Fey","size":"Medium","frame":"green-hag","model":"green-hag","summary":"Fog-shrouded siren-witch bartering safe passage","flavor":"Sells safe passage through her fog for a name, a memory, or a firstborn — and always collects in a currency the crew didn't expect."},{"name":"Lantern-Eyed Ghost Captain","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"ghost","model":"ghost","summary":"Translucent captain still haunting his own quarterdeck","flavor":"Still walks his own quarterdeck on the night the fog rolls thick, hailing living ships for a berth he'll never fill twice."},{"name":"Riptide Elemental","cr":5,"role":"elite","type":"Elemental","size":"Large","frame":"water-elemental","model":"water-elemental","summary":"Living riptide dragging a wreck's leftovers under","flavor":"A standing current with a temper, summoned or born where a ship went down wrong; drags cargo and crew alike to the same grave."},{"name":"Deep-Baron of the Drowning Grounds","cr":5,"role":"elite","type":"Humanoid","size":"Large","frame":"sahuagin-baron","model":"sahuagin-baron","summary":"Reef-ruling sea-devil warlord commanding raid packs","flavor":"Rules a reef of wrecks and the things that raid from them; ships that fish his water pay a toll in hulls."},{"name":"Plague-Hulk Zombie Crew","cr":6,"role":"elite","type":"Undead","size":"Large","frame":"chimera","model":"chimera","summary":"Fused mass of drowned dead still crewing the hulk","flavor":"A three-decker's worth of drowned dead fused by rot and current into one groaning, many-armed mass still trying to crew the ship."},{"name":"Storm-Caller of the Drowned Choir","cr":6,"role":"elite","type":"Humanoid","size":"Medium","frame":"mage","model":"mage","summary":"Voice-traded witch who calls storms on command","flavor":"Traded her voice to something under the swells for weather on command; the crew loves her and never quite meets her eyes."},{"name":"The Admiral of Nowhere","cr":8,"role":"high","type":"Undead","size":"Medium","frame":"vampire-nightbringer","model":"vampire-nightbringer","summary":"Undead fleet-admiral commanding a century-scuttled navy","flavor":"Commands a fleet that was scuttled a hundred years ago and never noticed; still promotes the drowned, still courts-martial the disloyal."},{"name":"The Keelbreaker","cr":9,"role":"high","type":"Monstrosity","size":"Huge","frame":"hydra","model":"hydra","summary":"Many-headed sea-brute older than the shipping lanes","flavor":"Many-headed and older than the shipping lanes; every captain who's fought it and lived describes a different number of heads."},{"name":"The Ghost Ship Herself","cr":10,"role":"high","type":"Undead","size":"Gargantuan","frame":"behir","model":"net-new: a sail-shredded derelict with a translucent hull, sailing herself","summary":"Self-sailing derelict crewed by its own drowned dead","flavor":"No living hand touches her wheel; she tacks into any wind, runs down any ship that spots her, and every soul she's ever taken still crews her rigging."},{"name":"The Fathom-Crowned Leviathan","cr":17,"role":"apex","type":"Monstrosity","size":"Gargantuan","frame":"kraken","model":"kraken","summary":"The keel-sunk horror sailors swear by and dread","flavor":"The keel-sunk horror every sailor's oath invokes without meaning it; wakes when a ship's debts to the sea itself finally come due."},{"name":"The Horizon's Own Reckoning","cr":19,"role":"apex","type":"Fiend","size":"Huge","frame":"balor","model":"net-new: a burning derelict captain wreathed in storm-fire, chained to a wheel of drowned hands","summary":"Storm-fire captain who sailed past the edge of the charts","flavor":"The line where the horizon keeps its own counsel made flesh — a captain who sailed too far past the edge of the charts and came back wrong, wearing a crown of storm-fire and unpaid debts."},{"name":"Salt-Cracked Deck Sweeper","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"warrior-infantry","model":"warrior-infantry","summary":"Low-rank deckhand enforcer, no say in the voyage","flavor":"A ship's boy grown into a shipboard bruiser, all rope-burn hands and no say in where the vessel sails."},{"name":"Powder Monkey Turned Cutthroat","cr":0.125,"role":"mook","type":"Humanoid","size":"Small","frame":"kobold","model":"kobold","summary":"Former powder-boy now knife-quick and patience-thin","flavor":"Started the crossing hauling shot to the gun deck; ended it with a knife of his own and no patience left."},{"name":"Barnacle-Crusted Beachcomber","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"commoner","model":"commoner","summary":"Wreck-looting beachcomber, quick to rob the living","flavor":"Picks a wreck's bones clean before the tide can, and isn't shy about who else gets picked clean too."},{"name":"Marooned Castaway","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"desperate-bandit","model":"desperate-bandit","summary":"Island-marooned mutineer's scapegoat, come back wrong","flavor":"Left on a spit of sand to die for a mutiny that wasn't his; came back off the island wrong and hungry."},{"name":"Gull-Picked Corpse Crab","cr":0.125,"role":"mook","type":"Beast","size":"Small","frame":"giant-crab","model":"giant-crab","summary":"Scavenging tideline crab drawn to the recently dead","flavor":"Scuttles the tideline in loose scavenging clusters, drawn to anything that used to breathe."},{"name":"Chain-Rattling Bilge Zombie","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"zombie","model":"zombie","summary":"Drowned bilge-worker who never noticed the sinking","flavor":"Drowned in the hold when the pumps failed and never noticed the ship went down around it."},{"name":"Wreck-Wood Skeleton","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton","model":"skeleton","summary":"Reef-floor skeleton reassembled by tide-logic","flavor":"Picked clean by fish and reassembled by whatever tide-logic runs the ocean floor's oldest graveyards."},{"name":"Grog-Mad Deckhand","cr":0.25,"role":"mook","type":"Humanoid","size":"Medium","frame":"tough","model":"tough","summary":"Becalmed sailor gone rum-mad and swinging","flavor":"Three weeks becalmed and a cracked rum cask turned an ordinary sailor into a swinging liability."},{"name":"Coral-Fanged Moray Swarm","cr":0.25,"role":"mook","type":"Beast","size":"Medium","frame":"swarm-of-piranhas","model":"swarm-of-piranhas","summary":"Territorial eel-knot nesting inside a breached hull","flavor":"A boiling knot of eels nesting in a hull-breach, territorial past all reason."},{"name":"Flying-Fish Strafer Flock","cr":0.25,"role":"mook","type":"Beast","size":"Medium","frame":"swarm-of-ravens","model":"swarm-of-ravens","summary":"Oversized gliding fish-flock that shreds exposed skin","flavor":"An unnaturally large school that glides clean over the gunwale and shreds an exposed hand or face."},{"name":"Bilge-Bloated Corpse Floater","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"zombie-plague-carrier","model":"zombie-plague-carrier","summary":"Bloated floating corpse that only moves when approached","flavor":"Bobs face-down until something living gets close, then it isn't face-down anymore."},{"name":"Rope-and-Rum Buccaneer","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"pirate","model":"pirate","summary":"Fair-weather buccaneer who renegotiates loyalty mid-fight","flavor":"Signed the articles for the split, not the cause, and will renegotiate both mid-boarding."},{"name":"Tide-Warped Sahuagin Scout","cr":0.5,"role":"mook","type":"Fiend","size":"Medium","frame":"sahuagin-warrior","model":"sahuagin-warrior","summary":"Sea-devil scout that tests hulls before the pod attacks","flavor":"Runs ahead of the raiding pod to test a hull's weak seams before the pack commits."},{"name":"Driftwood Effigy Watcher","cr":0.5,"role":"mook","type":"Construct","size":"Medium","frame":"scarecrow","model":"scarecrow","summary":"Wreck-spar effigy that patrols the reef it was built to ward","flavor":"Lashed together from wreck-spars by superstitious crews to ward the reef; wards it by walking the tideline itself now."},{"name":"Reef-Crawling Giant Crab","cr":0.5,"role":"mook","type":"Beast","size":"Medium","frame":"giant-crab","model":"giant-crab","summary":"Wreck-territorial crab that clamps and never releases","flavor":"Territorial over a wreck's cargo hold, clamps and doesn't let go until something breaks."},{"name":"Fogbound Lookout Wraith","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"specter","model":"specter","summary":"Dead lookout still calling sightings to a vanished crew","flavor":"Still stands the watch it died at, calling sightings to a crew that scattered a century ago."},{"name":"Anchor-Chain Ghoul","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"ghoul","model":"ghoul","summary":"Chain-tangled ghoul dragging fathoms of rusted iron","flavor":"Went down tangled in the anchor chain and rose still wrapped in it, dragging fathoms of rusted iron."},{"name":"Kraken-Spawn Tentacle Horror","cr":1,"role":"mook","type":"Aberration","size":"Medium","frame":"fish-folk","model":"fish-folk","summary":"Small deep-thing juvenile that boards and strikes throats","flavor":"A juvenile deep-thing washed inshore, small enough to board but old enough to know exactly where the throat is."},{"name":"Sea-Devil Net-Thrower","cr":1,"role":"mook","type":"Fiend","size":"Medium","frame":"sahuagin-warrior","model":"sahuagin-warrior","summary":"Sahuagin netter that drags swimmers under first","flavor":"Drags swimmers under with weighted netting before the rest of the raid ever surfaces."},{"name":"Salvage-Diver Ghoul","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"lacedon-sodden-ghoul","model":"lacedon-sodden-ghoul","summary":"Drowned salvager-ghoul that won't surface without its box","flavor":"Died prying a strongbox from a sunken hold and still won't surface without it."},{"name":"Hardtack Cannibal Crewman","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"Lifeboat survivor turned desperate, quiet cannibal","flavor":"What's left of a lifeboat crew that ran out of hardtack long before they ran out of each other."},{"name":"Shrieking Storm Petrel Swarm","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"swarm-of-bats","model":"swarm-of-bats","summary":"Storm-heralding bird swarm that screeches the ship's name","flavor":"Precedes every gale that matters, screaming the ship's name back at the crew before the wind does."},{"name":"Barrel-Bomb Mutineer","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit","model":"bandit","summary":"Mutineer wielding a lit powder keg as leverage","flavor":"Carries a lit powder keg into a boarding fight like it's a threat and a bargaining chip both."},{"name":"Wreck-Grown Rust Louse Swarm","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"rust-monster","model":"rust-monster","summary":"Hull-nesting vermin that rusts weapons to flakes","flavor":"Nests in derelict hulls and strips a boarding party's cutlasses to orange flakes before the fight even starts."},{"name":"Doldrums-Drunk Deserter","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"berserker","model":"berserker","summary":"Starvation-mad deserter, dangerous to would-be rescuers","flavor":"Jumped ship in the doldrums rather than starve slow, and regrets it in a way that makes him dangerous to rescuers."},{"name":"Barnacle Golem","cr":2,"role":"mook","type":"Construct","size":"Large","frame":"animated-armor","model":"net-new: a hull-plate golem crusted floor to helm in barnacles","summary":"Reef-grown armor golem woken by a scuttled hull","flavor":"Salvaged armor left lashed to a scuttled hull long enough for the reef to grow through the rivets and wake it up."},{"name":"Sea-Devil Priest's Acolyte","cr":2,"role":"mook","type":"Fiend","size":"Medium","frame":"sahuagin-priest","model":"sahuagin-priest","summary":"Junior sea-devil chanter half a beat behind the priest","flavor":"Chants the drowning-litany half a beat behind the priest, close enough to matter."},{"name":"Debt-Marked Purser","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"scout","summary":"Ship's purser running two ledgers, one true and one lie","flavor":"Keeps the true ledger of who owes the captain what, and the false one for the crew."},{"name":"Reef-Devil Trapper","cr":2,"role":"mook","type":"Fiend","size":"Medium","frame":"sahuagin-warrior","model":"sahuagin-warrior","summary":"Sea-devil that lures hulls onto reefs with false lanterns","flavor":"Lures hulls onto shoal-teeth with false lantern-signals, then finishes what the reef starts."},{"name":"Hollow-Eyed Lantern Ghost","cr":2,"role":"mook","type":"Undead","size":"Medium","frame":"will-o-wisp","model":"will-o-wisp","summary":"Drowned signalman's ghost-light, warning and luring both","flavor":"A drowned signalman's light, still swinging the warning nobody heeded, luring the unwary same as it once tried to save them."},{"name":"Rope-Trick Rigging Spider","cr":2,"role":"mook","type":"Monstrosity","size":"Large","frame":"giant-spider","model":"giant-spider","summary":"Rigging-nesting spider that snares sail-climbers with silk","flavor":"Nests high in a ghost ship's rigging, dropping silk lines to snare anyone who climbs to reef the sails."},{"name":"Rock-Skulking Bilge Ooze","cr":2,"role":"mook","type":"Ooze","size":"Medium","frame":"gray-ooze","model":"gray-ooze","summary":"Bilgewater ooze that corrodes hull-plate and boot leather alike","flavor":"Grew fat in a scuttled hold's standing bilgewater, corroding hull-plate and boot leather with equal patience."},{"name":"Quartermaster's Shakedown Man","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-captain","model":"bandit-captain","summary":"Articles-enforcer who finds loopholes when it profits him","flavor":"Enforces the Articles to the letter when it profits him and finds loopholes when it doesn't."},{"name":"Coral Golem Guardian","cr":3,"role":"elite","type":"Construct","size":"Large","frame":"animated-armor","model":"net-new: a jagged reef-coral colossus shaped like a boarding pike, alive with darting cleaner-fish","summary":"Patient coral colossus guarding a sunken treasure gallery","flavor":"Grown by something patient to guard a sunken treasure gallery, indifferent to the centuries it's taken."},{"name":"Storm-Wracked Harpy Matriarch","cr":3,"role":"elite","type":"Monstrosity","size":"Medium","frame":"harpy-matriarch","model":"harpy-matriarch","summary":"Wreck-nesting harpy matriarch that sings ships to their ruin","flavor":"Nests her brood on a wreck-reef and sings ships onto the rocks to feed them."},{"name":"Bone-Naga of the Drowned Vault","cr":4,"role":"elite","type":"Undead","size":"Large","frame":"bone-naga","model":"bone-naga","summary":"Ancient bone-naga coiled around a sunken vault's treasure","flavor":"Coiled around a sunken hold's strongbox for two hundred years, patient past any living captain's greed."},{"name":"Fen-Tide Merrow Raider","cr":4,"role":"elite","type":"Monstrosity","size":"Large","frame":"merrow","model":"merrow","summary":"Skiff-overturning merrow raider, plunder is an afterthought","flavor":"Overturns skiffs for the sport of it before it ever gets around to the plunder."},{"name":"Wreck-Diver Doppelganger","cr":4,"role":"elite","type":"Monstrosity","size":"Medium","frame":"doppelganger","model":"doppelganger","summary":"Shape-stealing killer that answers to its last victim's name","flavor":"Wears the face of whichever sailor it drowned last, and answers to that name at the next port."},{"name":"Rigging-Runner Assassin","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"bugbear-stalker-strangler","model":"bugbear-stalker-strangler","summary":"Above-boarding assassin who drops garrote-first onto helmsmen","flavor":"Boards from above, garrote-first, dropping from the mainmast onto whoever's steering."},{"name":"Brine-Cursed Werebear Bosun","cr":4,"role":"elite","type":"Monstrosity","size":"Medium","frame":"werebear","model":"net-new: a hulking, salt-matted bear-shape bosun's coat still buttoned over the fur","summary":"Cursed bosun who becomes a bear-thing under full moon","flavor":"Cursed by a witch-doctor for flogging the wrong sailor, and now the whole crew fears the full moon more than the storms."},{"name":"Powder-Keg Berserker Boarder","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"berserker-commander","model":"berserker-commander","summary":"First-wave boarding-axe berserker screaming a death-oath","flavor":"Leads the first wave over the gunwale swinging a boarding axe and screaming the crew's death-oath."},{"name":"Fogbank Siren's Herald","cr":4,"role":"elite","type":"Fey","size":"Medium","frame":"sea-hag","model":"sea-hag","summary":"Fog-wreathed hag singing harmony to lure ships ashore","flavor":"Sings the low harmony under the Siren's melody, close enough inshore that the fog never quite lifts."},{"name":"Sunken Chapel Revenant","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"wight-lord","model":"wight-lord","summary":"Drowned chaplain still preaching from a sunken pulpit","flavor":"A ship's chaplain who kept preaching as the water rose past the pulpit, and hasn't stopped since."},{"name":"Drowned Choir Cantor","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"mage","model":"mage","summary":"Storm-hymn cantor who calls weather nobody sane wants","flavor":"Leads the storm-hymn from the quarterdeck, calling weather nobody sane would ask for twice."},{"name":"Iron-Hulled Corsair Captain","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"pirate-captain","model":"pirate-captain","summary":"Three-ship corsair captain, sinker of every bounty-navy sent","flavor":"Runs a fleet of three under false flags, and has personally sunk every navy sent to collect the bounty."},{"name":"Reef Titan Anemone","cr":5,"role":"elite","type":"Monstrosity","size":"Large","frame":"otyugh","model":"otyugh","summary":"Anemone colony that mimics drowning victims to lure rescuers","flavor":"A hull-sized anemone colony that's learned the shape of a drowning man and mimics it to draw rescuers in."},{"name":"Gale-Bound Air Elemental Squallwright","cr":5,"role":"elite","type":"Elemental","size":"Large","frame":"air-elemental","model":"air-elemental","summary":"Bottled storm-elemental shaken loose in the worst weather","flavor":"Bound into a captain's storm-bottle generations back, and finally shaken loose in the worst possible weather."},{"name":"Drowned Duelist Wraith","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"wraith","model":"wraith","summary":"Duel-drowned officer's ghost, still gripping his rapier","flavor":"Lost the duel over prize-shares and went over the rail still holding his rapier; he's kept the grip."},{"name":"Sahuagin War-Priestess","cr":5,"role":"elite","type":"Fiend","size":"Medium","frame":"sahuagin-priest","model":"sahuagin-priest","summary":"Tide-timing sea-devil priestess who calls the surge to war","flavor":"Calls the tide itself into a raid, timing the assault to a surge no surface captain can predict."},{"name":"Boarding-Pike Skeleton Crew","cr":6,"role":"elite","type":"Undead","size":"Medium","frame":"skeleton-warrior","model":"skeleton-warrior","summary":"Disciplined drowned skeleton unit, still holds formation","flavor":"A drilled, disciplined unit of the drowned that still holds formation better than most living marines."},{"name":"Waterlogged Chimeric Hulk-Beast","cr":6,"role":"elite","type":"Undead","size":"Large","frame":"chimera","model":"chimera","summary":"Three drowned sailors fused into one furious hulk","flavor":"Three drowned crewmen fused by whatever curse sank the ship, now sharing one waterlogged, furious body."},{"name":"Deep-Baron's Shark-Bonded Enforcer","cr":6,"role":"elite","type":"Fiend","size":"Large","frame":"sahuagin-baron","model":"sahuagin-baron","summary":"Sea-devil baron who rides a bonded shark into every raid","flavor":"Rides a bonded reef shark into every raid and has never once had to swim himself."},{"name":"Hurricane-Voiced Storm Herald","cr":6,"role":"elite","type":"Elemental","size":"Large","frame":"invisible-stalker","model":"invisible-stalker","summary":"Unseen wind-scout that finds a ship's weakest rigging first","flavor":"An unseen wind-thing that rides ahead of a hurricane, testing a ship's rigging for the weak point the storm will use."},{"name":"Cursed Doubloon Wight-Captain","cr":6,"role":"elite","type":"Undead","size":"Medium","frame":"wight-lord","model":"wight-lord","summary":"Gold-cursed wight-captain who conscripts anyone who takes a coin","flavor":"Cursed by the very gold he stole to guard it forever, raising every sailor who touches a coin as his crew."},{"name":"Foundered Frigate's Ghast Bosun","cr":6,"role":"elite","type":"Undead","size":"Medium","frame":"ghast","model":"ghast","summary":"Foundered frigate's undead disciplinarian, punishment unending","flavor":"Still runs the flogging line on a foundered frigate's ghost-deck, and the punishment never actually ends."},{"name":"Kraken-Spawn Broodguard","cr":8,"role":"high","type":"Aberration","size":"Large","frame":"grick-ancient","model":"grick-ancient","summary":"Half-grown deep-thing guarding a brood-nest, already boat-sized","flavor":"Half-grown but already big enough to take a longboat down whole, guarding the nest for whatever birthed it."},{"name":"Drowned Fleet Admiral's Ghost","cr":8,"role":"high","type":"Undead","size":"Medium","frame":"vampire-nightbringer","model":"vampire-nightbringer","summary":"Ghost admiral commanding an invisible spectral squadron","flavor":"Still commands a spectral squadron that only he can see, and still expects every ship on the horizon to salute."},{"name":"Reef-Cracker Hydra","cr":8,"role":"high","type":"Monstrosity","size":"Huge","frame":"hydra","model":"hydra","summary":"Cave-denned hydra scarred by three failed charting attempts","flavor":"Denned in a sea-cave that's swallowed three ships trying to chart it, each head a different scar from the attempts."},{"name":"Boarding-Fiend Bone Devil","cr":9,"role":"high","type":"Fiend","size":"Large","frame":"bone-devil","model":"bone-devil","summary":"Contracted boarding-fiend, payment terms deliberately vague","flavor":"Contracted by a desperate captain for one impossible raid, and never bothered reading the fine print about payment."},{"name":"Storm-Bound Efreeti Corsair","cr":9,"role":"high","type":"Elemental","size":"Large","frame":"djinni","model":"net-new: a fire-wreathed genie bound into a captain's figurehead, steam hissing where flame meets sea-spray","summary":"Figurehead-bound fire-genie granting speed for an unpaid price","flavor":"Bound into a corsair ship's figurehead by a desperate deal, and grants the crew impossible speed for an unpaid price."},{"name":"Undertow Terror of the Shoals","cr":10,"role":"high","type":"Monstrosity","size":"Huge","frame":"remorhaz","model":"remorhaz","summary":"Shoal-burrowing terror that swallows hulls whole from beneath","flavor":"Burrows through sandbars and shoal-mud the way its cousins burrow through snow, swallowing hulls whole from below."},{"name":"Pale Fathom Wight-Lord","cr":10,"role":"high","type":"Undead","size":"Gargantuan","frame":"haunting-revenant","model":"haunting-revenant","summary":"Generational wreck-revenant that drags its whole crew back up","flavor":"Rises from a specific wreck-site once a generation, always dragging the whole doomed crew back up with him."},{"name":"Coral Throne Basilisk-Queen","cr":11,"role":"high","type":"Monstrosity","size":"Huge","frame":"behir","model":"behir","summary":"Reef-throne guardian that petrifies looters of a drowned crown","flavor":"Coils a sunken palace's reef-throne, petrifying anything that tries to loot the drowned crown beside her."},{"name":"Death-Knight of the Broken Articles","cr":11,"role":"high","type":"Undead","size":"Medium","frame":"death-knight-aspirant","model":"death-knight-aspirant","summary":"Blood-oathed undead enforcer of pirate-code violations","flavor":"Signed the Articles in his own blood and died enforcing every clause; still hunts crews who break the code."},{"name":"Sunken Archmage of the Drowned Spire","cr":12,"role":"high","type":"Humanoid","size":"Medium","frame":"archmage","model":"archmage","summary":"Two-centuries-drowned archmage still mid-spell in his tower","flavor":"Went down with his tower-ship still casting, and hasn't noticed two centuries pass underwater."},{"name":"Nightbringer of the Drowned Fleet","cr":13,"role":"high","type":"Undead","size":"Medium","frame":"vampire","model":"vampire","summary":"Shipboard vampire quietly turning a becalmed fleet's crew","flavor":"Turned in his own cabin during a becalmed crossing, and has been quietly recruiting the fleet ever since."},{"name":"The Bilge-Born Horror","cr":13,"role":"high","type":"Aberration","size":"Large","frame":"eye-tyrant","model":"eye-tyrant","summary":"Hold-grown horror that sees through the deck planks above","flavor":"Grew in the dark of a cursed hold on a diet of drowned stowaways, and sees every deck above it through the planks."},{"name":"The Drowned Doge","cr":14,"role":"apex","type":"Undead","size":"Medium","frame":"undead-eye-tyrant","model":"net-new: a bloated, crown-wearing merchant-lord corpse enthroned on a barnacled chair of fused coin","summary":"Drowned merchant-lord enthroned over the port he sank","flavor":"Bankrolled the fleet that sank an entire rival port, and now presides drowned over the wreckage he bought."},{"name":"The Ninth Wave Herald","cr":15,"role":"apex","type":"Elemental","size":"Huge","frame":"salamander-inferno-master","model":"net-new: a churning wall-wave given a face, lightning threading through its curling crest like veins","summary":"Sentient storm-wave that is the reason the ninth wave is worst","flavor":"Sailors swear the ninth wave in any storm is always the worst; this is why, and it knows the superstition is true."},{"name":"The Deathless Mutiny","cr":16,"role":"apex","type":"Undead","size":"Large","frame":"dracolich","model":"net-new: a fused mass of mutineers' corpses forming one many-armed horror","summary":"Fused mass of every drowned mutiny, wearing a stolen captain's coat","flavor":"Every crew that ever turned on its captain and drowned for it feeds this thing; it wears whichever coat the nearest mutiny needs."},{"name":"The Sunken Cathedral's Choir Eternal","cr":17,"role":"apex","type":"Undead","size":"Huge","frame":"lich","model":"net-new: a coral-crowned lich enthroned in a drowned cathedral nave","summary":"Lich-chaplain still preaching to a two-century-drowned congregation","flavor":"A ship's chaplain who lichified himself to keep preaching to a congregation that drowned two centuries ago and never left."},{"name":"The Maw That Charts No Course","cr":18,"role":"apex","type":"Monstrosity","size":"Gargantuan","frame":"purple-worm","model":"purple-worm","summary":"Chartless leviathan that swallows convoys from no fixed direction","flavor":"Surfaces on no chart and no schedule, swallowing whole convoys, and every survivor swears a different direction it came from."},{"name":"the Drowned Captain","cr":6,"role":"high","type":"undead","size":"Medium","frame":"pirate-captain","model":"pirate-captain","summary":"undead ship's-master, obsessed and unable to stop commanding","flavor":"Lashed to a wheel that rotted out from under him decades ago, he still barks headings to a crew that stopped answering. Cross his wake and he'll press every soul aboard into one more hunt.","source":"public-domain","sourceNote":"generic mad-captain figure in the vein of Melville's Ahab (1851, PD) — our own obsessive, not Ahab himself"},{"name":"Bosun Wormwood","cr":1,"role":"mook","type":"humanoid","size":"Medium","frame":"pirate","model":"pirate","summary":"rank-and-file cutlass pirate, first over the rail","flavor":"Every crew needs someone to swing first and count the take later. He's not smart, he's not brave, but there's always another one behind him.","source":"archetype","sourceNote":"stock cutthroat-pirate-mook archetype (uncopyrightable stock type)"},{"name":"the Bone Quartermaster","cr":1,"role":"elite","type":"undead","size":"Medium","frame":"skeleton-warrior","model":"skeleton","summary":"undead crewman, ledger-obsessed and cutlass-armed","flavor":"He still keeps the manifest, tallying cargo that turned to silt a hundred years back. Argue with his math and he'll settle it with a cutlass.","source":"archetype","sourceNote":"undead-crew archetype built on the ghost-ship stock trope"},{"name":"the Kraken","cr":23,"role":"apex","type":"aberration","size":"Gargantuan","frame":"kraken","model":"kraken","summary":"the mythic apex sea-titan, rarely surfaces, never forgotten","flavor":"Sailors call it a myth right up until the sea stands up around their ship. It doesn't hunt for food anymore — it hunts because something that old resents being disturbed.","source":"public-domain","sourceNote":"Norse/Scandinavian sea-monster legend, pre-modern folklore (also the Alfred Tennyson sonnet, 1830, PD)"},{"name":"Moby, the White Whale","cr":17,"role":"apex","type":"beast","size":"Gargantuan","frame":"dragon-turtle","model":"dragon-turtle","summary":"the pale, unkillable whale that turns and fights back","flavor":"Pale as bone and scarred by a hundred failed harpoons, it doesn't flee ships — it turns and comes back for them. Some captains hunt it for the bounty. Others hunt it because they can't stop.","source":"public-domain","sourceNote":"Melville, Moby-Dick (1851, PD) — the whale itself, not any adaptation's design"},{"name":"a Siren","cr":3,"role":"elite","type":"monstrosity","size":"Medium","frame":"harpy-matriarch","model":"harpy-matriarch","summary":"reef-perched singer whose song offers exhausted sailors relief","flavor":"The song doesn't promise treasure or lust — it promises rest, which is worse, because half the crew actually wants that. She only has to be patient; the rocks do the rest.","source":"public-domain","sourceNote":"Greek myth — the Sirens (Homer's Odyssey, ancient/PD)"},{"name":"a Siren-Flock Screecher","cr":1,"role":"mook","type":"monstrosity","size":"Medium","frame":"harpy","model":"harpy","summary":"young siren, screeches and dives rather than enchants","flavor":"Not every siren has the voice for the killing song — the young ones just shriek and dive-bomb, hoping to knock a sailor loose from the rigging while their elders finish the job.","source":"public-domain","sourceNote":"Greek myth — the Sirens, junior/flock member"},{"name":"Scylla","cr":14,"role":"apex","type":"aberration","size":"Huge","frame":"hydra","model":"hydra","summary":"strait-bound many-headed horror, takes a toll from every passing hull","flavor":"She doesn't chase ships — she waits in the same strait she's waited in since before anyone's grandmother, and takes exactly one sailor from every hull that passes too close to her side.","source":"public-domain","sourceNote":"Greek myth — Scylla, the six-headed strait-monster (Homer's Odyssey, ancient/PD)"},{"name":"the Charybdis Maw","cr":15,"role":"apex","type":"elemental","size":"Gargantuan","frame":"water-elemental","model":"water-elemental","summary":"living whirlpool that swallows the strait on a rhythm","flavor":"Not a creature so much as an appetite the sea itself grew — three times a day the strait empties into her throat and nothing caught in the pull ever argues its way back out.","source":"public-domain","sourceNote":"Greek myth — Charybdis, the whirlpool-monster paired with Scylla (Homer's Odyssey, ancient/PD)"},{"name":"the Flying Dutchman's Wheelman","cr":10,"role":"high","type":"undead","size":"Gargantuan","frame":"haunting-revenant","model":"haunting-revenant","summary":"the cursed ghost-ship itself, animate and hunting for crew","flavor":"Doomed to round the same cape forever, the ship's own helm has become a creature of splintered wood and drowned will — it doesn't want passengers, it wants company in the doom.","source":"public-domain","sourceNote":"the Flying Dutchman — Cape maritime legend, pre-modern folklore (first written accounts 18th c.)"},{"name":"a Dutchman Deckhand","cr":0.5,"role":"mook","type":"undead","size":"Medium","frame":"zombie","model":"zombie","summary":"waterlogged member of the cursed eternal crew","flavor":"Soaked through and past caring, they still haul the same lines they died hauling. Boarding one ship is the same as boarding the next, to them — the work never ends.","source":"public-domain","sourceNote":"the Flying Dutchman legend — the doomed crew, pre-modern folklore"},{"name":"Davy Jones's Chain-Ghoul","cr":1,"role":"elite","type":"undead","size":"Medium","frame":"lacedon-sodden-ghoul","model":"lacedon-sodden-ghoul","summary":"drowned-sailor ghoul climbing up from the seabed locker","flavor":"Every drowned sailor goes to the Locker eventually, the old saying goes — and some of them claw back up the anchor chain first, still hungry for one more meal above the waterline.","source":"folklore","sourceNote":"Davy Jones's Locker — sailors' folk-idiom for the seabed afterlife, maritime folklore (not a specific character design)"},{"name":"the Locker-Warden","cr":13,"role":"apex","type":"fiend","size":"Huge","frame":"marid","model":"marid","summary":"the folkloric seabed afterlife given a keeper, vast and patient","flavor":"Every sailor swears the Locker has a keeper who counts the dead as they settle. Whether that's true or just something sailors tell each other in a storm, something down there is definitely counting.","source":"folklore","sourceNote":"Davy Jones's Locker folk-idiom, personified as its own keeper — our invention on the folklore, not a claimed character"},{"name":"a Sea Hag of the Shoals","cr":2,"role":"elite","type":"fey","size":"Medium","frame":"sea-hag","model":"sea-hag","summary":"reef-dwelling hag who barters weather for confessions","flavor":"She trades storms for secrets and secrets for storms, and never tells you which one you actually bought. Sailors leave offerings on the reef so she'll look the other way.","source":"public-domain","sourceNote":"folk sea-hag figure, generic maritime witch-crone (not tied to any single copyrighted work)"},{"name":"a Sahuagin Raider","cr":0.5,"role":"mook","type":"fiend","size":"Medium","frame":"sahuagin-warrior","model":"sahuagin-warrior","summary":"reef-raiding fish-humanoid, opportunistic wreck-stripper","flavor":"They rise off the reef in packs when a hull rides too low and too slow, stripping a wreck bare before the survivors even reach the boats.","source":"archetype","sourceNote":"generic fish-humanoid raider archetype (own deep-water raider framing, no external IP)"},{"name":"a Sahuagin Depth-Priest","cr":2,"role":"elite","type":"fiend","size":"Medium","frame":"sahuagin-priest","model":"sahuagin-priest","summary":"deep cult priest who blesses reef-raids with dread invocations","flavor":"He blesses the raids in a tongue that predates any surface language, and the raiders fight harder for it — not out of faith exactly, more like fear of what he'd do if they didn't.","source":"archetype","sourceNote":"generic fish-humanoid priest archetype, own deep-sea cult framing"},{"name":"a Merrow Wrecker","cr":2,"role":"elite","type":"monstrosity","size":"Large","frame":"merrow","model":"merrow","summary":"brutish sea-ogre that swarms wrecks for the meal, not the loot","flavor":"Not clever, just strong and hungry and drawn to the sound of splintering hulls. A merrow doesn't wreck ships for treasure — treasure's just what's left after it eats.","source":"archetype","sourceNote":"generic ogre-of-the-sea archetype (folkloric merrow stock type, no specific IP)"},{"name":"the Bosun's Ghost","cr":4,"role":"elite","type":"undead","size":"Medium","frame":"banshee","model":"banshee","summary":"haunting ship's-officer whose whistle warns (or curses) the crew","flavor":"He still walks his rounds belowdecks, and any living sailor who hears his whistle in the dark knows to brace for something going badly wrong topside within the hour.","source":"archetype","sourceNote":"generic maritime-haunting archetype — the officer who died on duty and can't leave it"},{"name":"a Corsair Deckhand","cr":1,"role":"mook","type":"humanoid","size":"Medium","frame":"scout","model":"scout","summary":"nimble boarding-raider, cuts lines before the main assault","flavor":"Fast over the rigging and faster with a knife, these are the ones sent ahead to cut lines and douse lanterns before the boarding party even shows itself.","source":"archetype","sourceNote":"generic historical-corsair mook archetype — long-dead seafaring raider figure, not any named individual"},{"name":"the Storm-Bound Djinn","cr":11,"role":"apex","type":"elemental","size":"Large","frame":"djinni","model":"djinni","summary":"elemental genie fused into a waterspout, capricious and huge","flavor":"Bound into a waterspout centuries ago by a captain who never wrote down how, it now answers to no one and drags whole ships skyward just to watch them fall.","source":"archetype","sourceNote":"elemental sea-storm archetype drawn from the broad genie/elemental stock type of maritime legend"},{"name":"the Wrecking Reef-Wraith","cr":5,"role":"high","type":"undead","size":"Medium","frame":"wraith","model":"wraith","summary":"drowned wrecker's ghost, still luring ships onto the rocks","flavor":"In life it lit false beacon-fires to lure ships onto the rocks for salvage. In death it just lights the fires — there's no cargo left to want, only the habit.","source":"archetype","sourceNote":"generic ghost-of-the-shoals archetype — the drowned wrecker who lured ships onto rocks in life"}],
 "lost-world":[{"name":"Sand-Choked Sentry","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton","model":"skeleton","summary":"classic bone guardian, forever walking its post","flavor":"A picked-clean guard still standing post at a gate nobody uses, sand pouring from its ribs."},{"name":"Glyph-Warded Scarab Swarm","cr":0.25,"role":"mook","type":"Swarm","size":"Medium","frame":"swarm-of-insects","model":"swarm-of-rats","summary":"tomb-curse insect swarm guarding a sealed door","flavor":"A living seal poured into a doorway generations ago; disturb the lintel and the carpet of beetles rises."},{"name":"Sun-Fat Ridgeback","cr":0.25,"role":"mook","type":"Beast","size":"Medium","frame":"giant-lizard","model":"giant-lizard","summary":"oversized lizard basking among fallen ruins","flavor":"A sun-fat lizard the size of a hound, sunning on toppled cornices until your shadow crosses it."},{"name":"Linen-Wrapped Shambler","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"zombie","model":"zombie","summary":"rot-wrapped shambler retracing a dead ritual","flavor":"A pilgrim mummified mid-step by the dry wind, still shuffling a processional route no one remembers."},{"name":"Blind Archive-Gnawer","cr":0.125,"role":"mook","type":"Beast","size":"Small","frame":"giant-rat","model":"giant-rat","summary":"blind vermin swarm infesting the buried archive","flavor":"Pale, sightless rat-things nesting in the archive halls for a thousand years, chewing scrolls no one will miss."},{"name":"Cracked Watch-Idol","cr":0.5,"role":"mook","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"animated stone idol stuck on an endless patrol","flavor":"A hollow votive statue jerking through a guard pattern it can no longer complete without falling over."},{"name":"Vine-Choked Ambusher","cr":0.5,"role":"mook","type":"Beast","size":"Medium","frame":"giant-wolf-spider","model":"giant-wolf-spider","summary":"venomous ambush-spider lurking in overgrown ruins","flavor":"Something fat and patient in the vines strangling the ornamental garden; it strikes from beneath the flowers."},{"name":"Bone-Orchard Jackal","cr":0.25,"role":"mook","type":"Beast","size":"Medium","frame":"jackal","model":"jackal","summary":"scavenger jackal pack circling grave robbers","flavor":"Pack scavenger that has learned tomb-robbers mean an easy meal; it circles at the treeline, waiting for the digging to stop."},{"name":"Curse-Bound Grave Ghoul","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"ghoul","model":"ghoul","summary":"paralyzing ghoul, once a fellow tomb-raider","flavor":"Someone who broke the same seal you're about to break, and never made it back out."},{"name":"Snake-Cult Zealot","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"yuan-ti-infiltrator","model":"cultist","summary":"fanged serpent-cultist guarding forbidden rites","flavor":"A serpent-blooded devotee who kept the old faith alive underground long after the empire fell, fangs bared under a ceremonial mask."},{"name":"Wall-Set Spear-Guard","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"mummy","model":"mummy","summary":"bandaged vizier still guarding an empty throne","flavor":"The last vizier, wound in the same linens as the dead-tongue king it still serves, delivering proclamations to an empty throne room."},{"name":"Plinth-Fused Sentinel","cr":4,"role":"elite","type":"Construct","size":"Large","frame":"helmed-horror","model":"helmed-horror","summary":"stone temple guardian bound to bar the sanctum","flavor":"A carved guardian fused to its plinth, sworn to never let the inner sanctum see a second dawn of daylight."},{"name":"Riddle-Keeper of the Threshold","cr":6,"role":"elite","type":"Monstrosity","size":"Large","frame":"sphinx-of-secrets","model":"sphinx-of-lore","summary":"riddling sphinx guarding the tomb's final gate","flavor":"A stone-eyed watcher at the last unbroken gate, bound to test any who'd pass with a question the builders thought unanswerable."},{"name":"Raptor of the Ruined Plaza","cr":2,"role":"elite","type":"Beast","size":"Large","frame":"allosaurus","model":"allosaurus","summary":"pack-hunting raptor stalking the ruined plaza","flavor":"A lean pack-hunter that has ruled the crumbled plaza for generations, using fallen colonnades as blinds."},{"name":"Living Armor-Back","cr":3,"role":"elite","type":"Beast","size":"Huge","frame":"ankylosaurus","model":"ankylosaurus","summary":"club-tailed armored dinosaur, unstoppable and slow","flavor":"A slow tank of a beast that has worn a path through the sacred road for so long its footprints are mistaken for paving."},{"name":"Horned Terror of the Sacred Road","cr":5,"role":"elite","type":"Beast","size":"Huge","frame":"triceratops","model":"triceratops","summary":"three-horned dinosaur charging trespassers on sight","flavor":"A three-horned bull of a beast that charges anything crossing its stretch of the ceremonial highway."},{"name":"The Weeping Cistern","cr":5,"role":"elite","type":"Ooze","size":"Large","frame":"black-pudding","model":"black-pudding","summary":"corrosive ooze filling a flooded sacred bath","flavor":"Ceremonial water gone wrong across centuries of stagnation and old magic, filling the sunken bath-hall."},{"name":"Marching Colossus of the Processional","cr":5,"role":"elite","type":"Construct","size":"Large","frame":"flesh-golem","model":"stone-golem","summary":"towering stone statue still marching a dead parade","flavor":"A processional statue built to march the ceremonial road once a generation; the ceremony stopped, but nobody told the statue."},{"name":"Basalt Gaze of the Garden","cr":6,"role":"elite","type":"Monstrosity","size":"Large","frame":"medusa","model":"medusa","summary":"snake-haired guardian posing as garden statuary","flavor":"Cursed by the same magic that petrified the garden's statuary, she has become one more monument in a courtyard full of them — until she moves."},{"name":"Coiled Warden of the Inner Vault","cr":10,"role":"high","type":"Monstrosity","size":"Large","frame":"guardian-naga","model":"guardian-naga","summary":"giant guardian serpent coiled around the vault door","flavor":"A serpentine spirit bound by the builders to guard the innermost vault, ancient and imperturbably patient with intruders."},{"name":"Throne-Ape of the Fallen Grove","cr":7,"role":"high","type":"Beast","size":"Huge","frame":"giant-ape","model":"giant-ape","summary":"worshipped ape-god ruling the collapsed temple grove","flavor":"A colossal ape the ruin's people once worshipped as a living god; it still holds court over the collapsed temple grove, and it still expects tribute."},{"name":"Ever-Marching Automaton King","cr":9,"role":"high","type":"Construct","size":"Huge","frame":"clay-golem","model":"stone-golem","summary":"golem king still guarding a throne that's empty","flavor":"A war-engine built in the last king's image to defend the throne room forever; its coronation speech still loops, garbled, from a mouth that was never meant to speak this long."},{"name":"Apex Titan-Lizard","cr":8,"role":"high","type":"Beast","size":"Huge","frame":"tyrannosaurus-rex","model":"tyrannosaurus-rex","summary":"apex tyrant-lizard ruling the collapsed dome","flavor":"The garden's true owner now — a saurian titan that has claimed the collapsed dome as its den, indifferent to the empire whose bones it sleeps on."},{"name":"The Unread King","cr":15,"role":"apex","type":"Undead","size":"Medium","frame":"mummy-lord","model":"mummy-lord","summary":"the mummified god-king, cursed and finally waking","flavor":"The god-king himself, entombed with a dead language carved into his sarcophagus so no living mouth could ever again pronounce his true name — and no living hand could ever again wake him. Someone always finds a way."},{"name":"The Standing Monument","cr":17,"role":"apex","type":"Construct","size":"Gargantuan","frame":"colossus","model":"colossus","summary":"gargantuan stone colossus that never stopped watching","flavor":"The greatest work of the vanished builders — a titan raised to watch the horizon until the world ended, animated by a will so patient it has outlasted every empire since, including the one that made it."},{"name":"Sun-Baked Scrap Raptor","cr":0.25,"role":"mook","type":"Beast","size":"Small","frame":"giant-lizard","model":"giant-lizard","summary":"Small pack raptor darting between ruined stones","flavor":"A pack-hunting lizard the size of a hound, quick to swarm anything that stumbles."},{"name":"Feathered Sickle-Claw","cr":0.5,"role":"mook","type":"Beast","size":"Medium","frame":"axe-beak","model":"axe-beak","summary":"Feathered raptor slashing with a hooked hind claw","flavor":"A quick-footed hunter with a slashing rear claw, common in the temple scrub."},{"name":"Sickle-Toed Ambush Runner","cr":1,"role":"mook","type":"Beast","size":"Medium","frame":"death-dog","model":"net-new: a pair of raptors flanking prey between broken columns","summary":"Coordinated raptor pair flanking around fallen columns","flavor":"Coordinated raptors that flank prey between broken columns."},{"name":"Withered Grave-Servant","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"zombie","model":"zombie","summary":"Shuffling tomb-slave still walking its funeral circuit","flavor":"A tomb-slave animated by lingering funerary rites, shuffling in endless circuits."},{"name":"Salt-Cured Husk","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"zombie","model":"zombie","summary":"Salt-cured husk shambling with brittle relentlessness","flavor":"Preserved by desert salts rather than proper rites, brittle but relentless."},{"name":"Rattling Ossuary Ward","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton","model":"skeleton","summary":"Wire-bound bones standing eternal watch over bones","flavor":"Bones bound with copper wire to stand eternal watch over an ossuary door."},{"name":"Loose-Jointed Tomb Archer","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton-archer","model":"net-new: a rattling bone-guard still loosing arrows down a processional hall","summary":"Bone-guard still loosing arrows down the hall","flavor":"Old bone-guards still loosing arrows down processional halls."},{"name":"Dune-Coiled Fang Serpent","cr":0.25,"role":"mook","type":"Beast","size":"Medium","frame":"giant-venomous-snake","model":"net-new: a coiled venomous serpent nesting in a cracked idol plinth","summary":"Venomous serpent nesting in a cracked plinth","flavor":"Nests in cracked idol plinths, strikes at intruding feet."},{"name":"Constrictor of the Choked Aqueduct","cr":0.25,"role":"mook","type":"Beast","size":"Large","frame":"constrictor-snake","model":"net-new: a heavy-bodied serpent coiled against wet aqueduct stone","summary":"Heavy serpent squeezing prey against wet stone","flavor":"A heavy-bodied snake that squeezes prey against aqueduct stone."},{"name":"Sun-Cult Acolyte","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"Robed acolyte chanting to unanswering old gods","flavor":"A robed devotee chanting to gods the ruins no longer answer."},{"name":"Dead-Tongue Initiate","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"priest-acolyte","model":"net-new: a gaunt initiate muttering an extinct liturgical language","summary":"Initiate half-mad from an extinct liturgical tongue","flavor":"Trains in the extinct liturgical language, half-mad from isolation."},{"name":"Scaled Temple-Guard","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"orc-warrior","model":"orc-warrior","summary":"Hardened spear-guard sworn to a dead dynasty","flavor":"A hardened spear-bearer sworn to a dynasty centuries gone."},{"name":"Feather-Cloaked Sentinel","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"hobgoblin-soldier","model":"hobgoblin-soldier","summary":"Plumed sentinel marching the crumbling outer wall","flavor":"Marches the outer wall in molting ceremonial plumage."},{"name":"Idol-Cracked Jackal","cr":0.25,"role":"mook","type":"Beast","size":"Small","frame":"jackal","model":"net-new: a scavenger jackal denning beneath a toppled idol","summary":"Scavenger jackal denning beneath a toppled idol","flavor":"A scavenger pack that dens beneath toppled idols."},{"name":"Grave-Wasp Nest Cluster","cr":0.5,"role":"mook","type":"Beast","size":"Medium","frame":"giant-wasp","model":"net-new: a wasp nest cluster swarming out of a hollow sarcophagus","summary":"Wasp nest swarming from a hollow sarcophagus","flavor":"Nests inside hollow sarcophagi, swarming any disturbance."},{"name":"Chittering Reliquary Swarm","cr":0.25,"role":"mook","type":"Swarm","size":"Medium","frame":"swarm-of-insects","model":"net-new: a scarab swarm boiling out of a cracked reliquary","summary":"Scarab swarm boiling from a cracked reliquary","flavor":"Scarabs boiling out of a cracked reliquary at the first footstep."},{"name":"Rope-Fanged Pit Viper","cr":0.125,"role":"mook","type":"Beast","size":"Tiny","frame":"venomous-snake","model":"net-new: a coiled viper hidden in a false-bottomed coffin","summary":"Coiled viper hidden in a false-bottomed coffin","flavor":"Coils in false-bottomed sarcophagi as a trap-maker's last defense."},{"name":"Choke-Vine Ambusher","cr":0.5,"role":"mook","type":"Plant","size":"Medium","frame":"vine-blight","model":"net-new: a creeping vine blight rooted in cracked temple flagstone","summary":"Creeping vine blight rooted in cracked flagstone","flavor":"A creeping blight rooted in cracked temple flagstone."},{"name":"Spore-Choked Idol Fungus","cr":0,"role":"mook","type":"Plant","size":"Medium","frame":"shrieker-fungus","model":"net-new: a fungal growth on an idol that shrieks when disturbed","summary":"Idol fungus shrieking to summon every guardian","flavor":"Shrieks a warning when disturbed, drawing every guardian in earshot."},{"name":"Loincloth Grave-Robber","cr":0.125,"role":"mook","type":"Humanoid","size":"Medium","frame":"bandit","model":"bandit","summary":"Desperate local looting the same cursed tombs","flavor":"A local desperate enough to loot the same tombs the party is exploring."},{"name":"Whisper-Idol Cultist Fanatic","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist-fanatic","model":"cultist-fanatic","summary":"Fanatic convinced the silent idols still listen","flavor":"Speaks in the dead tongue and believes the idols still listen."},{"name":"Broken-Fang Wererat Tomb-Rat","cr":2,"role":"elite","type":"Monstrosity","size":"Medium","frame":"wererat","model":"net-new: a cursed grave-looter scurrying tomb tunnels as vermin","summary":"Cursed looter scurrying tunnels as vermin","flavor":"A cursed grave-looter who now scurries the tunnels as vermin by night."},{"name":"Stalking Sand-Ambusher","cr":3,"role":"elite","type":"Monstrosity","size":"Large","frame":"phase-spider","model":"net-new: a spider-shape slipping through desert heat-mirage to ambush","summary":"Ambusher slipping through heat-mirage to strike","flavor":"Slips between the desert's heat-mirage and the material world to strike."},{"name":"Petrifying Serpent-Crowned Guardian","cr":3,"role":"elite","type":"Monstrosity","size":"Medium","frame":"basilisk","model":"net-new: a stone-eyed guardian statue that petrifies with a glance","summary":"Stone-eyed guardian that petrifies with a glance","flavor":"A carved-looking beast said to have once been a living guard, now stone-eyed."},{"name":"Vulture-Headed Carrion Priest","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"bugbear-stalker","model":"net-new: a vulture-masked priest presiding over open-air excarnation rites","summary":"Vulture-masked priest presiding over excarnation rites","flavor":"Wears a vulture skull mask and presides over open-air excarnation rites."},{"name":"Sarcophagus-Bound Wight Steward","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"wight","model":"wight","summary":"Undead steward still enforcing dead household order","flavor":"Once the mummy-king's chief steward, still enforcing an outdated household order."},{"name":"Blazing Ember-Skull Oracle","cr":4,"role":"elite","type":"Undead","size":"Tiny","frame":"flameskull","model":"net-new: a burning severed skull muttering fire-lit prophecy","summary":"Astrologer's burning skull still muttering prophecy","flavor":"The severed head of a court astrologer, still muttering prophecy in fire."},{"name":"Broken Wing Terror-Bird","cr":4,"role":"elite","type":"Monstrosity","size":"Huge","frame":"giant-axe-beak","model":"giant-axe-beak","summary":"Flightless apex hunter ruling terraced garden ruins","flavor":"A flightless apex predator that once ruled the temple's terraced gardens."},{"name":"Vault-Sworn Ettin Doorkeeper","cr":4,"role":"elite","type":"Giant","size":"Large","frame":"ettin","model":"net-new: a two-headed brute chained to guard a single vault door","summary":"Two-headed brute oath-bound to guard one door","flavor":"Two-headed brute chained by old oath to guard a single vault door."},{"name":"Weretiger Jungle-Stalker","cr":4,"role":"elite","type":"Monstrosity","size":"Medium","frame":"weretiger","model":"net-new: a cursed hunter prowling the jungle canopy above the ruin","summary":"Cursed hunter prowling the ruin's jungle canopy","flavor":"A cursed hunter who prowls the jungle canopy above the ruin."},{"name":"Cracked-Idol Gargoyle Watcher","cr":2,"role":"elite","type":"Elemental","size":"Medium","frame":"gargoyle","model":"gargoyle","summary":"Stone guardian animated by residual sun-magic","flavor":"A stone temple guardian animated by residual sun-god magic."},{"name":"Ash-Grey Ochre Seep","cr":2,"role":"elite","type":"Ooze","size":"Large","frame":"ochre-jelly","model":"net-new: a corrosive ooze seeping through burial-chamber floor cracks","summary":"Corrosive ooze seeping through burial-chamber cracks","flavor":"Seeps through cracks in the burial chamber floor, dissolving the careless."},{"name":"Hollow-Coffer Gelatinous Vault","cr":2,"role":"elite","type":"Ooze","size":"Large","frame":"gelatinous-cube","model":"net-new: a cube-shaped ooze absorbing a tomb corridor's grave goods","summary":"Cube-shaped ooze absorbing centuries of grave goods","flavor":"Fills an entire tomb corridor, absorbing centuries of grave goods."},{"name":"Chain-Bound Barrow Ghast","cr":2,"role":"elite","type":"Undead","size":"Medium","frame":"ghast","model":"net-new: a ravenous ghast in rotted chains once served the king's table","summary":"Ravenous ghast once serving the king's table","flavor":"A ravenous grave-thing that once served the mummy-king's table."},{"name":"Bandaged Falconry Ghast","cr":2,"role":"elite","type":"Undead","size":"Medium","frame":"ghast-base","model":"net-new: a bandaged ghast tending the tomb's mummified hunting birds","summary":"Ghast tending the tomb's mummified hunting birds","flavor":"Handles the tomb's mummified hunting birds with rotted, careful hands."},{"name":"Toppled Minotaur Skeleton Guard","cr":2,"role":"elite","type":"Undead","size":"Large","frame":"minotaur-skeleton","model":"net-new: a skeletal minotaur guard still pacing its ruined maze","summary":"Skeletal labyrinth-guardian still pacing its maze","flavor":"The bones of a labyrinth-guardian, still pacing its maze in death."},{"name":"Grave-Silk Poltergeist","cr":2,"role":"elite","type":"Undead","size":"Medium","frame":"poltergeist","model":"net-new: a shrouded poltergeist hurling funerary urns at intruders","summary":"Poltergeist hurling urns at silence-breakers","flavor":"Hurls funerary urns and shrouds at anyone who breaks tomb silence."},{"name":"Zombie-Herd Elephant Carrier","cr":2,"role":"elite","type":"Undead","size":"Large","frame":"ogre-zombie","model":"net-new: a shambling zombie elephant still hauling grave-cart chains","summary":"Shambling zombie beast still hauling grave-cart chains","flavor":"A shambling beast of burden still hauling grave-cart chains."},{"name":"Snake-Cult Priest of the Hollow Coil","cr":2,"role":"elite","type":"Humanoid","size":"Medium","frame":"priest","model":"net-new: a chanting priest summoning serpents up from the foundations","summary":"Priest whose chants summon serpents from below","flavor":"Leads chants that draw serpents up from the temple's foundations."},{"name":"Sacrificial Blind Prophet","cr":2,"role":"elite","type":"Humanoid","size":"Medium","frame":"orc-blind-prophet","model":"net-new: a blind prophet claiming to speak for a buried god","summary":"Blind prophet claiming to speak for a buried god","flavor":"Claims to speak for a god buried under the plaza; sometimes right."},{"name":"Wrapped Gladiator of the Sun Pit","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"gladiator","model":"net-new: a bandage-wrapped undying gladiator dueling an empty arena","summary":"Undying champion still dueling a vanished crowd","flavor":"An undying champion still fighting exhibition duels for a vanished crowd."},{"name":"Bog-Sunk Umber Digger","cr":5,"role":"elite","type":"Monstrosity","size":"Large","frame":"umber-hulk","model":"umber-hulk","summary":"Tunneling digger whose gaze cracks minds below","flavor":"Tunnels beneath the temple, its gaze cracking minds through cracked floors."},{"name":"Rot-Feathered Bulette Ambusher","cr":5,"role":"elite","type":"Monstrosity","size":"Large","frame":"bulette","model":"bulette","summary":"Burrowing ambusher erupting under temple courtyards","flavor":"Erupts from beneath temple courtyards, scattering worshippers and looters alike."},{"name":"Sun-Forged Earth Colossus Fragment","cr":5,"role":"elite","type":"Elemental","size":"Large","frame":"earth-elemental","model":"earth-elemental","summary":"Animate wall-shard powered by buried sun-forges","flavor":"A shard of an ancient wall given animus by buried sun-forges."},{"name":"Cinder-Font Fire Warden","cr":5,"role":"elite","type":"Elemental","size":"Large","frame":"fire-elemental","model":"fire-elemental","summary":"Warden guarding the mummy-king's eternal brazier","flavor":"Guards the eternal brazier said to keep the mummy-king's tomb warm."},{"name":"Rope-Trap Roper of the Deep Shaft","cr":5,"role":"elite","type":"Aberration","size":"Large","frame":"roper","model":"roper","summary":"Stalactite-mimic lurking a deep excavation shaft","flavor":"Mimics a stalactite in the temple's deepest excavation shaft."},{"name":"Bloated Refuse-Idol Otyugh","cr":5,"role":"elite","type":"Aberration","size":"Large","frame":"otyugh","model":"otyugh","summary":"Refuse-fed horror lurking a forgotten temple well","flavor":"Feeds on centuries of temple refuse dumped down a forgotten well."},{"name":"Shambling Garden Overgrowth","cr":5,"role":"elite","type":"Plant","size":"Large","frame":"shambling-mound","model":"net-new: a sentient tangle of vines reclaiming a hanging garden","summary":"Sentient overgrowth reclaiming a hanging garden","flavor":"A reclaimed hanging garden, fully sentient and territorial now."},{"name":"Ashen Vampire-Spawn Handmaiden","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"vampire-spawn","model":"net-new: a pale undead handmaiden tending a long-empty throne","summary":"Undead handmaiden still tending an empty throne","flavor":"A royal handmaiden turned undead, still tending an empty throne."},{"name":"Wight-Lord of the Processional Guard","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"wight-lord","model":"net-new: an armored wight-lord commanding the marching dead guard","summary":"Undead lord commanding the marching dead guard","flavor":"Commands the lesser dead who still march the ceremonial road."},{"name":"Sky-Talon Wyvern of the Ziggurat","cr":6,"role":"elite","type":"Dragon","size":"Large","frame":"wyvern","model":"wyvern","summary":"Wyvern roosting atop the tallest step-pyramid","flavor":"Roosts atop the tallest step-pyramid, territorial over the whole valley."},{"name":"Idol-Warped Chimera of Three Gods","cr":6,"role":"elite","type":"Monstrosity","size":"Large","frame":"chimera","model":"chimera","summary":"Grafted horror built from three patron-beast idols","flavor":"A grafted horror built from the temple's three patron-beast idols."},{"name":"Eight-Legged Web-Warden of the Vault","cr":6,"role":"elite","type":"Monstrosity","size":"Large","frame":"drider","model":"drider","summary":"Half-cursed drider webbing shut the treasure vault","flavor":"Half-cursed guardian left to web shut the innermost treasure vault."},{"name":"Storm-Song Satyr Revelmaster of Ruins","cr":6,"role":"elite","type":"Fey","size":"Medium","frame":"satyr-revelmaster","model":"net-new: a fey satyr holding a feral revel among fallen columns","summary":"Fey revelmaster luring travelers to ruin-feasts","flavor":"Holds feral revels among the fallen columns, luring the reckless in."},{"name":"Hollow-Throated Vrock Carrion-Caller","cr":6,"role":"elite","type":"Fiend","size":"Large","frame":"vrock","model":"net-new: a vulture-headed demon bound to guard forbidden grave-magic","summary":"Summoned scavenger-demon guarding forbidden grave-magic","flavor":"A summoned scavenger-demon bound to guard forbidden grave-magic."},{"name":"Serpent-Sworn Lamia of the Oasis Court","cr":4,"role":"elite","type":"Fiend","size":"Large","frame":"lamia","model":"net-new: a serpent-bodied lamia charming travelers at a hidden oasis","summary":"Charming oasis fiend feeding on stolen years","flavor":"Charms travelers at a hidden oasis before feeding on their years."},{"name":"Basalt-Skinned Gorgon of the Sun Gate","cr":5,"role":"elite","type":"Construct","size":"Large","frame":"gorgon","model":"net-new: a bull-shaped stone construct breathing petrifying dust at a gate","summary":"Bull construct petrifying intruders at the sun gate","flavor":"A bull-shaped construct whose breath turns intruders to stone at the gate."},{"name":"Nine-Serpent Basalt Hydra Spawn","cr":8,"role":"high","type":"Monstrosity","size":"Huge","frame":"hydra","model":"hydra","summary":"Cistern hydra whose heads regrow when severed","flavor":"Guards the temple's central cistern, heads regrowing with each severed strike."},{"name":"Petrified Roc of the High Terraces","cr":11,"role":"high","type":"Monstrosity","size":"Gargantuan","frame":"roc","model":"net-new: a colossal roc nesting atop a crumbling stone terrace","summary":"Colossal roc nesting on the crumbling terrace","flavor":"A colossal bird that nests atop the crumbling highest terrace tier."},{"name":"Fossil-Chained Behir of the Under-Passage","cr":11,"role":"high","type":"Monstrosity","size":"Huge","frame":"behir","model":"behir","summary":"Lightning serpent-beast patrolling flooded passages","flavor":"A lightning-scaled serpent-beast that patrols the flooded under-passages."},{"name":"Dune-Sunk Purple Devourer","cr":15,"role":"high","type":"Monstrosity","size":"Gargantuan","frame":"purple-worm","model":"purple-worm","summary":"Colossal worm tunneling beneath the whole valley","flavor":"Tunnels beneath the whole valley, swallowing pilgrims and pillars alike."},{"name":"Efreeti Bound to the Eternal Forge-Idol","cr":11,"role":"high","type":"Elemental","size":"Large","frame":"efreeti","model":"net-new: a flame-wreathed efreeti chained to stoke an idol-forge","summary":"Bound efreeti stoking the temple's idol forge","flavor":"Bound by old contract to stoke the forge that casts the temple's idols."},{"name":"Cyclops Oracle of the Buried Eye","cr":10,"role":"high","type":"Giant","size":"Huge","frame":"cyclops-oracle","model":"net-new: a blinded one-eyed giant reading omens in collapsing stone","summary":"Blinded giant seer reading omens in ruined stone","flavor":"A blinded seer-giant who reads omens in the ruins' collapsing stone."},{"name":"Marble-Veined Storm Giant Excavator","cr":13,"role":"high","type":"Giant","size":"Huge","frame":"storm-giant","model":"net-new: a marble-veined giant standing guard over a quarry pit","summary":"Giant quarry-guard who once cut the temple's stones","flavor":"Once quarried the temple's founding stones; still guards the quarry pit."},{"name":"Death-Cultist Herald of the Buried Sun","cr":8,"role":"high","type":"Humanoid","size":"Medium","frame":"death-cultist","model":"net-new: a robed cultist preaching that the sun itself lies entombed","summary":"Cultist preaching the sun is entombed, awaiting blood rite","flavor":"Preaches that the sun itself is entombed and can be freed by blood rite."},{"name":"Archpriest of the Dead Liturgy","cr":12,"role":"high","type":"Humanoid","size":"Medium","frame":"archpriest","model":"net-new: an aged archpriest, last living speaker of a dead tongue","summary":"Last living speaker of the temple's dead liturgy","flavor":"The last living speaker of the temple's true dead language, and its final judge."},{"name":"Bone-Crowned Death Knight of the Ziggurat","cr":11,"role":"high","type":"Undead","size":"Medium","frame":"death-knight-aspirant","model":"net-new: a bone-crowned death knight commanding a legion long gone","summary":"Entombed general commanding a legion long gone","flavor":"An entombed general still commanding a legion that no longer exists."},{"name":"Vault-Sealed Naga of the Bone Archive","cr":8,"role":"high","type":"Undead","size":"Large","frame":"bone-naga","model":"net-new: a serpent-sage naga coiled guarding an archive of the dead","summary":"Serpent-sage guarding the archive of the dead's names","flavor":"A serpent-sage bound to guard the archive of dead names."},{"name":"Frost-Cracked Abominable Cave-Beast","cr":9,"role":"high","type":"Monstrosity","size":"Huge","frame":"abominable-yeti","model":"abominable-yeti","summary":"Anomalous cold-beast denning in a frost-slick cave","flavor":"An anomalous cold-thing that dens in the temple's deepest, frost-slick cave."},{"name":"Rakshasa Vizier of the Broken Court","cr":13,"role":"high","type":"Fiend","size":"Medium","frame":"rakshasa","model":"rakshasa","summary":"Fiendish vizier still whispering from the throne's shadow","flavor":"The mummy-king's old advisor, still whispering counsel from the shadows of the throne."},{"name":"The Undying Ape-Colossus of the Sacred Grove","cr":16,"role":"apex","type":"Construct","size":"Gargantuan","frame":"iron-golem","model":"net-new: a titanic stone ape-idol animated to punish desecrators","summary":"Titanic ape-idol punishing desecrators of the grove","flavor":"A titanic idol carved in the shape of the ape-god, animated to punish the grove's desecrators."},{"name":"Dragon-Turtle of the Drowned Necropolis","cr":17,"role":"apex","type":"Dragon","size":"Gargantuan","frame":"dragon-turtle","model":"net-new: a shelled leviathan wearing a swallowed necropolis like armor","summary":"Shelled leviathan wearing a swallowed necropolis","flavor":"A shelled leviathan that swallowed a lesser necropolis whole and now wears it like armor."},{"name":"The First Priest-King, Undying","cr":18,"role":"apex","type":"Undead","size":"Tiny","frame":"demilich","model":"net-new: a jeweled, dreaming skull, all that remains of a founder-king","summary":"Founder-king's jeweled skull still dreaming empire","flavor":"All that remains of the dynasty's founder, a jeweled skull that still dreams of empire."},{"name":"Emperor Wyrm of the Sunken Ziggurat","cr":17,"role":"apex","type":"Undead","size":"Huge","frame":"dracolich","model":"net-new: a great serpent-dragon corpse bound to its own ziggurat","summary":"Serpent-dragon bound in death to its own ziggurat","flavor":"A great serpent-dragon bound in death to the ziggurat it once terrorized alive."},{"name":"The Ever-Watching Sphinx of Final Judgment","cr":17,"role":"apex","type":"Celestial","size":"Large","frame":"sphinx-of-valor","model":"sphinx-of-valor","summary":"Threshold sphinx judging souls by riddle or blade","flavor":"Judges every soul that crosses the temple threshold, riddle or blade in equal measure."},{"name":"Medusa","cr":6,"role":"elite","type":"Monstrosity","size":"Medium","frame":"medusa","model":"medusa","summary":"snake-haired gaze-petrify guardian of a forbidden shrine","flavor":"A cursed priestess left to guard a ruin no one else will enter; she doesn't hunt, she waits for you to look.","source":"public-domain","sourceNote":"Greek myth (Perseus cycle)"},{"name":"the Minotaur","cr":3,"role":"elite","type":"Monstrosity","size":"Large","frame":"minotaur-of-the-horned-king","model":"minotaur-of-the-horned-king","summary":"bull-headed labyrinth-warden, gores anything that gets turned around","flavor":"Bred as a punishment and grown into a king of his own maze — the walls moved to keep him, so now he moves them to keep you.","source":"public-domain","sourceNote":"Greek myth (Theseus / Cretan labyrinth)"},{"name":"the Hydra","cr":8,"role":"apex","type":"Monstrosity","size":"Huge","frame":"hydra","model":"hydra","summary":"regenerating many-headed swamp apex predator","flavor":"Every wound you land is a negotiation it wins later — cut deep enough, fast enough, or it simply outlasts you with one more mouth.","source":"public-domain","sourceNote":"Greek myth (Labors of Herakles)"},{"name":"the Cyclops","cr":6,"role":"elite","type":"Giant","size":"Huge","frame":"cyclops-sentry","model":"cyclops-sentry","summary":"one-eyed shepherd-giant sentry, brutal in close quarters","flavor":"He counts his flock by touch, one eye or none, and either way he's never once lost track of an intruder.","source":"public-domain","sourceNote":"Greek myth (Homer's Odyssey, Polyphemus)"},{"name":"the Oracle Cyclops","cr":10,"role":"high","type":"Giant","size":"Huge","frame":"cyclops-oracle","model":"cyclops-oracle","summary":"blind seer-giant, prophetic elite variant of the sentry","flavor":"Blinded on purpose, so the story goes, in trade for seeing further — he'll tell you your death before he deals it.","source":"public-domain","sourceNote":"Greek myth — Cyclopes as forge-kin of Hephaestus / seer tradition"},{"name":"the Chimera","cr":6,"role":"elite","type":"Monstrosity","size":"Large","frame":"chimera","model":"chimera","summary":"lion/goat/serpent composite, breathes fire mid-roar","flavor":"Three heads, three different opinions about how you should die — the goat screams first so the lion and the dragon don't have to.","source":"public-domain","sourceNote":"Greek myth (Iliad; Bellerophon cycle)"},{"name":"the Harpy","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"harpy","model":"harpy","summary":"filth-winged bird-woman raider, hunts in screaming flocks","flavor":"They don't so much attack as infest — a shrieking cloud that strips a camp of food and morale in the same pass.","source":"public-domain","sourceNote":"Greek myth (Argonautica; Aeneid)"},{"name":"the Harpy Matriarch","cr":3,"role":"elite","type":"Monstrosity","size":"Medium","frame":"harpy-matriarch","model":"harpy-matriarch","summary":"harpy brood-leader, coordinates the swarm's dive attacks","flavor":"Older, meaner, and smart enough to use her flock as bait — she circles while they soften you up.","source":"public-domain","sourceNote":"Greek myth — harpy tradition, elevated to a brood-leader"},{"name":"the Sphinx-Warden","cr":9,"role":"high","type":"Monstrosity","size":"Large","frame":"manticore","model":"net-new: lion-bodied, human-faced, feathered-winged riddler perched on a ruined threshold","summary":"riddling lion-bodied guardian barring a sealed passage","flavor":"She'll let you pass if you answer well — and she is in absolutely no hurry, because she has outlived every wrong answer she's ever heard.","source":"public-domain","sourceNote":"Greek/Egyptian myth (riddle-guardian tradition, Oedipus cycle)"},{"name":"Anubis's Jackal-Priest","cr":8,"role":"high","type":"Humanoid","size":"Medium","frame":"guard-captain","model":"net-new: jackal-masked embalmer-priest in funerary wrappings, ceremonial flail","summary":"jackal-masked tomb-priest, judges intruders before it fights them","flavor":"He was a man once, before the mask stopped coming off — now he weighs every heart that walks into his tomb, including his own.","source":"public-domain","sourceNote":"Egyptian myth/religion (Anubis, funerary tradition) — treated as a masked mortal priesthood, not the god"},{"name":"the Mummy","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"mummy","model":"mummy","summary":"bandage-wrapped rot-cursed guardian of a sealed tomb","flavor":"Wrapped, sealed, and cursed on purpose — it was meant to stay down here forever, and it resents every second you've made that not true.","source":"public-domain","sourceNote":"Egyptian funerary myth/folklore (pre-1929 literary tradition, e.g. Stoker's Jewel of Seven Stars)"},{"name":"Gilgamesh's Shade","cr":11,"role":"apex","type":"Humanoid","size":"Medium","frame":"death-knight-aspirant","model":"net-new: a once-great king's armored shade, bull-horned crown, still swinging for immortality","summary":"legendary king's undying shade, apex melee boss","flavor":"He tore down Humbaba, refused his own death twice, and still lost the one fight that mattered — now he re-fights every stranger like they might be that fight.","source":"public-domain","sourceNote":"Epic of Gilgamesh (Mesopotamian, ancient/public domain)"},{"name":"Humbaba","cr":8,"role":"apex","type":"Giant","size":"Huge","frame":"fomorian","model":"net-new: bark-skinned forest titan, roaring face of coiled intestine-like features per the epic's description","summary":"monstrous forest-guardian giant, terrifying roar attack","flavor":"He was posted here to keep the cedar forest safe from people exactly like you, and he has never once been relieved of that duty.","source":"public-domain","sourceNote":"Epic of Gilgamesh — forest guardian set by the gods"},{"name":"Grendel","cr":7,"role":"high","type":"Monstrosity","size":"Large","frame":"troll","model":"net-new: hulking marsh-born raider, iron-resistant hide, drags prey back to the fen","summary":"iron-immune marsh-raider, hunts camps at night","flavor":"He doesn't want your gold and doesn't want your land — he wants the noise you make to stop, permanently.","source":"public-domain","sourceNote":"Beowulf (Old English epic, public domain)"},{"name":"Grendel's Mother","cr":6,"role":"elite","type":"Monstrosity","size":"Large","frame":"merrow","model":"net-new: a mere-dwelling avenger, drags the fight underwater to fight on her terms","summary":"underwater ambush-avenger, drags foes into her mere","flavor":"She only comes up out of the mere when someone's killed one of hers — and by then the math has already stopped being in your favor.","source":"public-domain","sourceNote":"Beowulf — the mere-wife, avenging kin"},{"name":"Raptor Pack-Hunter","cr":0.5,"role":"mook","type":"Beast","size":"Medium","frame":"wolf","model":"net-new: feathered pack-hunting dromaeosaur, quick and coordinated","summary":"quick feathered pack-hunter, always comes in threes","flavor":"One alone is a nuisance; hearing three more calling back from the treeline is the actual threat.","source":"public-domain","sourceNote":"paleontological fact (dromaeosaurid dinosaur), no IP owner"},{"name":"Pteranodon Screecher","cr":0.25,"role":"mook","type":"Beast","size":"Medium","frame":"pteranodon","model":"pteranodon","summary":"cliff-nesting flying scavenger, snatches and flees","flavor":"It doesn't want a fight, it wants your lunch — but it'll take a finger to get it.","source":"public-domain","sourceNote":"paleontological fact (pterosaur), no IP owner"},{"name":"Allosaurus","cr":2,"role":"elite","type":"Beast","size":"Large","frame":"allosaurus","model":"allosaurus","summary":"mid-sized ambush predator, fast and relentless","flavor":"Not the biggest thing in the valley, just the fastest thing willing to test that against you.","source":"public-domain","sourceNote":"paleontological fact, no IP owner"},{"name":"Triceratops","cr":5,"role":"high","type":"Beast","size":"Huge","frame":"triceratops","model":"triceratops","summary":"armored horned grazer, devastating charge when cornered","flavor":"It would honestly rather be left alone grazing the fern-flats — it just won't be told to move twice.","source":"public-domain","sourceNote":"paleontological fact, no IP owner"},{"name":"Tyrannosaurus Rex","cr":8,"role":"apex","type":"Beast","size":"Huge","frame":"tyrannosaurus-rex","model":"tyrannosaurus-rex","summary":"the valley's apex predator, ends most fights in one bite","flavor":"The valley has a food chain and one name at the top of it — everything else here is just working out how to be somewhere else when it walks by.","source":"public-domain","sourceNote":"paleontological fact, no IP owner"}],
 "gloom":[{"name":"Threshold Rat","cr":0.125,"role":"mook","type":"Beast","size":"Tiny","frame":"giant-rat","model":"giant-rat","summary":"Vermin omen fleeing whatever else lives here","flavor":"Ordinary vermin that nest only in houses where something else already lives; they scatter from the cellar door the instant it's ajar, and never go back in."},{"name":"Guttered Wick","cr":0.125,"role":"mook","type":"Undead","size":"Tiny","frame":"will-o-wisp","model":"will-o-wisp","summary":"Drifting corpse-light that steals your shadow","flavor":"A candle-flame that should have died in the draft an hour ago; it drifts room to room looking for the wick it lost. Touch its light and your own shadow forgets to follow you for a minute."},{"name":"Grinning Poppet","cr":0.25,"role":"mook","type":"Construct","size":"Tiny","frame":"animated-flying-sword","model":"animated-flying-sword: a small porcelain doll skittering upright on cracked joints","summary":"The haunted doll that creeps when unwatched","flavor":"Left on the nursery shelf for three generations, it only moves when no one is looking directly at it, and it is always exactly one shelf closer than it was."},{"name":"Pallid Newcomer","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"zombie","model":"zombie","summary":"Fresh-buried neighbor still walking its route","flavor":"Someone who died recently enough that the neighbors still wave. It walks the same route to the same house every night and knocks exactly three times."},{"name":"Bone-Rattle Skeleton","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton","model":"skeleton","summary":"Reassembled grave-bones, a cult's patient tool","flavor":"Grave-robbed bones reassembled by something patient; it clicks when it walks, a metronome counting down to whatever the cult needs it for."},{"name":"Zealous Initiate","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"Robed true-believer running the ritual anyway","flavor":"A true believer in plain robes, still capable of guilt, still capable of running the ritual anyway. Answers to the coven without question."},{"name":"Static Reflection","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"shadow","model":"shadow","summary":"Mirror-double, one second behind, draining you","flavor":"A mirror-image one full second behind, that finally catches up and steps out of the glass. It drains you the way a slow leak drains a tire — you don't notice until you're on the ground."},{"name":"Rot-Handed Ghoul","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"ghoul","model":"ghoul","summary":"Grave-eater whose bite paralyzes the mourner","flavor":"Once a mourner who ate what it was supposed to bury; its paralytic bite is the reason funerals in the gloom are held at noon, never dusk."},{"name":"Moonshackled Cur","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"dire-wolf","model":"dire-wolf","summary":"Half-turned wolf-thing running with the pack","flavor":"Runs in the pack that follows the werewolf's howl, half-turned and losing more of itself with every full moon it survives."},{"name":"Household Poltergeist","cr":2,"role":"mook","type":"Undead","size":"Medium","frame":"poltergeist","model":"poltergeist","summary":"Decades-long tantrum that throws the furniture","flavor":"Not a haunting — a tantrum, ongoing, decades long. It throws whatever's closest and has strong opinions about who's allowed in its kitchen."},{"name":"Cellar Warden","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"wight","model":"wight","summary":"The cult's own guard now opening the door","flavor":"The cult leaves it down in the dark to keep the door shut from the inside — except lately it's been the one opening it."},{"name":"Full-Moon Shepherd","cr":3,"role":"elite","type":"Monstrosity","size":"Medium","frame":"werewolf","model":"werewolf","summary":"The neighbor who wears a wolf's face at midnight","flavor":"Wears its human face at the market and its true face at midnight, and swears every time it will be the last. It never is."},{"name":"Hollow-Robed Zealot","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"mummy","model":"mummy","summary":"Self-mummified elder still preaching to no one","flavor":"A cult elder who finished the rite on himself; wrapped in the vestments he died in, still leading services nobody living attends."},{"name":"Possessed Vessel","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"doppelganger","model":"doppelganger","summary":"A person worn like a coat, blinking wrong","flavor":"Wears a person like a coat, imperfectly — the voice is right but the blinking is wrong. Whatever's inside it wants the body back once its work is finished."},{"name":"The Slow Reflection","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"ghost","model":"ghost","summary":"Ghost one second behind, plotting to catch up","flavor":"Lives one mirror-second out of sync with the world; it has had a full lifetime alone in that lag to plan what it'll do the moment it catches up."},{"name":"Grief-Fed Banshee","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"banshee","model":"banshee","summary":"Wailing widow owed a wake that never came","flavor":"Mourns in a key that shatters glass and eardrums both; she was promised a wake that never happened, and she's still owed it."},{"name":"Coven Matriarch","cr":5,"role":"elite","type":"Fey","size":"Medium","frame":"night-hag","model":"night-hag","summary":"Coven matriarch trading in stolen sleep and souls","flavor":"The eldest of a coven of three, who trades in stolen sleep and worse; her sisters answer to her the way a storm answers to the moon."},{"name":"Marrow Revenant","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"vampire-spawn","model":"vampire-spawn","summary":"Undead thing that only wants its killer, unerringly","flavor":"Came back wrong and remembers exactly who wronged it. Walks in a straight line toward its killer through locked doors, walls, anything."},{"name":"Candlewax Doppelganger","cr":6,"role":"elite","type":"Monstrosity","size":"Medium","frame":"medusa","model":"medusa","summary":"Melting face that copies whoever stares longest","flavor":"A face that melts and re-sets itself into whoever last looked at it too long; meeting its eyes is how it decides which of you to become next."},{"name":"Congregation Made Flesh","cr":8,"role":"high","type":"Aberration","size":"Large","frame":"yuan-ti-abomination","model":"yuan-ti-abomination","summary":"A coven's dozen bodies fused into one prayer","flavor":"What happens when a coven's devotion finally has somewhere to go — a dozen willing bodies fused at the altar into one thing that still, somehow, prays."},{"name":"Warden of the Cellar Door","cr":8,"role":"high","type":"Undead","size":"Medium","frame":"vampire-nightbringer","model":"vampire-nightbringer","summary":"Vampire bound to the door that's never shut","flavor":"Bound to the one door in the house that's never fully closed; it has watched every family that ever lived there and outlasted all of them."},{"name":"Bell-Tolling Revenant","cr":10,"role":"high","type":"Undead","size":"Gargantuan","frame":"haunting-revenant","model":"haunting-revenant","summary":"Bell-tower revenant tolling once per debt owed","flavor":"A funeral bell's worth of grief given shape and a bell-tower's worth of reach; it tolls once for every soul it's owed, and it keeps very careful count."},{"name":"The Second Face in the Glass","cr":13,"role":"high","type":"Undead","size":"Medium","frame":"vampire","model":"vampire","summary":"Elder vampire kingpin living inside the mirrors","flavor":"An elder vampire kingpin who lives entirely inside reflective surfaces, one beat behind its prey, until the night it decides to be early instead."},{"name":"The Uninvited","cr":15,"role":"apex","type":"Undead","size":"Medium","frame":"mummy-lord","model":"mummy-lord","summary":"Ancient thing that only ever needs one knock","flavor":"It always knocks first. Every house it has ever entered, it was let in — a guest, a mourner, a face someone half-remembered — and it has never once needed to knock twice."},{"name":"The Possession at the Root","cr":19,"role":"apex","type":"Fiend","size":"Huge","frame":"balor","model":"balor","summary":"A congregation's willing vessels burned to one shape","flavor":"Not a demon wearing a body — a congregation's worth of willing vessels burned down to one true and monstrous shape, still calling itself by the coven's oldest, most patient name."},{"name":"Crawlspace Widow","cr":0.25,"role":"mook","type":"Beast","size":"Tiny","frame":"giant-wolf-spider","model":"giant-wolf-spider","summary":"Attic spider that drops on sleepers","flavor":"A bloated house-spider the size of a cat that drops from attic rafters onto sleeping throats."},{"name":"Threadbare Scarecrow","cr":1,"role":"mook","type":"Construct","size":"Medium","frame":"scarecrow","model":"scarecrow","summary":"Straw effigy that walks after moonrise","flavor":"A field-post effigy stuffed with grave-dirt straw that unpins itself at moonrise."},{"name":"Ashen Widow's Cat","cr":0.125,"role":"mook","type":"Beast","size":"Tiny","frame":"cat","model":"cat","summary":"Unblinking cat that tracks the dead","flavor":"A funeral-black cat that never blinks and always knows which door hides the coffin."},{"name":"Gutter Wraith","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"specter","model":"specter","summary":"Drowned grudge haunting the storm drains","flavor":"A drowned drunk's grudge, sluicing through storm drains looking for the one who left him there."},{"name":"Wick-Eyed Changeling Child","cr":0.5,"role":"mook","type":"Fey","size":"Small","frame":"sprite","model":"sprite","summary":"Cradle-swapped child with a widening smile","flavor":"A too-quiet foundling left in a cradle, its smile widening only when no one is looking."},{"name":"Tallow Ghoul","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"lacedon-sodden-ghoul","model":"lacedon-sodden-ghoul","summary":"Candle-vigil ghoul dripping rendered fat","flavor":"A ghoul that drips rendered fat from a crypt-candle vigil that never ended."},{"name":"Splintered Marionette","cr":0.5,"role":"mook","type":"Construct","size":"Small","frame":"animated-flying-sword","model":"net-new: a puppet with its own cut strings, still bowing","summary":"Self-cut puppet bowing to an empty house","flavor":"A puppet-theater star whose strings were cut by its own hand, still bowing to an empty house."},{"name":"Bog-Sunk Revenant","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton-warrior","model":"skeleton-warrior","summary":"Peat-bog hanged man risen with the noose","flavor":"A peat-preserved corpse hauled from the marsh, its noose still knotted at the throat."},{"name":"Pox-Marked Thrall","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"Plague villager thralled to a whisper","flavor":"A plague-branded villager who traded a fever for a whisper that never stops."},{"name":"Feral Barn Bat-Swarm","cr":0.25,"role":"mook","type":"Beast","size":"Large","frame":"swarm-of-bats","model":"swarm-of-bats","summary":"Bell-triggered swarm pouring from the rafters","flavor":"A rafters-thick cloud of bats that only stirs when the church bell cracks midnight."},{"name":"Rope-Burned Suicide","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"specter","model":"specter","summary":"Hanging-tree haunt re-living its last minute","flavor":"A hanging-tree haunt that re-lives its last minute on anyone who lingers beneath the branch."},{"name":"Hollow Nursemaid","cr":2,"role":"mook","type":"Undead","size":"Medium","frame":"greater-shadow","model":"greater-shadow","summary":"Lullaby-humming absence in the nursery wall","flavor":"A governess-shaped absence that hums lullabies through the nursery wall long after the family fled."},{"name":"Cur of the Black Barn","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"death-dog","model":"death-dog","summary":"Loyal farm dog that starved and rose wrong","flavor":"A farm dog that starved loyal beside its master's grave and rose wrong."},{"name":"Rat-King Knot","cr":2,"role":"mook","type":"Beast","size":"Medium","frame":"swarm-of-rats","model":"swarm-of-rats","summary":"Tail-fused rats forming one furious knot","flavor":"Dozens of sewer rats fused tail-to-tail into one furious, many-headed knot."},{"name":"Choir-Loft Poltergeist","cr":2,"role":"mook","type":"Undead","size":"Medium","frame":"poltergeist","model":"poltergeist","summary":"Organist's fury slamming hymnals and bellropes","flavor":"An organist's fury, still slamming hymnal pages and yanking bellropes no hand can hold."},{"name":"Gravecloth Zombie","cr":0.25,"role":"mook","type":"Undead","size":"Medium","frame":"zombie","model":"zombie","summary":"Shroud-stitched exhumee lurching by grave-light","flavor":"A shroud-wrapped exhumee, still stitched into its burial linens, lurching by grave-light."},{"name":"Fen Ghoul","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"ghoul","model":"ghoul","summary":"Crypt-nesting ghoul with silt-slick claws","flavor":"A ghoul that nests in flooded family crypts, its claws slick with graveyard silt."},{"name":"Beast of the Full Moon Runt","cr":2,"role":"mook","type":"Monstrosity","size":"Medium","frame":"wererat","model":"wererat","summary":"Freshly bitten victim terrified of itself","flavor":"A fresh-bitten victim mid-transformation, more terrified of itself than of you."},{"name":"Wax-Sealed Familiar","cr":0.25,"role":"mook","type":"Beast","size":"Tiny","frame":"raven","model":"raven","summary":"Coven crow with a beak sewn shut","flavor":"A coven's carrier-crow, its beak sewn shut around a secret it will die before dropping."},{"name":"Sackcloth Effigy","cr":0.5,"role":"mook","type":"Construct","size":"Small","frame":"twig-blight","model":"twig-blight","summary":"Hair-stitched poppet animated by a pinned name","flavor":"A burnt-corn poppet stitched with a stranger's hair, animated by whoever's name is pinned to its chest."},{"name":"Ossuary Skitterling","cr":0.25,"role":"mook","type":"Undead","size":"Tiny","frame":"crawling-claw","model":"crawling-claw","summary":"Severed charnel-wall hand scrabbling homeward","flavor":"A single severed hand from the charnel wall, still scrabbling toward its own coffin."},{"name":"Lantern-Jawed Corpse Candle","cr":2,"role":"mook","type":"Undead","size":"Tiny","frame":"will-o-wisp","model":"will-o-wisp","summary":"Grave-light that feeds on following mourners","flavor":"A death-light that hovers over fresh graves, feeding on the grief of mourners who follow it."},{"name":"Widow's Veil Shade","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"shadow","model":"shadow","summary":"Mirror-shed silhouette that grieves at funerals","flavor":"A mourning-dress silhouette that peels off mirrors during funerals to grieve alongside the living."},{"name":"Feasting Cellar Grub","cr":0.5,"role":"mook","type":"Beast","size":"Small","frame":"giant-centipede","model":"giant-centipede","summary":"Pale centipede fattened on deeper offerings","flavor":"A pale root-cellar centipede fattened on offerings left for something worse living deeper down."},{"name":"Rusalka's Drowned Bride","cr":1,"role":"mook","type":"Undead","size":"Medium","frame":"specter","model":"specter","summary":"Jilted drowned bride walking out dripping","flavor":"A jilted bride who walked into the millpond in her gown and now walks out of it, dripping."},{"name":"Fanged Chorister","cr":1,"role":"mook","type":"Monstrosity","size":"Medium","frame":"harpy","model":"harpy","summary":"Hymn-voiced ghoul luring the faithful closer","flavor":"A choir-loft ghoul whose hymn-perfect voice lures the faithful within reach of its talons."},{"name":"Marrow Beetle Swarm","cr":1,"role":"mook","type":"Beast","size":"Large","frame":"swarm-of-insects","model":"swarm-of-insects","summary":"Grave-beetle carpet that strips corpses clean","flavor":"A carpet of grave-beetles that strips a corpse to clean bone in a single feeding."},{"name":"Bell-Jar Wraith","cr":2,"role":"mook","type":"Undead","size":"Medium","frame":"greater-shadow","model":"greater-shadow","summary":"Failed experiment reaching for its notes","flavor":"A physician's failed experiment, trapped between a bell jar and the grave, still reaching for its notes."},{"name":"Attic-Bound Revenant","cr":2,"role":"mook","type":"Undead","size":"Medium","frame":"wight","model":"wight","summary":"Locked-away relative still pacing six feet","flavor":"A locked-away relative the family pretended never existed, still pacing the same six feet."},{"name":"Coven Apprentice","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist-fanatic","model":"cultist-fanatic","summary":"Hedge-witch initiate half in love with the dark","flavor":"A hedge-witch initiate memorizing the coven's book by candle-stub, half in love with the dark it teaches."},{"name":"Reliquary Ghast","cr":2,"role":"mook","type":"Undead","size":"Medium","frame":"ghast-base","model":"ghast-base","summary":"Stolen saint's corpse gone hungry in vestments","flavor":"A saint's stolen corpse gone hungry, still wearing the vestments it was buried in."},{"name":"Ossified Bell-Ringer","cr":2,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton-warrior","model":"skeleton-warrior","summary":"Skeleton still ringing an unheard dusk bell","flavor":"A campanile skeleton that still climbs the tower stair each dusk, ringing a bell no one else hears."},{"name":"Charnel-Yard Skeleton Archer","cr":0.5,"role":"mook","type":"Undead","size":"Medium","frame":"skeleton-archer","model":"skeleton-archer","summary":"Crossbow skeleton still holding its cemetery post","flavor":"A crossbow-armed grave-guard skeleton that still holds its post along the cemetery wall."},{"name":"Full-Moon Enforcer","cr":3,"role":"elite","type":"Monstrosity","size":"Medium","frame":"werewolf","model":"werewolf","summary":"Pack lieutenant hiding claws until convenient","flavor":"A pack lieutenant who hunts in human guise all week and only shows its claws at the coven's convenience."},{"name":"Steeple Bloodkin","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"vampire-spawn","model":"vampire-spawn","summary":"Choirmaster vampire leading hymns with stitched smile","flavor":"A choirmaster turned bloodsucker who still leads the hymn each Sunday, mouth stitched into a smile."},{"name":"The Weeping Bride","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"banshee","model":"banshee","summary":"Jilted ghost bride whose scream shatters glass","flavor":"A ghost bride whose scream shatters glass at the mention of the groom who left her at the altar."},{"name":"Warden of the Drowning Pool","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"wight","model":"wight","summary":"Cursed executioner guarding the drowning pool","flavor":"A witch-trial executioner cursed to guard the millpond where he condemned the innocent."},{"name":"Hollow-Throated Ghast Priest","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"ghast","model":"ghast","summary":"Defrocked cleric who joined his flock's feast","flavor":"A defrocked cleric who fed his own flock to something in the crypt and joined the feast."},{"name":"Coven Hexweaver","cr":5,"role":"elite","type":"Fey","size":"Medium","frame":"green-hag","model":"green-hag","summary":"Coven's youngest sister, bargains cruelly","flavor":"A three-sister coven's youngest voice, still human enough to bargain, cruel enough to relish it."},{"name":"The Mirror-Bound Twin","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"ghost","model":"ghost","summary":"Face-stealing reflection waiting in every mirror","flavor":"A reflection that stole its owner's face centuries ago and now waits in every polished surface."},{"name":"Rite-Scarred Zealot Captain","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"cultist-fanatic","model":"cultist-fanatic","summary":"Ritual leader scarred with a forbidden name","flavor":"A ritual leader whose scars spell the summoning name in a language the tongue was never meant for."},{"name":"Charnel-House Ogre Zombie","cr":3,"role":"elite","type":"Undead","size":"Large","frame":"ogre-zombie","model":"ogre-zombie","summary":"Gravedigger's corpse raised by his own rite","flavor":"A gravedigger's own hulking corpse, reanimated by the very rite he used to raise others."},{"name":"The Second Groom","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"wight-lord","model":"wight-lord","summary":"Jilted suitor presiding over an eternal reception","flavor":"A jilted suitor who murdered the wedding party and now presides over an eternal, empty reception."},{"name":"Loomstitch Doppelganger","cr":3,"role":"elite","type":"Monstrosity","size":"Medium","frame":"doppelganger","model":"doppelganger","summary":"Face-thief impersonating the beloved village elder","flavor":"A face-thief who replaced a beloved village elder months ago, and no one has noticed the seams yet."},{"name":"Gallows Wraith Captain","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"wraith","model":"wraith","summary":"Hanged highwayman commanding lesser gibbet-spirits","flavor":"An executed highwayman who commands lesser hanged-spirits from the crossroads gibbet."},{"name":"Vestry Revenant","cr":7,"role":"elite","type":"Undead","size":"Huge","frame":"graveyard-revenant","model":"graveyard-revenant","summary":"Swollen sexton digging until his killer's found","flavor":"A murdered sexton, swollen with grave-rot fury, who will not stop digging until his killer is found."},{"name":"Cellar-Bound Bulette Grub","cr":5,"role":"elite","type":"Monstrosity","size":"Large","frame":"bulette","model":"bulette","summary":"Burrowing horror surfacing through open graves","flavor":"A burrowing horror that tunneled up under a village graveyard and now surfaces through open plots."},{"name":"Coven Matron's Cauldron-Kin","cr":6,"role":"elite","type":"Fey","size":"Medium","frame":"night-hag","model":"night-hag","summary":"Second matriarch trading in nightmares, not curses","flavor":"A second matriarch of the same coven, who trades in nightmares rather than curses."},{"name":"Blood-Thrall Chevalier","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"knight","model":"knight","summary":"Centuries-loyal knight thrall, still starving","flavor":"A knight sworn to a vampire's service centuries past, still armored, still loyal, still starving."},{"name":"Ashfall Mummy Curate","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"mummy","model":"mummy","summary":"Punished elder mummified alive, still shepherding","flavor":"A sect elder mummified alive as punishment, now shepherding the congregation from inside its wrappings."},{"name":"Marrow-Bound Wererat Broker","cr":4,"role":"elite","type":"Monstrosity","size":"Medium","frame":"wererat","model":"wererat","summary":"Sewer relic-fixer who bites debtors","flavor":"A black-market fixer who trades cursed relics from the sewers, and bites those who don't pay."},{"name":"Widow-Maker Banshee Elder","cr":6,"role":"elite","type":"Undead","size":"Medium","frame":"banshee","model":"banshee","summary":"Generations-old wail that claims every husband","flavor":"A generations-old keening spirit whose wail has claimed every man who married into her bloodline."},{"name":"Coffin-Nail Wight Sergeant","cr":4,"role":"elite","type":"Undead","size":"Medium","frame":"wight","model":"wight","summary":"Buried captain drilling reanimated ranks by night","flavor":"A militia captain buried with his men, now drilling their reanimated ranks in the churchyard at night."},{"name":"Blood-Drunk Vampire Familiar Knight","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"vampire-familiar","model":"vampire-familiar","summary":"Turned squire guarding the coffin, hunting by dusk","flavor":"A turned squire who serves his master's coffin by day and hunts travelers by dusk."},{"name":"Seance Circle Medium","cr":3,"role":"elite","type":"Humanoid","size":"Medium","frame":"priest","model":"priest","summary":"Parlor medium who opened a door she can't close","flavor":"A parlor spiritualist who really did open a door, and now can't close it, or doesn't want to."},{"name":"Effigy-Bound Flesh Golem","cr":5,"role":"elite","type":"Construct","size":"Medium","frame":"flesh-golem","model":"flesh-golem","summary":"Resurrectionist's patchwork sewn from village corpses","flavor":"A resurrectionist's stitched patchwork, sewn from a village's worth of the recently deceased."},{"name":"The Uninherited Heir","cr":3,"role":"elite","type":"Undead","size":"Medium","frame":"ghost","model":"ghost","summary":"Disinherited ghost rewriting the will in blood","flavor":"A disinherited son who haunts the family estate, rewriting the will in blood on the study wall each night."},{"name":"Coven Familiar Alpha","cr":3,"role":"elite","type":"Monstrosity","size":"Large","frame":"winter-wolf","model":"winter-wolf","summary":"Coven-bound wolf whose howl carries a curse","flavor":"A frost-pale wolf bound to the coven's oldest hex, its howl carrying a curse instead of a warning."},{"name":"Rot-Crowned Spirit Naga","cr":8,"role":"elite","type":"Fiend","size":"Large","frame":"spirit-naga","model":"spirit-naga","summary":"Serpentine grave-idol worshipped as a saint","flavor":"A grave-cult idol given serpentine unlife, worshipped by the possessed congregation as a saint."},{"name":"The Chained Confessor","cr":9,"role":"high","type":"Undead","size":"Large","frame":"eye-tyrant-zombie","model":"eye-tyrant-zombie","summary":"Fused inquisition victims forced to confess","flavor":"An inquisitor's own victims fused into one shackled horror, forced to confess sins that were never theirs."},{"name":"Blood-Countess's First Spawn","cr":8,"role":"high","type":"Undead","size":"Medium","frame":"vampire-nightbringer","model":"vampire-nightbringer","summary":"Ancient childe groomed to replace the matriarch","flavor":"The vampire matriarch's oldest childe, groomed for centuries to eventually replace her."},{"name":"Church-Broken Death Knight","cr":11,"role":"high","type":"Undead","size":"Medium","frame":"death-knight-aspirant","model":"death-knight-aspirant","summary":"Crusader who slaughtered his flock, guards its grave","flavor":"A crusader who slaughtered his own congregation at the coven's whisper, and now guards their unmarked grave."},{"name":"The Cellar Door's Real Keeper","cr":9,"role":"high","type":"Aberration","size":"Large","frame":"grick-ancient","model":"grick-ancient","summary":"Generation-fed tunneling horror mistaken for legend","flavor":"A tunneling horror the covens have fed for generations, mistaken by the village for a mere legend."},{"name":"Matriarch of the Full Moon Pack","cr":8,"role":"high","type":"Monstrosity","size":"Huge","frame":"yuan-ti-abomination","model":"yuan-ti-abomination","summary":"Alpha whose bite founds a whole bloodline","flavor":"A were-beast alpha whose bite carries a curse potent enough to found an entire bloodline in one night."},{"name":"The Archivist of Screams","cr":10,"role":"high","type":"Undead","size":"Gargantuan","frame":"haunting-revenant","model":"haunting-revenant","summary":"Librarian who became the sum of every scream","flavor":"A librarian who catalogued every scream in the manor's history and became the sum of them."},{"name":"Blightmother's Chosen Vessel","cr":10,"role":"high","type":"Fiend","size":"Medium","frame":"yochlol","model":"yochlol","summary":"Cult conduit to something old beneath the church","flavor":"A cult's living conduit to something old and hungry beneath the church foundation."},{"name":"The Reflection That Escaped","cr":13,"role":"high","type":"Undead","size":"Medium","frame":"vampire","model":"vampire","summary":"Mirror-escaped vampire hunting its former family","flavor":"A vampire that shattered its own mirror-prison and now hunts the family it once served for a hundred years."},{"name":"Wax Cathedral Sentinel","cr":9,"role":"high","type":"Construct","size":"Large","frame":"clay-golem","model":"clay-golem","summary":"Vigil-wax colossus animated by a century of grief","flavor":"A candle-wax colossus grown from a century of dripped vigil-tapers, animated by grief alone."},{"name":"The Possessed Cardinal","cr":11,"role":"high","type":"Fiend","size":"Large","frame":"horned-devil","model":"horned-devil","summary":"Church official possessed, sermons not his own","flavor":"A high church official whose sermons now come from something else entirely, congregation unaware."},{"name":"Gravebound Necrohulk","cr":7,"role":"high","type":"Plant","size":"Large","frame":"violet-fungus-necrohulk","model":"violet-fungus-necrohulk","summary":"Mass grave grown into a fungal flesh horror","flavor":"A mass grave that sprouted fungal flesh over centuries, wearing every buried skeleton at once."},{"name":"The Hollow Cardinal Enthroned","cr":15,"role":"apex","type":"Undead","size":"Medium","frame":"mummy-lord","model":"mummy-lord","summary":"Mummified saint-king ruling a dead congregation","flavor":"A saint-king mummified on his own cathedral throne, still ruling a congregation of the dead."},{"name":"The Bloodline's First Sin","cr":17,"role":"apex","type":"Undead","size":"Medium","frame":"death-knight","model":"death-knight","summary":"Founding ancestor enforcing the house's damning pact","flavor":"The founding ancestor of a cursed noble house, still enforcing the pact that damned every heir since."},{"name":"The Rite Given Flesh","cr":16,"role":"apex","type":"Fiend","size":"Large","frame":"marilith","model":"marilith","summary":"Century-long ritual completed as living flesh","flavor":"A century-long summoning ritual finally completed, wearing the coven's collective sacrifice as a body."},{"name":"Grand Matriarch of the Blood Court","cr":21,"role":"apex","type":"Undead","size":"Medium","frame":"lich","model":"lich","summary":"Vampire queen who transcended into lichdom","flavor":"A vampire queen who transcended even undeath through a lichdom pact, ruling both realms of the dead."},{"name":"The Everlasting Congregation","cr":19,"role":"apex","type":"Undead","size":"Huge","frame":"yuan-ti-abomination","model":"yuan-ti-abomination","summary":"Entire drowned parish fused into one singing mass","flavor":"An entire drowned parish fused by a cataclysmic ritual into one endless, singing, grasping mass."},{"name":"the Bloodless Bride","cr":0.5,"role":"mook","type":"undead","size":"Medium","frame":"zombie","model":"zombie","summary":"shuffling grave-bride, drawn to warmth and mourning","flavor":"A shambling grave-bride still in her rotted wedding linens, drawn to warmth and grief in equal measure; she doesn't hunt so much as attend, over and over, a wedding that ended badly.","source":"folklore","sourceNote":"European folk-revenant/vampire folklore (pre-literary, no single owner)"},{"name":"Renfield's Kin","cr":0.25,"role":"mook","type":"humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"insect-eating thrall serving something undead","flavor":"An asylum-thin thrall who traded sanity for a taste of borrowed immortality; catches flies, counts them, offers the count up like a prayer.","source":"public-domain","sourceNote":"Stoker, Dracula (1897, PD) — the Renfield archetype, generalized (not the named character)"},{"name":"the Carrion Wolf","cr":0.25,"role":"mook","type":"beast (shapechanger)","size":"Medium","frame":"wolf","model":"wolf","summary":"grave-fed wolf edging toward the curse","flavor":"Not yet a full were-thing — just a wolf that has fed on the wrong grave and picked up a taste, and a little too much cunning, for it.","source":"folklore","sourceNote":"generic European werewolf folklore (pre-literary tradition, not any specific IP)"},{"name":"Fog-Walker","cr":0.25,"role":"mook","type":"beast","size":"Large","frame":"giant-bat","model":"giant-bat","summary":"fog-bound phantom hound, harmless in clear air","flavor":"A pale hound-shape that only holds together inside fog; step into clear air and it's a stray dog again, confused and harmless.","source":"archetype","sourceNote":"generic Gothic-horror mist/fog-hound stock creature"},{"name":"the Somnambulist","cr":0.5,"role":"mook","type":"humanoid","size":"Medium","frame":"commoner","model":"commoner","summary":"a townsperson's cruel second self, out after dark","flavor":"A respectable townsperson by day; by dusk something narrower and meaner wears their face out into the streets. They remember none of it — the gloom remembers all of it.","source":"public-domain","sourceNote":"Stevenson, Strange Case of Dr Jekyll and Mr Hyde (1886, PD) — the split-self archetype, generalized"},{"name":"Ashen Handmaiden","cr":1,"role":"mook","type":"undead","size":"Medium","frame":"specter","model":"specter","summary":"loyal ghost-servant, stuck in a burned house's routine","flavor":"Still dusting a house that burned down a century ago; she'll answer the door for guests who knocked before her own death, and mistake the party for them.","source":"archetype","sourceNote":"generic Gothic-manor servant-ghost stock type"},{"name":"Innsmouth Hollow-Kin","cr":1,"role":"mook","type":"humanoid","size":"Medium","frame":"lacedon-sodden-ghoul","model":"lacedon-sodden-ghoul","summary":"gill-marked villager with an unspoken tide-hunger","flavor":"A villager whose family married the tide-line one generation too many; gill-slits under a high collar, and a hunger for the shallows nobody in town will name out loud.","source":"archetype","sourceNote":"generic isolated-fishing-village/hybrid-folk stock type (not any specific IP's mythos)"},{"name":"the Wolf-Cursed","cr":3,"role":"elite","type":"humanoid (shapechanger)","size":"Medium","frame":"werewolf","model":"werewolf","summary":"the classic moon-bound curse, mid-transformation","flavor":"Cursed at a crossroads or bitten in a churchyard — the story varies by village, but the moon doesn't care which version is true.","source":"folklore","sourceNote":"generic European werewolf/loup-garou folklore"},{"name":"the Steward of the House","cr":5,"role":"elite","type":"undead","size":"Large","frame":"flesh-golem","model":"flesh-golem","summary":"eloquent, grieving, stitched-together giant","flavor":"Stitched together and abandoned by its maker, it reads philosophy it finds in ruined libraries and hates almost as eloquently as it grieves; cornered, it is devastating, and it knows exactly why it became this.","source":"public-domain","sourceNote":"Shelley, Frankenstein (1818, PD) — the Creature, our own take, novel-version only (articulate, wounded, not a mute brute)"},{"name":"Lady of the Blood Countess's Line","cr":5,"role":"elite","type":"undead","size":"Medium","frame":"night-hag","model":"night-hag","summary":"patient, affectionate centuries-old blood-drinker","flavor":"Centuries of patient, intimate hunting have made her gentler than any predator has a right to be — she prefers a slow, doting courtship of her prey to a chase.","source":"public-domain","sourceNote":"Le Fanu, Carmilla (1872, PD)"},{"name":"the Riderless Terror","cr":4,"role":"elite","type":"undead","size":"Large","frame":"warhorse-skeleton","model":"warhorse-skeleton","summary":"headless rider hunting a replacement skull, every autumn","flavor":"A cannonball took his head at some forgotten muster, and every autumn he rides out looking for a replacement — pumpkin, skull, or yours, he isn't particular.","source":"public-domain","sourceNote":"Irving, The Legend of Sleepy Hollow (1820, PD) — the Headless Horseman"},{"name":"the Unseen Guest","cr":6,"role":"elite","type":"humanoid","size":"Medium","frame":"invisible-stalker","model":"invisible-stalker","summary":"invisible chemist, tracked by breath and footprints","flavor":"Bandaged only when he wants to be seen; the rest of the time you track him by breath-fog on cold glass and the footprints that appear in spilled flour.","source":"public-domain","sourceNote":"Wells, The Invisible Man (1897, PD) — the Griffin archetype, our own take (a chemist undone by his own formula, not a specific film design)"},{"name":"the Portrait's Truth","cr":6,"role":"elite","type":"undead","size":"Medium","frame":"vampire-spawn","model":"vampire-spawn","summary":"ageless beauty whose hidden portrait holds the rot","flavor":"Ageless and lovely to look at; somewhere in the house hangs the ledger of every cruelty, rotting so its owner never has to. Destroy the portrait and you destroy the deal.","source":"public-domain","sourceNote":"Wilde, The Picture of Dorian Gray (1890, PD)"},{"name":"the Baba Yaga","cr":9,"role":"high","type":"fey","size":"Large","frame":"arch-hag","model":"arch-hag","summary":"chicken-legged hut-witch who judges before she helps","flavor":"Her hut walks on chicken legs and judges visitors before she does; help without being asked and she rewards extravagantly, ask without helping and you become the next fence-post skull.","source":"folklore","sourceNote":"Slavic folklore — Baba Yaga (settled, widely published legend figure, not a living closed tradition)"},{"name":"the Gorgon's Daughter","cr":6,"role":"high","type":"monstrosity","size":"Medium","frame":"medusa","model":"medusa","summary":"gaze-cursed gorgon, curating a garden of statues","flavor":"She keeps a garden of the men who looked, arranged by the year they made the mistake; she's stopped being angry about it and started being a curator.","source":"public-domain","sourceNote":"Greek myth — Medusa (ancient, no owner)"},{"name":"the Opera-House Phantom","cr":8,"role":"high","type":"humanoid","size":"Medium","frame":"assassin","model":"assassin","summary":"masked genius-architect ruling from beneath the stage","flavor":"A genius disfigured and driven underground who built a kingdom of trapdoors and misdirection beneath the stage he was never allowed to stand on; he'll kill for the right voice as readily as he'd die for it.","source":"public-domain","sourceNote":"Leroux, The Phantom of the Opera (1910, PD)"},{"name":"the Impaler-Count","cr":13,"role":"apex","type":"undead","size":"Medium","frame":"vampire","model":"vampire","summary":"ancient, courtly count who owns the road home","flavor":"Old enough to have negotiated treaties in three dead empires; he doesn't need to chase you, because he already owns the roads, the weather, and the wolves between you and the border.","source":"public-domain","sourceNote":"Stoker, Dracula (1897, PD) — novel version (charismatic, ancient, commanding wolves/mist, not any film's fangs-and-cape design)"},{"name":"the Woeful Cry","cr":4,"role":"elite","type":"undead","size":"Medium","frame":"banshee","model":"banshee","summary":"keening death-omen spirit; herald, not killer","flavor":"She doesn't kill; she announces. Hearing her keen at your door is the gloom's way of telling you the paperwork on your death is already filed — what you do with the notice is still yours.","source":"folklore","sourceNote":"Irish/Scottish folklore — the banshee (settled literary/folkloric figure, generalized, treated as an omen-spirit rather than flattened into a stock ghost)"},{"name":"the House That Remembers","cr":7,"role":"high","type":"undead","size":"Huge","frame":"haunting-revenant","model":"haunting-revenant","summary":"a haunted manor that rearranges itself to relive its dead","flavor":"Every family that ever died under this roof left a little of their worst moment behind, and the house learned to move the furniture with it; it doesn't want visitors, it wants witnesses.","source":"archetype","sourceNote":"generic Gothic-haunted-house stock type (the manor-as-monster trope)"}],
 "bright-kingdom":[{"name":"Wind-Up Soldier","cr":0.125,"role":"mook","type":"Construct","size":"Small","frame":"animated-flying-sword","model":"animated-flying-sword","summary":"clockwork toy soldier, keeps marching until unwound","flavor":"A key juts from its back, ticking down; when it hits zero the toy soldier salutes and falls apart, spilling gears. Its bayonet-poke still draws real blood."},{"name":"Plush Ripper","cr":0.25,"role":"mook","type":"Construct","size":"Small","frame":"cockatrice","model":"cockatrice","summary":"cuddly stuffed animal hiding a mouthful of hooks","flavor":"Button eyes, felt seams, a music-box giggle — and a mouth full of hooked steel teeth sewn in wrong. It cuddles up before it bites."},{"name":"Candy-Cane Golem","cr":0.5,"role":"mook","type":"Construct","size":"Medium","frame":"gray-ooze","model":"gray-ooze","summary":"hard-candy construct, sweet shell hides razor shards","flavor":"A shambling column of hard-shell peppermint, sweet enough to lure children and sharp enough at the broken edges to open an artery."},{"name":"Jack-in-the-Box Stalker","cr":0.5,"role":"mook","type":"Construct","size":"Medium","frame":"scarecrow","model":"scarecrow","summary":"boxed ambusher springs out mid-tune, already too close","flavor":"Crouches motionless inside a painted crate for hours, cranking out a tinny tune, until the lid bursts and it's already inside your guard."},{"name":"Laughing-Mask Swarm","cr":1,"role":"mook","type":"Aberration","size":"Medium","frame":"swarm-of-crawling-claws","model":"swarm-of-crawling-claws","summary":"swarm of grinning masks that clatter, snap, giggle","flavor":"A drift of hollow carnival masks, all fixed grins, clattering and snapping at ankles in a chorus of muffled giggling that never quite becomes words."},{"name":"Balloon-Skin Grub","cr":0.25,"role":"mook","type":"Beast","size":"Small","frame":"giant-centipede","model":"giant-centipede","summary":"squeaking balloon-hide grub that deflates when popped","flavor":"Squeaks like a dog toy with every bite; pop it and it deflates into a wet rubbery flap that still twitches."},{"name":"Carnival Tout","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"cultist","model":"cultist","summary":"grinning barker who herds marks toward the big tent","flavor":"Striped vest, painted grin, a barker's patter that never stops — 'Step right up!' — while it herds you toward the tent with a knife up its sleeve."},{"name":"Static-Charge Kitten","cr":1,"role":"mook","type":"Fey","size":"Tiny","frame":"homunculus","model":"homunculus","summary":"sparking fey kitten, a pet that shocks you dead","flavor":"Fur standing on end, purring like a dying engine; every pet it gives back is a jolt that can stop a weak heart."},{"name":"Marching Peanut","cr":0.125,"role":"mook","type":"Plant","size":"Small","frame":"twig-blight","model":"twig-blight","summary":"grinning peanut-soldier in an endless parade conga line","flavor":"A grinning legume-soldier on toothpick legs, part of an endless conga line pouring out of a parade float. Salted, but never quite dead."},{"name":"Piñata Brute","cr":2,"role":"mook","type":"Construct","size":"Large","frame":"ogre","model":"ogre","summary":"paper-hide brute that bursts into candy shrapnel","flavor":"Papier-mâché skin stretched taut over a swinging club-arm; crack it open in the right spot and it detonates candy shrapnel and stolen teeth."},{"name":"Carousel Nightmare","cr":3,"role":"elite","type":"Undead","size":"Large","frame":"warhorse-skeleton","model":"warhorse-skeleton","summary":"carved carousel horse torn free, circling for blood","flavor":"A painted wooden charger torn loose from its pole, galloping in place no longer — gilt cracked, glass eyes rolling, hooves that never stop circling for the kill."},{"name":"Sugar-Rush Harlequin","cr":3,"role":"elite","type":"Fey","size":"Medium","frame":"bugbear-stalker","model":"pixie-wonderbringer","summary":"jittering harlequin brawler, hopped up on rock candy","flavor":"Diamond-patched and cackling, it mainlines rock candy between blows, moving in jittery double-time no eye can quite track until the pratfall becomes a killing blow."},{"name":"Bubblegum Ooze","cr":3,"role":"elite","type":"Ooze","size":"Large","frame":"gelatinous-cube","model":"gelatinous-cube","summary":"pink bubblegum ooze, engulfs and dissolves you slowly","flavor":"Bright pink, sickly-sweet-smelling, and stickier than any trap — it swallows whole and digests slow enough you can hear yourself dissolve."},{"name":"Claw-Machine Horror","cr":4,"role":"elite","type":"Construct","size":"Medium","frame":"helmed-horror","model":"helmed-horror","summary":"arcade claw-machine on legs, rigged to never miss","flavor":"A coin-op cabinet on stilted legs, its steel claw always 'almost' catching you — until the game rigs itself to let the claw actually close."},{"name":"Funhouse Double","cr":3,"role":"elite","type":"Monstrosity","size":"Medium","frame":"doppelganger","model":"doppelganger","summary":"mirror-warped double wearing your own stretched face","flavor":"Steps out of a warped mirror wearing your own face stretched a little too wide, mimicking your voice back at you a half-second behind."},{"name":"Ferris-Wheel Horror","cr":5,"role":"elite","type":"Monstrosity","size":"Large","frame":"gorgon","model":"gargoyle","summary":"rolling wheel-boned horror, its gaze turns you to stone","flavor":"Rusted gondolas for a ribcage, it rolls upright on its own broken wheel-rim, and anything that looks too long into its lantern-eyes seizes up stone-still."},{"name":"Cotton-Candy Wraith","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"wraith","model":"wraith","summary":"sugar-sweet drifting haze that feeds on happy memories","flavor":"A drifting pink haze that smells of childhood summer fairs, sweet right up until it's inside your lungs, unspooling your last happy memory as it feeds."},{"name":"Arcade Sentinel","cr":6,"role":"elite","type":"Aberration","size":"Medium","frame":"mage","model":"void-monk-zerth","summary":"glitching screen-boss, bolts skip you straight to wounded","flavor":"Pixelated and buzzing, it flickers between screen and floor, hurling glitching bolts that skip frames of your body straight past the pain and into the wound."},{"name":"Mascot-Suit Puppeteer","cr":6,"role":"elite","type":"Aberration","size":"Medium","frame":"fish-folk-archpriest","model":"grell","summary":"hollow mascot suit worn by tendrils wearing your smile","flavor":"The beloved mascot costume is empty air on the inside — a knot of grasping tendrils wearing the plush like a second skin, waving for the children with someone else's hand."},{"name":"Firework Effigy","cr":8,"role":"high","type":"Elemental","size":"Large","frame":"fire-elemental","model":"fire-elemental","summary":"living fireworks display, still building to a finale","flavor":"Built for the finale and never told the show is over, it keeps blooming into new colors overhead, each burst a little closer to the crowd."},{"name":"The Ringmaster","cr":9,"role":"high","type":"Fey","size":"Medium","frame":"night-hag","model":"night-hag","summary":"top-hatted ringmaster who commands the whole show","flavor":"Top hat, painted smile, a whip that cracks louder than thunder — every act in the tent performs for him, willing or not, and the show never ends until he says so."},{"name":"The Overwound Nutcracker","cr":10,"role":"high","type":"Construct","size":"Large","frame":"stone-golem","model":"stone-golem","summary":"giant nutcracker soldier, jaw snaps clean through bone","flavor":"Painted uniform, oversized jaw hinged to crack more than nuts — every strike is a full-body snap of that grinning mouth, splintering whatever's fed to it."},{"name":"Vending-Machine Colossus","cr":11,"role":"high","type":"Construct","size":"Large","frame":"iron-golem","model":"iron-golem","summary":"coin-slot golem, dispenses violence for your last coin","flavor":"Rows of snack-slots for a chest, it dispenses whatever you 'paid' for — usually a fist — and jams itself deliberately so you keep feeding it coins."},{"name":"The Birthday King","cr":15,"role":"apex","type":"Fey","size":"Large","frame":"arch-hag","model":"planetar","summary":"crowned rigger of the game no one is meant to win","flavor":"Crowned in melted candles, he presides over the game you cannot win — the wheel is rigged, the dice are his teeth, and every prize you claim costs you a year of your life."},{"name":"The Grinning Prize","cr":18,"role":"apex","type":"Aberration","size":"Gargantuan","frame":"undead-eye-tyrant","model":"kraken","summary":"top-shelf plush titan, a dozen button-eyes snap open","flavor":"The top shelf's biggest stuffed monster, too big for any booth, its dozen glass-button eyes all open at once the moment you finally win it."},{"name":"Tin Drummer Boy","cr":0.125,"role":"mook","type":"Construct","size":"Small","frame":"animated-flying-sword","model":"animated-flying-sword","summary":"drumming tin toy that locks your heartbeat to its beat","flavor":"Beats an unbreakable march rhythm that syncs enemy hearts to its tempo until they seize up mid-stride."},{"name":"Rag Doll Skulker","cr":0.25,"role":"mook","type":"Construct","size":"Small","frame":"cockatrice","model":"cockatrice","summary":"limp rag doll that scuttles the second you look away","flavor":"Limp and lifeless until your back is turned, then it scuttles on button-thread joints, needle fingers first."},{"name":"Gumdrop Sprite","cr":0.125,"role":"mook","type":"Fey","size":"Tiny","frame":"pixie","model":"pixie","summary":"sugar-shard pixie giggling above dog-whistle pitch","flavor":"A candy-coated pixie that pelts foes with hardened sugar shrapnel, giggling in a register only dogs and the dying can hear."},{"name":"Squeak-Toy Hound","cr":0.25,"role":"mook","type":"Construct","size":"Small","frame":"giant-rat","model":"giant-rat","summary":"rubber toy dog whose bite-squeak gets louder with damage","flavor":"Every bite compresses its rubber chest into a cheerful squeak that somehow gets louder the deeper the wound."},{"name":"Confetti Wisp","cr":0.5,"role":"mook","type":"Elemental","size":"Small","frame":"smoke-mephit","model":"smoke-mephit","summary":"glitter-storm elemental made of razor-edged party confetti","flavor":"A cloud of shredded paper and glitter that swirls into a blinding storm, each fleck razor-cut at the edge."},{"name":"Marionette Cutpurse","cr":0.5,"role":"mook","type":"Construct","size":"Medium","frame":"bandit","model":"bandit","summary":"string-puppet thief worked by an unseen hand overhead","flavor":"Jointed limbs jerk on visible strings that lead up into empty air; something above is definitely still pulling."},{"name":"Pop-Gun Grenadier","cr":0.5,"role":"mook","type":"Humanoid","size":"Medium","frame":"warrior-infantry","model":"warrior-infantry","summary":"toy-soldier grenadier lobbing shrapnel-cored party favors","flavor":"Fires corked party-favor rounds that detonate on impact with genuine shrapnel hidden under the cork."},{"name":"Licorice Whip-Vine","cr":0.5,"role":"mook","type":"Plant","size":"Medium","frame":"vine-blight","model":"vine-blight","summary":"sticky black candy-vine that lashes and constricts","flavor":"Sticky black ropes of edible-looking vine lash out and constrict, tasting faintly of anise and old blood."},{"name":"Kite-String Wraith","cr":1,"role":"mook","type":"Undead","size":"Small","frame":"skeleton","model":"skeleton","summary":"paper kite dragging a bone-child on garrote-taut string","flavor":"A torn paper kite drags a skeletal child's shape behind it on razor-taut string, forever chasing an updraft that never comes."},{"name":"Snow-Globe Wisp","cr":0.25,"role":"mook","type":"Elemental","size":"Tiny","frame":"ice-mephit","model":"ice-mephit","summary":"trapped globe-spirit that shakes itself into a blizzard","flavor":"Trapped forever inside a floating glass sphere, it shakes itself into a blinding blizzard when threatened."},{"name":"Puppet-Show Ghoul","cr":1,"role":"mook","type":"Undead","size":"Small","frame":"ghoul","model":"ghoul","summary":"hand-puppet corpse twitching to an absent puppeteer","flavor":"A hand-puppet corpse with a painted grin sewn permanently open, fingers still twitching to an absent puppeteer's cues."},{"name":"Ticket-Booth Imp","cr":1,"role":"mook","type":"Fiend","size":"Small","frame":"imp","model":"imp","summary":"toll-imp who brands hands and demands blood admission","flavor":"Demands admission in blood before letting anyone leave the fairgrounds, stamping hands with a brand that never fades."},{"name":"Streamer Serpent","cr":0.5,"role":"mook","type":"Beast","size":"Medium","frame":"giant-venomous-snake","model":"giant-venomous-snake","summary":"crepe-scaled snake whose sweet venom masks as punch","flavor":"Crepe-paper scales trail like party streamers as it strikes, its venom sweet enough to be mistaken for punch."},{"name":"Popcorn Blight","cr":0.25,"role":"mook","type":"Plant","size":"Small","frame":"twig-blight","model":"twig-blight","summary":"kernel-husk plant that bursts in scalding shrapnel steam","flavor":"Clusters of white kernel-husks burst apart in a shower of blinding steam and hooked husk-shrapnel."},{"name":"Domino Sentinel","cr":1,"role":"mook","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"toppling domino construct that chain-falls in a crushing line","flavor":"Stands rigid in a row until one falls; then the whole line topples in a cascading, crushing avalanche."},{"name":"Wooden Nutcracker Cadet","cr":0.5,"role":"mook","type":"Construct","size":"Medium","frame":"scarecrow","model":"scarecrow","summary":"shell-cracking nutcracker jaw that prefers fingers now","flavor":"Painted teeth clamp with a jaw built for cracking shells, now finding fingers just as satisfying."},{"name":"Yo-Yo Stringer","cr":1,"role":"mook","type":"Humanoid","size":"Medium","frame":"scout","model":"scout","summary":"street performer garroting foes with a weighted yo-yo","flavor":"Whips a weighted yo-yo on garrote-strength string that returns to hand freighted with whatever it wraps."},{"name":"Fun-Fair Goblin","cr":0.25,"role":"mook","type":"Fey","size":"Small","frame":"goblin-warrior","model":"goblin-warrior","summary":"rigged carnival-game goblin who charges fingers, not coins","flavor":"Small, gaudy, and vicious, it hawks rigged ring-toss games where losing costs a finger, not a coin."},{"name":"Prize-Claw Scuttler","cr":1,"role":"mook","type":"Construct","size":"Small","frame":"giant-centipede","model":"giant-centipede","summary":"detached claw-machine grabber skittering on cable legs","flavor":"A detached claw-machine grabber skitters on cable legs, forever hunting something small enough to clamp and lift."},{"name":"Whack-a-Mole Ambusher","cr":0.5,"role":"mook","type":"Beast","size":"Small","frame":"giant-badger","model":"giant-badger","summary":"burrowing mole-toy that pops up to bite, then vanishes","flavor":"Pops from hidden holes to bite before vanishing back down, rewarding the quick with only a bruised knuckle."},{"name":"Fortune Machine Familiar","cr":1,"role":"mook","type":"Construct","size":"Small","frame":"homunculus","model":"homunculus","summary":"fortune-teller automaton whose cards come horribly true","flavor":"A mechanical gypsy bust dispenses cursed fortune cards that come cheerfully, horribly true."},{"name":"Bumper-Car Brawler","cr":1,"role":"mook","type":"Construct","size":"Medium","frame":"ogre","model":"ogre","summary":"stripped bumper-car chassis that charges and never stops grinning","flavor":"A stripped-down bumper car chassis charges anything in its lane, crumpling on impact and grinning wider each hit."},{"name":"Peppermint Stalker","cr":0.5,"role":"mook","type":"Construct","size":"Small","frame":"kobold","model":"kobold","summary":"caroling candy-striped goblinoid dragging prey to sugar vats","flavor":"A candy-cane-striped homunculus with a hook-shaped hand, humming carols while it drags foes toward the sugar vats."},{"name":"Merry-Go-Round Foal","cr":2,"role":"mook","type":"Construct","size":"Large","frame":"warhorse","model":"warhorse","summary":"carousel horse torn free of its pole, still bobbing as it tramples","flavor":"A gilded carousel horse tears free of its pole mid-spin, still bobbing up and down as it tramples the crowd."},{"name":"Face-Paint Marauder","cr":2,"role":"mook","type":"Humanoid","size":"Medium","frame":"berserker","model":"berserker","summary":"grease-painted brawler laughing through every clubbing swing","flavor":"Grease-paint smeared into a permanent scream-grin, it laughs through every swing of its balloon-animal club."},{"name":"Toy-Chest Mimic","cr":2,"role":"mook","type":"Monstrosity","size":"Medium","frame":"mimic","model":"mimic","summary":"toy-chest mimic whose lid is lined with teeth","flavor":"Looks like the best toy box in the playroom until the lid's teeth close on the hand that reaches in."},{"name":"Two-Faced Jester","cr":3,"role":"elite","type":"Fey","size":"Medium","frame":"doppelganger","model":"doppelganger","summary":"jester whose two painted faces switch mid-attack, unpredictably","flavor":"One painted face grins, the other weeps; it switches mid-sentence and mid-swing, and you never learn which is the lie."},{"name":"Marionette Master","cr":4,"role":"elite","type":"Humanoid","size":"Medium","frame":"bandit-captain","model":"bandit-captain","summary":"puppeteer who yanks strings to animate a squad mid-fight","flavor":"Works a cross of tangled strings that yank a squad of animate puppets into sudden, borrowed violence."},{"name":"Whirligig Horror","cr":4,"role":"elite","type":"Construct","size":"Large","frame":"gorgon","model":"gorgon","summary":"spinning rotor-ride whose scythe gondolas scatter red confetti","flavor":"A carnival ride's rotor arms spin faster than sight, each seat a scythe-edged gondola scattering the crowd in red confetti."},{"name":"Sawdust Strongman","cr":4,"role":"elite","type":"Humanoid","size":"Large","frame":"ettin","model":"ettin","summary":"two-headed circus strongman crushing while both heads lie","flavor":"A two-headed circus strongman act, each head shouting a different crowd-pleasing lie while the shared arms crush the truth out of you."},{"name":"Balloon-Animal Chimera","cr":3,"role":"elite","type":"Construct","size":"Medium","frame":"cockatrice-regent","model":"cockatrice-regent","summary":"twisted-latex chimera that pops apart and re-knots itself","flavor":"Twisted latex shapes into a dog-headed, snake-necked menagerie that pops apart and re-knots itself around a wound."},{"name":"Cotton-Candy Spinner Witch","cr":4,"role":"elite","type":"Fey","size":"Medium","frame":"green-hag","model":"green-hag","summary":"sugar-floss witch whose spun webs harden into glass thread","flavor":"Spins sugar-floss webs from a rusted machine-heart, luring children close before the floss hardens to glass thread."},{"name":"Painted Pony Revenant","cr":4,"role":"elite","type":"Undead","size":"Large","frame":"warhorse-skeleton","model":"warhorse-skeleton","summary":"ghost carousel horse trampling an endless six-foot loop","flavor":"A carousel horse's ghost gallops the same six feet of track forever, trampling anyone standing where the pole once was."},{"name":"Rubber-Duck Leviathan","cr":4,"role":"elite","type":"Beast","size":"Large","frame":"giant-crocodile","model":"giant-crocodile","summary":"cheerful bath-toy giant with a jaw unhinging past its grin","flavor":"An oversized bath toy bobs cheerfully atop the fairground's dunk-tank pool, jaw unhinging wider than its floating grin should allow."},{"name":"Static Shock Clown","cr":5,"role":"elite","type":"Elemental","size":"Medium","frame":"azer-pyromancer","model":"azer-pyromancer","summary":"crackling clown discharging balloon-rubbed static arcs","flavor":"Rubber-soled and crackling, it rubs a balloon against its own painted hide until arcs of blue static leap for the crowd."},{"name":"Fun House Mirror-Stalker","cr":5,"role":"elite","type":"Aberration","size":"Medium","frame":"invisible-stalker","model":"invisible-stalker","summary":"mirror-dweller that stretches your reflection's arm to grab you","flavor":"Lives in the warped glass of every funhouse mirror, stretching your reflection's arm long enough to reach through and grab."},{"name":"Bearded Sideshow Prophet","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"cultist-fanatic","model":"cultist-fanatic","summary":"tent prophet whose tarot readings land as curses","flavor":"A tent-show oddity who reads futures off a deck of tarot-carnival cards, each prediction a curse dressed as a prize."},{"name":"Cymbal-Monkey Swarm","cr":5,"role":"elite","type":"Beast","size":"Medium","frame":"swarm-of-stirges","model":"swarm-of-stirges","summary":"clashing wind-up monkey troop that shatters focus and eardrums","flavor":"A skittering troop of wind-up cymbal monkeys clashes brass in a deafening rhythm that shatters concentration and eardrums alike."},{"name":"Puppet Theater Ghost","cr":5,"role":"elite","type":"Undead","size":"Medium","frame":"ghost","model":"ghost","summary":"stage-ghost that casts bystanders into its unheard endless play","flavor":"Haunts a collapsed proscenium stage, casting itself as every character in a play only it can hear, dragging watchers into the script."},{"name":"Shooting-Gallery Marksman","cr":5,"role":"elite","type":"Humanoid","size":"Medium","frame":"guard-captain","model":"guard-captain","summary":"gallery marksman who swapped tin ducks for screaming real ones","flavor":"Never misses a moving target; his rifle's tin ducks have been replaced with real, screaming ones for practice."},{"name":"Cackling Music-Box Horror","cr":6,"role":"elite","type":"Construct","size":"Medium","frame":"mage","model":"mage","summary":"ballerina automaton whose backward lullaby ages listeners down","flavor":"A brass ballerina spins atop a box that plays a lullaby backward, and every reversed note peels a year off whoever listens."},{"name":"The Understudy Doppel","cr":6,"role":"elite","type":"Monstrosity","size":"Medium","frame":"medusa","model":"medusa","summary":"mask-cycling mimic wearing the faces of the fair's dead","flavor":"Wears the faces of everyone who's ever died at the fair, cycling masks mid-conversation until you can't remember who you were talking to."},{"name":"Pinwheel Djinn","cr":6,"role":"elite","type":"Elemental","size":"Medium","frame":"invisible-stalker","model":"invisible-stalker","summary":"pinwheel-bound genie whose wishes twist gaudy and cruel","flavor":"Bound into a spinning pinwheel toy, it grants wishes that always twist back gaudy and cruel, true to the letter and never the spirit."},{"name":"Toy Soldier Colonel","cr":6,"role":"elite","type":"Construct","size":"Medium","frame":"warrior-veteran","model":"warrior-veteran","summary":"clockwork colonel drilling a squad of key-wound infantry","flavor":"Commands a squad of wind-up infantry with parade-ground precision, keys still turning in every subordinate's back."},{"name":"Bell-Tower Puppet","cr":6,"role":"elite","type":"Construct","size":"Large","frame":"stone-golem","model":"stone-golem","summary":"clock-tower automaton whose hourly strike finds softer targets","flavor":"A cathedral-clock automaton strikes the hour on the crowd below, its bronze mallet finding softer targets than the bell."},{"name":"Rictus Ringleader","cr":7,"role":"elite","type":"Fey","size":"Medium","frame":"bugbear-stalker-strangler","model":"bugbear-stalker-strangler","summary":"whip-cracking sideshow boss whose grin is stitched shut","flavor":"A whip-cracking sideshow boss whose smile is stitched, not painted, and whose acts always end with someone missing."},{"name":"Sugar-Spun Basilisk","cr":6,"role":"elite","type":"Monstrosity","size":"Medium","frame":"basilisk","model":"basilisk","summary":"candy-eyed basilisk that crystallizes prey into hard candy","flavor":"Gazes at foes with candy-glass eyes, and whatever it stares at slowly crystallizes into a life-size hard-candy statue."},{"name":"Popcorn Machine Golem","cr":7,"role":"elite","type":"Construct","size":"Large","frame":"flesh-golem","model":"flesh-golem","summary":"overheated popcorn-machine golem hailing scalding kernels","flavor":"Overheated kernels burst from its chest cavity in a scalding, blinding hail while its stitched apron soaks up the mess."},{"name":"Wax Figure Doppelganger","cr":7,"role":"elite","type":"Monstrosity","size":"Medium","frame":"yuan-ti-abomination","model":"yuan-ti-abomination","summary":"wax-museum figure that melts into a dozen grasping arms","flavor":"Stands frozen among a wax museum's other figures until a hand brushes too close, then melts into a dozen grasping arms."},{"name":"Grand Prize Chimera","cr":7,"role":"elite","type":"Construct","size":"Large","frame":"chimera","model":"chimera","summary":"three-headed stuffed-prize chimera, each head still tagged","flavor":"Stitched from three unclaimed stuffed-animal prizes, each head still wears its raffle tag and its own hunger."},{"name":"Runaway Roller-Coaster Wyrm","cr":8,"role":"high","type":"Construct","size":"Large","frame":"young-red-dragon","model":"young-red-dragon","summary":"derailed coaster track turned serpent, cars clacking as teeth","flavor":"A derailed coaster track has grown a serpentine mind of its own, its cars now teeth clacking down an endless, screaming loop."},{"name":"Grand Guignol Actor","cr":8,"role":"high","type":"Undead","size":"Medium","frame":"vampire-nightbringer","model":"vampire-nightbringer","summary":"undead stage actor whose prop dagger's blood is now real","flavor":"Died mid-performance and never left the stage, reciting the same monologue while the blood in his prop dagger turns real."},{"name":"Hedge-Maze Minotaur","cr":9,"role":"high","type":"Monstrosity","size":"Large","frame":"minotaur-of-the-horned-king","model":"minotaur-of-the-horned-king","summary":"topiary-bull minotaur that reshapes the maze to trap guests","flavor":"Grown from hedge-clippings into a living topiary bull, it reshapes the maze walls behind guests so no path leads back out."},{"name":"The Barker's Voice","cr":9,"role":"high","type":"Aberration","size":"Large","frame":"grell","model":"grell","summary":"omnipresent barker-voice hiding a tentacled body in speaker horns","flavor":"A disembodied, amplified voice that fills the fairground from every direction, its tentacled true body hidden inside the speaker horns."},{"name":"Wheel-of-Fortune Oracle","cr":9,"role":"high","type":"Fey","size":"Medium","frame":"night-hag","model":"night-hag","summary":"rigged fortune-wheel witch who collects on every fated spin","flavor":"Spins a rigged wheel that decides not prizes but fates, and every guest who plays owes her whatever the wheel names."},{"name":"Tilt-a-Whirl Horror","cr":10,"role":"high","type":"Aberration","size":"Large","frame":"cloaker","model":"cloaker","summary":"spinning ride-maw that disorients riders while digesting them","flavor":"Folds its riders into a spinning cup-shaped maw, disorientation and gravity doing half the digesting for it."},{"name":"Effigy of the Midway","cr":10,"role":"high","type":"Construct","size":"Large","frame":"clay-golem","model":"clay-golem","summary":"towering lost-and-found effigy animated by collected grudges","flavor":"A towering scarecrow-king built from every unclaimed prize and lost mitten, animated by the fair's collected grudges."},{"name":"Puppet King's Herald","cr":11,"role":"high","type":"Fey","size":"Medium","frame":"satyr-revelmaster","model":"satyr-revelmaster","summary":"herald whose compelling fanfare herds crowds toward danger","flavor":"Announces the Ringmaster's arrivals with a fanfare that compels the crowd to applaud even as it herds them toward the tents."},{"name":"Hall of Mirrors Horror","cr":11,"role":"high","type":"Aberration","size":"Large","frame":"mind-thief-arcanist","model":"mind-thief-arcanist","summary":"hive-minded shattered mirror-hall, every shard a coordinated attacker","flavor":"A shattered fun-house hallway given a hive mind, each shard-reflection a separate, coordinated attacker."},{"name":"Grandfather Clock Devourer","cr":12,"role":"high","type":"Construct","size":"Large","frame":"iron-golem","model":"iron-golem","summary":"antique clock-golem whose chime ages victims to dust","flavor":"An antique carnival clock swallows time itself, its pendulum swing aging anyone caught in its chime to dust."},{"name":"The Understudy King","cr":12,"role":"high","type":"Fey","size":"Medium","frame":"arcanaloth","model":"arcanaloth","summary":"backstage understudy rehearsing to seize the Birthday King's crown","flavor":"Waits backstage to replace the Birthday King the instant he falters, rehearsing the crown's cruelty in an empty dressing room mirror."},{"name":"Roulette Devil","cr":13,"role":"high","type":"Fiend","size":"Medium","frame":"rakshasa","model":"rakshasa","summary":"cursed casino-tent devil who collects bets in stolen years","flavor":"Runs the fairground's cursed gaming tent, and every bet placed against him pays out in years of the loser's life."},{"name":"The Grand Carousel Titan","cr":13,"role":"high","type":"Construct","size":"Huge","frame":"storm-giant","model":"storm-giant","summary":"whole carousel fused into a lurching titan of bobbing wooden limbs","flavor":"An entire carousel has fused into one lurching gilded titan, its wooden animals now limbs still bobbing on their poles."},{"name":"The Confetti Cannon Colossus","cr":14,"role":"apex","type":"Construct","size":"Huge","frame":"frost-giant","model":"frost-giant","summary":"siege-toy cannon launching cheerful bursts of glass confetti","flavor":"A fairground siege-toy that once fired harmless streamers now launches shrapnel-glass confetti in cheerful, deadly bursts."},{"name":"Matriarch of the Sideshow","cr":15,"role":"apex","type":"Monstrosity","size":"Large","frame":"medusa","model":"medusa","summary":"ancient sideshow exhibit whose curse feeds on being watched","flavor":"The oldest exhibit in the tent, kept alive by decades of gawking stares, her curse now feeds on being watched, not touched."},{"name":"The Perpetual Winner","cr":16,"role":"apex","type":"Undead","size":"Medium","frame":"death-knight-aspirant","model":"death-knight-aspirant","summary":"undying champion whose losing challengers become living trophies","flavor":"Has won every game at the fair a thousand times over and cannot stop; challengers who lose join his trophy case, still breathing."},{"name":"The Calliope Behemoth","cr":17,"role":"apex","type":"Construct","size":"Huge","frame":"dracolich","model":"dracolich","summary":"steam-organ dragon whose cheerful hymn liquefies listeners' bones","flavor":"A steam organ grew a serpent's spine and dragon's wind, and its cheerful hymn liquefies bone in anyone who can still hear it."},{"name":"Warden of the Big Top","cr":18,"role":"apex","type":"Aberration","size":"Gargantuan","frame":"eye-tyrant","model":"eye-tyrant","summary":"vast tent-eye that conscripts failed performers as new attractions","flavor":"The tent's peak is one vast, veiled eye that watches every act performed beneath it, and every failed performer becomes its next attraction."},{"name":"The Sold-Out Show","cr":19,"role":"apex","type":"Fiend","size":"Huge","frame":"balor","model":"balor","summary":"eternal demon-headliner whose lights burn brighter per soul billed","flavor":"A demon booked eternally for one final performance, its stage lights burning brighter with every soul added to the marquee."},{"name":"The Never-Ending Attraction","cr":21,"role":"apex","type":"Fey","size":"Large","frame":"arch-hag","model":"arch-hag","summary":"court rival running an endless ride that loops joy into captivity","flavor":"A rival to the Birthday King's court, she runs the ride that never lets guests off, looping the same three minutes of joy into decades of captivity."},{"name":"Marching Band Automaton","cr":1,"role":"mook","type":"Construct","size":"Medium","frame":"skeleton-warrior","model":"skeleton-warrior","summary":"brass-skeleton whose off-key blare shatters concentration","flavor":"A brass-instrument skeleton blares off-key notes that rattle armor loose and shatter concentration mid-spell."},{"name":"Rubber Ball Bouncer","cr":0.25,"role":"mook","type":"Construct","size":"Small","frame":"homunculus","model":"homunculus","summary":"grinning rubber ball bouncing faster with every bone-jarring hit","flavor":"A red rubber ball with a painted smiling face bounces at increasing speed, each impact a bone-jarring thud."},{"name":"Strongman Hammer Golem","cr":3,"role":"elite","type":"Construct","size":"Medium","frame":"helmed-horror","model":"helmed-horror","summary":"high-striker golem whose swing is meant for skulls, not bells","flavor":"Rings the high-striker bell with a swing meant for skulls, its painted grin never dimming no matter how loud the crack."},{"name":"Petting-Zoo Horror","cr":1,"role":"mook","type":"Beast","size":"Medium","frame":"giant-goat","model":"giant-goat","summary":"once-gentle petting-zoo animal grown too many teeth","flavor":"Once a gentle attraction, its wool now hides too many teeth, and it head-butts with a strength no child should have petted."},{"name":"Glow-Stick Wisp","cr":0.25,"role":"mook","type":"Elemental","size":"Tiny","frame":"will-o-wisp","model":"will-o-wisp","summary":"bobbing glow-stick wisp that lures stragglers off the path","flavor":"A chemical-glow spirit lures children off the midway paths with a cheerful bobbing light, then snaps their glow out cold."},{"name":"Cake-Topper Golem","cr":4,"role":"elite","type":"Construct","size":"Medium","frame":"flesh-golem","model":"flesh-golem","summary":"fused bride-groom cake figure, frosting-slick, still smiling","flavor":"A porcelain bride-and-groom figurine fused into one lurching shape, frosting-slick and still smiling for a wedding long over."},{"name":"the Playing-Card Guard","cr":0.125,"role":"mook","type":"Construct","size":"Medium","frame":"clockwork-law-construct-duodrone","model":"clockwork-law-construct-duodrone","summary":"flat card-soldier, obeys any shouted rank","flavor":"Flat, hinged, and utterly loyal to a rank it can't read — it swings a spade-halberd edge-on so it nearly vanishes, then face-on so it looms.","source":"public-domain","sourceNote":"Carroll, Alice's Adventures in Wonderland (1865, PD) — the Queen of Hearts' card-soldiers who paint the roses red"},{"name":"the Tin Soldier's Hollow Cousin","cr":0.25,"role":"mook","type":"Construct","size":"Medium","frame":"clockwork-law-construct-monodrone","model":"clockwork-law-construct-monodrone","summary":"wind-up soldier, marches until unwound","flavor":"Painted smile, key still turning in its back; it marches in whatever direction it was last wound, even off a table's edge.","source":"archetype","sourceNote":"stock nursery-toy-come-to-life archetype (generic wind-up soldier, not any single IP's toy line)"},{"name":"the March Hare","cr":0.5,"role":"mook","type":"Beast","size":"Medium","frame":"giant-badger","model":"net-new: lanky twitching hare in a waistcoat of fur, teacup always in one paw","summary":"tea-mad hare, hostile to clocks and cutlery","flavor":"It never stops setting the table and never stops smashing it; ours argues with the furniture between bites.","source":"public-domain","sourceNote":"Carroll, Alice's Adventures in Wonderland (1865, PD) — the tea-party Hare, mad from too much March"},{"name":"a Wicked Witch's Wolf","cr":0.25,"role":"mook","type":"Beast","size":"Medium","frame":"wolf","model":"wolf","summary":"storybook wolf, mimics a soft voice before attacking","flavor":"Chalk-dust still clings to its throat from swallowing a voice that wasn't its own; it talks before it bites, and the talking is the worse part.","source":"public-domain","sourceNote":"Grimm fairy-tale wolves (Little Red Riding Hood / the Wolf and the Seven Young Kids, PD folk tradition)"},{"name":"Geppetto's Runaway Marionette","cr":0.5,"role":"mook","type":"Construct","size":"Small","frame":"animated-flying-sword","model":"animated-flying-sword","summary":"lying puppet, nose-hinge lengthens with each lie","flavor":"Its nose is a broken hinge that keeps lengthening whenever it insists it means no harm; the strings dangling from its wrists still twitch toward a hand that isn't there.","source":"public-domain","sourceNote":"Collodi, Le avventure di Pinocchio (1883, PD) — a puppet who lied its way out of its strings"},{"name":"the Piper's Rat","cr":0.25,"role":"mook","type":"Beast","size":"Small","frame":"giant-rat","model":"giant-rat","summary":"tune-compelled rat, swarms toward any melody","flavor":"It can't help following music, even music it invents by chewing on pipes; a column of them will drown a room before the tune even lands.","source":"public-domain","sourceNote":"the Pied Piper of Hamelin legend (medieval German folk legend, PD)"},{"name":"the Mouse King's Sentry","cr":1,"role":"elite","type":"Beast","size":"Medium","frame":"giant-hyena","model":"net-new: scrawny multi-headed mouse-courtier in a torn paper crown","summary":"multi-headed mouse-courtier, argues with itself mid-fight","flavor":"Extra heads, extra crowns, extra grudges — it snaps at whichever slight it remembers most that second.","source":"public-domain","sourceNote":"Hoffmann, Nussknacker und Mausekönig (1816, PD) — the Mouse King's seven-headed court"},{"name":"the Nutcracker Grenadier","cr":1,"role":"elite","type":"Construct","size":"Medium","frame":"animated-armor","model":"animated-armor","summary":"wooden grenadier, jaw-hinge crushing bite","flavor":"Jaw hinged to crack more than nuts; painted eyes track motion better than most flesh does.","source":"archetype","sourceNote":"generic wooden-soldier toy archetype (the Nutcracker's rank-and-file, not the named prince)"},{"name":"the Cheshire Grin","cr":2,"role":"elite","type":"Fey","size":"Medium","frame":"sea-hag","model":"net-new: striped cat dissolving into mist, grin the last visible feature","summary":"fading cat, taunts and phases out mid-combat","flavor":"It answers every question with a worse one and vanishes exactly when a hit should land; the grin is the last thing to go, and the first thing to come back.","source":"public-domain","sourceNote":"Carroll, Alice's Adventures in Wonderland (1865, PD) — the cat that fades to only its smile"},{"name":"the Winged Monkey Raider","cr":2,"role":"elite","type":"Monstrosity","size":"Medium","frame":"giant-owl","model":"giant-owl","summary":"cap-bound flying monkey, resents its own orders","flavor":"It hates every second of the compulsion and takes it out on whoever's closest; free one mid-fight and it simply leaves.","source":"public-domain","sourceNote":"L. Frank Baum, The Wonderful Wizard of Oz (1900, PD, novel version) — the Wicked Witch of the West's flying monkey soldiers, bound by the Golden Cap"},{"name":"the Goblin Toymaker","cr":2,"role":"elite","type":"Fey","size":"Small","frame":"green-hag","model":"net-new: hunched goblin tinker hung with keys, spare parts, and a whistle","summary":"toy-peddling goblin, remote-commands nearby constructs","flavor":"Every toy it's ever sold is still listening for its whistle; it fights by recalling its merchandise, not by swinging anything itself.","source":"archetype","sourceNote":"stock malevolent-toymaker/goblin-tinkerer archetype drawing on Grimm-style goblin/gnome tradition (PD folk motif, not any branded IP)"},{"name":"the Queen of Hearts","cr":4,"role":"high","type":"Humanoid","size":"Medium","frame":"guard-captain","model":"net-new: imperious card-court queen, oversized ruffed gown, axe she never swings herself","summary":"tyrant queen, commands the battlefield instead of fighting it","flavor":"She never actually swings the axe — she just declares a sentence and the room's own furniture carries it out; the tantrum is the spell.","source":"public-domain","sourceNote":"Carroll, Alice's Adventures in Wonderland (1865, PD) — 'Off with their heads!'"},{"name":"the Grimm Woodland Witch","cr":5,"role":"high","type":"Fey","size":"Medium","frame":"night-hag","model":"night-hag","summary":"cannibal-witch, lures and force-feeds before the kill","flavor":"She fattens what she can't yet eat and eats what she's already fattened; the oven is a door she keeps ajar just to hear you consider it.","source":"public-domain","sourceNote":"Grimm fairy-tale witches (Hansel and Gretel's gingerbread-house witch; PD folk tradition, our own original description — no film likeness)"},{"name":"the Wicked Witch of the West","cr":6,"role":"high","type":"Humanoid","size":"Medium","frame":"archpriest","model":"net-new: one-eyed witch wrapped in dust-colored robes, umbrella-staff, no green skin","summary":"beast-commanding witch, dissolves rather than dies clean","flavor":"Ours is a hoarder of borrowed servants, not a green face — she never fights fair and she never fights dry-eyed once the bucket comes out.","source":"public-domain","sourceNote":"L. Frank Baum, The Wonderful Wizard of Oz (1900, PD novel version) — melts to water, commands wolves/crows/bees/monkeys, not any film's green-skin design"},{"name":"the Mouse King","cr":7,"role":"high","type":"Monstrosity","size":"Large","frame":"troll","model":"troll","summary":"seven-headed rat-king, regenerates through internal rivalry","flavor":"Seven heads mean seven opinions about how you should die; killing one crown just promotes the angriest survivor.","source":"public-domain","sourceNote":"Hoffmann, Nussknacker und Mausekönig (1816, PD) — the seven-crowned rival of the Nutcracker Prince"},{"name":"the Automaton in the Wicker Man's Skin","cr":5,"role":"high","type":"Construct","size":"Medium","frame":"scarecrow","model":"scarecrow","summary":"straw guardian-construct, patrols a fixed boundary forever","flavor":"Straw where a heart should sit and a painted grin that never once needed the muscles to hold it; it guards the toybox border like it remembers being told to.","source":"archetype","sourceNote":"scarecrow-come-to-life archetype (generic animated-guardian toybox motif, not any branded character)"},{"name":"the Wonderland Jabberwock","cr":10,"role":"apex","type":"Dragon","size":"Large","frame":"young-red-dragon","model":"young-red-dragon","summary":"nonsense-dragon, telegraphs doom in verse before it strikes","flavor":"It doesn't so much attack as arrive — burbling, whiffling, eyes of flame — and the vorpal answer is always a blade someone else forged.","source":"public-domain","sourceNote":"Carroll, Through the Looking-Glass (1871, PD) — 'the jaws that bite, the claws that catch'"},{"name":"the Tin Woodman, Rusted Wrong","cr":9,"role":"apex","type":"Construct","size":"Large","frame":"iron-golem","model":"iron-golem","summary":"hollow tin giant, mourns while it swings the axe","flavor":"Somewhere under the seams is the man who kept chopping even after every piece of him was replaced; he still oils his own joints mid-fight, out of habit, not need.","source":"public-domain","sourceNote":"L. Frank Baum, The Wonderful Wizard of Oz (1900, PD novel version) — the woodman who traded his flesh limb by limb for tin"},{"name":"the Hamelin Piper","cr":11,"role":"apex","type":"Humanoid","size":"Medium","frame":"spy-master","model":"net-new: gaunt piper in motley, pipe always at his lips, never draws a blade","summary":"compulsion piper, turns the battlefield's own mooks against it","flavor":"He never raises a weapon; he raises a tune, and the toybox itself gets up to dance for him, one compelled soldier at a time.","source":"public-domain","sourceNote":"the Pied Piper of Hamelin legend (medieval German folk legend, PD) — paid in rats, repaid in children"},{"name":"the Wonderland Executioner-Court","cr":8,"role":"apex","type":"Swarm","size":"Large","frame":"swarm-of-lemures","model":"net-new: a whirling mass of card-guards rising as a single verdict","summary":"card-mob swarm, group-verdict area attacks","flavor":"A deck's worth of guards rising as one verdict; it doesn't think, it convicts, and it convicts everyone in reach at once.","source":"public-domain","sourceNote":"Carroll, Alice's Adventures in Wonderland (1865, PD) — the trial of the Knave of Hearts, the mob of cards"}]
};
